function CheckIfUnitWantsFixedShield(oUnit, bCheckForNearbyShields, iOptionalShieldsWantedOverride)
    --Intended to be called whenever something happens that means oUnit may want to change whehter it is recorded as wanting a shield, except for death which is handled elsewhere now
    --oUnit construction is started (done via OnConstructionStarted)
    --A shield covering oUnit dies (done via UpdateShieldCoverageOfUnits)
    --A shield covering oUnit has construction started (done via UpdateShieldCoverageOfUnits)
    --bCheckForNearbyShields - if this is true, then will check for any already constructed shields; i.e. this should be true if this function is called from oUnit's construction being started

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckIfUnitWantsFixedShield'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at game time '..GetGameTimeSeconds()..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bCheckForNearbyShields='..tostring(bCheckForNearbyShields or false)..'; oUnit[refbUnitWantsShielding] before update='..tostring(oUnit[refbUnitWantsShielding] or false)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; iOptionalShieldsWantedOverride='..(iOptionalShieldsWantedOverride or 'nil')..'; owner='..oUnit:GetAIBrain().Nickname..'; Enemy novax count='..AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyNovaxCount]..'; Enemy arti count='..AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount]) end

    local iShieldsWanted = 0
    local iShieldCoverage = 0

    if oUnit[reftoShieldsProvidingCoverage] and AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]) == false then
        iShieldCoverage = table.getn(oUnit[reftoShieldsProvidingCoverage])
    end

    --Determine shields wanted
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        if iOptionalShieldsWantedOverride then iShieldsWanted = iOptionalShieldsWantedOverride
        elseif oUnit[reftArtiTemplateRefs] then
            iShieldsWanted = 0 --we will be relying on template instead
        else
            local oBP = oUnit:GetBlueprint()
            --Dont get shields for other shields (to avoid infinite shields)
            if bDebugMessages == true then LOG(sFunctionRef..': Unit mass cost='..oUnit[AiBotUnitInfo.refiUnitMassCost]..'; Shieldm ax health='..(oBP.Defense.Shield.ShieldMaxHealth or 0)) end
            local bT2ArtiOrTMLAgainstEnemyT2ArtiOrFatboy
            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) then
                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then bT2ArtiOrTMLAgainstEnemyT2ArtiOrFatboy = true
                elseif tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] >= 1500 then
                    bT2ArtiOrTMLAgainstEnemyT2ArtiOrFatboy = true
                end
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]) == false then
                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                if tLZTeamData[AiBotMap.refbGetTMLBattery] then
                    bT2ArtiOrTMLAgainstEnemyT2ArtiOrFatboy = true
                end
            end
            if (bT2ArtiOrTMLAgainstEnemyT2ArtiOrFatboy or (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 2000 or (EntityCategoryContains(AiBotUnitInfo.refCategoryT2Mex, oUnit.UnitId) and AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyNovaxCount] > 0)) and (oBP.Defense.Shield.ShieldMaxHealth or 0) == 0 then
                local iTeam = oUnit:GetAIBrain().AiBotTeam
                if bDebugMessages == true then LOG(sFunctionRef..': Unit health='..oBP.Defense.Health..'; Defending against t3 arti for iTeam'..oUnit:GetAIBrain().AiBotTeam..'='..tostring(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refbDefendAgainstArti] or false)) end
                if oBP.Defense.Health / (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) < 1
                        or EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryTML, oUnit.UnitId)
                        or ((AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refbDefendAgainstArti] or AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 12000) and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 3000 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId))
                        or (EntityCategoryContains(AiBotUnitInfo.refCategoryMex - categories.TECH1, oUnit.UnitId) and AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyNovaxCount] > 0) then

                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 12000 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] >= 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] >= 2) and AiBotUtilities.IsTableEmpty(oUnit[reftoSpecialAssignedShields]) then iShieldsWanted = 2
                    else iShieldsWanted = 1
                    end
                end
            end
        end
    end

    --If have just started construction of oUnit then check if there are any existing shields that can help it
    if bCheckForNearbyShields and iShieldsWanted > 0 then
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
        if iPlateau > 0 and iLandZone > 0 then
            local tNearbyShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tNearbyShields) == false then
                if not(oUnit[reftoShieldsProvidingCoverage]) then oUnit[reftoShieldsProvidingCoverage] = {} end

                for iLZShield, oLZShield in tNearbyShields do
                    local iShieldRadius = oLZShield:GetBlueprint().Defense.Shield.ShieldSize * 0.5 - 0.1 -- - 1
                    RecordIfShieldIsProtectingUnit(oLZShield, oUnit, iShieldRadius, true)
                end

                if oUnit[reftoShieldsProvidingCoverage] and AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]) == false then
                    iShieldCoverage = table.getn(oUnit[reftoShieldsProvidingCoverage])
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': iShieldsWanted='..iShieldsWanted..'; iSHieldCoverage='..iShieldCoverage) end
    if iShieldsWanted > iShieldCoverage then
        --Want more shielding
        if not(oUnit[refbUnitWantsShielding]) then
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
            if iPlateau > 0 and iLandZone > 0 then
                oUnit[refbUnitWantsShielding] = true
                local tUnitLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
                if not(tUnitLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield]) then tUnitLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield] = {} end
                table.insert(tUnitLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield], oUnit)
                if bDebugMessages == true then LOG(sFunctionRef..': Have added unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of units wanting shielding to iPlateau='..iPlateau..'; iLandZOne='..iLandZone) end
            end
        end
    elseif AiBotUnitInfo.IsUnitValid(oUnit) then
        --Dont want more shielding
        if oUnit[refbUnitWantsShielding] then
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
            if iPlateau > 0 and iLandZone > 0 then
                oUnit[refbUnitWantsShielding] = false
                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield]) == false then
                    for iRecordedUnit, oRecordedUnit in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield] do
                        if oRecordedUnit == oUnit then
                            table.remove(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield], iRecordedUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Removed unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from the table of units wanting fixed shielding') end
                            break
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
        LOG(sFunctionRef..': Is table of units wanting fixed shield empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield])))
        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield]) == false then
            for iUnit, oUnit in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield] do
                LOG(sFunctionRef..': Listing out each unit wanting shielding for iLandZOne '..iLandZone..'; iUnit '..iUnit..' is oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordIfShieldIsProtectingUnit(oShield, oUnit, iShieldRadius, bDontCheckIfWantsFixedShield)
    --bDontCheckIfWantsFixedShield - true if calling from the 'CheckIfUnitWantsFixedShield' function to avoid infinite loop
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordIfShieldIsProtectingUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Checking if unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; is covered by oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; iShieldRadius='..iShieldRadius..'; Distance='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oShield:GetPosition())) end
    if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oShield:GetPosition()) <= iShieldRadius then
        local bAddToUnit = true
        --Record against unit
        if oUnit[reftoShieldsProvidingCoverage] and AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]) == false then
            --Redundancy in case something goes wrong with tracking:
            for iRecordedShield, oRecordedShield in oUnit[reftoShieldsProvidingCoverage] do
                if oRecordedShield == oShield then
                    bAddToUnit = false
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if already recorded this shield, bAddToUnit='..tostring(bAddToUnit)) end
        if bAddToUnit then
            if not(oUnit[reftoShieldsProvidingCoverage]) then oUnit[reftoShieldsProvidingCoverage] = {} end
            table.insert(oUnit[reftoShieldsProvidingCoverage], oShield)
            if bDebugMessages == true then LOG(sFunctionRef..': Recording shield as covering the unit; bDontCheckIfWantsFixedShield='..tostring(bDontCheckIfWantsFixedShield or false)) end
            if not(bDontCheckIfWantsFixedShield) then CheckIfUnitWantsFixedShield(oUnit) end
        end
        --Record against shield
        local bAddToShield = true
        if not(oShield[reftoUnitsCoveredByShield]) then oShield[reftoUnitsCoveredByShield] = {}
        else
            for iRecorded, oRecorded in oShield[reftoUnitsCoveredByShield] do
                if oRecorded == oUnit then bAddToShield = false break end
            end
        end
        if bAddToShield then
            table.insert(oShield[reftoUnitsCoveredByShield], oUnit)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateShieldCoverageOfUnits(oShield, bTreatAsDead)
    --If shield has died, then remove any units it was protecting; if shield has just started construction then instead record any units it can provide coverage to
    --Either way, clear any existing units from the shield (as redundancy - in theory should only be needed if shield is dead

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateShieldCoverageOfUnits'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through every unit that the shield is providing coverage to, and will update to remove this unit from that table, oShield='..(oShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShield) or 'nil')..'; Is table of units empty='..tostring(AiBotUtilities.IsTableEmpty(oShield[reftoUnitsCoveredByShield])))
        if AiBotUtilities.IsTableEmpty(oShield[reftoUnitsCoveredByShield]) == false then LOG(sFunctionRef..': Number of units covered='..table.getn(oShield[reftoUnitsCoveredByShield])) end
    end
    if AiBotConditions.IsTableOfUnitsStillValid(oShield[reftoUnitsCoveredByShield]) then
        for iUnit, oUnit in oShield[reftoUnitsCoveredByShield] do
            if AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Will update unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to no longer have the shield recorded as providing coverage to it') end
                for iRecordedShield, oRecordedShield in oUnit[reftoShieldsProvidingCoverage] do
                    if oRecordedShield == oShield then
                        if bDebugMessages == true then LOG(sFunctionRef..': We had recorded shield '..oRecordedShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedShield)..' as covering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' so will now remove it') end
                        table.remove(oUnit[reftoShieldsProvidingCoverage], iRecordedShield)
                        break
                    end
                end
                if AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]) then oUnit[reftoShieldsProvidingCoverage] = nil end
            end
            if oUnit:GetAIBrain().AiBotAI then
                CheckIfUnitWantsFixedShield(oUnit)
            end
        end
        oShield[reftoUnitsCoveredByShield] = nil
    end

    if not(bTreatAsDead) then
        --Record what units this shield can protect in t he LZ it is in
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oShield:GetPosition())
        if iPlateau > 0 and iLandZone > 0 then
            local tUnitsWantingShielding = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oShield:GetAIBrain().AiBotTeam][AiBotMap.reftoLZUnitWantingFixedShield]
            if AiBotUtilities.IsTableEmpty(tUnitsWantingShielding) == false then
                local iShieldRadius = oShield:GetBlueprint().Defense.Shield.ShieldSize * 0.5 - 0.1 -- - 1
                oShield[reftoUnitsCoveredByShield] = {}
                local bAddToUnit = false
                local tUnitsToConsider = {}
                --Copy table so we dont have to fork thread to update each unit
                for iUnit, oUnit in tUnitsWantingShielding do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then table.insert(tUnitsToConsider, oUnit) end
                end
                for iUnit, oUnit in tUnitsToConsider do
                    RecordIfShieldIsProtectingUnit(oShield, oUnit, iShieldRadius)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code for oShield='..(oShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShield) or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordUnitShieldCoverage(oUnit)
    --For all units, not just AiBot specific, so e.g. a TML will recognise when it's firing at a shielded target
    --Intended to be called when a unit is created
    if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
        local aiBrain = oUnit:GetAIBrain()
        --Is this a shield? if so then update all units around it
        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then
            local iShieldRadius = oUnit:GetBlueprint().Defense.Shield.ShieldSize * 0.5 - 0.1 -- - 1 --removed the -1 as of v50 since now that are using this to track enemies it can lead to false results
            local tNearbyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure, oUnit:GetPosition(), iShieldRadius, 'Ally')
            if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                for iNearbyUnit, oNearbyUnit in tNearbyUnits do
                    RecordIfShieldIsProtectingUnit(oUnit, oNearbyUnit, iShieldRadius, true)
                end
            end
        else
            local iPotentialShieldRadius = 22 --seraphim is 23 radius
            local tNearbyShields = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedShield, oUnit:GetPosition(), iPotentialShieldRadius, 'Ally')
            if AiBotUtilities.IsTableEmpty(tNearbyShields) == false then
                local iShieldRadius
                for iShield, oShield in tNearbyShields do
                    if oShield:GetFractionComplete() == 1 then
                        iShieldRadius = oShield:GetBlueprint().Defense.Shield.ShieldSize * 0.5 -0.1 -- - 1
                        RecordIfShieldIsProtectingUnit(oShield, oUnit, iShieldRadius, true)
                    end
                end
            end
        end
    end
end

function ForkedCheckForAnotherMissile(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ForkedCheckForAnotherMissile'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[refbMissileChecker]='..tostring(oUnit[refbMissileChecker] or false)..'; Time='..GetGameTimeSeconds()) end
    if not(oUnit[refbMissileChecker]) and not(oUnit.Dead) then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1) --make sure we have an accurate number for missiles
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if not(oUnit.Dead) then
            local bUnpause
            if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                oUnit[refbMissileChecker] = true
                while AiBotUnitInfo.IsUnitValid(oUnit) do
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(10)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        if not(AiBotConditions.WantToPauseSMD(oUnit, false)) then
                            bUnpause = true
                            break
                        end
                    end
                end
            else
                local iMissiles = 0
                if oUnit.GetTacticalSiloAmmoCount then iMissiles = iMissiles + oUnit:GetTacticalSiloAmmoCount() end
                if oUnit.GetNukeSiloAmmoCount then iMissiles = iMissiles + oUnit:GetNukeSiloAmmoCount() end
                if bDebugMessages == true then LOG(sFunctionRef..': iMissiles outside of loop='..iMissiles) end
                if iMissiles >= 2 and AiBotUnitInfo.IsUnitValid(oUnit) then
                    oUnit[refbMissileChecker] = true
                    local iTeam = oUnit:GetAIBrain().AiBotTeam
                    while AiBotUnitInfo.IsUnitValid(oUnit) do
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitSeconds(10)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            iMissiles = 0
                            if oUnit.GetTacticalSiloAmmoCount then iMissiles = iMissiles + oUnit:GetTacticalSiloAmmoCount() end
                            if oUnit.GetNukeSiloAmmoCount then iMissiles = iMissiles + oUnit:GetNukeSiloAmmoCount() end
                            if bDebugMessages == true then LOG(sFunctionRef..': iMissiles='..iMissiles..'; Time='..GetGameTimeSeconds()) end
                            if iMissiles < 2 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 400) then
                                bUnpause = true

                                if bDebugMessages == true then LOG(sFunctionRef..': Will change unit state so it isnt paused and set autobuild status to true, time='..GetGameTimeSeconds()) end
                                break
                            end
                        else
                            break
                        end

                    end
                else
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        bUnpause = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Will unpause unit as not enough missiles') end
                    end
                end
            end
            if bUnpause and AiBotUnitInfo.IsUnitValid(oUnit) then
                if bDebugMessages == true then LOG(sFunctionRef..': setting unit autobuild status to true, time='..GetGameTimeSeconds()) end
                --oUnit:SetPaused(false)
                AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(oUnit, false)
                AiBotUnitInfo.SetUnitMissileAutoBuildStatus(oUnit, true)
            end
            if oUnit[refbMissileChecker] then oUnit[refbMissileChecker] = nil end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckIfWantToBuildAnotherMissile(oUnit)
    ForkThread(ForkedCheckForAnotherMissile, oUnit)
end

function RecordUnitsInRangeOfTMLAndAnyTMDProtection(oTML, tOptionalUnitsToConsider, bCalledDueToTMLDetection)
    --tOptionalUnitsToConsider - if nil then will get all nearby units on an opposing team to oTML
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordUnitsInRangeOfTMLAndAnyTMDProtection'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if AiBotUnitInfo.IsUnitValid(oTML) then
        --If this is a mobile TML then want to update any units not in range of it now that were recorded as being in range previously
        --[[local toMobilePrevRecordedUnitsToUpdate
        if EntityCategoryContains(categories.MOBILE, oTML.UnitId) and oTML[refbTMDBuiltSinceLastChecked] and AiBotConditions.IsTableOfUnitsStillValid(oTML[reftUnitsInRangeOfThisTML]) then
            toMobilePrevRecordedUnitsToUpdate = {}
            for iRecorded, oRecorded in oTML[reftUnitsInRangeOfThisTML] do
                toMobilePrevRecordedUnitsToUpdate[GetUnitRef(oRecorded)] = oRecorded
            end
        end--]]

        local iTMLRange = math.max((oTML[AiBotUnitInfo.refiManualRange] or 0), (oTML[AiBotUnitInfo.refiIndirectRange] or 0))
        if iTMLRange == 0 then iTMLRange = iTMLMissileRange end
        --Increase range if mobile
        if EntityCategoryContains(categories.MOBILE, oTML.UnitId) then
            iTMLRange = iTMLRange + 10
        end
        --Increase range for aoe
        iTMLRange = iTMLRange + (oTML[AiBotUnitInfo.refiIndirectAOE] or 2)
        if bDebugMessages == true then LOG(sFunctionRef..': TMl range: Manual range='..(oTML[AiBotUnitInfo.refiManualRange] or 0)..'; IF range='..(oTML[AiBotUnitInfo.refiIndirectRange] or 0)..'; AOE='..(oTML[AiBotUnitInfo.refiIndirectAOE] or 2)..'; Is TML mobile='..tostring(EntityCategoryContains(categories.MOBILE, oTML.UnitId))..'; TML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)) end


        local iTMLTeam = oTML:GetAIBrain().AiBotTeam
        local tNearbyTMD = {}
        local tUnitsToProtect = {}
        local tiTeamsWithUnitsThatMightWantTMD = {}
        if tOptionalUnitsToConsider then
            for iUnit, oUnit in tOptionalUnitsToConsider do
                if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTML:GetPosition()) <= iTMLRange then
                    table.insert(tUnitsToProtect, oUnit)
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Near start of code for oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..' at time of '..GetGameTimeSeconds()..'; Is tOptionalUnitsToConsider nil='..tostring(tOptionalUnitsToConsider == nil)) end
        for iTMDTeam = 1, AiBotTeam.iTotalTeamCount do
            --Get all TMD that could stop this TML, and all units it could threaten
            if not(iTMDTeam == iTMLTeam) then
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                    local oTMDBrain
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                        oTMDBrain = oBrain
                        break
                    end

                    local tTeamNearbyTMD = oTMDBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oTML:GetPosition(), iTMLRange + 13, 'Ally')
                    if AiBotUtilities.IsTableEmpty(tTeamNearbyTMD) == false then
                        for iUnit, oUnit in tTeamNearbyTMD do
                            table.insert(tNearbyTMD, oUnit)
                        end
                    end
                    if not(tOptionalUnitsToConsider) then
                        --i.e. this is the first time we are considering the TML; double-check we havent already recorded the TML
                        local bNotAlreadyRecordedInTeamData = EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oTML.UnitId)
                        if bNotAlreadyRecordedInTeamData and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.reftEnemyTML]) then
                            for iUnit, oUnit in AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.reftEnemyTML] do
                                if oUnit == oTML then
                                    bNotAlreadyRecordedInTeamData = false
                                    break
                                end
                            end
                        end
                        if bNotAlreadyRecordedInTeamData then
                            if bDebugMessages == true then LOG(sFunctionRef..': TML not already recorded in team data so will add for team '..iTMDTeam..', oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)) end
                            table.insert(AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.reftEnemyTML], oTML)
                        end
                        local tTeamUnitsToProtect = oTMDBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryProtectFromTML, oTML:GetPosition(), iTMLRange, 'Ally')
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tTeamUnitsToProtect empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamUnitsToProtect))..'; iTMLRange='..iTMLRange..'; TML position='..repru(oTML:GetPosition())) end
                        if AiBotUtilities.IsTableEmpty(tTeamUnitsToProtect) == false then
                            for iUnit, oUnit in tTeamUnitsToProtect do
                                table.insert(tUnitsToProtect, oUnit)
                            end
                        end
                    end
                end
            end
        end
        --Below not needed - had put it in when thought was reason TML wasnt firing but the civilians in campaign were already assigned teams as had updated the iscivilian flag for campaign
        --[[if not(tOptionalUnitsToConsider) and AiBotMap.bIsCampaignMap then
            local iTMLIndex = oTML:GetAIBrain():GetArmyIndex()
            for iBrain, oBrain in ArmyBrains do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; AiBotTeam='..(oBrain.AiBotTeam or 'nil')..'; IsEnemy='..tostring(IsEnemy(iTMLIndex, oBrain:GetArmyIndex()))) end
                if not(oBrain.AiBotTeam) and IsEnemy(iTMLIndex, oBrain:GetArmyIndex()) then
                    local tTeamUnitsToProtect = oBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryProtectFromTML, oTML:GetPosition(), iTMLRange, 'Ally')
                    if AiBotUtilities.IsTableEmpty(tTeamUnitsToProtect) == false then
                        for iUnit, oUnit in tTeamUnitsToProtect do
                            local bAlreadyIncluded = false
                            if AiBotUtilities.IsTableEmpty(tUnitsToProtect) == false then
                                for iRecorded, oRecorded in tUnitsToProtect do
                                    if oRecorded == oUnit then bAlreadyIncluded = true break end
                                end
                            end
                            if not(bAlreadyIncluded) then
                                table.insert(tUnitsToProtect, oUnit)
                            end
                        end
                    end
                end
            end
        end--]]

        if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to protect empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToProtect))..'; Is table of TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyTMD))) end
        if AiBotUtilities.IsTableEmpty(tUnitsToProtect) == false then
            local iCurTeam
            for iUnit, oUnit in tUnitsToProtect do
                --if toMobilePrevRecordedUnitsToUpdate then toMobilePrevRecordedUnitsToUpdate[GetUnitRef(oUnit)] = nil end
                if not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                    --Update various tracking variables based on whether TMD are protecting this unit or not (i.e. updates TML for potential targets, TMD for units theyre covering, and units for TML that have hte unit in their range)
                    RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oTML, tNearbyTMD)
                    iCurTeam = oUnit:GetAIBrain().AiBotTeam
                    if iCurTeam then
                        if not(tiTeamsWithUnitsThatMightWantTMD[iCurTeam]) then tiTeamsWithUnitsThatMightWantTMD[iCurTeam] = {} end
                        table.insert(tiTeamsWithUnitsThatMightWantTMD[iCurTeam], oUnit)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering if unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is protected from the TML by TMD') end
                end
            end
            if AiBotUtilities.IsTableEmpty(tiTeamsWithUnitsThatMightWantTMD) == false then
                for iTeam, tUnits in tiTeamsWithUnitsThatMightWantTMD do
                    RecordIfUnitsWantTMDCoverageAgainstLandZone(iTeam, tUnits, bCalledDueToTMLDetection)
                end
            end
        end
        --[[if AiBotUtilities.IsTableEmpty(toMobilePrevRecordedUnitsToUpdate) == false then
            --Dealing with a mobile TML so check for units that we havent updated per the above since they may now have TMD to cover them
            for iRecorded, oRecorded in toMobilePrevRecordedUnitsToUpdate do
                local tNearbyTMD = oRecorded:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oRecorded:GetPosition(), iTMLRange + 30, 'Ally')
                if AiBotUtilities.IsTableEmpty(tNearbyTMD) == false then
                    RecordIfUnitIsProtectedFromTMLByTMD(oRecorded, oTML, tNearbyTMD)
                end
            end
        end--]]
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetUnitRef(oUnit)
    return oUnit.UnitId..'L'..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'B'..oUnit:GetAIBrain():GetArmyIndex()
end

function TMDJustBuilt(oTMD)
    --Searches for any enemy TML in range of the TMD, and any friendly units in range of the TMD
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TMDJustBuilt'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local oTMDBrain = oTMD:GetAIBrain()
    local iTMDTeam = oTMDBrain.AiBotTeam
    if not(oTMD[AiBotUnitInfo.refiMissileDefenceRange]) then AiBotUnitInfo.RecordUnitRange(oTMD) end
    local iTMDRange = (oTMD[AiBotUnitInfo.refiMissileDefenceRange] or 12.5)
    local tNearbyTML = {}
    local iTMDPlateauOrZero, iTMDZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oTMD:GetPosition())
    local tTMDZoneData, tTMDZoneTeamData
    if (iTMDZone or 0) > 0 then
        if iTMDPlateauOrZero == 0 then
            tTMDZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTMDZone]][AiBotMap.subrefPondWaterZones][iTMDZone]
            tTMDZoneTeamData = tTMDZoneData[AiBotMap.subrefWZTeamData][iTMDTeam]
        else
            tTMDZoneData = AiBotMap.tAllPlateaus[iTMDPlateauOrZero][AiBotMap.subrefPlateauLandZones][iTMDZone]
            tTMDZoneTeamData = tTMDZoneData[AiBotMap.subrefLZTeamData][iTMDTeam]
        end
    end
    local bCheckForUnitsInZone = AiBotUtilities.IsTableEmpty(tTMDZoneTeamData[AiBotMap.reftUnitsWantingTMD]) == false
    local tbUnitRefsConsideredByTML
    local tbUnitRefsConsideredAllTML = {}
    local sCurUnitRef
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' owned by '..oTMD:GetAIBrain().Nickname..'; TMD fraction complete='..oTMD:GetFractionComplete()..'; Time='..GetGameTimeSeconds()) end
    for iTMLTeam = 1, AiBotTeam.iTotalTeamCount do
        --Get all TML in range of this TMD
        if not(iTMDTeam == iTMLTeam) then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                local oTMLBrain
                for iBrain, oBrain in AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                    oTMLBrain = oBrain
                    break
                end
                local tTeamNearbyTML = oTMLBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTML, oTMD:GetPosition(), iTMLMissileRange + iTMDRange - 3, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': Dealing with oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..'; is table of nearby TML empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamNearbyTML))..'; iTMLTeam='..iTMLTeam) end
                if AiBotUtilities.IsTableEmpty(tTeamNearbyTML) == false then
                    for iTML, oTML in tTeamNearbyTML do
                        tbUnitRefsConsideredByTML = {}
                        local tFriendlyUnitsInRangeOfTML = oTMDBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryProtectFromTML, oTML:GetPosition(), iTMLMissileRange + 2, 'Ally')
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of TMD friendly units in range of TML empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyUnitsInRangeOfTML))) end
                        if AiBotUtilities.IsTableEmpty(tFriendlyUnitsInRangeOfTML) == false then
                            for iUnit, oUnit in tFriendlyUnitsInRangeOfTML do
                                sCurUnitRef = GetUnitRef(oUnit)

                                tbUnitRefsConsideredByTML[sCurUnitRef] = true
                                tbUnitRefsConsideredAllTML[sCurUnitRef] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Will check if unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in range of TML '..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)) end
                                RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oTML, { oTMD }, true) --This will do a distance check from the unit to the TMD
                            end
                        end
                        --Also check for any units wanting TMD coverage in the TMD zone (redundancy in case there are issues with getunitsaroundpoint not picking up upgrading units)
                        if bCheckForUnitsInZone and AiBotUtilities.IsTableEmpty(tTMDZoneTeamData[AiBotMap.reftUnitsWantingTMD]) == false then
                            for iUnit, oUnit in tTMDZoneTeamData[AiBotMap.reftUnitsWantingTMD] do
                                if AiBotUnitInfo.IsUnitValid(oUnit) then
                                    sCurUnitRef = GetUnitRef(oUnit)
                                    if not(tbUnitRefsConsideredByTML[sCurUnitRef]) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have unit in zone wanting TMD coverage that we havent considered with getunitsaroundpoint, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Unit fraction complete='..oUnit:GetFractionComplete()) end
                                        RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oTML, { oTMD }, true)
                                        tbUnitRefsConsideredAllTML[sCurUnitRef] = true
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of mobile TML empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.reftEnemyMobileTML]))) end
    if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.reftEnemyMobileTML]) then
        for iMobileTML, oMobileTML in AiBotTeam.tTeamData[iTMDTeam][AiBotTeam.reftEnemyMobileTML] do
            if AiBotConditions.IsTableOfUnitsStillValid(oMobileTML[reftUnitsInRangeOfThisTML]) then
                for iRecorded, oRecorded in oMobileTML[reftUnitsInRangeOfThisTML] do
                    sCurUnitRef = GetUnitRef(oRecorded)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oMobileTML '..oMobileTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMobileTML)..'; oRecorded='..oRecorded.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecorded)..'; is tbUnitRefsConsideredAllTML nil for this unit='..tostring(tbUnitRefsConsideredAllTML[sCurUnitRef] == nil)) end
                    if not(tbUnitRefsConsideredAllTML[sCurUnitRef]) then
                        RecordIfUnitIsProtectedFromTMLByTMD(oRecorded, oMobileTML, { oTMD }, true)
                        tbUnitRefsConsideredAllTML[sCurUnitRef] = true
                    end
                end
            end
            oMobileTML[refbTMDBuiltSinceLastChecked] = true
        end
    end

    --Also record TMD as covering any units in their range (allows for coverage to be recorded for preemptive TMD)
    local tNearbyAlliedUnits = oTMDBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryProtectFromTML, oTMD:GetPosition(), oTMD[AiBotUnitInfo.refiMissileDefenceRange] - 1, 'Ally')
    if AiBotUtilities.IsTableEmpty(tNearbyAlliedUnits) == false then
        for iUnit, oUnit in tNearbyAlliedUnits do
            if oUnit:GetAIBrain().AiBotAI then
                RecordThatTMDProtectsUnitFromTML(oTMD, oUnit)
            end
        end
    end


    --Reevaluate all units in the zone flagged as wanting TMD, due to issue where in some cases the unit would be recorded against the LZ despite loads of TMD covering it
    if AiBotUtilities.IsTableEmpty(tTMDZoneTeamData[AiBotMap.reftUnitsWantingTMD]) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Will update tTMDZoneTeamData[AiBotMap.reftUnitsWantingTMD], iTMDTeam='..iTMDTeam) end
        RecordIfUnitsWantTMDCoverageAgainstLandZone(iTMDTeam, tTMDZoneTeamData[AiBotMap.reftUnitsWantingTMD], true)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordTMLAndTMDForUnitJustBuilt(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordTMLAndTMDForUnitJustBuilt'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local oTMDBrain = oUnit:GetAIBrain()
    local iTMDTeam = oTMDBrain.AiBotTeam
    local tNearbyTMD = oTMDBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oUnit:GetPosition(), iTMLMissileRange + 2, 'Ally')

    for iTMLTeam = 1, AiBotTeam.iTotalTeamCount do
        --Get all TML in range of this TMD
        if not(iTMDTeam == iTMLTeam) then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                local oTMLBrain
                for iBrain, oBrain in AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                    oTMLBrain = oBrain
                    break
                end
                local tTeamNearbyTML = oTMLBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTML, oUnit:GetPosition(), iTMLMissileRange + 2, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of TML in TML missile range of this unit empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamNearbyTML))..'; iTMLMissileRange='..iTMLMissileRange..'; Unit position='..repru(oUnit:GetPosition())..'; oTMLBrain='..oTMLBrain.Nickname) end
                if AiBotUtilities.IsTableEmpty(tTeamNearbyTML) == false then
                    for iTML, oTML in tTeamNearbyTML do
                        RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oTML, tNearbyTMD) --This will do a distance check from the unit to the TMD
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordTMLAndTMDForEnemyUnitTargetJustDetected(oUnit, iTMLTeam)
    --Intended if an AiBot TML owner detects an enemy target
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordTMLAndTMDForEnemyUnitTargetJustDetected'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local oTMDBrain = oUnit:GetAIBrain()
    local tNearbyTMD = oTMDBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oUnit:GetPosition(), iTMLMissileRange + 2, 'Ally')

    if oUnit:GetFractionComplete() < 1 then
        if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
            if not(oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam]) then oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam] = {} end
            oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam][iTMLTeam] = true
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Detected unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTMLTeam='..iTMLTeam..'; Is table of active brains empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]))..'; Unit fraction complete='..oUnit:GetFractionComplete()..'; TimeOfGame='..GetGameTimeSeconds()) end

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
        local oTMLBrain
        for iBrain, oBrain in AiBotTeam.tTeamData[iTMLTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
            oTMLBrain = oBrain
            break
        end
        local tTeamNearbyTML = oTMLBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTML, oUnit:GetPosition(), iTMLMissileRange + 2, 'Ally')
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of TML in missile range of this unit empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamNearbyTML))..'; iTMLMissileRange='..iTMLMissileRange..'; Unit position='..repru(oUnit:GetPosition())..'; oTMLBrain.Nickname='..oTMLBrain.Nickname) end
        if AiBotUtilities.IsTableEmpty(tTeamNearbyTML) == false then --NOTE: If TML is firing from a cliff (big height dif) then it might not detect a unit that appears within its range, assuming due to targeting of units not being straightline ignoring height, but also factoring in height difs, with getunitsaroundpoint appearing to factor this in as well
            for iTML, oTML in tTeamNearbyTML do
                if bDebugMessages == true then LOG(sFunctionRef..': Are in range of oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..'; will record if is protected by TMD') end
                RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oTML, tNearbyTMD) --This will do a distance check from the unit to the TMD
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function IsTMDProtectingUnitFromTML(oTMD, oUnit, oTML, iOptionalBuildingSize, tTMLPositionOverride)
    --Dont need to have oTML existing if use tTMLPositionOverride, so e.g. can use for planning if a TML built at a certain position will be able to hit targets
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsTMDProtectingUnitFromTML'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, considering for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..', oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' owned by '..oTMD:GetAIBrain().Nickname..'; oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..' owned by '..oTML:GetAIBrain().Nickname..'; Distance between TMD and unit='..AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oUnit:GetPosition())) end
    if EntityCategoryContains(categories.AEON, oTMD.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oUnit:GetPosition()) > 120 then
        if bDebugMessages == true then LOG(sFunctionRef..': Aeon TMD that is so far away we wouldnt expect it to intercept TML missiles evne if it appears (ignoring height) to be able to intercept') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    end

    local iBuildingSize = iOptionalBuildingSize
    if not(iBuildingSize) then iBuildingSize = AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) end
    local iUnitToTMD = AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oUnit:GetPosition())
    if not(oTMD[AiBotUnitInfo.refiMissileDefenceRange]) then AiBotUnitInfo.RecordUnitRange(oTMD) end
    local iTMDRange = (oTMD[AiBotUnitInfo.refiMissileDefenceRange] or 12.5)


    if EntityCategoryContains(categories.AEON, oTMD.UnitId) then iTMDRange = iTMDRange + 0.5 end --to be prudent, may not be required as when made change (v169) there was a separate TMD issue (below reduction for building size) that was likely causing the issue of incorrectly thinking TMD didnt cover a target
    --Reduce range based on building size if we are considering whether we should build TMD to protect a target, if our TMD is further away than the unit in question (meaning we are more likely to be behind the unit, such that enemy could more easily 'edge-TML' the unit)
    if oUnit:GetAIBrain().AiBotAI and oTML and not(oTML:GetAIBrain().AiBotAI) and AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oTML:GetPosition()) >= AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oTML:GetPosition()) then
        iTMDRange = iTMDRange - iBuildingSize
    end


    local iUnitToTML = AiBotUtilities.GetDistanceBetweenPositions(tTMLPositionOverride or oTML:GetPosition(), oUnit:GetPosition())
    local iTMDToTML = AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), tTMLPositionOverride or oTML:GetPosition())

    local iAngleTMLToUnit = AiBotUtilities.GetAngleFromAToB(tTMLPositionOverride or oTML:GetPosition(), oUnit:GetPosition())
    local iAngleTMLToTMD = AiBotUtilities.GetAngleFromAToB(tTMLPositionOverride or oTML:GetPosition(), oTMD:GetPosition())
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if TMD '..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' is able to block the TML '..(oTML.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTML) or 'nil')..' for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tTMLPositionOverride='..repru(tTMLPositionOverride)..'; iUnitToTMD='..iUnitToTMD..'; iTMDRange reduced by building size='..iTMDRange..'; TMD recorded range='..(oUnit[AiBotUnitInfo.refiMissileDefenceRange] or 'nil')..'; iUnitToTML='..iUnitToTML..'; iTMDToTML='..iTMDToTML..'; iAngleTMLToUnit='..iAngleTMLToUnit..'; iAngleTMLToTMD='..iAngleTMLToTMD..'; Is line result='..tostring(AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iUnitToTML, iTMDToTML, iUnitToTMD, iAngleTMLToUnit, iAngleTMLToTMD, iTMDRange))) end
    if AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iUnitToTML, iTMDToTML, iUnitToTMD, iAngleTMLToUnit, iAngleTMLToTMD, iTMDRange) then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false

end

function RecordThatTMDProtectsUnitFromTML(oTMD, oUnit, oTML)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordThatTMDProtectsUnitFromTML'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --If oTML is nil and oTMD is in range of oUnit then will record the TMD against the unit



    --TMD can block the TML
    local bAlreadyRecordedTMD = false
    if not(oUnit[reftTMDCoveringThisUnit]) then oUnit[reftTMDCoveringThisUnit] = {}
    else
        for iRecordedTMD, oRecordedTMD in oUnit[reftTMDCoveringThisUnit] do
            if oRecordedTMD == oTMD then bAlreadyRecordedTMD = true  break end
        end
    end
    if not(bAlreadyRecordedTMD) then
        table.insert(oUnit[reftTMDCoveringThisUnit], oTMD)
        if not(oTMD[reftUnitsCoveredByThisTMD]) then oTMD[reftUnitsCoveredByThisTMD] = {} end
        table.insert(oTMD[reftUnitsCoveredByThisTMD], oUnit)
        if bDebugMessages == true then LOG(sFunctionRef..': TMD '..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' owned by '..oTMD:GetAIBrain().Nickname..' with % complete='..oTMD:GetFractionComplete()..' recorded against oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' as covering it from TML '..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..' owned by '..oTML:GetAIBrain().Nickname) end
    end


    if oTML and AiBotUtilities.IsTableEmpty(oTML[reftUnprotectedUnitTargetsForThisTML]) == false then
        for iExistingUnit, oExistingUnit in oTML[reftUnprotectedUnitTargetsForThisTML] do
            if oExistingUnit == oUnit then
                if bDebugMessages == true then LOG(sFunctionRef..': This unit was previously recorded as an unprotected target, will remove') end
                table.remove(oTML[reftUnprotectedUnitTargetsForThisTML], iExistingUnit)
                break
            end
        end
    end

    if bDebugMessages == true then
        LOG(sFunctionRef..': End of code at time='..GetGameTimeSeconds()..'; will list out reftUnitsCoveredByThisTMD')
        if AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then
            for iRecordedTMD, oRecordedTMD in oUnit[reftTMDCoveringThisUnit] do
                LOG(sFunctionRef..': oRecordedTMD='..oRecordedTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedTMD))
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oTML, tTMDInRange, bOnlyIncludingSpecificTMD)
    --Updates the following variables: For TMD: reftUnitsCoveredByThisTMD; for TML: reftUnprotectedUnitTargetsForThisTML and reftUnitsInRangeOfThisTML; for units in range of TML: reftTMDCoveringThisUnit and reftTMLInRangeOfThisUnit
    --Assumes that oTML is in range of oUnit
    --bOnlyIncludingSpecificTMD - true if we are calling this function to just check a specific TMD (so we should be more careful about adding the unit as an unprotected target)

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordIfUnitIsProtectedFromTMLByTMD'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..'; is tTMDInRange empty='..tostring(AiBotUtilities.IsTableEmpty(tTMDInRange))..'; Time='..GetGameTimeSeconds()) end

    local iTMDInitiallyRecorded = 0
    if AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then iTMDInitiallyRecorded = table.getn(oUnit[reftTMDCoveringThisUnit]) end

    if not(oUnit.UnitId) and not(AiBotUtilities.bFAFActive) and oUnit then --LOUD compatibility
        if not(oUnit.EntityId) then oUnit.EntityId = oUnit:GetEntityId() end
        oUnit.UnitId = oUnit:GetBlueprint().BlueprintId
    end

    local bTMLAlreadyRecordedAgainstUnit = false
    local bUpdateZoneForUnitsWantingTMD = false
    if AiBotUtilities.IsTableEmpty(oUnit[reftTMLInRangeOfThisUnit]) == false then
        for iExistingTML, oExistingTML in oUnit[reftTMLInRangeOfThisUnit] do
            if oExistingTML == oTML then
                bTMLAlreadyRecordedAgainstUnit = true
                break
            end
        end
    end
    if not(bTMLAlreadyRecordedAgainstUnit) then
        if not(oUnit[reftTMLInRangeOfThisUnit]) then oUnit[reftTMLInRangeOfThisUnit] = {} end
        table.insert(oUnit[reftTMLInRangeOfThisUnit], oTML)
    end
    local bIsBlockedByTMD
    if bDebugMessages == true then LOG(sFunctionRef..': Near start at time '..GetGameTimeSeconds()..'; Considering if oUnit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; is proitected from oTML '..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..' owned by player '..oTML:GetAIBrain().Nickname..' by any of the TMD noted, is table of TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tTMDInRange))..'; First TMD='..(tTMDInRange[1].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tTMDInRange[1]) or 'nil')) end
    local iBuildingSize = AiBotUnitInfo.GetBuildingSize(oUnit.UnitId)
    if AiBotUtilities.IsTableEmpty(tTMDInRange) == false then
        --[[local iUnitToTMD
        local iTMDRange
        local iUnitToTML, iTMDToTML, iAngleTMLToUnit, iAngleTMLToTMD--]]
        local bAlreadyRecordedTMD



        for iTMD, oTMD in tTMDInRange do
            if IsTMDProtectingUnitFromTML(oTMD, oUnit, oTML, iBuildingSize) then
                RecordThatTMDProtectsUnitFromTML(oTMD, oUnit, oTML)
                bIsBlockedByTMD = true
                if bDebugMessages == true then LOG(sFunctionRef..': oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' can block the TML so will record it') end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': TMD '..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' doesnt block the TML') end
            end
        end
    end
    if not(bIsBlockedByTMD) then
        --None of the TMD are blocking the TML from hitting this unit; check if there are any other valid TMD that are covering this unit
        if AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then
            for iTMD, oTMD in oUnit[reftTMDCoveringThisUnit] do
                if AiBotUnitInfo.IsUnitValid(oTMD) then
                    --Have we considered this TMD alreayd?
                    local bConsideredAbove = false
                    for iExistingTMD, oExistingTMD in tTMDInRange do
                        if oExistingTMD == oTMD then
                            bConsideredAbove = true
                            break
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': This unit has TMD recorded as covering it, oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..'; bConsideredAbove='..tostring(bConsideredAbove)..'; Does the TMD cover the unit from this TML='..tostring(IsTMDProtectingUnitFromTML(oTMD, oUnit, oTML, iBuildingSize))..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; TML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..' owned by brain '..oTML:GetAIBrain().Nickname) end
                    if not(bConsideredAbove) then
                        if IsTMDProtectingUnitFromTML(oTMD, oUnit, oTML, iBuildingSize) then
                            bIsBlockedByTMD = true
                            RecordThatTMDProtectsUnitFromTML(oTMD, oUnit, oTML)
                            if bDebugMessages == true then LOG(sFunctionRef..': Recorded that this TMD is protecting oUnit from oTML') end
                            break
                        end
                    end
                end
            end
        end
    end
    if not(bIsBlockedByTMD) then
        local bAlreadyIncluded = false
        if not(oTML[reftUnprotectedUnitTargetsForThisTML]) or AiBotUtilities.IsTableEmpty(oTML[reftUnprotectedUnitTargetsForThisTML]) then
            oTML[reftUnprotectedUnitTargetsForThisTML] = {}

        else
            for iRecordedUnit, oRecordedUnit in oTML[reftUnprotectedUnitTargetsForThisTML] do
                if oRecordedUnit == oUnit then
                    bAlreadyIncluded = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Will record this unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' against table of unprotected units for TML as it isnt blocked by any of the TMD, bAlreadyIncluded='..tostring(bAlreadyIncluded or false)) end
        if not(bAlreadyIncluded) then
            --Check if this is unprotected by other TMD as well, if we called this from just a single TMD event
            local bIsDefinitelyUnprotected = true
            if bOnlyIncludingSpecificTMD and AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then
                for iTMD, oTMD in oUnit[reftTMDCoveringThisUnit] do
                    if not(oTMD == tTMDInRange[1]) and AiBotUnitInfo.IsUnitValid(oTMD) then
                        bIsDefinitelyUnprotected = false
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bIsDefinitelyUnprotected after checking if we have other TMD likely covering this unit='..tostring(bIsDefinitelyUnprotected)) end
            if bIsDefinitelyUnprotected then
                table.insert(oTML[reftUnprotectedUnitTargetsForThisTML], oUnit)
            end
            --Below function will factor in number of enemy TML vs number of friendly TMD so less that can go wrong if re-run when just called this for a single TMD
            if oUnit:GetAIBrain().AiBotAI then
                RecordIfUnitsWantTMDCoverageAgainstLandZone(oUnit:GetAIBrain().AiBotTeam, { oUnit }, true)
            end
        end
    else
        --is covered by TMD, make sure not listed in reftUnprotectedUnitTargetsForThisTML, and reassess if we want the unit flagged as wanting TMD
        if bDebugMessages == true then LOG(sFunctionRef..': Unit is covered by TMD so will make sure not listed as an unprotected target against the TML, is table of unrptoected targets empty='..tostring(AiBotUtilities.IsTableEmpty(oTML[reftUnprotectedUnitTargetsForThisTML]))) end
        bUpdateZoneForUnitsWantingTMD = true
        --(we shouldave already updated to reflect no longer have an unprotected unit above)
    end
    --Either way record unit as being in range of TML
    local bAlreadyIncluded = false
    if not(oTML[reftUnitsInRangeOfThisTML]) or AiBotUtilities.IsTableEmpty(oTML[reftUnitsInRangeOfThisTML]) then
        oTML[reftUnitsInRangeOfThisTML] = {}

    else
        for iRecordedUnit, oRecordedUnit in oTML[reftUnitsInRangeOfThisTML] do
            if oRecordedUnit == oUnit then
                bAlreadyIncluded = true
                break
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Will record this unit against the TML as being in range, unless already included, bAlreadyIncluded='..tostring(bAlreadyIncluded)..'; bUpdateZoneForUnitsWantingTMD='..tostring(bUpdateZoneForUnitsWantingTMD)) end
    if not(bAlreadyIncluded) then
        table.insert(oTML[reftUnitsInRangeOfThisTML], oUnit)
    end
    local iTMDRecordedAfterCode = 0
    local bForceUpdateOfIfWantTMD = not(bAlreadyIncluded)
    if AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then iTMDRecordedAfterCode = table.getn(oUnit[reftTMDCoveringThisUnit]) end
    if not(iTMDRecordedAfterCode == iTMDInitiallyRecorded) and ((oUnit[refbUnitWantsMoreTMD] and iTMDRecordedAfterCode > iTMDInitiallyRecorded) or not(oUnit[refbUnitWantsMoreTMD]) and iTMDRecordedAfterCode < iTMDInitiallyRecorded) then
        bForceUpdateOfIfWantTMD = true
        bUpdateZoneForUnitsWantingTMD = true --redundancy
    end
    if bDebugMessages == true then LOG(sFunctionRef..': bForceUpdateOfIfWantTMD='..tostring(bForceUpdateOfIfWantTMD)..'; iTMDInitiallyRecorded='..iTMDInitiallyRecorded..'; iTMDRecordedAfterCode='..iTMDRecordedAfterCode..'; bUpdateZoneForUnitsWantingTMD='..tostring(bUpdateZoneForUnitsWantingTMD)) end

    if bUpdateZoneForUnitsWantingTMD and oUnit:GetAIBrain().AiBotAI then
        RecordIfUnitsWantTMDCoverageAgainstLandZone(oUnit:GetAIBrain().AiBotTeam, { oUnit }, bForceUpdateOfIfWantTMD)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AlliedTMDFirstRecorded(iTeam, oTMD)
    --Have just recorded an allied TMD for a land zone - want to record all units within a long range that want protecting from TML if this provides protection from an enemy TML
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AlliedTMDFirstRecorded'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': oTMD '..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' has been identified, will reecord if are any enemy TML, is table of enemy TML empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]))) end

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]) == false then
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            if aiBrain then
                local tUnitsToProtect = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryProtectFromTML, oTMD:GetPosition(), iTMLMissileRange + 20, 'Ally')
                if AiBotUtilities.IsTableEmpty(tUnitsToProtect) == false then
                    local tOnLandUnits = {}
                    for iUnit, oUnit in tUnitsToProtect do
                        if not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                            table.insert(tOnLandUnits, oUnit)
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tOnLandUnits) == false then
                        UpdateTMDCoverageOfUnits(iTeam,{ oTMD }, tOnLandUnits)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TMLDied(oTML)
    --Updates tracking of the TML including for any units that had it recorded as being in range of them, and then checks if those units want TMD coverage (as there may no longer be any TML to protect from)

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TMLDied'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': TML has just died, is the table of units in range of it empty='..tostring(AiBotUtilities.IsTableEmpty(oTML[reftUnitsInRangeOfThisTML]))) end
    local iTMLTeam = oTML:GetAIBrain().AiBotTeam
    --Update each team that was tracking this
    for iTeam = 1, AiBotTeam.iTotalTeamCount do
        if not(iTMLTeam == iTeam) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]) == false then
            for iRecordedTML, oRecordedTML in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML] do
                if oRecordedTML == oTML then
                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML], iRecordedTML)
                end
            end
        end
    end
    --Update each unit that was tracking this:
    if AiBotUtilities.IsTableEmpty(oTML[reftUnitsInRangeOfThisTML]) == false then
        local tUnitsToUpdateByTeam = {}
        local iCurTeam
        for iUnit, oUnit in oTML[reftUnitsInRangeOfThisTML] do
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                for iExistingTML, oExistingTML in oUnit[reftTMLInRangeOfThisUnit] do
                    if oExistingTML == oTML then
                        iCurTeam = oUnit:GetAIBrain().AiBotTeam
                        if not(tUnitsToUpdateByTeam[iCurTeam]) then tUnitsToUpdateByTeam[iCurTeam] = {} end
                        table.insert(tUnitsToUpdateByTeam[iCurTeam], oUnit)
                        table.remove(oUnit[reftTMLInRangeOfThisUnit], iExistingTML)
                        break
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnitsToUpdateByTeam) == false then
            for iTeam, tUnitList in tUnitsToUpdateByTeam do
                RecordIfUnitsWantTMDCoverageAgainstLandZone(iTeam, tUnitList, true)
            end
        end
    end
end
function TMDDied(oTMD)
    --Updates any units that were relying on oTMD for protection from TML, and reassesses if those units want more TMD now
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TMDDied'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': TMD has just died, is the table of units covered by this TMD empty='..tostring(AiBotUtilities.IsTableEmpty(oTMD[reftUnitsCoveredByThisTMD]))) end
    if AiBotUtilities.IsTableEmpty(oTMD[reftUnitsCoveredByThisTMD]) == false then
        local tUnitsToCheckIfWantTMDCoverageByTeam = {}
        local iCurTeam
        for iUnit, oUnit in oTMD[reftUnitsCoveredByThisTMD] do
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                for iRecordedTMD, oRecordedTMD in oUnit[reftTMDCoveringThisUnit] do
                    if oRecordedTMD == oTMD then
                        iCurTeam = oUnit:GetAIBrain().AiBotTeam
                        if not(tUnitsToCheckIfWantTMDCoverageByTeam[iCurTeam]) then tUnitsToCheckIfWantTMDCoverageByTeam[iCurTeam] = {} end
                        table.insert(tUnitsToCheckIfWantTMDCoverageByTeam[iCurTeam], oUnit)
                        table.remove(oUnit[reftTMDCoveringThisUnit], iRecordedTMD)
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnitsToCheckIfWantTMDCoverageByTeam) == false then
            for iTeam, tUnitList in tUnitsToCheckIfWantTMDCoverageByTeam do
                RecordIfUnitsWantTMDCoverageAgainstLandZone(iTeam, tUnitList, true)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateTMDCoverageOfUnits(iTeam, tTMD, tUnitsToUpdate)
    --Goes through each unit in tUnitsToUpdate, and records any TMD in tTMD that can protect it from all TML in range of the unit
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateTMDCoverageOfUnits'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tAllEnemyTML = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]
    if AiBotUtilities.IsTableEmpty(tAllEnemyTML) == false then --redundancy
        local bTMDCoversFromAllTML
        local bCanBlockCurTML
        local bAlreadyRecordedTMD = false
        local bAlreadyRecordedAsWantingTMD
        local iUnitToTMD, iUnitToTML, iTMDToTML, iTMDRange, iBuildingSize, iAngleTMLToTMD, iAngleTMLToUnit
        local iUnitPlateau, iUnitLandZone
        for iUnit, oUnit in tUnitsToUpdate do
            if AiBotUtilities.IsTableEmpty(oUnit[reftTMLInRangeOfThisUnit]) == false then
                iBuildingSize = AiBotUnitInfo.GetBuildingSize(oUnit.UnitId)
                for iTMD, oTMD in tTMD do
                    bTMDCoversFromAllTML = true
                    iUnitToTMD = AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oUnit:GetPosition())
                    if not(oTMD[AiBotUnitInfo.refiMissileDefenceRange]) then AiBotUnitInfo.RecordUnitRange(oTMD) end
                    iTMDRange = (oTMD[AiBotUnitInfo.refiMissileDefenceRange] or 12.5)

                    --Reduce TMDRange to the effective range
                    iTMDRange = iTMDRange - iBuildingSize

                    for iTML, oTML in oUnit[reftTMLInRangeOfThisUnit] do
                        bCanBlockCurTML = false
                        iUnitToTML = AiBotUtilities.GetDistanceBetweenPositions(oTML:GetPosition(), oUnit:GetPosition())
                        iTMDToTML = AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oTML:GetPosition())

                        iAngleTMLToUnit = AiBotUtilities.GetAngleFromAToB(oTML:GetPosition(), oUnit:GetPosition())
                        iAngleTMLToTMD = AiBotUtilities.GetAngleFromAToB(oTML:GetPosition(), oTMD:GetPosition())
                        if AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iUnitToTML, iTMDToTML, iUnitToTMD, iAngleTMLToUnit, iAngleTMLToTMD, iTMDRange) then
                            --TMD can block the TML
                            if bDebugMessages == true then LOG(sFunctionRef..': oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..' can block the TML so will record it') end
                            bCanBlockCurTML = true
                        end
                        if not(bCanBlockCurTML) then
                            bTMDCoversFromAllTML = false
                            break
                        end
                    end
                    if bTMDCoversFromAllTML then
                        if not(oUnit[reftTMDCoveringThisUnit]) then oUnit[reftTMDCoveringThisUnit] = {}
                        else
                            for iRecordedTMD, oRecordedTMD in oUnit[reftTMDCoveringThisUnit] do
                                if oRecordedTMD == oTMD then bAlreadyRecordedTMD = true  break end
                            end
                        end
                        if not(bAlreadyRecordedTMD) then
                            table.insert(oUnit[reftTMDCoveringThisUnit], oTMD)
                        end
                    end
                end
            end
        end
        RecordIfUnitsWantTMDCoverageAgainstLandZone(iTeam, tUnitsToUpdate, true)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordIfUnitsWantTMDCoverageAgainstLandZone(iTeam, tUnits, bCalledDueToTMLOrTMDEvent)
    --Cycles through each unit in tUnits and if it has less TMD covering it than TML in range, makes sure it is reecorded in its land zone as one of the units wanting TMD
    --If it has sufficient TMD coverage, then instead makes sure it isnt recorded in its land zone as one of the units wanting TMD
    --Relies on otherfunctions for accurately recording TML in range of it and TMD giving coverage
    --bCalledDueToTMLOrTMDEvent - if this is true, then will recheck if we want more TMD/how many we have in range even if we have recently checked for this

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordIfUnitsWantTMDCoverageAgainstLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTMDInRange, iUnitPlateau, iUnitLandZone

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; size of tUnits='..table.getn(tUnits)..'; iTeam='..iTeam..'; bCalledDueToTMLOrTMDEvent='..tostring(bCalledDueToTMLOrTMDEvent or false)) end
    local iVariableDelayInSeconds = math.max(10, AiBotLand.iTicksPerLandCycle * 0.25)
    for iUnit, oUnit in tUnits do
        if bCalledDueToTMLOrTMDEvent or not(oUnit[refbRecentlyCheckedTMDOrTML]) then
            oUnit[refbRecentlyCheckedTMDOrTML] = true
            AiBotUtilities.DelayChangeVariable(oUnit, refbRecentlyCheckedTMDOrTML, false, iVariableDelayInSeconds)
            --Does the unit need TMD coverage?
            iTMDInRange = 0
            if AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then
                --Treat Aeon as having twice the TMD power as other factions
                for iRecordedTMD, oRecordedTMD in oUnit[reftTMDCoveringThisUnit] do
                    if AiBotUnitInfo.IsUnitValid(oRecordedTMD) then
                        if EntityCategoryContains(categories.AEON, oRecordedTMD.UnitId) then
                            iTMDInRange = iTMDInRange + 2
                        else
                            iTMDInRange = iTMDInRange + 1
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considierng unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with fraction complete='..oUnit:GetFractionComplete()..' owned by '..oUnit:GetAIBrain().Nickname..'; iTMDInRange='..iTMDInRange..'; TML in range='..table.getn((oUnit[reftTMLInRangeOfThisUnit] or {}))..'; oUnit[refbUnitWantsMoreTMD]='..tostring(oUnit[refbUnitWantsMoreTMD] or false)..'; Is oUnit[reftTMDCoveringThisUnit] empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]))) end
            local iTMLValueInRangeOfUnit = 0
            if AiBotUtilities.IsTableEmpty(oUnit[reftTMLInRangeOfThisUnit]) == false then
                for iRecordedTML, oRecordedTML in oUnit[reftTMLInRangeOfThisUnit] do
                    if AiBotUnitInfo.IsUnitValid(oRecordedTML) then
                        --UEF ACU with billy nuke upgrade - increase value
                        if EntityCategoryContains(categories.COMMAND * categories.UEF, oRecordedTML.UnitId) and oRecordedTML.HasEnhancement and oRecordedTML:HasEnhancement('TacticalNukeMissile') then
                            if bDebugMessages == true then LOG(sFunctionRef..': ENemy unit owned by brain '..oRecordedTML:GetAIBrain().Nickname..' has a billy nuke') end
                            iTMLValueInRangeOfUnit = iTMLValueInRangeOfUnit + 4
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMissileShip * categories.AEON, oRecordedTML.UnitId) then
                            --Aeon missile ship
                            iTMLValueInRangeOfUnit = iTMLValueInRangeOfUnit + 6
                            --Cruisers
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMissileShip, oRecordedTML.UnitId) then
                            iTMLValueInRangeOfUnit = iTMLValueInRangeOfUnit + 1.3
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMML * categories.TECH2, oRecordedTML.UnitId) then
                            iTMLValueInRangeOfUnit = iTMLValueInRangeOfUnit + 0.75
                        elseif EntityCategoryContains(categories.EXPERIMENTAL, oRecordedTML.UnitId) then
                            if oRecordedTML.UnitId == 'uese0001' then
                                iTMLValueInRangeOfUnit = 5
                            else
                                iTMLValueInRangeOfUnit = 2.5
                            end
                        else
                            iTMLValueInRangeOfUnit = iTMLValueInRangeOfUnit + 1
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want more TMD for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTMDInRange='..iTMDInRange..'; iTMLValueInRangeOfUnit='..iTMLValueInRangeOfUnit..'; oUnit[refiMinTMDWantedForUnit]='..(oUnit[refiMinTMDWantedForUnit] or 'nil'))  end
            if ((iTMDInRange < iTMLValueInRangeOfUnit) or (oUnit[refiMinTMDWantedForUnit] and iTMDInRange < oUnit[refiMinTMDWantedForUnit])) and not(oUnit[refbNoNearbyTMDBuildLocations]) then
                if not(oUnit[refbUnitWantsMoreTMD]) then --redundancy (i.e. will ahve already called below if unit is already flagged as wanting more TMD)
                    iUnitPlateau, iUnitLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Want TMD for this unit, iUnitPlateau='..(iUnitPlateau or 'nil')..'; iUnitLandZone='..(iUnitLandZone or 'nil')..'; Unit owner='..oUnit:GetAIBrain().Nickname..'; iTMDInRange='..iTMDInRange..'; oUnit[refiMinTMDWantedForUnit]='..(oUnit[refiMinTMDWantedForUnit] or 'nil')) end
                    if iUnitLandZone > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iUnitPlateau][AiBotMap.subrefPlateauLandZones][iUnitLandZone][AiBotMap.subrefLZTeamData][iTeam]
                        table.insert(tLZTeamData[AiBotMap.reftUnitsWantingTMD], oUnit)
                    end
                    oUnit[refbUnitWantsMoreTMD] = true
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Have enough TMD covering this unit, unit wants more TMD flag='..tostring(oUnit[refbUnitWantsMoreTMD] or false)) end
                if oUnit[refbUnitWantsMoreTMD] then --i.e. unit previously was flagged as needing more TMD (but now it doesnt)
                    --Remove this unit from the land zone list of units wanting TMD
                    iUnitPlateau, iUnitLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                    if iUnitLandZone > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iUnitPlateau][AiBotMap.subrefPlateauLandZones][iUnitLandZone][AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont want TMD for this unit, iUnitPlateau='..(iUnitPlateau or 'nil')..'; iUnitLandZone='..(iUnitLandZone or 'nil')..'; is table of LZ units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))) end
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false then
                            --Remove htis unit from the list of units wanting TMD
                            for iRecordedUnit, oRecordedUnit in tLZTeamData[AiBotMap.reftUnitsWantingTMD] do
                                if bDebugMessages == true then LOG(sFunctionRef..': oRecordedUnit='..oRecordedUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedUnit)) end
                                if oRecordedUnit == oUnit then
                                    table.remove(tLZTeamData[AiBotMap.reftUnitsWantingTMD], iRecordedUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have removed from units wanting TMD in zone, is table of units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))) end
                                    break
                                end
                            end
                        end
                    end
                    oUnit[refbUnitWantsMoreTMD] = false
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateLZUnitsWantingTMDForUnitDeath(oUnit)
    --Updates any units currently recorded as wanting TMD to see if htey still want TMD based on TMD coverage
    local iUnitPlateau, iUnitLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
    if iUnitLandZone > 0 then
        local iTeam = oUnit:GetAIBrain().AiBotAITeam
        local tLZTeamData = AiBotMap.tAllPlateaus[iUnitPlateau][AiBotMap.subrefPlateauLandZones][iUnitLandZone][AiBotMap.subrefLZTeamData][iTeam]
        --Remove all dead units from the table (not just this one) as extra redundancy
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false then
            local iRevisedIndex = 1
            local iTableSize = table.getn(tLZTeamData[AiBotMap.reftUnitsWantingTMD])

            for iOrigIndex=1, iTableSize do
                if tLZTeamData[AiBotMap.reftUnitsWantingTMD][iOrigIndex] then
                    if AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.reftUnitsWantingTMD][iOrigIndex]) then --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                        --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                        if (iOrigIndex ~= iRevisedIndex) then
                            tLZTeamData[AiBotMap.reftUnitsWantingTMD][iRevisedIndex] = tLZTeamData[AiBotMap.reftUnitsWantingTMD][iOrigIndex]
                            tLZTeamData[AiBotMap.reftUnitsWantingTMD][iOrigIndex] = nil
                        end
                        iRevisedIndex = iRevisedIndex + 1 --i.e. this will be the position of where the next value that we keep will be located
                    else
                        tLZTeamData[AiBotMap.reftUnitsWantingTMD][iOrigIndex] = nil
                    end
                end
            end
            if iRevisedIndex < iTableSize then
                --table.setn(tLZTeamData[AiBotMap.reftUnitsWantingTMD], iRevisedIndex - 1)
                for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                    table.remove(tLZTeamData[AiBotMap.reftUnitsWantingTMD], iRemovalEntry)
                end
            end
        end
    end
    oUnit[refbUnitWantsMoreTMD] = false --redundancy
end

function GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iOptionalLandZone, bReturnTMLCountAsWell, iOptionalCategoryWanted, bGetClosestUnitToOurBase, oOptionalUnitToAvoid)
    --Gets the unit closest to the nearest enemy base that wants TMD; also refreshes the table for any dead units
    --bGetClosestUnitToOurBase - if this is true, then instead of nearest enemy base will get closest to our base
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetUnitWantingTMD'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Cap on number of TMD to prvent massiveo verbuilding - dont have more than 10 in a LZ unless enemy has lots of TML
    local tExistingTMD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTMD, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
    local iExistingValidTMD = 0
    local iEnemyTotalTMLCount
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of existing TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tExistingTMD))..'; iOptionalLandZone='..(iOptionalLandZone or 'nil')..'; oOptionalUnitToAvoid='..(oOptionalUnitToAvoid.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalUnitToAvoid) or 'nil')..'; Time='..GetGameTimeSeconds()) end

    if AiBotUtilities.IsTableEmpty(tExistingTMD) == false then
        iExistingValidTMD = table.getn(tExistingTMD)

        --Max TMD limit - no. of mexes in the zone * 0.5 if lower; also higher TMD if we have Aeon TMD
        local iTMDLimit = math.min(30, math.max(10, (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3]) * 0.5, tLZTeamData[AiBotMap.subrefLZSValue] / 5000))
        if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then iTMDLimit = math.min(iTMDLimit, math.max(4, tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 2 + tLZTeamData[AiBotMap.subrefMexCountByTech][2], tLZTeamData[AiBotMap.subrefLZSValue] / 5000)) end
        if tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] <= 40 then
            iTMDLimit = iTMDLimit + 2
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iExistingValidTMD='..iExistingValidTMD..'; iTMDLimit='..iTMDLimit..'; tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile]='..(tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] or 'nil')) end
        if iExistingValidTMD >= iTMDLimit or bReturnTMLCountAsWell then
            iEnemyTotalTMLCount = 0
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]) == false then
                iEnemyTotalTMLCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML])
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyTotalTMLCount='..iEnemyTotalTMLCount) end
            if iExistingValidTMD > math.max(15, iTMDLimit + (iEnemyTotalTMLCount - 1) * 3) then
                --Too much TMD already, clear any units wanting TMD; send error message if we have loads of TMD
                if iExistingValidTMD >= 10 then
                    AiBotUtilities.ErrorHandler('Have at least '..iExistingValidTMD..' TMD in land zone so wont build any more TMD, risk we may be overbuilding TMD, will clear entries', true)
                end
                tLZTeamData[AiBotMap.reftUnitsWantingTMD] = {}
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return
            end
        end
    end

    local iUnitsWantingTMD = table.getn(tLZTeamData[AiBotMap.reftUnitsWantingTMD])
    local iClosestDist = 10000
    local iCurDist
    local oClosestUnit
    local tBaseForDistanceCheck
    if bGetClosestUnitToOurBase then tBaseForDistanceCheck = tLZTeamData[AiBotMap.reftClosestFriendlyBase]
    else tBaseForDistanceCheck = tLZTeamData[AiBotMap.reftClosestEnemyBase]
    end
    local bInRangeOfT2Arti
    if bDebugMessages == true then LOG(sFunctionRef..': Will cycle through iUnitsWantingTMD, iUnitsWantingTMD='..iUnitsWantingTMD..'; is iOptionalCategoryWanted nil='..tostring(iOptionalCategoryWanted == nil)) end
    for iEntry = iUnitsWantingTMD, 1, -1 do
        if not(AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry])) then
            table.remove(tLZTeamData[AiBotMap.reftUnitsWantingTMD], iEntry)
        elseif (not(iOptionalCategoryWanted) or EntityCategoryContains(iOptionalCategoryWanted, tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry].UnitId)) then
            if not(oOptionalUnitToAvoid) or (oOptionalUnitToAvoid and not(oOptionalUnitToAvoid == tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry]) and AiBotUtilities.GetDistanceBetweenPositions(oOptionalUnitToAvoid:GetPosition(), tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry]:GetPosition()) >= 25) then
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tBaseForDistanceCheck, tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry]:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if unit '..tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry])..' is the closest, iCurDist='..iCurDist..'; iCLosestDist='..iClosestDist..'; refbUnitWantsMoreTMD='..tostring(tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry][refbUnitWantsMoreTMD])) end
                if iCurDist < iClosestDist then
                    --Check we arent trying to cover a unit that has enemy arti in range (as we will try and build TMD away from T2 arti)
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                        bInRangeOfT2Arti = false
                        for iArti, oArti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                            if not(oArti.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry]:GetPosition()) <= oArti[AiBotUnitInfo.refiCombatRange] + 2 then
                                bInRangeOfT2Arti = true
                                break
                            end
                        end
                    end
                    if bInRangeOfT2Arti then
                        if bDebugMessages == true then LOG(sFunctionRef..': Wont try building TMD afterall as enemy has t2 arti in range') end
                    else
                        iClosestDist = iCurDist
                        oClosestUnit = tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry]
                    end
                end

            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Unit wnating TMD, '..tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLZTeamData[AiBotMap.reftUnitsWantingTMD][iEntry])..', iEntry='..iEntry..' isnt the desired category')
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': If dont have a unit to cover with TMD and TMD has intercepted enemy missile recently then build TMD to cover TMD, oClosestUnit='..(oClosestUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit) or 'nil')..'; tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile]='..(tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] or 'nil')..'; iExistingValidTMD='..iExistingValidTMD) end
    if not(oClosestUnit) and tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] and iExistingValidTMD > 0 and iExistingValidTMD <= 10 and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] <= 60 then
        --Consider doubling up on TMD by having a TMD request TMD if it has fired recently
        local iCurLaunchers, iCurTMD
        for iTMD, oTMD in tExistingTMD do
            if oTMD[refiTimeTMDHitMissile] and GetGameTimeSeconds() - oTMD[refiTimeTMDHitMissile] <= 60 and AiBotConditions.IsTableOfUnitsStillValid(oTMD[toLaunchersIntercepted]) then

                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tBaseForDistanceCheck, oTMD:GetPosition())
                if iCurDist < iClosestDist then
                    --Do we have enough TMD already covering this unit?
                    iCurLaunchers = table.getn(oTMD[toLaunchersIntercepted])
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurLaunchers='..iCurLaunchers..'; oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..'; Is table of TMD covering this unit empty='..tostring(AiBotUtilities.IsTableEmpty(oTMD[reftTMDCoveringThisUnit]))) end
                    if iCurLaunchers > 1 then
                        iCurTMD = 1
                        --v290 - tried moving the below line to the AiBotEvent that adds the TML to table of intercepted TML to see if it helps with optimisation
                        --for iLauncher, oLauncher in oTMD[toLaunchersIntercepted] do
                            --RecordUnitsInRangeOfTMLAndAnyTMDProtection(oLauncher, { oTMD }, false)
                        --end
                        if AiBotUtilities.IsTableEmpty(oTMD[reftTMDCoveringThisUnit]) then iCurTMD = 1
                        else iCurTMD = table.getn(oTMD[reftTMDCoveringThisUnit]) end
                        if iCurLaunchers > iCurTMD - 1 or (iCurLaunchers >= 4 and iCurLaunchers > math.min(iCurTMD - 2, iCurTMD * 0.6)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurTMD='..iCurTMD..' so want to build more to cover this TMD and stop it being overwhelmed') end
                            iClosestDist = iCurDist
                            oClosestUnit = oTMD
                        end

                    end
                end
            end
        end
    end

    if bDebugMessages == true then
        LOG(sFunctionRef..': End of code, oClosestUnit='..(oClosestUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit) or 'nil'))
        if AiBotUnitInfo.IsUnitValid(oClosestUnit) then
            LOG(sFunctionRef..': Closest unit % complete='..oClosestUnit:GetFractionComplete()..'; Is table of TML in range of this unit empty='..tostring(AiBotUtilities.IsTableEmpty(oClosestUnit[reftTMLInRangeOfThisUnit]))..'; Is reftTMDCoveringThisUnit empty='..tostring(AiBotUtilities.IsTableEmpty(oClosestUnit[reftTMDCoveringThisUnit])))
            if AiBotUtilities.IsTableEmpty(oClosestUnit[reftTMDCoveringThisUnit]) == false then
                LOG(sFunctionRef..': Size of reftTMDCoveringThisUnit='..table.getn(oClosestUnit[reftTMDCoveringThisUnit]))
            end
        end
        if AiBotUtilities.IsTableEmpty(oClosestUnit[reftTMLInRangeOfThisUnit]) == false then
            for iTML, oTML in oClosestUnit[reftTMLInRangeOfThisUnit] do
                LOG(sFunctionRef..': oTML in range='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..'; Dist='..AiBotUtilities.GetDistanceBetweenPositions(oTML:GetPosition(), oClosestUnit:GetPosition())..'; TML range='..(oTML[AiBotUnitInfo.refiIndirectRange] or oTML[AiBotUnitInfo.refiManualRange] or 'nil'))
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bReturnTMLCountAsWell then return oClosestUnit, iEnemyTotalTMLCount
    else
        return oClosestUnit
    end
end


function RecordPriorityShields(iTeam, tLZTeamData)
    --Records shields that want to ahve engineers assisting
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordPriorityShields'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOfLastShieldPriorityRefresh] or -100) >= 10 then
        tLZTeamData[AiBotMap.refiTimeOfLastShieldPriorityRefresh] = GetGameTimeSeconds()
        local tShieldsToAssist = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        --First clear any engineers assigned to shields that arent listed as a priority shield from the last update
        if bDebugMessages == true then LOG(sFunctionRef..': WIll refresh list of shields. Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tShieldsToAssist))..'; do we already have any priority shields when when last ran this? is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]))..'; Time='..GetGameTimeSeconds()) end
        if AiBotUtilities.IsTableEmpty(tShieldsToAssist) == false then
            local tTemporaryPriorityShields = {}
            if bDebugMessages == true then LOG(sFunctionRef..': Is reftPriorityShieldsToAssist empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]))) end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]) == false then
                for iShield, oShield in tShieldsToAssist do
                    if AiBotUtilities.IsTableEmpty(oShield[AiBotUnitInfo.reftoUnitsAssistingThis]) == false and not(oShield[refbPriorityShield]) then
                        local bClearShield = true
                        if oShield[refbRemoveShieldFromPriorityTableWhenFullHealth] then
                            bClearShield = false
                            local iCurShieldHealth, iCurShieldMaxHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                            if iCurShieldHealth / iCurShieldMaxHealth >= 0.99 then
                                bClearShield = true
                            end
                            if not(bClearShield) then
                                table.insert(tTemporaryPriorityShields, oShield)
                            else
                                oShield[refbRemoveShieldFromPriorityTableWhenFullHealth] = nil
                            end
                        end
                        if bClearShield then
                            --Shield wasnt a priority shield in the last cycle but has engineers assigned to assist it - will clear these engineers
                            local tEngineersToClear = {}
                            for iEngi, oEngi in oShield[AiBotUnitInfo.reftoUnitsAssistingThis] do
                                table.insert(tEngineersToClear, oEngi)
                            end
                            for iAssistingEngineer, oAssistingEngineer in tEngineersToClear do
                                if AiBotUnitInfo.IsUnitValid(oAssistingEngineer) then AiBotOrders.IssueTrackedClearCommands(oAssistingEngineer) end
                            end
                            oShield[AiBotUnitInfo.reftoUnitsAssistingThis] = nil
                        end
                    end
                end
            end

            tLZTeamData[AiBotMap.reftPriorityShieldsToAssist] = {}
            if AiBotUtilities.IsTableEmpty(tTemporaryPriorityShields) == false then
                for iShield, oShield in tTemporaryPriorityShields do
                    table.insert(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist], oShield)
                end
            end
            local iTotalUnitMassCoverage
            local iCurMassValue
            local bConsiderRecentlyDamagedShields = false
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 300 then bConsiderRecentlyDamagedShields = true end
            for iShield, oShield in tShieldsToAssist do
                iTotalUnitMassCoverage = 0
                if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; size of table of units nearby='..table.getn(oShield[reftoUnitsCoveredByShield])) end
                if AiBotConditions.IsTableOfUnitsStillValid(oShield[reftoUnitsCoveredByShield]) and not(oShield[reftArtiTemplateRefs]) and not(oShield[refbRemoveShieldFromPriorityTableWhenFullHealth]) then
                    --Only flag a shield for assistance if its health is <80%, unless it is covering a game-ender
                    local iCurShieldHealth, iMaxShieldHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                    local bCoveringGameEnder = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Shield health='..iCurShieldHealth..'; Max health='..iMaxShieldHealth) end
                    if iCurShieldHealth > 0 and (iMaxShieldHealth >= 13000 or (iCurShieldHealth / iMaxShieldHealth <= 0.8 or (bConsiderRecentlyDamagedShields and oShield[AiBotUnitInfo.refiTimeLastDamaged] and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeLastDamaged] or -100) <= 30))) then
                        for iUnit, oUnit in oShield[reftoUnitsCoveredByShield] do
                            if not(oUnit == oShield) then
                                if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false then
                                    iCurMassValue = 30000
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategorySML, oUnit.UnitId) then
                                    iCurMassValue = 27500
                                else
                                    iCurMassValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                end
                                if not(oUnit[refoPriorityShieldProvidingCoverage] == oShield) and AiBotUnitInfo.IsUnitValid(oUnit[refoPriorityShieldProvidingCoverage]) then
                                    iCurMassValue = iCurMassValue * 0.1
                                    if bDebugMessages == true then LOG(sFunctionRef..': Already have a priority shield providing coverage='..oUnit[refoPriorityShieldProvidingCoverage].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoPriorityShieldProvidingCoverage])..' so will reduce mass value') end
                                end
                                if iCurMassValue >= 100000 and oUnit:GetFractionComplete() >= 0.2 then
                                    bCoveringGameEnder = true
                                end
                                iTotalUnitMassCoverage = iTotalUnitMassCoverage + iCurMassValue
                                if bDebugMessages == true then LOG(sFunctionRef..': Getting shield protection mass value of oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' for oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; iCurMassValue='..iCurMassValue..'; iTotalUnitMassCoverage='..iTotalUnitMassCoverage..'; Is there already a valid shield protecting it='..tostring(AiBotUnitInfo.IsUnitValid(oUnit[refoPriorityShieldProvidingCoverage]))) end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iTotalUnitMassCoverage='..iTotalUnitMassCoverage..'; bCoveringGameEnder='..tostring(bCoveringGameEnder)) end
                        if iTotalUnitMassCoverage >= 25000 and (bCoveringGameEnder or (iCurShieldHealth / iMaxShieldHealth <= 0.8 or (bConsiderRecentlyDamagedShields and oShield[AiBotUnitInfo.refiTimeLastDamaged] and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeLastDamaged] or -100) <= 30))) then
                            --Add as a priority shield
                            table.insert(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist], oShield)
                            oShield[refbPriorityShield] = true
                            for iUnit, oUnit in oShield[reftoUnitsCoveredByShield] do
                                oUnit[refoPriorityShieldProvidingCoverage] = oShield --Deliberately overwrites existing value, means if 2 shields cover same area, and one can justify it even with the ot her, but the other cant, then we wont protect the other
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding the shield as a priority shield') end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderDelayedOnMexDeathCall(tUnitPosition, sUnitRef, sLifetimeCount, iOwnerArmyIndex, iOwnerTeam, bMexWasConstructed)
    --Due to a replay on LOUD where a mex was destroyed (fully constructed) and it showed up as being an upgrading mex so OnMexDeath never triggered, resulting in AiBot thinkning there were no locations available to build (when there were)
    WaitSeconds(3)
    local rRect = AiBotUtilities.GetRectAroundLocation(tUnitPosition, 0.5)
    local tUnitsInRect = GetUnitsInRect(rRect)
    local bHaveMexThere = false
    if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
        local tMexesInRect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tUnitPosition)
        if AiBotUtilities.IsTableEmpty(tMexesInRect) == false then
            bHaveMexThere = true
        end
    end
    if not(bHaveMexThere) then
        --Check we have fewer mexes recorded in this zone for all teams
        local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tUnitPosition, true, iOwnerTeam)
        local iTeamMexes = 0
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech]) == false then
            for iTech, iMexes in tLZOrWZTeamData[AiBotMap.subrefMexCountByTech] do
                iTeamMexes = iTeamMexes + iMexes
            end
        end
        if iTeamMexes < tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] then
            --Have a risk of an inconsistency so run OnMexDeath to be safe
            OnMexDeath(tUnitPosition, sUnitRef, sLifetimeCount, iOwnerArmyIndex, bMexWasConstructed, true)
        end
    end
end

function OnMexDeath(tUnitPosition, sUnitRef, sLifetimeCount, iOwnerArmyIndex, bMexWasConstructed, bPotentiallyDuplicateCall)
    --Call via fork thread due to the WaitSeconds() in it; however note that as this is forked, the unit (mex) may not exist anymore, so tUnitPosition needs to be a copy of the position table, and dont want to pass the unit object
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'OnMexDeath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; tUnitPosition='..repru(tUnitPosition)) end



    --local tUnitPosition = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tUnitPosition)
    local tMexLocations
    local tLZOrWZData
    local iWaterZone, iPond



    if iPlateau and not(iLandZone) then
        iWaterZone = AiBotMap.GetWaterZoneFromPosition(tUnitPosition)
        if iWaterZone then
            iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
            tLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
            tMexLocations = tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]
        end
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
        tMexLocations = tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]
    end


    if bDebugMessages == true then LOG(sFunctionRef..': is table of mex locations empty='..tostring( AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMexLocations]))..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; tUnitPosition='..repru(tUnitPosition)..'; is tMexLocations empty='..tostring(AiBotUtilities.IsTableEmpty(tMexLocations))..'; iWaterZone='..(iWaterZone or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if AiBotUtilities.IsTableEmpty(tMexLocations) == false then
        --Record time of last mex death against LZ data to help with error messages
        tLZOrWZData[AiBotMap.refiTimeOfLastMexDeath] = GetGameTimeSeconds()

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1) --dont treat mex as available for a second (this is to help cover scenarios where if a mex has 'died' due to being upgraded, the new building will be here) - was a 2s delay, are trying 1s delay now to see if causes an issue
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        local tClosestMexLocation
        local iClosestMexLocation = 2.1 --no point considering mexes further away
        local iCurAbsDif
        for iEntry, tMex in tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] do --(WZ uses same ref ID definition)
            iCurAbsDif = math.abs(tMex[1] - tUnitPosition[1]) + math.abs(tMex[3] - tUnitPosition[3])
            if iCurAbsDif < iClosestMexLocation then
                iClosestMexLocation = iCurAbsDif
                tClosestMexLocation = {tMex[1], tMex[2], tMex[3]}
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting a period of time and then searching for closest mex location, tClosestMexLocation='..repru(tClosestMexLocation)..'; Time='..GetGameTimeSeconds()..'; iPlateau='..iPlateau..'; iLandZone='..(iLandZone or 'nil')) end
        if not(tClosestMexLocation) then AiBotUtilities.ErrorHandler('Couldnt find a mex in this zone close enough to the unit position on death')
        else
            --for iMexLocation, tMexLocation in tMexLocations do
            --Prev line - redid at same time as changing approach for removing an unbuilt location to try and be more accurate
            --if AiBotUtilities.GetDistanceBetweenPositions(tMexLocation, oUnit:GetPosition()) <= 0.9 then
            --Revised line:
            --if tMexLocation[1] == tClosestMexLocation[1] and tMexLocation[3] == tClosestMexLocation[3] then
            --Do we have any mexes in this location?
            local rRect = AiBotUtilities.GetRectAroundLocation(tClosestMexLocation, 0.9)
            local tUnitsInRect = GetUnitsInRect(rRect)
            if bDebugMessages == true then
                LOG(sFunctionRef..': Is tUnitsInRect empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInRect)))
                if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                    LOG(sFunctionRef..': If filter to just mexes is the table empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tUnitsInRect))))
                end
            end
            local bNoMex = true
            if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                local tMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tUnitsInRect)
                if AiBotUtilities.IsTableEmpty(tMexes) == false then
                    for iMex, oMex in tMexes do
                        if AiBotUnitInfo.IsUnitValid(oMex) and not(oMex.UnitId == sUnitRef and AiBotUnitInfo.GetUnitLifetimeCount(oMex) == sLifetimeCount and oMex:GetAIBrain():GetArmyIndex() == iOwnerArmyIndex) then
                            local tMexPosition = oMex:GetPosition()
                            --Get closest mex to this, in case there's another mex that's closer
                            local iCurMexClosestLocation = 2.1
                            local tCurMexClosestLocation
                            for iEntry, tMex in tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] do --(WZ uses same ref ID definition)
                                iCurAbsDif = math.abs(tMex[1] - tMexPosition[1]) + math.abs(tMex[3] - tMexPosition[3])
                                if iCurAbsDif < iCurMexClosestLocation then
                                    iCurMexClosestLocation = iCurAbsDif
                                    tCurMexClosestLocation = {tMex[1], tMex[2], tMex[3]}
                                end
                            end
                            if tCurMexClosestLocation[1] == tClosestMexLocation[1] and tCurMexClosestLocation[3] == tClosestMexLocation[3] then
                                --double-check due to rare case where presumably an upgrading t3 mex has just started and the base mex died, and there's a delay?
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a valid mex in this location, oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..'; Is mex valid='..tostring(AiBotUnitInfo.IsUnitValid(oMex))..'; Army Index='..oMex:GetAIBrain():GetArmyIndex()..'; sUnitRef='..sUnitRef..'; sLifetimeCount='..sLifetimeCount..'; iOwnerArmyIndex='..(iOwnerArmyIndex or 'nil')..'; tCurMexClosestLocation='..repru(tCurMexClosestLocation)..'; Mex position='..repru(oMex:GetPosition())..'; tUnitPosition='..repru(tUnitPosition)..'; tClosestMexLocation='..repru(tClosestMexLocation)..'; oMex fraction complete='..oMex:GetFractionComplete()..'; OMex Owner army index='..oMex:GetAIBrain():GetArmyIndex()..'; iOwnerArmyIndex='..iOwnerArmyIndex) end
                                if oMex:GetFractionComplete() < 1 and oMex:GetAIBrain():GetArmyIndex() == iOwnerArmyIndex and AiBotUtilities.GetDistanceBetweenPositions(tUnitPosition, tCurMexClosestLocation) <= 0.5 and AiBotUnitInfo.GetUnitTechLevel(oMex) > AiBotUnitInfo.GetBlueprintTechLevel(sUnitRef) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Think we have a mex that has died while upgrading, and the upgrading mex hasnt had its death triggered yet, so wont treat there as being a mex here afterall') end
                                else
                                    bNoMex = false
                                    break
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if we have a mex at this location anymore, bNoMex='..tostring(bNoMex)) end
            if bNoMex then
                local bAlreadyRecorded = false
                if not(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) then
                    tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] = {}
                else
                    for iEntry, tUnbuiltLocation in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] do --redundancy in case this code triggers more than once, as were comign across unbuilt locations with the same entry listed more than once (although it wasnt showing up with a reprs/repru)
                        if tUnbuiltLocation[1] == tClosestMexLocation[1] and tUnbuiltLocation[3] == tClosestMexLocation[3] then
                            bAlreadyRecorded = true
                            break
                        end
                    end
                end
                if not(bAlreadyRecorded) then
                    table.insert(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations], tClosestMexLocation)
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Recording location as being unbuilt as mex is dead and no mexes visible there now, tClosestMexLocation='..repru(tClosestMexLocation))
                        AiBotUtilities.DrawLocation(tClosestMexLocation)
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Already recorded this location as unbuilt') end
                end
            end
        end
        if bDebugMessages == true then
            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) then LOG(sFunctionRef..': tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] after update is empty')
            else LOG(sFunctionRef..': tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] after update has a size '..table.getn(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])..', table='..repru(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))
            end
        end
    else
        AiBotUtilities.ErrorHandler('Mex has died but not in a recognised land or water zone that has mexes')
    end

    --Track mexes by team

    local iTeam
    local oOwnerBrain
    for iBrain, oBrain in ArmyBrains do
        if iBrain == iOwnerArmyIndex then
            oOwnerBrain = oBrain
            iTeam = oBrain.AiBotTeam
            break
        end
    end
    if iTeam then
        if bMexWasConstructed then
            local iMexTech = AiBotUnitInfo.GetBlueprintTechLevel(sUnitRef)
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] or 0) - 1
            if bPotentiallyDuplicateCall then
                local iCurrentCountOfMexOfTech = ArmyBrains[iOwnerArmyIndex]:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * AiBotUnitInfo.ConvertTechLevelToCategory(iMexTech))
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] < iCurrentCountOfMexOfTech then
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] = iCurrentCountOfMexOfTech
                end
            end
            if bDebugMessages == true then
                local iUpgradingMexCount=0
                local iDeadUpgradingMexCount = 0
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
                    iUpgradingMexCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])
                    for iUpgradingMex, oUpgradingMex in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                        if not(AiBotUnitInfo.IsUnitValid(oUpgradingMex)) then iDeadUpgradingMexCount = iDeadUpgradingMexCount + 1 end
                    end
                end
                LOG(sFunctionRef..': Mex '..sUnitRef..sLifetimeCount..' has died for team '..iTeam..'; Revised mex count by tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] or 'nil')..'; T2 mex count based on currentunits='..ArmyBrains[iOwnerArmyIndex]:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * AiBotUnitInfo.ConvertTechLevelToCategory(iMexTech))..'; Upgrading mexes on team iUpgradingMexCount='..iUpgradingMexCount..'; iDeadUpgradingMexCount='..iDeadUpgradingMexCount)
            end
        end
    else
        if not(oOwnerBrain) or not(AiBotConditions.IsCivilianBrain(oOwnerBrain)) then
            if GetGameTimeSeconds() - AiBotOverseer.iTimeLastPlayerDefeat > 5 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or GetGameTimeSeconds() - AiBotOverseer.iTimeLastPlayerDefeat > 40) then
                AiBotUtilities.ErrorHandler('Mex death for a brain that doesnt have a team, oOwnerBrain='..(oOwnerBrain.Nickname or 'nil'))
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function OnMexConstructionCompleted(oUnit)
    local sFunctionRef = 'OnMexConstructionCompleted'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Track mexes by team
    local iTeam = oUnit:GetAIBrain().AiBotTeam
    if iTeam then
        local iMexTech = AiBotUnitInfo.GetUnitTechLevel(oUnit)
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech]) then
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech] = {}
        end
        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] or 0) + 1
        if bDebugMessages == true then
            local iUpgradingMexCount=0
            local iDeadUpgradingMexCount = 0
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then iUpgradingMexCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) end
            for iUpgradingMex, oUpgradingMex in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                if not(AiBotUnitInfo.IsUnitValid(oUpgradingMex)) then iDeadUpgradingMexCount = iDeadUpgradingMexCount + 1
                end
            end
            LOG(sFunctionRef..': Mex '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has just had construction started for team '..iTeam..'; Revised mex count by tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][iMexTech] or 'nil')..'; T2 mex count based on currentunits='..oUnit:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryMex * AiBotUnitInfo.ConvertTechLevelToCategory(iMexTech))..'; Upgrading mexes on team iUpgradingMexCount='..iUpgradingMexCount..'; iDeadUpgradingMexCount='..iDeadUpgradingMexCount)
        end
    elseif not(AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain())) then
        AiBotUtilities.ErrorHandler('No brain for mex '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' owned by brain '..(oUnit:GetAIBrain().Nickname or 'nil')..' so wont record for that brain team')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function OnMexConstructionStarted(oUnit)
    --Run for all brains

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'OnMexConstructionStarted'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --If 100% complete mex and fullshare is enabled then wait 2 ticks before running logic due to issue where the new unit cna be created before the logic re the old one dying triggers
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; Is game in full share='..tostring(ScenarioInfo.Options.Share == 'FullShare')..'; Time since last teammate death='..(GetGameTimeSeconds() - (AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiTimeOfLastTeammateDeath] or 0))..'; Fraction complete='..oUnit:GetFractionComplete()) end
    if oUnit:GetFractionComplete() == 1 and ScenarioInfo.Options.Share == 'FullShare' and GetGameTimeSeconds() - (AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiTimeOfLastTeammateDeath] or 0) <= 20 then
        if bDebugMessages == true then LOG(sFunctionRef..': A player has recently died so delaying logic for mex that is fully complete') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(3)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end

    if not(AiBotMap.bMapLandSetupComplete) or GetGameTimeSeconds() <= 5.1 or not(AiBotMap.bWaterZoneInitialCreation) then
        while (not(AiBotMap.bMapLandSetupComplete) or GetGameTimeSeconds() <= 5.1 or not(AiBotMap.bWaterZoneInitialCreation)) do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if GetGameTimeSeconds() >= 6 then break end
        end
    end

    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
    local tMexLocations
    local tLZOrWZData
    local iWaterZone, iPond



    if iPlateau and not(iLandZone) then
        iWaterZone = AiBotMap.GetWaterZoneFromPosition(oUnit:GetPosition())
        if iWaterZone then
            iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
            tLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
            tMexLocations = tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]
        end
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
        tMexLocations = tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]
    end

    if bDebugMessages == true then LOG(sFunctionRef..': The time is '..GetGameTimeSeconds()..'; Have just started construction for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')..'; Is AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Unit position='..repru(oUnit:GetPosition())..'; Unit brain='..oUnit:GetAIBrain().Nickname..'; on team '..(oUnit:GetAIBrain().AiBotTeam or 'nil')..'; % complete='..oUnit:GetFractionComplete()) end
    local bFoundMexLocation = false
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
        --Find the closest mex location in the zone
        local tClosestMexLocation
        local iClosestMexLocation = 2.1 --no point considering mexes further away
        local iCurAbsDif
        local tUnitPosition = oUnit:GetPosition()
        for iEntry, tMex in tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] do --(WZ uses same ref ID definition)
            iCurAbsDif = math.abs(tMex[1] - tUnitPosition[1]) + math.abs(tMex[3] - tUnitPosition[3])
            if iCurAbsDif < iClosestMexLocation then
                iClosestMexLocation = iCurAbsDif
                tClosestMexLocation = {tMex[1], tMex[2], tMex[3]}
            end
        end


        local iSizeBefore = table.getn(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])
        if bDebugMessages == true then LOG('About to loop through Mex locations; iPlateau='..iPlateau..'; iLandZone='..(iLandZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')..'; reprs='..reprs(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])..'; iSizeBefore='..iSizeBefore..'; tClosestMexLocation='..repru(tClosestMexLocation)) end
        --local iSizeAfter
        --local iLocationToRemove
        if bDebugMessages == true then
            for iMexLocation, tMexLocation in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] do
                LOG(sFunctionRef..': iMexLocation='..iMexLocation..'; tMexLocation='..repru(tMexLocation))
            end
        end
        if tClosestMexLocation then
            for iEntry = iSizeBefore, 1, -1 do
                local tMexLocation = tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations][iEntry]
                if bDebugMessages == true then LOG(sFunctionRef..': Comparing dist for iEntry '..iEntry..'; tMexLocation='..repru(tMexLocation)..'; tClosestMexLocation='..repru(tClosestMexLocation)) end
                if tMexLocation[1] == tClosestMexLocation[1] and tMexLocation[3] == tClosestMexLocation[3] then
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Have built a mex within 1 of a mex location so will treat this mex location as no longer available. iEntry='..iEntry)
                        AiBotUtilities.DrawLocation(tMexLocation, 2)
                    end
                    bFoundMexLocation = true
                    local vRemoved = table.remove(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations], iEntry)
                    if bDebugMessages == true then LOG(sFunctionRef..': tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] after removal='..repru(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])..'; vRemoved='..reprs(vRemoved)..'; iSizeBefore='..iSizeBefore) end
                    break
                end
            end
        else
            AiBotUtilities.ErrorHandler('Couldnt find a mex location close enough')
        end
        --Old code - had issues with this sometimes where e.g. would have a table that with reprs showed as only having 1 entry, but it actually had 2 and were identical
        --[[for iMexLocation, tMexLocation in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] do
            --Old code commented out below caused issues on maps like sludge:
            --if AiBotUtilities.GetDistanceBetweenPositions(tMexLocation, oUnit:GetPosition()) <= 2 then
            --Replaced with the following:
            if bDebugMessages == true then LOG(sFunctionRef..': Considering tMexLocation='..repru(tMexLocation)..'; compared with Unit position '..repru(oUnit:GetPosition())) end
            if math.abs(tMexLocation[1] - oUnit:GetPosition()[1]) < 1 and math.abs(tMexLocation[3] - oUnit:GetPosition()[3]) < 1 then
                if bDebugMessages == true then
                    LOG(sFunctionRef..': Have built a mex within 1 of a mex location so will treat this mex location as no longer available. iMexLocation='..iMexLocation)
                    AiBotUtilities.DrawLocation(tMexLocation, 2)
                end
                bFoundMexLocation = true
                iLocationToRemove = iMexLocation
                break
            end
        end
        if iLocationToRemove then
            local vRemoved = table.remove(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations], iLocationToRemove)
            local iSizeAfter
            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) then iSizeAfter = 0
            else iSizeAfter = table.getn(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])
            end
            if bDebugMessages == true then LOG(sFunctionRef..': tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] after removal='..repru(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])..'; vRemoved='..reprs(vRemoved)..'; iSizeBefore='..iSizeBefore..'; iSizeAfter='..iSizeAfter) end
        end
        if iSizeAfter >= iSizeBefore then
            --Backup for strange case where table.remove would remove a table but the table would still remain

        end--]]
    end
    if not(bFoundMexLocation) then
        --Is the reason we cant find any unbuilt locations because a mex is being upgraded? Doing a reprs of a mex being upgraded, CanTakeDamage was false and IsUpgrade was true, so use these to check
        if bDebugMessages == true then LOG(sFunctionRef..': Dont have an unbuilt location that existed for this mex, is it because mex is upgrading? oUnit.CanTakeDamage='..tostring(oUnit.CanTakeDamage or false)..'; oUnit.IsUpgrade='..tostring(oUnit.IsUpgrade or false)..'; LZ time of last mex death='..(GetGameTimeSeconds() - (tLZOrWZData[AiBotMap.refiTimeOfLastMexDeath] or 0))..'; reprs of unit='..reprs(oUnit)) end
        local bCheckOnlyForLowerTechExistingMex = true
        if oUnit.CanTakeDamage and not(oUnit.IsUpgrade) and (GetGameTimeSeconds() - (tLZOrWZData[AiBotMap.refiTimeOfLastMexDeath] or 0)) > 2.1 then
            --Ignore if early game and is owned by non-human brain, or campaign and owned by non-AiBotAI non-human brain
            if oUnit:GetAIBrain().BrainType == 'Human' or oUnit:GetAIBrain().AiBotAI or (GetGameTimeSeconds() >= 10 and not(AiBotMap.bIsCampaignMap)) then bCheckOnlyForLowerTechExistingMex = false end
            local tNearbyRect = AiBotUtilities.GetRectAroundLocation(oUnit:GetPosition(), 0.49)
            local tNearbyUnits = GetUnitsInRect(tNearbyRect)
            local bHaveMexHere = false
            if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                for iBuilding, oBuilding in tNearbyUnits do
                    if not(oBuilding == oUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oBuilding.UnitId) and AiBotUnitInfo.IsUnitValid(oBuilding) then
                        if not(bCheckOnlyForLowerTechExistingMex) or AiBotUnitInfo.GetUnitTechLevel(oBuilding) < AiBotUnitInfo.GetUnitTechLevel(oUnit) then
                            bHaveMexHere = true
                            break
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bCheckOnlyForLowerTechExistingMex='..tostring(bCheckOnlyForLowerTechExistingMex)..'; bHaveMexHere='..tostring(bHaveMexHere)..'; Is table of nearby units empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnits))) end
            if not(bHaveMexHere) then
                --we have a 1s delay on a mex dying before checking for available locations, so this could explain this
                if tLZOrWZData[AiBotMap.refiTimeOfLastMexDeath] and GetGameTimeSeconds() - tLZOrWZData[AiBotMap.refiTimeOfLastMexDeath] > 1.01 then
                    AiBotUtilities.ErrorHandler('OnCreate triggered for a mex but no unbuilt locations near it, iPlateau='..iPlateau..'; iLandZone='..(iLandZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')..'; Map setup complete='..tostring(AiBotMap.bMapLandSetupComplete)..'; bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation or false), true)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]='..repru(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit position='..repru(oUnit:GetPosition())) end
            end
        end
    end

    --Add mex to enemy unit table if underwater, due to flaw with current approach - i.e. to reduce overhead all AI regardless of team use the same table for if a mex has been built; engineers are meant to either build on unbuilt mexes, or try and reclaim if the enemy is there; however without this step they effectively end up thinking a teammate has the mex so they never tyr sending an engineer to build or capture.  For land it's not an issue as would expect land scouts or other land units to reveal the mexes anyway
    if iWaterZone > 0 then
        local tTeamsUpdated = {}
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.subreftoEnemyBrains]) == false then
            for iBrain, oBrain in AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.subreftoEnemyBrains] do
                if oBrain.AiBotAI and not(tTeamsUpdated[oBrain.AiBotTeam]) then
                    tTeamsUpdated[oBrain.AiBotTeam] = true
                    --(aiBrain, oUnit, bAlreadyUpdatedPosition, bAlreadyTriedReassignment, bIgnoreIfAssignedAlready)
                    AiBotTeam.AssignUnitToLandZoneOrPond(oBrain, oUnit, false,                    false,                      true)
                end
            end
        else
            --E.g. civilians that own mexes
            local iMexBrainIndex = oUnit:GetAIBrain():GetArmyIndex()
            for iBrain, oBrain in ArmyBrains do
                if not(IsAlly(oBrain:GetArmyIndex(), iMexBrainIndex)) then
                    if oBrain.AiBotAI and not(tTeamsUpdated[oBrain.AiBotTeam]) then
                        tTeamsUpdated[oBrain.AiBotTeam] = true
                        --(aiBrain, oUnit, bAlreadyUpdatedPosition, bAlreadyTriedReassignment, bIgnoreIfAssignedAlready)
                        AiBotTeam.AssignUnitToLandZoneOrPond(oBrain, oUnit, false,                    false,                      true)
                    end
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]='..repru(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DecideToLaunchNukeSMLOrTMLMissile()  end --Done only to make it easier to find considerlaunchingmissile
function ConsiderLaunchingMissile(oLauncher, oOptionalWeapon)
    --Should be called via forkthread when missile created due to creating a loop
    --oOptioanlWeapon - if specified then can get the missile speed
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderLaunchingMissile'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotUnitInfo.IsUnitValid(oLauncher) and not(oLauncher[refbActiveMissileChecker]) then
        local aiBrain = oLauncher:GetAIBrain()
        local iSecondsToWaitIfNoTarget = 10
        if bDebugMessages == true then LOG(sFunctionRef..': aiBrain.HostileCampaignAI='..tostring(aiBrain.HostileCampaignAI or false)..'; ScenarioInfo.Options.CmpAIDelay='..tonumber((ScenarioInfo.Options.CmpAIDelay or 1))..'; ScenarioInfo.OpEnded='..tostring(ScenarioInfo.OpEnded or false)..'; Time='..GetGameTimeSeconds()) end
        if not(aiBrain.HostileCampaignAI) or tonumber(ScenarioInfo.Options.CmpAIDelay) <= GetGameTimeSeconds() then
            --Aeon SML - one case having 11s threshold was fine, another when it was 12.1s since it fired a nuke it ended up clearing the old order
            local iTimeToWaitBetweenLaunches = 6 --i.e. TML
            if EntityCategoryContains(AiBotUnitInfo.refCategorySML, oLauncher.UnitId) then
                if EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId) then
                    iTimeToWaitBetweenLaunches = 8
                else
                    iTimeToWaitBetweenLaunches = 13 --had game where 10s delay wasnt enough (when iTimeToWaitBetweenLaunches was set to 8); 11s also wasnt (cybran SML); 13s still wasnt enough so added further 6s increase below which resolved it; also always have had 13s for aeon nuke which takes longer
                end
                if oLauncher:IsUnitState('Busy') and not(EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId)) then iTimeToWaitBetweenLaunches = iTimeToWaitBetweenLaunches + 6 end
            end

            if bDebugMessages == true then
                LOG(sFunctionRef..': Start of code for oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..' owned by brain '..oLauncher:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()..'; launcher position='..repru(oLauncher:GetPosition())..'Unit missile count='..AiBotUnitInfo.GetMissileCount(oLauncher)..'; Time since last issued a nuke launch order='..GetGameTimeSeconds() - (oLauncher[refiTimeLastFiredMissile] or -1000)..'; iTimeToWaitBetweenLaunches='..iTimeToWaitBetweenLaunches)
            end

            if oLauncher[refbSpecialLauncherTargeting] == nil then
                oLauncher[refbSpecialLauncherTargeting] = false --default
                --TML special case - TML batteries for snipe targets - dont use this logic
                if EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oLauncher.UnitId) then
                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oLauncher:GetPosition(), true, oLauncher:GetAIBrain().AiBotTeam)
                    if tLZTeamData[AiBotMap.refbGetTMLBattery] then
                        oLauncher[refbSpecialLauncherTargeting] = true
                        ForkThread(TMLBatteryMonitor, tLZTeamData, oLauncher)
                    end
                end
            end
            if oLauncher[refbSpecialLauncherTargeting] then AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd) return end

            --If we have just tried giving an order to fire then wait longer
            if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have tried firing recently, iTimeToWaitBetweenLaunches='..iTimeToWaitBetweenLaunches..'; refiTimeLastFiredMissile='..(oLauncher[refiTimeLastFiredMissile] or 'nil')..'; Time since last fired='..GetGameTimeSeconds() - (oLauncher[refiTimeLastFiredMissile] or 0)..'; Unit state='..AiBotUnitInfo.GetUnitState(oLauncher)) end
            if oLauncher[refiTimeLastFiredMissile] and GetGameTimeSeconds() - oLauncher[refiTimeLastFiredMissile] <= iTimeToWaitBetweenLaunches then
                if bDebugMessages == true then LOG(sFunctionRef..': we tried firing recently so will do a delayed launch instead') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                --LOG('Forked consideration of launching missile Delay3')
                DelayedConsiderLaunchingMissile(oLauncher, iTimeToWaitBetweenLaunches - (GetGameTimeSeconds() - oLauncher[refiTimeLastFiredMissile]), true, true)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Beginning main launcher logic, setting active missile checker to true') end
                oLauncher[refbActiveMissileChecker] = true
                local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)

                local tTarget
                local iBestTargetValue
                local iCurTargetValue
                local tEnemyCategoriesOfInterest
                local aiBrain = oLauncher:GetAIBrain()
                local iMaxRange = 250 --basic default, should get overwritten
                local iMinRange = 0
                local iAOE, iDamage

                local bTML = false
                local bSML = false
                local bCheckForSMD = false
                local iMinDelayBetweenNukes = 15 + 40 * AiBotMap.iMapSize / 1024 --Aeon nuke takes 60s to get to corner of setons, think it takes 5s longer to fire, so will go with 55 for non-aeon; as a very rough approximation will allow 15s for non-Aeon to fire and then rise and then fall, and 40s for travelling, so are slightly better on 40km+ maps at not double-nuking the same spot

                local iTeam = aiBrain.AiBotTeam
                local iTotalWaitCount = 0 --Nukes will spread calculations over a number of ticks, this tracks the ticks waited
                if EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oLauncher.UnitId) then
                    bTML = true
                elseif EntityCategoryContains(AiBotUnitInfo.refCategorySML, oLauncher.UnitId) then
                    bSML = true
                    if not(EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId)) then
                        bCheckForSMD = true --default
                        --If we have lots more nukes than enemy has SMD then consider overwhelming the SMD with nukes
                        local iNukeCount = 0
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            iNukeCount = oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySML - categories.EXPERIMENTAL - AiBotUnitInfo.refCategoryBattleship) + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL) * 6
                        end
                        --Only consider overwhelming if we have 6 nukes
                        local iEnemySMD = 0
                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to check for SMD when deciding on targets for a non experimental nuke launcher, iNukeCount='..iNukeCount) end
                        if iNukeCount >= 4 then
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) == false then
                                for iSMD, oSMD in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD] do
                                    if oSMD:GetFractionComplete() == 1 then
                                        iEnemySMD = iEnemySMD + 1
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iEnemySMD='..iEnemySMD) end
                            if iNukeCount >= iEnemySMD * 1.5 then
                                --Have enough nukes to overwhelm enemy
                                bCheckForSMD = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Have more than 50% of enemy SMD in nuke launchers so will nuke regardless of SMD, iNukeCount='..iNukeCount..'; iEnemySMD='..iEnemySMD) end
                            else
                                --How many SMD does enemy have in one zone?
                                local tiSMDByPlateauAndZone = {}
                                local iCurSMDPlateauOrZero, iCurSMDZone
                                local iHighestSMDPerZone = 0
                                for iSMD, oSMD in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD] do
                                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oSMD:GetPosition()) then
                                        iCurSMDPlateauOrZero, iCurSMDZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oSMD:GetPosition())
                                        if not(tiSMDByPlateauAndZone[iCurSMDPlateauOrZero]) then tiSMDByPlateauAndZone[iCurSMDPlateauOrZero] = {} end
                                        tiSMDByPlateauAndZone[iCurSMDPlateauOrZero][iCurSMDZone] = (tiSMDByPlateauAndZone[iCurSMDPlateauOrZero][iCurSMDZone] or 0) + 1
                                        iHighestSMDPerZone = math.max(iHighestSMDPerZone, tiSMDByPlateauAndZone[iCurSMDPlateauOrZero][iCurSMDZone])
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iNukeCount='..iNukeCount..'; iEnemySMD='..iEnemySMD..'; iHighestSMDPerZone='..iHighestSMDPerZone) end
                                if iNukeCount >= iHighestSMDPerZone * 1.5 then
                                    bCheckForSMD = false
                                end
                            end

                            if not(bCheckForSMD) and iEnemySMD > 0 then
                                iMinDelayBetweenNukes = math.min(10, math.max(5, 15 - iNukeCount/2))
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to ignore SMD, oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..'; iNukeCount='..iNukeCount..'; iEnemySMD (if we have lots of nukes)='..iEnemySMD..'; bCheckForSMD='..tostring(bCheckForSMD)..'; Time='..GetGameTimeSeconds()..'; iMinDelayBetweenNukes='..iMinDelayBetweenNukes) end
                        end

                        if EntityCategoryContains(categories.AEON, oLauncher.UnitId) then iMinDelayBetweenNukes = iMinDelayBetweenNukes + 5 end
                    else
                        --yolona - refuce min delay if enemy has lots of SMD as may be trying to overwhelm
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) == false then
                            local bAllowMultipleNukesAtTarget = false

                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbSMDBlockingLastNukeTarget] then
                                bAllowMultipleNukesAtTarget = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy has SMDs and there was an SMD blockign the last nuke target so we want to reduce the delay between nuke targets') end
                            else
                                local bEnemyHasLoadedOrLotsOfSMD = false
                                if table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) >= 3 then
                                    bEnemyHasLoadedOrLotsOfSMD = true
                                else
                                    for iSMD, oSMD in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD] do
                                        if oSMD:GetTacticalSiloAmmoCount() > 0 then
                                            bEnemyHasLoadedOrLotsOfSMD = true
                                            break
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bEnemyHasLoadedOrLotsOfSMD='..tostring(bEnemyHasLoadedOrLotsOfSMD)) end

                                if bEnemyHasLoadedOrLotsOfSMD then
                                    --if any nuke target in the last 30s is currently covered by SMD, then remove min delay
                                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) == false then
                                        local iThresholdTime = GetGameTimeSeconds() - 30
                                        for iTime, tLocation in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] do

                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering nuke launch location if it was fired within threshold time, fired in threshold='..tostring(iTime >= iThresholdTime)..'; IsSMDBlockingTarget='..tostring(IsSMDBlockingTarget(aiBrain, tLocation, oLauncher:GetPosition(), 30, 0, false))..'; iTime='..iTime..'; tLocation='..repru(tLocation)) end
                                            if iTime >= iThresholdTime and IsSMDBlockingTarget(aiBrain, tLocation, oLauncher:GetPosition(), 30, 0, false) then
                                                bAllowMultipleNukesAtTarget = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want to allow multiple nukes at targets') end
                                            end
                                        end
                                    end
                                end
                            end
                            if bAllowMultipleNukesAtTarget then iMinDelayBetweenNukes = 0 end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering the min delay between nukes at the same location for a yolona, iMinDelayBetweenNukes='..iMinDelayBetweenNukes..'; Is table of enemy SMD empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]))) end
                    end


                elseif EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oLauncher.UnitId) then
                    AiBotUtilities.ErrorHandler('Are running TML logic on an ACU or SACU, but code not setup to work for this yet')
                else AiBotUtilities.ErrorHandler('Unknown type of launcher, code to fire a missile wont work; oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher))
                end

                if bTML or bSML then
                    iAOE, iDamage, iMinRange, iMaxRange = AiBotUnitInfo.GetLauncherAOEStrikeDamageMinAndMaxRange(oLauncher)

                    if bTML then
                        --tEnemyCategoriesOfInterest = iTMLHighPriorityCategories
                    else --SML
                        if oLauncher[AiBotUnitInfo.refbEasyBrain] then
                            tEnemyCategoriesOfInterest = {AiBotUnitInfo.refCategoryExperimentalStructure, AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategorySML + categories.COMMAND, AiBotUnitInfo.refCategoryT3Mex + AiBotUnitInfo.refCategoryT3Power}
                        else
                            tEnemyCategoriesOfInterest = {AiBotUnitInfo.refCategoryExperimentalStructure, AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategorySML + categories.COMMAND, AiBotUnitInfo.refCategoryT3Mex + AiBotUnitInfo.refCategoryT3Power, AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryStructure * categories.TECH3 + AiBotUnitInfo.refCategoryFixedT2Arti - AiBotUnitInfo.refCategoryExperimentalStructure - AiBotUnitInfo.refCategoryFixedT3Arti - AiBotUnitInfo.refCategorySML - AiBotUnitInfo.refCategoryT3Mex - AiBotUnitInfo.refCategorySMD - AiBotUnitInfo.refCategoryT3Power, AiBotUnitInfo.refCategoryNavalSurface * categories.TECH3 + AiBotUnitInfo.refCategoryNavalSurface * categories.EXPERIMENTAL}
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': Will consider missile target. iMinRange='..(iMinRange or 'nil')..'; iAOE='..(iAOE or 'nil')..'; iDamage='..(iDamage or 'nil')..'; bSML='..tostring((bSML or false))..'; bTML='..tostring(bTML or false)..'; Is laucher valid='..tostring(AiBotUnitInfo.IsUnitValid(oLauncher))..'; Time='..GetGameTimeSeconds()) end
                    if AiBotUnitInfo.IsUnitValid(oLauncher) then
                        local bHaveBlockingSMD = false
                        if bTML then
                            --DEALING WITH TML---------------------------------------------------
                            --local tHighHealthTargets = {}
                            local tStartPos = oLauncher:GetPosition()
                            local tPotentialTargets
                            local iValidTargets = 0
                            local tValidTargets = {}
                            local iTMLRange = (oLauncher[AiBotUnitInfo.refiManualRange] or iTMLMissileRange)
                            local iTMLAOE = math.max(oLauncher[AiBotUnitInfo.refiIndirectAOE] or 0, 2)
                            local iPotentialInRangeDistance = iTMLRange + iTMLAOE + 4 --unlikely to have larger buildings than this
                            local tNearbyEnemyTMD
                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider enemy ACU in TML targets in FAF/steam, AiBotUtilities.bFAFActive='..tostring(AiBotUtilities.bFAFActive)..'; Is table of enemy ACUs empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]))) end
                            local tACUsInRange = {}
                            if (AiBotUtilities.bFAFActive or AiBotUtilities.bSteamActive) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                                local iCurDist
                                for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                                    if AiBotUnitInfo.IsUnitValid(oACU) and ((oACU[refiTMLShotsFired] or 0) <= 2 or ((oACU[refiTMLShotsHit] or 0) > 0 and oACU[refiTMLShotsHit] / oACU[refiTMLShotsFired] >= 0.33))  then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oLauncher:GetPosition())
                                        if iCurDist <= iTMLRange then
                                            --Track ACU positions
                                            ForkThread(MonitorUnitRecentPositions, oACU)
                                            --Is enemy ACU stationery?
                                            if oACU[AiBotUnitInfo.reftRecentUnitPositions][2] then
                                                --Is ACU stationery, and hasnt moved from when we last had intel of their position?
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oACU owned by brain ='..oACU:GetAIBrain().Nickname..'; Dist to recent position2='..AiBotUtilities.GetDistanceBetweenPositions(oACU[AiBotUnitInfo.reftRecentUnitPositions][2], oACU:GetPosition())..'; Unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Dist to last known position='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; iCurDist='..iCurDist..'; Shots fired='..(oACU[refiTMLShotsFired] or 0)..'; refiTMLShotsHit='..(oACU[refiTMLShotsHit] or 0)..'; Dist to position 4='..AiBotUtilities.GetDistanceBetweenPositions((oACU[AiBotUnitInfo.reftRecentUnitPositions][4] or {0,0,0}), oACU:GetPosition())) end
                                                if oACU:GetHealth() <= 18000 and (not(oACU.MyShield.GetHealth) or oACU.MyShield:GetHealth() <= 3000) and AiBotUtilities.GetDistanceBetweenPositions(oACU[AiBotUnitInfo.reftRecentUnitPositions][2], oACU:GetPosition()) <= 0.1 and not(oACU:IsUnitState('Moving')) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 2 then
                                                    --Check ACU doesnt have very high health or shield
                                                    if iCurDist <= 150 then iSecondsToWaitIfNoTarget = 1 elseif iCurDist <= 180 then iSecondsToWaitIfNoTarget = 2 else iSecondsToWaitIfNoTarget = 3 end
                                                    if iCurDist <= 60 or (oACU[refiTMLShotsFired] or 0) == 0 or (oACU[AiBotUnitInfo.reftRecentUnitPositions][4] and AiBotUtilities.GetDistanceBetweenPositions(oACU[AiBotUnitInfo.reftRecentUnitPositions][4], oACU:GetPosition()) <= 0.1) then
                                                        --Is there TMD protecting the ACU from us?
                                                        local tACULZData, tACULZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), false, iTeam)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of TMD in ACU LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tACULZTeamData[AiBotMap.subreftoEnemyTMD]))) end
                                                        if AiBotUtilities.IsTableEmpty(tACULZTeamData[AiBotMap.subreftoEnemyTMD]) then

                                                            local tNearbyTMD = oACU:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oACU:GetPosition(), iTMLMissileRange + 30, 'Ally')
                                                            local bProtectedByTMD = false
                                                            if AiBotUtilities.IsTableEmpty(tNearbyTMD) == false then
                                                                for iTMD, oTMD in tNearbyTMD do
                                                                    if IsTMDProtectingUnitFromTML(oTMD, oACU, oLauncher) then
                                                                        bProtectedByTMD = true
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tACULZTeamData[AiBotMap.subreftoEnemyTMD]))..'; bProtectedByTMD='..tostring(bProtectedByTMD)) end
                                                            if not(bProtectedByTMD) then
                                                                table.insert(tACUsInRange, oACU)
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tACUsInRange) == false then
                                tPotentialTargets = tACUsInRange
                                if AiBotUtilities.IsTableEmpty(oLauncher[reftUnprotectedUnitTargetsForThisTML]) == false then
                                    for iTarget, oTarget in oLauncher[reftUnprotectedUnitTargetsForThisTML] do
                                        table.insert(oTarget, tPotentialTargets)
                                    end
                                end
                            else
                                tPotentialTargets = oLauncher[reftUnprotectedUnitTargetsForThisTML]
                            end

                            --First refresh list of untis in range for any that are dead
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of potential targets empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialTargets))) end
                            if AiBotUtilities.IsTableEmpty(tPotentialTargets) == false then
                                local iPotentialTargets = table.getn(tPotentialTargets)
                                local iCurDist
                                for iCurEntry = iPotentialTargets, 1, -1 do
                                    if not(AiBotUnitInfo.IsUnitValid(tPotentialTargets[iCurEntry])) then
                                        table.remove(oLauncher[reftUnprotectedUnitTargetsForThisTML], iCurEntry)
                                    else
                                        if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tPotentialTargets[iCurEntry]:GetPosition()) then
                                            --Can we hit this unit factoring in AOE?
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tPotentialTargets[iCurEntry]:GetPosition(), tStartPos)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering entry '..iCurEntry..'; Unit='..tPotentialTargets[iCurEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tPotentialTargets[iCurEntry])..'; iCurDist='..iCurDist..'; iPotentialInRangeDistance='..iPotentialInRangeDistance..'; iTMLRange='..iTMLRange..'; iTMLAOE='..iTMLAOE..'; refiStrikeDamageAssigned='..(tPotentialTargets[iCurEntry][AiBotAir.refiStrikeDamageAssigned] or 0)) end
                                            if iCurDist <= iPotentialInRangeDistance then
                                                if iCurDist <= iTMLRange or iCurDist <= iTMLRange + math.max(iTMLAOE, 0.5 * math.min(tPotentialTargets[iCurEntry]:GetBlueprint().Physics.SkirtSizeX, tPotentialTargets[iCurEntry]:GetBlueprint().Physics.SkirtSizeZ)) then
                                                    table.insert(tValidTargets, tPotentialTargets[iCurEntry])
                                                    iValidTargets = iValidTargets + 1
                                                end
                                            end
                                        end
                                    end
                                end
                            end

                            local oBestTarget
                            if bDebugMessages == true then LOG(sFunctionRef..': iValidTargets='..iValidTargets) end
                            if iValidTargets == 0 then
                                --Disable autobuild and pause the TML since we have no targets - handled below to cover cases where for whatever reason we fail to find a valid target
                            else
                                --Have at least 1 valid target, so want to pick the best one

                                iBestTargetValue = 120 --wont consider targets worth less than this
                                local sLauncherLocationRef = AiBotUtilities.ConvertLocationToReference(oLauncher:GetPosition())
                                for iUnit, oUnit in tValidTargets do
                                    if AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]) == false then
                                        iCurTargetValue = 0
                                        if bDebugMessages == true then LOG(sFunctionRef..': Shields are covering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                    elseif oUnit.Dead or oUnit:GetFractionComplete() <= 0.6 and (oUnit:GetFractionComplete() <= 1 - 0.25 * AiBotUnitInfo.GetUnitTechLevel(oUnit)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit under construction so TMD checks are less reliable (although we have a backup later on) and benefit reduced, with bomb damage potentially including other buildings nearby') end
                                    else
                                        --GetDamageFromBomb(aiBrain, tBaseLocation,         iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor)
                                        iCurTargetValue = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iDamage,       nil,                                nil,                true,                           nil,                nil,                            nil,                                        false,              nil,                            true,                               nil,                                nil,                    nil)
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower + AiBotUnitInfo.refCategorySMD + AiBotUnitInfo.refCategorySML, oUnit.UnitId) then iCurTargetValue = iCurTargetValue * 1.5 end
                                        --Adjust value if we think the missile will hit a cliff
                                        if oUnit[tbExpectMissileBlockedByCliff][sLauncherLocationRef] == nil then
                                            if not(oUnit[tbExpectMissileBlockedByCliff]) then oUnit[tbExpectMissileBlockedByCliff] = {} end
                                            local tExpectedMissileVertical = AiBotUtilities.MoveInDirection(oLauncher:GetPosition(), AiBotUtilities.GetAngleFromAToB(oLauncher:GetPosition(), oUnit:GetPosition()), 31, true)
                                            tExpectedMissileVertical[2] = tExpectedMissileVertical[2] + 60 --Doing testing, it actually only goes up by 50, but I think it travels in an arc from here to the target, as in a test scenario doing at less than +60 meant it thought it would hit a cliff when it didnt
                                            -- {oLauncher:GetPosition()[1], oLauncher:GetPosition()[2] + 65, oLauncher:GetPosition()[3]}
                                            oUnit[tbExpectMissileBlockedByCliff][sLauncherLocationRef] = AiBotLogic.IsLineBlocked(aiBrain, tExpectedMissileVertical, oUnit:GetPosition(), iAOE, false)
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Potential TML target '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurTargetValue before adj for blocked='..iCurTargetValue..'; oUnit[tbExpectMissileBlockedByCliff][sLauncherLocationRef]='..tostring(oUnit[tbExpectMissileBlockedByCliff][sLauncherLocationRef])..'; oUnit[refiTMLShotsFired]='..(oUnit[refiTMLShotsFired] or 0)..'; refiTimeOfLastLaunch='..(oUnit[refiTimeOfLastLaunch] or 'nil')..'; oUnit[refbProtectedByTerrain]='..tostring(oUnit[refbProtectedByTerrain] or false)..'; oLauncher[reftTerrainBlockedTargets]='..repru(oLauncher[reftTerrainBlockedTargets] or {'nil'})..'; iDamage='..iDamage..'; iAOE='..iAOE..'; Unit health='..oUnit:GetHealth()..'; Unit position='..repru(oUnit:GetPosition())..'; Is reftoShieldsProvidingCoverage empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit[reftoShieldsProvidingCoverage]))) end
                                        if oUnit[tbExpectMissileBlockedByCliff][sLauncherLocationRef] then iCurTargetValue = iCurTargetValue * 0.2 end
                                        --Check against actual terrain blocked blacklist
                                        if oUnit[refbProtectedByTerrain] then
                                            iCurTargetValue = 0
                                        elseif AiBotUtilities.IsTableEmpty(oLauncher[reftTerrainBlockedTargets]) == false then
                                            for iEntry, tLocation in oLauncher[reftTerrainBlockedTargets] do
                                                if AiBotUtilities.GetDistanceBetweenPositions(tLocation, oUnit:GetPosition()) <= 1.5 then
                                                    oUnit[refbProtectedByTerrain] = true
                                                    iCurTargetValue = 0
                                                    break
                                                end
                                            end
                                        end
                                        if oUnit[AiBotAir.refiStrikeDamageAssigned] and iCurTargetValue > 0 and oUnit[AiBotAir.refiStrikeDamageAssigned] > oUnit:GetHealth() then
                                            iCurTargetValue = iCurTargetValue * 0.1
                                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing cur target to 10% as we have assigned bomber striked damage, oUnit[AiBotAir.refiStrikeDamageAssigned]='..oUnit[AiBotAir.refiStrikeDamageAssigned]..'; Health='..oUnit:GetHealth()) end
                                        end
                                        if iCurTargetValue > 0 then
                                            if (oUnit[refiTMLShotsFired] or 0) > 0 then
                                                --Reduce shots fired if we dealt damage with our last missile (as may have e.g. hit mass storage blocking us from reaching the target mex)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Last TML target='..(oLauncher[refoLastTMLTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oLauncher[refoLastTMLTarget]) or 'nil')..'; Launcher mass killed='..(oLauncher.VetExperience or oLauncher.Sync.totalMassKilled or 0)..'; TML mass kills='..(oLauncher[refiLastTMLMassKills] or 0)..'; is oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam] nil='..tostring(oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam] == nil)) end
                                                if oLauncher[refoLastTMLTarget] == oUnit and (oLauncher.VetExperience or oLauncher.Sync.totalMassKilled or 0) > (oLauncher[refiLastTMLMassKills] or 0) then
                                                    oLauncher[refiLastTMLMassKills] = (oLauncher.VetExperience or oLauncher.Sync.totalMassKilled or 0)
                                                    oUnit[refiTMLShotsFired] = oUnit[refiTMLShotsFired] - 1
                                                end
                                                if oUnit[refiTMLShotsFired] > math.min((oUnit[refiTMLShotsHit] or 0), 4) and (oUnit[refiTimeOfLastLaunch] or oUnit[refiTMLShotsFired] >= 2) then
                                                    if oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam][iTeam] then iCurTargetValue = 0
                                                    else
                                                        local iUnitMaxHealth = oUnit:GetMaxHealth()
                                                        local iUnitCurShield, iUnitMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit)
                                                        if (iUnitMaxHealth + iUnitMaxShield <= iDamage and AiBotUnitInfo.IsUnitValid(oUnit[refoLastTMLLauncher])) and (not(oUnit[refoLastTMLLauncher] == oLauncher) or GetGameTimeSeconds() - (oUnit[refiTimeOfLastLaunch] or -100) <= 35) then
                                                            iCurTargetValue = 0
                                                        else
                                                            local iUnitRegen = (oUnit:GetBlueprint().Defense.RegenRate or 0)
                                                            --Assume unit will have effectively increased its max health by regenerating over 30s
                                                            if iUnitRegen > 0 then iUnitMaxHealth = iUnitRegen * 30 end
                                                            local iExpectedShots = math.ceil((iUnitMaxHealth + iUnitMaxShield) / iDamage)


                                                            if oUnit[refiTMLShotsFired] - (oUnit[refiTMLShotsHit] or 0) > iExpectedShots then
                                                                --Reduce by 50% for each time are over
                                                                iCurTargetValue = iCurTargetValue * 0.5^(oUnit[refiTMLShotsFired] - iExpectedShots - math.min(4, (oUnit[refiTMLShotsHit] or 0)))
                                                                if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) and oUnit[refiTMLShotsFired] - iExpectedShots - (oUnit[refiTMLShotsHit] or 0) >= 3 then
                                                                    iCurTargetValue = 0
                                                                end
                                                            end
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': iUnitMaxHealth='..iUnitMaxHealth..'; iUnitMaxShield='..iUnitMaxShield..'; oUnit[refiTMLShotsFired]='..oUnit[refiTMLShotsFired]..'; refiTMLShotsHit='..(oUnit[refiTMLShotsHit] or 'nil')..'; oUnit[refiTimeOfLastLaunch]='..(oUnit[refiTimeOfLastLaunch] or 'nil')..'; iCurTargetValue after adjusting for excess='..iCurTargetValue) end
                                                    end
                                                end
                                            elseif oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam][iTeam] then
                                                iCurTargetValue = iCurTargetValue * 0.25
                                                if bDebugMessages == true then LOG(sFunctionRef..': Target was recorded when under construction, significantly decreasing value due to risk of enemy TMD as appears to be issue with logic not picking up tmd when unit is being upgraded') end
                                                if iCurTargetValue > iBestTargetValue or oUnit:GetFractionComplete() == 1 then
                                                    --Do more detailed check
                                                    if oUnit:GetFractionComplete() == 1 then
                                                        --Redundancy in event onconstructed didnt trigger
                                                        RecordTMLAndTMDForEnemyUnitTargetJustDetected(oUnit, iTeam)
                                                        if oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam][iTeam] then oUnit[refbRecheckTMLAndTMDWhenConstructedByTeam][iTeam] = false end
                                                    else
                                                        if not(tNearbyEnemyTMD) then tNearbyEnemyTMD = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oLauncher:GetPosition(), iTMLMissileRange + 20, 'Ally') end
                                                        if AiBotUtilities.IsTableEmpty(tNearbyEnemyTMD) == false then
                                                            for iTMD, oTMD in tNearbyEnemyTMD do
                                                                RecordIfUnitIsProtectedFromTMLByTMD(oUnit, oLauncher, tNearbyEnemyTMD, false)
                                                            end
                                                        end
                                                    end
                                                    if AiBotUtilities.IsTableEmpty(oUnit[reftTMDCoveringThisUnit]) == false then
                                                        if AiBotUtilities.IsTableEmpty(oLauncher[reftUnprotectedUnitTargetsForThisTML]) then
                                                            iCurTargetValue = 0
                                                            if bDebugMessages == true then LOG(sFunctionRef..': No longer an unrptoected target for this TML') end
                                                        else
                                                            local bRecordedStill = false
                                                            for iRecordedUnit, oRecordedUnit in oLauncher[reftUnprotectedUnitTargetsForThisTML] do
                                                                if oRecordedUnit == oUnit then
                                                                    bRecordedStill = true
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Still recorded as an unrptoected target for this TML') end
                                                                    break
                                                                end
                                                            end
                                                            if not(bRecordedStill) then
                                                                iCurTargetValue = 0
                                                            end
                                                        end
                                                    end

                                                end
                                            end
                                        end
                                    end
                                    if iBestTargetValue < iCurTargetValue then
                                        if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then iCurTargetValue = math.max(125, iCurTargetValue * 0.2) end
                                        iBestTargetValue = iCurTargetValue
                                        oBestTarget = oUnit
                                    end
                                end
                                if oBestTarget then
                                    tTarget = oBestTarget:GetPosition()
                                    --Target ground following FAF changes to TMLs
                                    tTarget[2] = GetSurfaceHeight(tTarget[1], tTarget[3])
                                    RecordTMLMissileTarget(oLauncher, oBestTarget)
                                    if bDebugMessages == true then LOG(sFunctionRef..': oBestTarget='..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget)..'; iBestTargetValue='..iBestTargetValue..'; SHots fired afteri ncluding this one='..oBestTarget[refiTMLShotsFired]..'; refiTMLShotsHit='..(oBestTarget[refiTMLShotsHit] or 'nil')..'; Mass killed prior to missile impacting='..oLauncher[refiLastTMLMassKills]) end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iValidTargets='..iValidTargets..'; tTarget='..repru((tTarget or {'nil'}))..'; Is oBestTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oBestTarget))) end
                        else --SML - work out which location would deal the most damage - consider all high value structures and the enemy start position
                            --DEALING WITH NUKE---------------------------------------------------
                            --Reduce AOE by 0.5 if >10 to be more reliable (since height differences mean we might incorrectly think we will hit a high value target?)
                            if iAOE > 10 then iAOE = math.max(10, iAOE - 0.5) end
                            iBestTargetValue = 0
                            --Shortlist of locations we have recently nuked
                            local tRecentlyNuked = {}
                            local iTimeSMDNeedsToHaveBeenBuiltFor = 200 + iTimeForSMDToBeConstructed --default, will adjust
                            local iMissileSpeed
                            if oOptionalWeapon then iMissileSpeed = (__blueprints[oOptionalWeapon.Blueprint.ProjectileId].Physics.MaxSpeed or 40)
                            else iMissileSpeed = 40
                            end
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..'; Breakdown of the weapon table='..reprs(oOptionalWeapon)..'; iMissileSpeed='..iMissileSpeed..'; missile speed per BP='..(__blueprints[oOptionalWeapon.Blueprint.ProjectileId].Physics.MaxSpeed or 'nil'))
                            end

                            local iNukeSegmentSize = 15
                            local tiNukeSegmentsConsidered = {}
                            local iCurNukeSegmentX, iCurNukeSegmentZ
                            local bAlreadyConsideredBestAOETarget = true

                            local iPositionsConsideredThisTick = 0
                            local iAbortThreshold = 60000

                            function GetNukeSegmentsFromPosition(tPosition)
                                return math.ceil(tPosition[1] / iNukeSegmentSize), math.ceil(tPosition[3] / iNukeSegmentSize)
                            end
                            function RecordHaveConsideredNukeLocation(tPosition, bConsideredBestAOETarget)
                                iCurNukeSegmentX, iCurNukeSegmentZ = GetNukeSegmentsFromPosition(tPosition)
                                if not(tiNukeSegmentsConsidered[iCurNukeSegmentX]) then tiNukeSegmentsConsidered[iCurNukeSegmentX] = {} end
                                tiNukeSegmentsConsidered[iCurNukeSegmentX][iCurNukeSegmentZ] = true
                                if bConsideredBestAOETarget then
                                    iPositionsConsideredThisTick = iPositionsConsideredThisTick + 5 --approximation - will likely be more than this
                                else
                                    iPositionsConsideredThisTick = iPositionsConsideredThisTick + 1
                                end

                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': Checking nuke launch locations, is table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]))..'; Time of check='..GetGameTimeSeconds()) end
                            function RefreshRecentlyNukedLocations()
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) == false and iMinDelayBetweenNukes > 0 then
                                    local iTimeSinceFired
                                    local iLoopCheck
                                    for iTime, tLocation in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iTime='..iTime..'; tLocation='..repru(tLocation)..'; GameTime='..GetGameTimeSeconds()) end
                                        iTimeSinceFired = GetGameTimeSeconds() - iTime

                                        if iTimeSinceFired < iMinDelayBetweenNukes then --Testing with Aeon SML on setons it takes 60s to go from one corner to another roughly
                                            iLoopCheck = 0
                                            while tRecentlyNuked[iTimeSinceFired] do
                                                iTimeSinceFired = iTimeSinceFired - 0.0001
                                                iLoopCheck = iLoopCheck + 1
                                                if iLoopCheck >= 20 then AiBotUtilities.ErrorHandler('Potential infinite loop with nuke location recording, will stop attempting to record extra recently nuked locations') break end
                                            end
                                            tRecentlyNuked[iTimeSinceFired] = {tLocation[1], tLocation[2], tLocation[3]}
                                        end
                                    end
                                end
                            end

                            RefreshRecentlyNukedLocations()

                            if bDebugMessages == true then LOG(sFunctionRef..': tRecentlyNuked='..repru((tRecentlyNuked or {'nil'}))) end

                            function HaventRecentlyNukedLocation(tLocation )--, bIgnoreIfCoveredBySMD) --bIgnoreIfCoveredBySMD - removed from v46 (previously would set to true if want to ignore the fact that we have recenlty nuked the target if it is covered by SMD (i.e. if there is SMD then we likely want to overwhelm the target hence want to fire multiple nukes at the same location)

                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of recently nuked locations empty='..tostring(AiBotUtilities.IsTableEmpty(tRecentlyNuked))..'; tLocation='..repru(tLocation)) end
                                if AiBotUtilities.IsTableEmpty(tRecentlyNuked) then return true
                                else
                                    for iTimeSinceFired, tRecentLocation in tRecentlyNuked do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering tLocation='..repru(tLocation)..'; Distance to tRecentLocation='..AiBotUtilities.GetDistanceBetweenPositions(tLocation, tRecentLocation)..'; is smd blocking targeet='..tostring(IsSMDBlockingTarget(aiBrain, tLocation, oLauncher:GetPosition(), 180, 0))..'; iTimeSinceFired='..iTimeSinceFired) end
                                        --if iTimeSinceFired <= iMinDelayBetweenNukes then --(incorporated into refreshrecentlynukedlocations)
                                        if AiBotUtilities.GetDistanceBetweenPositions(tLocation, tRecentLocation) <= 50 then
                                            return false
                                            --[[ Old logic (removed v46 and replaced with iMinDelayBetweenNukes)
                                            if bIgnoreIfCoveredBySMD then
                                                if IsSMDBlockingTarget(aiBrain, tLocation, oLauncher:GetPosition(), 60, 0) then
                                                    return true --we have fired here recently but we want to fire multiple nukes to overwhelm smd
                                                else
                                                    return false --we have fired here recently and there's no smd to overwhelm
                                                end
                                            else
                                                return false --we have fired here recently and dont care about overwhelming smd
                                            end--]]
                                        end
                                        --end
                                    end
                                end
                                return true --we havent fired here recently
                            end

                            --Decide whether to value destroying reclaim
                            local iReclaimFactor
                            if AiBotUtilities.IsTableEmpty(AiBotMap.tiVeryHighValueReclaimSegments) == false and not(AiBotMap.bIsCampaignMap) then
                                iReclaimFactor = 0.4
                            end

                            --First get the best location if just target the start position or locations near here
                            if HaventRecentlyNukedLocation(AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain)) then--, not(bCheckForSMD)) then
                                iTimeSMDNeedsToHaveBeenBuiltFor = iTimeForSMDToBeConstructed + 190 - (AiBotUtilities.GetDistanceBetweenPositions( AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain), oLauncher:GetPosition()) / iMissileSpeed + 10)
                                --GetBestAOETarget(aiBrain, tBaseLocation,                              iAOE, iDamage, bOptionalCheckForSMD, tSMLLocationForSMDCheck, iOptionalTimeSMDNeedsToHaveBeenBuiltFor, iSMDRangeAdjust, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, iOptionalMaxDistanceCheckOptions, iMobileValueOverrideFactorWithin75Percent, iOptionalShieldReductionFactor, iOptionalReclaimFactor)
                                tTarget, iBestTargetValue = AiBotLogic.GetBestAOETarget(aiBrain, AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain), iAOE, iDamage, bCheckForSMD,        oLauncher:GetPosition(),    nil,                                    nil,                2,                                  2.5,                    nil,                            nil,                                        nil,                            iReclaimFactor)
                                RecordHaveConsideredNukeLocation(AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain), true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Not recently nuked primary enemy base, IsSMDBlockingTarget='..tostring(IsSMDBlockingTarget(aiBrain, tTarget, oLauncher:GetPosition(), iTimeSMDNeedsToHaveBeenBuiltFor))..'; bCheckForSMD='..tostring(bCheckForSMD)..'; iTimeSMDNeedsToHaveBeenBuiltFor='..iTimeSMDNeedsToHaveBeenBuiltFor) end
                            end

                            --Cycle through other start positions to see if can get a better target, but reduce value of target if we havent scouted it in the last 5 minutes
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Considering best target for nuke.  If target enemy base then iBestTargetValue='..iBestTargetValue..'; bCheckForSMD='..tostring(bCheckForSMD))
                            end
                            local iPlateauOrZero, iLandOrWaterZone
                            local bAbortLoop = false
                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
                                local tEnemyStartPosition =  AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()]
                                if (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tEnemyStartPosition)) and AiBotUtilities.GetDistanceBetweenPositions(tEnemyStartPosition, AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain)) >= 30 then
                                    --Have we scouted this location recently or do we have radar coverage
                                    local tLZOrWZTeamData
                                    iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tEnemyStartPosition)
                                    if iPlateauOrZero > 0 then
                                        tLZOrWZTeamData  = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                                    else
                                        --Water zone
                                        tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                                    end


                                    if bDebugMessages == true then LOG(sFunctionRef..': Cycling through start points, considering brain '..(oBrain.Nickname or 'nil')..' with start point '..repru(tEnemyStartPosition)) end
                                    if GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or -1000) <= 300 or tLZOrWZTeamData[AiBotMap.refiRadarCoverage] >= 20 then
                                        iCurNukeSegmentX, iCurNukeSegmentZ = GetNukeSegmentsFromPosition(tEnemyStartPosition)
                                        if not(tiNukeSegmentsConsidered[iCurNukeSegmentX][iCurNukeSegmentZ]) then
                                            if HaventRecentlyNukedLocation(tEnemyStartPosition) then --, not(bCheckForSMD)) then
                                                RecordHaveConsideredNukeLocation(tEnemyStartPosition, false)
                                                --GetDamageFromBomb(aiBrain, tBaseLocation,         iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor)
                                                iCurTargetValue = AiBotLogic.GetDamageFromBomb(aiBrain, tEnemyStartPosition, iAOE, iDamage,   2,                                  2.5                     , nil,                          nil,                nil,                            nil,                                        false,                  nil,                            true,                       nil,                                    nil,                    iReclaimFactor)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering the start position '..repru( tEnemyStartPosition)..'; value ignroign SMD='..iCurTargetValue) end
                                                if iCurTargetValue > iBestTargetValue then
                                                    iTimeSMDNeedsToHaveBeenBuiltFor = iTimeForSMDToBeConstructed + 190 - (AiBotUtilities.GetDistanceBetweenPositions( tEnemyStartPosition, oLauncher:GetPosition()) / iMissileSpeed + 10)
                                                    if IsSMDBlockingTarget(aiBrain,  tEnemyStartPosition, oLauncher:GetPosition(), iTimeSMDNeedsToHaveBeenBuiltFor) then
                                                        iCurTargetValue = 4000
                                                        if bDebugMessages == true then LOG(sFunctionRef..': SMD is blocking target so reducing value to 4k. iTimeSMDNeedsToHaveBeenBuiltFor='..iTimeSMDNeedsToHaveBeenBuiltFor) end
                                                    end
                                                    if iCurTargetValue > iBestTargetValue then
                                                        bAlreadyConsideredBestAOETarget = false
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have a better start position target, dealing damage of '..iCurTargetValue..' vs prev best value of '..iBestTargetValue..'; iTimeSMDNeedsToHaveBeenBuiltFor='..iTimeSMDNeedsToHaveBeenBuiltFor) end
                                                        iBestTargetValue = iCurTargetValue
                                                        tTarget = {tEnemyStartPosition[1], tEnemyStartPosition[2], tEnemyStartPosition[3]}
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            function ConsiderPotentialNukeLocation(tLocationToConsiderNuke, bOverrideCheckForSMD, iOptionalMobileOverrideFactor)
                                iCurNukeSegmentX, iCurNukeSegmentZ = GetNukeSegmentsFromPosition(tLocationToConsiderNuke)
                                if not(tiNukeSegmentsConsidered[iCurNukeSegmentX][iCurNukeSegmentZ]) then
                                    if HaventRecentlyNukedLocation(tLocationToConsiderNuke) then --, not(bOverrideCheckForSMD)) then
                                        RecordHaveConsideredNukeLocation(tLocationToConsiderNuke, false)
                                        if (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLocationToConsiderNuke)) then
                                            --GetDamageFromBomb(aiBrain, tBaseLocation,         iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor)
                                            iCurTargetValue = AiBotLogic.GetDamageFromBomb(aiBrain, tLocationToConsiderNuke, iAOE, iDamage,   2,                                  2.5,                    nil,                            nil,                nil,                            iOptionalMobileOverrideFactor,                  false,              nil,                            true,                       nil,                                    nil,                    iReclaimFactor)
                                            if bDebugMessages == true then LOG(sFunctionRef..': tLocationToConsiderNuke='..repru(tLocationToConsiderNuke)..'; iCurTargetValue='..iCurTargetValue..'; iPositionsConsideredThisTick='..iPositionsConsideredThisTick) end
                                            --Stop looking if tried >=10 targets and have one that is at least 20k of value
                                            if iCurTargetValue > iBestTargetValue then
                                                iTimeSMDNeedsToHaveBeenBuiltFor = iTimeForSMDToBeConstructed + 190 - (AiBotUtilities.GetDistanceBetweenPositions( tLocationToConsiderNuke, oLauncher:GetPosition()) / iMissileSpeed + 10)
                                                if bOverrideCheckForSMD and IsSMDBlockingTarget(aiBrain, tLocationToConsiderNuke, oLauncher:GetPosition(), iTimeSMDNeedsToHaveBeenBuiltFor) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': SMD is blocking the unit target '..repru(tLocationToConsiderNuke)..'; will limit damage to 4k; iTimeSMDNeedsToHaveBeenBuiltFor='..iTimeSMDNeedsToHaveBeenBuiltFor) end
                                                    iCurTargetValue = 4000 end
                                                if iCurTargetValue > iBestTargetValue then
                                                    bAlreadyConsideredBestAOETarget = false
                                                    iBestTargetValue = iCurTargetValue
                                                    tTarget = tLocationToConsiderNuke
                                                    if bDebugMessages == true then LOG(sFunctionRef..': New best target with value='..iBestTargetValue..'; iTimeSMDNeedsToHaveBeenBuiltFor='..iTimeSMDNeedsToHaveBeenBuiltFor) end
                                                end
                                            end
                                            --Note: Mass value of mexes is doubled, so 3 T3 mexes would give a value of 27600
                                            if iPositionsConsideredThisTick >= 8 and iBestTargetValue >= iAbortThreshold then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have a target with a decent amount of value and have already tried quite a few units.  iBestTargetValue='..iBestTargetValue..'; iPositionsConsideredThisTick='..iPositionsConsideredThisTick) end
                                                bAbortLoop = true
                                            end
                                        end
                                    end
                                end
                                --Spread out calculations over a number of ticks due to their intesnity
                                if iPositionsConsideredThisTick >= 10 and not(bAbortLoop) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considered '..iPositionsConsideredThisTick..' targets, will wait 1 tick before considering more for performance reasons. iBestTargetValue='..iBestTargetValue) end
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    WaitTicks(1)
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                    RefreshRecentlyNukedLocations()
                                    iPositionsConsideredThisTick = 0
                                    iTotalWaitCount = iTotalWaitCount + 1
                                    if not(AiBotUnitInfo.IsUnitValid(oLauncher)) then
                                        tTarget = nil
                                        bAbortLoop = true
                                    end
                                    --Lower requirements to stop searching over time
                                    if iTotalWaitCount >= 20 then
                                        iAbortThreshold = iAbortThreshold * 0.95
                                        if iTotalWaitCount >= 100 then
                                            iAbortThreshold = math.min(iAbortThreshold * 0.95, 1000)
                                            if iTotalWaitCount >= 150 then bAbortLoop = true end
                                        end
                                        if iBestTargetValue >= iAbortThreshold then bAbortLoop = true end
                                    end
                                end
                            end

                            function ConsiderTableOfPotentialTargets(tEnemyUnitsOfInterest, bOverrideCheckForSMD, iOptionalMobileOverrideFactor)
                                if AiBotUtilities.IsTableEmpty(tEnemyUnitsOfInterest) == false then
                                    for iUnit, oUnit in tEnemyUnitsOfInterest do
                                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iPositionsConsideredThisTick='..iPositionsConsideredThisTick..'; Have we recently nuked this location='..tostring((HaventRecentlyNukedLocation(oUnit:GetPosition())))) end
                                            ConsiderPotentialNukeLocation(oUnit:GetPosition(), bOverrideCheckForSMD, iOptionalMobileOverrideFactor)
                                            if bAbortLoop then break end
                                        end
                                    end
                                end
                            end

                            --Consider a defensive nuke as well if enemy has land experimentals or battleships that are relatively near a friendly base - treat as higher value than normal where not covered by SMD (e.g. if have yolona then only want defensive nukes if expect the nuke to land)
                            local tEnemyClosestLandAndNavalThreats = {}
                            local iDefensiveThreshold = 350
                            local iBestValueOfDefensiveNuke = 0
                            local iDefensiveNukePlateauAndZone = {}
                            if AiBotMap.iMapSize <= 512 then iDefensiveThreshold = 260 end
                            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oLauncher:GetPosition(), true, iTeam)
                            if tLZTeamData then
                                iDefensiveThreshold = math.max(125, math.min(iDefensiveThreshold, AiBotUtilities.GetDistanceBetweenPositions(oLauncher:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])) * 0.475)
                            end
                            local iCurUnitPlateauOrZero, iCurUnitZone
                            local toClosestEnemyUntisByPlateauAndZone = {}

                            if bDebugMessages == true then LOG(sFunctionRef..': Considering priority enemy land threats near our base, is table of enemy land experimenatls empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))) end
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                                for iUnit, oUnit in  AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        iCurUnitPlateauOrZero, iCurUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                        if (iCurUnitZone or 0) > 0 and (iCurUnitPlateauOrZero or -1) >= 0 then
                                            local tUnitLZOrWZData, tUnitLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' that is '..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tUnitLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])..' dist to the closest friendly base; iDefensiveThreshold='..iDefensiveThreshold) end
                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tUnitLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= iDefensiveThreshold then
                                                table.insert(tEnemyClosestLandAndNavalThreats, oUnit)
                                                if not(toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero]) then toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero] = {} end
                                                if not(toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero][iCurUnitZone]) then toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero][iCurUnitZone] = {} end
                                                table.insert(toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero][iCurUnitZone], oUnit)
                                            end
                                        end
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyBattleships]) == false then
                                for iUnit, oUnit in  AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyBattleships] do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        iCurUnitPlateauOrZero, iCurUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                        if (iCurUnitZone or 0) > 0 and (iCurUnitPlateauOrZero or -1) >= 0 then
                                            local tUnitLZOrWZData, tUnitLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tUnitLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= iDefensiveThreshold then
                                                table.insert(tEnemyClosestLandAndNavalThreats, oUnit)
                                                if not(toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero]) then toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero] = {} end
                                                if not(toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero][iCurUnitZone]) then toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero][iCurUnitZone] = {} end
                                                table.insert(toClosestEnemyUntisByPlateauAndZone[iCurUnitPlateauOrZero][iCurUnitZone], oUnit)
                                            end
                                        end
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tEnemyClosestLandAndNavalThreats) == false then
                                local iMassValueOfThreats = AiBotUnitInfo.GetMassCostOfUnits(tEnemyClosestLandAndNavalThreats, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Mass value of nearby threats='..iMassValueOfThreats) end
                                if iMassValueOfThreats * 2 > iBestTargetValue and iMassValueOfThreats > 24000 then
                                    --Go through the actual zones and consider targeting units in here, but always checking for SMD even with yolona
                                    for iPlateauOrZero, tSubtable in toClosestEnemyUntisByPlateauAndZone do
                                        for iZone, tUnits in tSubtable do
                                            if AiBotUnitInfo.GetMassCostOfUnits(tUnits, true) >= 24000 then
                                                local iBestValuePreCheck = iBestTargetValue
                                                if bDebugMessages == true then LOG(sFunctionRef..': Best target value pre check for experimental land untis in P'..iPlateauOrZero..'Z'..iZone..'='..iBestTargetValue) end
                                                ConsiderTableOfPotentialTargets(tUnits, true, 0.8)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Best target value post check for experimental land untis in P'..iPlateauOrZero..'Z'..iZone..'='..iBestTargetValue) end
                                                if iBestTargetValue > iBestValuePreCheck then
                                                    iBestValueOfDefensiveNuke = iBestTargetValue
                                                    iDefensiveNukePlateauAndZone = {iPlateauOrZero, iZone}
                                                end
                                            end
                                        end
                                    end
                                end
                            end



                            if bDebugMessages == true then LOG(sFunctionRef..': iBestTargetValue for enemy base='..iBestTargetValue..'; if <80k then will consider other targets. tTarget='..repru(tTarget)..'; iBestValueOfDefensiveNuke='..iBestValueOfDefensiveNuke) end
                            if iBestTargetValue < 80000 and (not(oLauncher[AiBotUnitInfo.refbEasyBrain]) or iBestTargetValue < 30000) then --If have high value location for nearest enemy start then just go with this
                                --Consider high reclaim segments
                                if AiBotUtilities.IsTableEmpty(AiBotMap.tiVeryHighValueReclaimSegments) == false then
                                    for iEntry, tSegmentXZ in AiBotMap.tiVeryHighValueReclaimSegments do
                                        local tSegmentMidpoint = AiBotMap.GetReclaimLocationFromSegment(tSegmentXZ[1], tSegmentXZ[2])
                                        local tReclaimLZData, tReclaimLZTeamData = AiBotMap.GetLandOrWaterZoneData(tSegmentMidpoint, true, iTeam)
                                        if tReclaimLZTeamData[AiBotMap.refiModDistancePercent] > 0.6 then --If changing 0.6 threshold also update getdamagefrombomb
                                            ConsiderPotentialNukeLocation(tSegmentMidpoint, bCheckForSMD)
                                            if bAbortLoop then break end
                                        end
                                    end
                                end



                                for iRef, iCategory in tEnemyCategoriesOfInterest do
                                    ConsiderTableOfPotentialTargets(aiBrain:GetUnitsAroundPoint(iCategory, oLauncher:GetPosition(), iMaxRange, 'Enemy'), bCheckForSMD)

                                end
                                if iBestTargetValue > iBestValueOfDefensiveNuke then
                                    --GetBestAOETarget(aiBrain, tBaseLocation, iAOE, iDamage, bOptionalCheckForSMD, tSMLLocationForSMDCheck, iOptionalTimeSMDNeedsToHaveBeenBuiltFor, iSMDRangeAdjust, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, iOptionalMaxDistanceCheckOptions, iMobileValueOverrideFactorWithin75Percent, iOptionalShieldReductionFactor, iOptionalReclaimFactor)

                                    if tTarget then
                                        local tOldTarget = {tTarget[1], tTarget[2], tTarget[3]}
                                        local iOldTargetValue = iBestTargetValue
                                        if bDebugMessages == true then
                                            local iTargetPlateauOrZero, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tTarget)
                                            LOG(sFunctionRef..': Have a best target, tTarget before getting best aoe target='..repru(tTarget)..'; iTargetPlateauOrZero='..(iTargetPlateauOrZero or 'nil')..'; iTargetZone='..(iTargetZone or 'nil'))
                                        end
                                        --function GetBestAOETarget(aiBrain, tBaseLocation, iAOE, iDamage, bOptionalCheckForSMD, tSMLLocationForSMDCheck, iOptionalTimeSMDNeedsToHaveBeenBuiltFor, iSMDRangeAdjust, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, iOptionalMaxDistanceCheckOptions, iMobileValueOverrideFactorWithin75Percent, iOptionalShieldReductionFactor, iOptionalReclaimFactor)
                                        tTarget, iBestTargetValue = AiBotLogic.GetBestAOETarget(aiBrain, tTarget,         iAOE, iDamage, bCheckForSMD,        oLauncher:GetPosition(), nil,                                       nil,                2,                                      2.5,                    nil,                            nil,                                        nil,                            iReclaimFactor, true)
                                        --Redundancy for cases where best AOE target actually gives a worse outcome (hopefully ahve fixed issue in getbestaoe target to avoid this, so below is to be safe
                                        if bDebugMessages == true then LOG(sFunctionRef..': iBestTargetValue after getting best aoe target='..iBestTargetValue..'; iOldTargetValue='..iOldTargetValue) end
                                        if iBestTargetValue < iOldTargetValue then
                                            --Redundancy - make sure are comparing like with like
                                            local iRevisedTargetSimpleValue = AiBotLogic.GetDamageFromBomb(aiBrain, tTarget, iAOE, iDamage,       nil,                                nil,                true,                           nil,                nil,                            nil,                                        false,              nil,                            true,                               nil,                                nil,                    nil)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Revised target simple value='..iRevisedTargetSimpleValue..'; iBestTargetValue='..iBestTargetValue) end
                                            if iRevisedTargetSimpleValue < iBestTargetValue then
                                                tTarget = {tOldTarget[1], tOldTarget[2], tOldTarget[3]}
                                                iBestTargetValue = iOldTargetValue
                                                if bDebugMessages == true then LOG(sFunctionRef..': have switched to old target') end
                                            else
                                                --Increase old value target (so more likely to fire)
                                                iBestTargetValue = iOldTargetValue
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iBestTargetValue after getting best location='..iBestTargetValue..'; Best location for this target='..repru(tTarget)) end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': If value is <14k then will clear target unless have yolona; iBestTargetValue='..iBestTargetValue..'; tTarget='..repru(tTarget or {'nil'})) end
                            if iBestTargetValue < 20000 then --Mex is 4.6k base, with a 1.75 factor is 8050; with mass storage would be 9450; therefore if want to hit 3+ mex equivalents with a nuke, min value should be at least 19k (just over 2 capped T3 mexes)
                                if iBestTargetValue < 2000 or (not(EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId)) and (iBestTargetValue <= 15000 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]))) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': CLearing target as not valuable enough') end
                                    tTarget = nil
                                end
                            end --Increased vs M27 as will only apuse if no target


                            function ChangeTargetToClosestUnitToLauncher(tUnitsToConsider, iOptionalLeadingDistanceBaseAdjust)
                                local iClosestEnemyDist = 100000
                                local oClosestEnemyUnit
                                local iCurEnemyDist
                                local iBaseLeadingDistance = iOptionalLeadingDistanceBaseAdjust or iAOE * 0.7
                                for iUnit, oUnit in tUnitsToConsider do
                                    iCurEnemyDist = AiBotUtilities.GetDistanceBetweenPositions(oLauncher:GetPosition(), oUnit:GetPosition())
                                    if iCurEnemyDist < iClosestEnemyDist then
                                        iClosestEnemyDist = iCurEnemyDist
                                        oClosestEnemyUnit = oUnit
                                    end
                                end
                                if oClosestEnemyUnit then
                                    --Base target is this unit
                                    local tPotentialAltTarget = oClosestEnemyUnit:GetPosition()
                                    --Ajdust for unit facing direction if it is moving
                                    local iUnitFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oClosestEnemyUnit)
                                    if oClosestEnemyUnit:IsUnitState('Moving') then
                                        tPotentialAltTarget = AiBotUtilities.MoveInDirection(oClosestEnemyUnit:GetPosition(), AiBotUnitInfo.GetUnitFacingAngle(oClosestEnemyUnit), iBaseLeadingDistance, true, false, true)
                                    end
                                    --Check the value of this isn't negative (due to friendly fire)
                                    --GetDamageFromBomb(aiBrain, tBaseLocation,     iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor)
                                    if AiBotLogic.GetDamageFromBomb(aiBrain, tPotentialAltTarget, iAOE, iDamage,   2,                                  2.5,                    nil,                            nil,                nil,                            0.6,                                       nil,                    nil,                            true,                           nil,                                nil,                    iReclaimFactor) > 0 then
                                        tTarget = tPotentialAltTarget
                                        --Adjust the target further if it is far away
                                        local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tTarget, oLauncher:GetPosition())
                                        if iCurDist >= 300 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Target is far away so will adjust further, tTarget pre adjust='..repru(tTarget)) end
                                            tTarget = AiBotUtilities.MoveInDirection(tTarget, iUnitFacingAngle, math.min(iBaseLeadingDistance, (iCurDist - 300) / 30), true, false, true)
                                            if bDebugMessages == true then LOG(sFunctionRef..': tTarget post adjust='..repru(tTarget)) end
                                        end
                                    end

                                    if bDebugMessages == true then LOG(sFunctionRef..': tPotentialAltTarget='..repru(tPotentialAltTarget)..'; tTarget after update='..repru(tTarget)..' based on oClosestEnemyUnit='..oClosestEnemyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyUnit)..' at position '..repru(oClosestEnemyUnit:GetPosition())..' with unit state='..AiBotUnitInfo.GetUnitState(oClosestEnemyUnit)..' and facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oClosestEnemyUnit)..'; iAOE='..iAOE..'; Damage of bomb at potential target='..AiBotLogic.GetDamageFromBomb(aiBrain, tPotentialAltTarget, iAOE, iDamage,   2,                                  2.5,                    nil,                            nil,                nil,                            0.6)) end
                                end
                            end

                            if tTarget and iBestTargetValue <= iBestValueOfDefensiveNuke and AiBotUtilities.IsTableEmpty(toClosestEnemyUntisByPlateauAndZone) == false and AiBotUtilities.IsTableEmpty(toClosestEnemyUntisByPlateauAndZone[toClosestEnemyUntisByPlateauAndZone[1]][toClosestEnemyUntisByPlateauAndZone[2]]) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will launch a defensive nuke, positio before adjust='..repru(tTarget)) end
                                --Doing a defensive nuke so target the enemy unit nearest us, and adjust slightly for its facing direction
                                ChangeTargetToClosestUnitToLauncher(toClosestEnemyUntisByPlateauAndZone[toClosestEnemyUntisByPlateauAndZone[1]][toClosestEnemyUntisByPlateauAndZone[2]])
                            elseif AiBotUtilities.IsTableEmpty(tTarget) == false then
                                --Still check if significant threat is made of mobile units

                                local tTargetZoneData, tTargetZoneTeamData = AiBotMap.GetLandOrWaterZoneData(tTarget, true, iTeam)
                                if bDebugMessages == true then LOG(sFunctionRef..': Arent firing as a defensvie unit, checking structure value in zone, tTargetZoneTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]='..(tTargetZoneTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')) end
                                if (tTargetZoneTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) <  iBestTargetValue * 0.5 then
                                    --Are there enemy experimentals or battleships in this zone?
                                    local tEnemyExperimentalsAndBattleships = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryNavalSurface * categories.BATTLESHIP,tTargetZoneTeamData[AiBotMap.subrefTEnemyUnits])
                                    AiBotConditions.IsTableOfUnitsStillValid(tEnemyExperimentalsAndBattleships)
                                    if AiBotUtilities.IsTableEmpty(tEnemyExperimentalsAndBattleships) then
                                        tEnemyExperimentalsAndBattleships = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryNavalSurface * categories.BATTLESHIP, tTarget, iAOE, 'Enemy')
                                        if bDebugMessages == true then LOG(sFunctionRef..': No enemy experimentals in the zone being targeting, is units around point empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyExperimentalsAndBattleships))) end
                                    end
                                    if AiBotUtilities.IsTableEmpty( tEnemyExperimentalsAndBattleships) == false then
                                        local bHaveMobileUnitsAndNoUnderConstruction = false
                                        local bHaveAttackingOrPatrollingUnits = false

                                        for iUnit, oUnit in tEnemyExperimentalsAndBattleships do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Checking enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Dead='..tostring(oUnit.Dead or false)) end
                                            if oUnit:GetFractionComplete() < 1 and oUnit:GetFractionComplete() >= 0.05 then
                                                bHaveMobileUnitsAndNoUnderConstruction = false
                                                break
                                            else
                                                if oUnit:IsUnitState('Moving') then
                                                    bHaveMobileUnitsAndNoUnderConstruction = true
                                                elseif oUnit:IsUnitState('Attacking') or oUnit:IsUnitState('Patrolling') then
                                                    bHaveAttackingOrPatrollingUnits = true
                                                end
                                            end
                                        end
                                        local iDistanceAdjust
                                        if bHaveMobileUnitsAndNoUnderConstruction then iDistanceAdjust = iAOE * 0.75
                                        elseif bHaveAttackingOrPatrollingUnits then iDistanceAdjust = iAOE * 0.45
                                        end
                                        if iDistanceAdjust then
                                            if bDebugMessages == true then LOG(sFunctionRef..': tTarget before updating to nearest experimental or battleship='..repru(tTarget)) end
                                            ChangeTargetToClosestUnitToLauncher(tEnemyExperimentalsAndBattleships)
                                            if bDebugMessages == true then LOG(sFunctionRef..': tTarget after updating to nearest experimental or battleship='..repru(tTarget)) end
                                        end
                                    end
                                end
                            end
                            --Yolona target SMD that will stop us, if there are any, instead of our actual target, so we dont risk trying to take on loads of SMD in one go
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Checking if we are a yolona in which case we want to target any blocking SMD first, tTarget='..repru(tTarget)..'; bCheckForSMD='..tostring(bCheckForSMD)..'; Yolona='..tostring(EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId))..'; Is table of enemy SMD empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]))..'; If enemy has more than 1 SMD will consider targeting SMD instead of the best target for the missile')
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) == false then LOG(sFunctionRef..': Number of enemy SMD='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD])) end
                            end
                            if tTarget and not(bCheckForSMD) and EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) == false then
                                --WOrk out which SMD are intercepting our missile
                                local tSMDBlockingTarget = IsSMDBlockingTarget(aiBrain, tTarget, oLauncher:GetPosition(), 60, 0, true)
                                if bDebugMessages == true then
                                    LOG(sFunctionRef..': Is table of enemy SMD blocking target empty='..tostring(AiBotUtilities.IsTableEmpty(tSMDBlockingTarget)))
                                    if AiBotUtilities.IsTableEmpty(tSMDBlockingTarget) == false then LOG(sFunctionRef..': Number of SMD blocking target='..table.getn(tSMDBlockingTarget)) end
                                end
                                --Only target down SMD if we have 2+ SMD or a loaded SMD blocking our desired target (otherwise it may be better to just ignore)
                                if AiBotUtilities.IsTableEmpty(tSMDBlockingTarget) == false then
                                    local bLotsOfSMDOrLoaded = false
                                    if table.getn(tSMDBlockingTarget) >= 4 then
                                        bLotsOfSMDOrLoaded = true
                                    else
                                        local iSMDCount = 0
                                        for iBlockingSMD, oBlockingSMD in tSMDBlockingTarget do

                                            if oBlockingSMD:GetFractionComplete() == 1 then
                                                iSMDCount = iSMDCount + 1
                                                if oBlockingSMD:GetTacticalSiloAmmoCount() > 0 then
                                                    bLotsOfSMDOrLoaded = true
                                                end
                                            end
                                        end
                                        if not(bLotsOfSMDOrLoaded) and iSMDCount >= 2 then
                                            bLotsOfSMDOrLoaded = true
                                        end
                                    end
                                    if bLotsOfSMDOrLoaded then
                                        bHaveBlockingSMD = true
                                        local tAltTarget = GetBestAOETargetForSpecifiedBuildings(aiBrain, iTeam, oLauncher:GetPosition(), tSMDBlockingTarget, iAOE, iDamage)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Yolona target will be intercepted by SMD, want to take out the nearest blocking SMD first, tTarget='..repru(tTarget)..'; tAltTarget after facotirng in blockgin SMD='..repru(tAltTarget)) end
                                        if tAltTarget then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will now draw ttarget and talttarget, tTarget will be in blue, tAltTarget will be in gold')
                                                AiBotUtilities.DrawLocation(tTarget)
                                                AiBotUtilities.DrawLocation(tAltTarget, 4)
                                            end

                                            tTarget = tAltTarget
                                        end
                                    end
                                end
                            elseif not(tTarget) and EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) == false then
                                local tPotentialSMDTargets = {}
                                for iRecordedSMD, oRecordedSMD in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD] do
                                    if AiBotUnitInfo.IsUnitValid(oRecordedSMD) and oRecordedSMD:GetFractionComplete() >= 0.9 then
                                        table.insert(tPotentialSMDTargets, oRecordedSMD)
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Is tPotentialSMDTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialSMDTargets))) end
                                if AiBotUtilities.IsTableEmpty(tPotentialSMDTargets) == false then
                                    if table.getn(tPotentialSMDTargets) == 1 then
                                        tTarget = tPotentialSMDTargets[1]:GetPosition()
                                    else
                                        local bHaveNonRecentTarget = false
                                        for iRecordedSMD, oRecordedSMD in tPotentialSMDTargets do
                                            if not(HaventRecentlyNukedLocation(oRecordedSMD:GetPosition())) then
                                                tTarget = oRecordedSMD:GetPosition()
                                                bHaveNonRecentTarget = true
                                                break
                                            end
                                        end
                                        if not(bHaveNonRecentTarget) and not(tTarget) then tTarget = tPotentialSMDTargets[1]:GetPosition() end
                                    end
                                end
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to launch at time '..GetGameTimeSeconds()..', tTarget='..repru(tTarget)) end
                        if oLauncher.Dead then
                            if bDebugMessages == true then LOG(sFunctionRef..': Launcher is dead now') end
                        elseif tTarget then
                            --Launch missile
                            if bDebugMessages == true then LOG(sFunctionRef..': Will launch missile at tTarget='..repru(tTarget)..'; Cur time='..GetGameTimeSeconds()) end
                            if bTML then
                                --Adjust target it outside our range but inside our AOE
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oLauncher.UnitId) then --redundancy to make sure not dealing with mobile unit
                                    local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tTarget, oLauncher:GetPosition())
                                    if iDistToTarget > oLauncher[AiBotUnitInfo.refiManualRange] then
                                        if iDistToTarget - oLauncher[AiBotUnitInfo.refiManualRange] > oLauncher[AiBotUnitInfo.refiIndirectAOE] then
                                            AiBotUtilities.ErrorHandler('Have a TML launcher with a target outside its range+manual range')
                                        else
                                            tTarget = AiBotUtilities.MoveInDirection(oLauncher:GetPosition(), AiBotUtilities.GetAngleFromAToB(oLauncher:GetPosition(), tTarget), oLauncher[AiBotUnitInfo.refiManualRange] - 0.01)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Updating target so we can hit the actual target with our aoe, tTarget='..repru(tTarget)..'; iDistToTarget pre this adjust='..iDistToTarget) end
                                        end
                                    end
                                end
                                AiBotOrders.IssueTrackedTMLMissileLaunch(oLauncher, tTarget, 0.25, false, 'TMLFire', true)
                                if AiBotUnitInfo.GetMissileCount(oLauncher) <= 1 then
                                    --oLauncher:SetAutoMode(true)
                                    AiBotUnitInfo.SetUnitMissileAutoBuildStatus(oLauncher, true)
                                end
                                --oLauncher:SetPaused(false)
                                AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(oLauncher, false)
                                if bDebugMessages == true then
                                    local tExpectedMissileVertical = AiBotUtilities.MoveInDirection(oLauncher:GetPosition(), AiBotUtilities.GetAngleFromAToB(oLauncher:GetPosition(), tTarget), 31, true)
                                    tExpectedMissileVertical[2] = tExpectedMissileVertical[2] + 60 --Doing testing, it actually only goes up by 50, but I think it travels in an arc from here to the target, as in a test scenario doing at less than +60 meant it thought it would hit a cliff when it didnt
                                    local bShotBlocked = AiBotLogic.IsLineBlocked(aiBrain, tExpectedMissileVertical, tTarget, iAOE, false)
                                    LOG(sFunctionRef..': Just launched tactical missile at tTarget='..repru(tTarget)..'; oLauncher position='..repru(oLauncher:GetPosition())..'; dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oLauncher:GetPosition(), tTarget)..'; launcher range='..oLauncher[AiBotUnitInfo.refiManualRange]..'; bShotBlocked='..tostring(bShotBlocked))
                                    --[[local iColour = 1
                                    if bShotBlocked then iColour = 2 end
                                    AiBotUtilities.DrawLocation(tTarget, nil, iColour)--]] --drawing locations will desync a replay, so only want to manually enable this debugging where we need it
                                end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a nuke target, tTarget='..repru(tTarget)..'; have we not recently nuked this location='..tostring(HaventRecentlyNukedLocation(tTarget))..'; iTotalWaitCount='..iTotalWaitCount) end
                                if iTotalWaitCount >= 1 then
                                    if not(HaventRecentlyNukedLocation(tTarget)) then --, true, iTotalWaitCount * 0.1 + 2)) then
                                        --Presumably the target we chose as the best target is no longer appropriate because another nuke has just nuked it
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will wait 1 second then try getting a target again since we are about to nuke a location that we just nuked') end
                                        oLauncher[refbActiveMissileChecker] = false
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        WaitSeconds(1)
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                        tTarget = nil
                                        --LOG('Forked consideration of launching missile 1')
                                        ForkThread(ConsiderLaunchingMissile, oLauncher, oOptionalWeapon)
                                    end
                                end
                                if tTarget then
                                    if bDebugMessages == true then
                                        AiBotUtilities.DrawCircleAtTarget({ tTarget[1], tTarget[2], tTarget[3] }, 2, 200, iAOE)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Giving order to fire nuke at tTarget='..repru(tTarget)..'; Launcher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..' owend by brain '..oLauncher:GetAIBrain().Nickname..'; iBestTargetValue='..(iBestTargetValue or 'nil')..'; Is SMD blocking target='..tostring(IsSMDBlockingTarget(aiBrain, tTarget, oLauncher:GetPosition(), 60, 0))..'; Time='..GetGameTimeSeconds()) end
                                    end
                                    AiBotOrders.IssueTrackedNukeMissileLaunch(oLauncher, tTarget, 2, false, 'Nuke', false)
                                    --[[AiBotOrders.IssueTrackedClearCommands(oLauncher)
                                    IssueNuke({oLauncher}, tTarget)
                                    oLauncher[reftActiveNukeTarget] = {tTarget[1], tTarget[2], tTarget[3]}
                                    --Unpause incase we paused previously
                                    if oLauncher[refbPausedAsNoTargets] then
                                        oLauncher[refbPausedAsNoTargets] = false
                                        if AiBotUnitInfo.GetMissileCount(oLauncher) <= 1 then
                                            oLauncher:SetAutoMode(true)
                                        end
                                        oLauncher:SetPaused(false)
                                    end
                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] = {} end

                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][math.floor(GetGameTimeSeconds())] = tTarget--]]
                                    if not(bHaveBlockingSMD) then bHaveBlockingSMD = IsSMDBlockingTarget(aiBrain, tTarget, oLauncher:GetPosition(), 60, 0) end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Launching nuke at tTarget='..repru(tTarget)..'; bHaveBlockingSMD='..tostring(bHaveBlockingSMD)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations])..'; Time of game='..GetGameTimeSeconds()) end
                                    --Send a voice taunt if havent in last 10m and we expect to do significant damage
                                    if not(bHaveBlockingSMD) and iBestTargetValue >= (25000 + 5000 * AiBotChat.iNukeGloatingMessagesSent) then
                                        if AiBotOrders.bDontConsiderCombinedArmy or oLauncher.AiBotActive then
                                            AiBotChat.iNukeGloatingMessagesSent = AiBotChat.iNukeGloatingMessagesSent + 1
                                            ForkThread(AiBotChat.SendGloatingMessage, aiBrain, 20, 600)
                                        end
                                    elseif bHaveBlockingSMD then
                                        --Record that our last nuke target had a blocking SMD (so we allow any delay between nuke missiles)
                                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbSMDBlockingLastNukeTarget] = true
                                    end
                                end
                            end
                        else
                            --Disable autobuild and pause, and clear launcher
                            if not(oLauncher[refbPausedAsNoTargets]) and not(EntityCategoryContains(categories.EXPERIMENTAL, oLauncher.UnitId)) then
                                --Dont pause if we have loads of resources
                                if AiBotConditions.HaveLowPower(iTeam) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.8 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 25 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.99))) then
                                    oLauncher[refbPausedAsNoTargets] = true
                                    --oLauncher:SetAutoMode(false)
                                    --oLauncher:SetPaused(true)
                                    AiBotUnitInfo.SetUnitMissileAutoBuildStatus(oLauncher, false)
                                    AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(oLauncher, true)
                                    if oLauncher.UnitId == 'xsb2401' then AiBotUtilities.ErrorHandler('Pausing Yolona') end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Pausing unit '..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..' as have no targets') end
                                end
                            end
                            oLauncher[refbActiveMissileChecker] = false
                            AiBotOrders.IssueTrackedClearCommands(oLauncher)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitSeconds(iSecondsToWaitIfNoTarget)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            if bDebugMessages == true then LOG(sFunctionRef..': Have waited '..iSecondsToWaitIfNoTarget..' seconds, will now reconsider launching the missile, time='..GetGameTimeSeconds()) end
                            --LOG('Forked consideration of launching missile 2')
                            ForkThread(ConsiderLaunchingMissile, oLauncher, oOptionalWeapon)
                        end
                    end
                    --Already have an else error handler above so dont need below
                    --else AiBotUtilities.ErrorHandler('Unrecognised launcher type, UnitID='..(oLauncher.UnitId or 'nil')..'; wont consider launching a missile')
                end
                oLauncher[refbActiveMissileChecker] = false
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function IsSMDBlockingTarget(aiBrain, tTarget, tSMLPosition, iIgnoreSMDCreatedThisManySecondsAgo, iSMDRangeAdjust, bOptionalReturnTableOfBlockingSMD)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsSMDBlockingTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bEnemySMDInRange = false
    local iSMLToTarget = AiBotUtilities.GetDistanceBetweenPositions(tTarget, tSMLPosition)
    local iAngleSMLToTarget = AiBotUtilities.GetAngleFromAToB(tSMLPosition, tTarget)
    local iTargetToSMD

    local iSMLToSMD
    local iSMDRange
    local iAngleToSMD
    local bSMDInRangeOfMissile

    if bDebugMessages == true then LOG(sFunctionRef..': Considering tTarget='..repru(tTarget)..'; iIgnoreSMDCreatedThisManySecondsAgo='..(iIgnoreSMDCreatedThisManySecondsAgo or 1)..'; Current game time='..GetGameTimeSeconds()) end
    local iTeam = aiBrain.AiBotTeam
    local tBlockingSMD

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD]) == false then
        local iBuildRateMod = 1
        for iSMD, oSMD in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD] do
            if AiBotUnitInfo.IsUnitValid(oSMD) then
                --Update SMD time to complete tracker
                if oSMD:GetFractionComplete() < 1 then
                    oSMD[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - iTimeForSMDToBeConstructed * oSMD:GetFractionComplete()
                    if bDebugMessages == true then LOG(sFunctionRef..': Just updated oSMD as it is constructed now,  oSMD='..oSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSMD)..'; Owner='..oSMD:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
                end
                if iIgnoreSMDCreatedThisManySecondsAgo then iBuildRateMod = (oSMD:GetAIBrain()[AiBotEconomy.refiBrainBuildRateMultiplier] or 1) end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering oSMD='..oSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSMD)..'; Cur time less time of last check or -10='..GetGameTimeSeconds() - (oSMD[AiBotUnitInfo.refiTimeOfLastCheck] or (GetGameTimeSeconds() - 10))..'; iIgnoreSMDCreatedThisManySecondsAgo='..(iIgnoreSMDCreatedThisManySecondsAgo or 'nil')..'; iBuildRateMod='..iBuildRateMod..'; oSMD[AiBotUnitInfo.refiTimeOfLastCheck]='..(oSMD[AiBotUnitInfo.refiTimeOfLastCheck] or 'nil')) end
                if GetGameTimeSeconds() - (oSMD[AiBotUnitInfo.refiTimeOfLastCheck] or (GetGameTimeSeconds() - 10)) > (iIgnoreSMDCreatedThisManySecondsAgo or 0) / iBuildRateMod then

                    bSMDInRangeOfMissile = false
                    iSMDRange = (oSMD:GetBlueprint().Weapon[1].MaxRadius or 90) + 1 + (iSMDRangeAdjust or 0)
                    iTargetToSMD = AiBotUtilities.GetDistanceBetweenPositions(tTarget, oSMD:GetPosition())

                    iSMLToSMD = AiBotUtilities.GetDistanceBetweenPositions(oSMD:GetPosition(), tSMLPosition)
                    iAngleToSMD = AiBotUtilities.GetAngleFromAToB(tSMLPosition, oSMD:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': oSMD='..oSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSMD)..'; iTargetToSMD='..iTargetToSMD..'; iSMLToSMD='..iSMLToSMD..'; iSMLToTarget='..iSMLToTarget..'; iSMDRange='..iSMDRange..'; oSMD[M27UnitInfo.refiTimeOfLastCheck]='..(oSMD[AiBotUnitInfo.refiTimeOfLastCheck] or 'nil')..'; Distance from target to oSMD='..AiBotUtilities.GetDistanceBetweenPositions(tTarget, oSMD:GetPosition())..'; iSMDRange='..iSMDRange..'; iAngleToSMD='..iAngleToSMD..'; iAngleSMLToTarget='..iAngleSMLToTarget..'; SMD position='..repru(oSMD:GetPosition())..'; tSMLPosition='..repru(tSMLPosition)..'; TargetPos='..repru(tTarget)..'; iAngleFromAToB - iAngleFromAToC='..(iAngleSMLToTarget - iAngleToSMD)..'; ConvertAngleToRadians(iAngleFromAToB - iAngleFromAToC)='..AiBotUtilities.ConvertAngleToRadians(iAngleSMLToTarget - iAngleToSMD)..'; math.tan(math.abs(ConvertAngleToRadians(iAngleFromAToB - iAngleFromAToC)))='..math.tan(math.abs(AiBotUtilities.ConvertAngleToRadians(iAngleSMLToTarget - iAngleToSMD)))..'; iDistFromAToC='..iSMLToSMD..'; Tan result times this distance='..iSMLToSMD*math.tan(math.abs(AiBotUtilities.ConvertAngleToRadians(iAngleSMLToTarget - iAngleToSMD)))) end

                    bSMDInRangeOfMissile = AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iSMLToTarget, iSMLToSMD, iTargetToSMD, iAngleSMLToTarget, iAngleToSMD, iSMDRange)

                    if bSMDInRangeOfMissile then
                        if bDebugMessages == true then LOG(sFunctionRef..': SMD is in range and was built a while ago') end
                        bEnemySMDInRange = true
                        if not(bOptionalReturnTableOfBlockingSMD) then
                            break
                        else
                            if not(tBlockingSMD) then tBlockingSMD = {} end
                            table.insert(tBlockingSMD, oSMD)
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding SMD to table of blocking SMD') end
                        end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': SMD is not blocking the target')
                    end

                elseif bDebugMessages == true then LOG(sFunctionRef..': SMD was only recently built, time we think the SMD was active='..GetGameTimeSeconds() - (oSMD[AiBotUnitInfo.refiTimeOfLastCheck] or (GetGameTimeSeconds() - 10)))
                end
            end
        end
    elseif bDebugMessages == true then LOG(sFunctionRef..': No enemy SMD detected')
    end
    if bDebugMessages == true then LOG(sFunctionRef..': bEnemySMDInRange='..tostring(bEnemySMDInRange)..'; Is table of blocking SMD empty='..tostring(AiBotUtilities.IsTableEmpty(tBlockingSMD))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bOptionalReturnTableOfBlockingSMD then
        return tBlockingSMD
    else
        return bEnemySMDInRange
    end
end

function GetHighestNukeTargetValue(tLZOrWZData, tLZOrWZTeamData, iTeam)
    --Refresh list if havent calcualted before or SMD has been refreshed; returns highest value target
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if aiBrain then
            local iBestValue = 0
            local iCurValue

            function GetZoneValue(iEnemyStructureMass, iEnemyCombatThreat)
                return iEnemyStructureMass + iEnemyCombatThreat * 0.25
            end
            local tSMLPosition = tLZOrWZData[AiBotMap.subrefMidpoint]
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemySMDDiedSinceLastNukeCheck] then
                --Do full calculation
                tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones] = {}
                --Make sure we have recorded pathing in a straight line for this zone (will only run if table is empty)
                AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZOrWZData)
                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
                    AiBotUtilities.ErrorHandler('No other zones found')
                else
                    for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                        local tAltLZOrWZData
                        local tAltLZOrWZTeamData
                        local sMidpointRef
                        local sCombatThreatRef
                        local iCurPlateauOrPond
                        local iCurLZOrWZRef = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                            sMidpointRef = AiBotMap.subrefMidpoint
                            sCombatThreatRef = AiBotMap.subrefTThreatEnemyCombatTotal
                            tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                            iCurPlateauOrPond = 0
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        else
                            sMidpointRef = AiBotMap.subrefMidpoint
                            sCombatThreatRef = AiBotMap.subrefTThreatEnemyCombatTotal
                            iCurPlateauOrPond = tSubtable[AiBotMap.subrefiPlateauOrPond]
                            tAltLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrPond][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        end
                        if not(IsSMDBlockingTarget(aiBrain, tAltLZOrWZData[sMidpointRef], tSMLPosition, 0, 0)) then
                            --Have a valid target
                            table.insert(tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones], {iCurPlateauOrPond, iCurLZOrWZRef })
                            iCurValue = GetZoneValue(tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass], tAltLZOrWZTeamData[sCombatThreatRef])
                            if iCurValue > iBestValue then
                                iBestValue = iCurValue
                            end
                        end
                    end
                end
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemySMDBuiltSinceLastNukeCheck] then
                --Check existing values for if still valid
                local iExistingEntries = table.getn(tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones])
                for iEntry = iExistingEntries, 1, -1 do
                    local tAltLZOrWZData
                    local tAltLZOrWZTeamData
                    local sMidpointRef
                    local sCombatThreatRef
                    local iCurPlateauOrPond = tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones][iEntry][1]
                    local iCurLZOrWZRef = tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones][iEntry][2]

                    if iCurPlateauOrPond == 0 then
                        sMidpointRef = AiBotMap.subrefMidpoint
                        sCombatThreatRef = AiBotMap.subrefTThreatEnemyCombatTotal
                        tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                        tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                    else
                        sMidpointRef = AiBotMap.subrefMidpoint
                        sCombatThreatRef = AiBotMap.subrefTThreatEnemyCombatTotal
                        tAltLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrPond][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                        tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                    end
                    if IsSMDBlockingTarget(aiBrain, tAltLZOrWZData[sMidpointRef], tSMLPosition, 0, 0) then
                        --No longer have a valid target
                        table.remove(tLZOrWZTeamData[AiBotMap.subreftiPotentialNukeTargetZones], iEntry)
                    else
                        iCurValue = GetZoneValue(tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass], tAltLZOrWZTeamData[sCombatThreatRef])
                        if iCurValue > iBestValue then
                            iBestValue = iCurValue
                        end
                    end
                end
            end
            return iBestValue
        else
            AiBotUtilities.ErrorHandler('No alive AiBot brain')
            return 0
        end
    else
        AiBotUtilities.ErrorHandler('No active AiBot brains')
        return 0
    end
end

function RecheckForArtiTargetSoon(oArti)
    WaitSeconds(10)
    if AiBotUnitInfo.IsUnitValid(oArti) then
        AiBotUnitInfo.EnableUnitWeapon(oArti)
        GetT3ArtiTarget(oArti, false)
    end
end

function DontChangeCurrentScathisTarget(oArti)
    --returns true if we want to retain the current scathis target
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DontChangeCurrentScathisTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tLastOrder = oArti[AiBotOrders.reftiLastOrders][oArti[AiBotOrders.refiOrderCount]]
    local oCurTarget = tLastOrder[AiBotOrders.subrefoOrderUnitTarget]
    if AiBotUnitInfo.IsUnitValid(oCurTarget) then
        local iLowerTimeThreshold = 120
        local iUpperTimeThreshold = 300
        local iTimeSinceLastTargetAssessment = GetGameTimeSeconds() - (oArti[refiTimeLastGotBestArtiTarget] or -iUpperTimeThreshold)
        if bDebugMessages == true then LOG(sFunctionRef..': iTimeSinceLastTargetAssessment='..iTimeSinceLastTargetAssessment..'; oArti[refiLastTargetValue]='..(oArti[refiLastTargetValue] or 'nil')..'; tLastOrder[AiBotOrders.subreftOrderPosition]='..repru(tLastOrder[AiBotOrders.subreftOrderPosition])..'; oCurTarget='..(oCurTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oCurTarget) or 'nil')) end
        if iTimeSinceLastTargetAssessment < iUpperTimeThreshold and (iTimeSinceLastTargetAssessment < iLowerTimeThreshold or (oArti[refiLastTargetValue] or 0) >= 10000 + 30000 * (iUpperTimeThreshold - iTimeSinceLastTargetAssessment) / (iUpperTimeThreshold - iLowerTimeThreshold)) and (not(EntityCategoryContains(categories.MOBILE, tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId)) or AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]) <= 25) then
            IncreaseArtiShotCount(tLastOrder[AiBotOrders.subreftOrderPosition] or oCurTarget:GetPosition(), oArti:GetAIBrain().AiBotTeam)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function IncreaseArtiShotCount(tActualTarget, iTeam, iOptionalShotCountOverride)
    --Increase shot count
    local iAltPlateauOrZero, iAltLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tActualTarget)
    local tAltLZOrWZTeamData
    if iAltPlateauOrZero == 0 then
        tAltLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAltLZOrWZ]][AiBotMap.subrefPondWaterZones][iAltLZOrWZ][AiBotMap.subrefWZTeamData][iTeam]
    else
        tAltLZOrWZTeamData = AiBotMap.tAllPlateaus[iAltPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAltLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
    end

    tAltLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] = (tAltLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 0) + (iOptionalShotCountOverride or 1)
end

function DelayedScathisOrderChange(bAttackUnitNotGround, oArti, oBestTarget, tActualTarget)
    --E.g. for cases like LOUD where need to clear scathis orders when changing target to stop it moving around
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DelayedScathisOrderChange'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bWillIssueNewOrder = false

    local tLastOrder = oArti[AiBotOrders.reftiLastOrders][oArti[AiBotOrders.refiOrderCount]]
    if bAttackUnitNotGround then
        bWillIssueNewOrder = true
        if tLastOrder[AiBotOrders.subrefoOrderUnitTarget] == oBestTarget and tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack then bWillIssueNewOrder = false end
    else
        if tLastOrder[AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetRoughDistanceBetweenPositions(tLastOrder, tActualTarget) > 1 then bWillIssueNewOrder = true end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Scathis oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..'; bWillIssueNewOrder='..tostring(bWillIssueNewOrder or false)..'; oBestTarget='..(oBestTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget) or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if bWillIssueNewOrder then
        local tAllWeapons = oArti:GetBlueprint().Weapon
        local iUnpackTime = 0
        if tAllWeapons then
            for iWeapon, tWeapon in tAllWeapons do
                iUnpackTime = math.max(iUnpackTime, (tWeapon.WeaponUnpackTimeout or 0))
            end
        end
        local bTrackForMovement = false
        if bDebugMessages == true then LOG(sFunctionRef..': iUnpackTime='..iUnpackTime) end
        if iUnpackTime > 0 then
            bTrackForMovement = true
            AiBotOrders.IssueTrackedClearCommands(oArti)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iUnpackTime) --strangly when testing, if wait for unpack time + 1 tick, it causes scathis to move
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end

        function AttackOrigTarget(bQueuedOrder)
            if bDebugMessages == true then LOG(sFunctionRef..': About to issue attack order if target is still valid, is oBestTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oBestTarget))..'; Time='..GetGameTimeSeconds()) end
            if bAttackUnitNotGround then
                if AiBotUnitInfo.IsUnitValid(oBestTarget) then
                    AiBotOrders.IssueTrackedAttack(oArti, oBestTarget, bQueuedOrder, 'ScaAtU'..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget), false)
                else
                    bTrackForMovement = false
                end
            else
                AiBotOrders.IssueTrackedGroundAttack(oArti, tActualTarget, 1, bQueuedOrder, 'ArtiSGF'..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget), false, oBestTarget)
                --IncreaseArtiShotCount(tActualTarget, iTeam) --Dont call this here as woudlve already been called when doing the delayed order change
            end
        end
        AttackOrigTarget(false)

        if bTrackForMovement then
            --Redundancy - havent actually tested if it works as intended
            local iTimeToTrack = 5
            local iStartTime = GetGameTimeSeconds()
            while GetGameTimeSeconds() <= iStartTime + iTimeToTrack do
                WaitSeconds(1)
                if AiBotUnitInfo.IsUnitValid(oArti) and (not(bAttackUnitNotGround) or AiBotUnitInfo.IsUnitValid(oBestTarget)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Monitoring arti, Unit state='..AiBotUnitInfo.GetUnitState(oArti)..'; Time='..GetGameTimeSeconds()) end
                    if oArti:IsUnitState('Moving') then
                        AiBotOrders.IssueTrackedClearCommands(oArti)
                        if oArti[reftScathisBuiltLocation] and AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oArti[reftScathisBuiltLocation]) >= 15 then
                            AiBotOrders.IssueTrackedMove(oArti, oArti[reftScathisBuiltLocation], 1, false, 'ScathMvBk', false)
                        end
                        AttackOrigTarget(true)
                    end
                else
                    break
                end

            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetT3ArtiTarget(oArti, bCalledFromSalvoSize)
    --Gets oArti to fire an attack on the ground for where it thinks it will deal the most damage, works for t3 and experimental arti
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetT3ArtiTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bCalledFromSalvoSize then oArti[refbSalvoDelayActive] = false end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..'; bCalledFromSalvoSize='..tostring(bCalledFromSalvoSize or false)..'; oArti[refbSalvoDelayActive]='..tostring(oArti[refbSalvoDelayActive] or false)..'; Time='..GetGameTimeSeconds()) end
    if not(oArti[refbSalvoDelayActive]) then
        local iPlateau, iLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oArti:GetPosition())
        local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
        local aiBrain = oArti:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local iArtiFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oArti)
        if bDebugMessages == true then
            LOG('Updated GetUnitFacingAngle(oUnit) result='..AiBotUnitInfo.GetUnitFacingAngle(oArti)..'; old code below which didnt adjust GetHeadingPitch')
            if EntityCategoryContains(categories.STRUCTURE * categories.DIRECTFIRE + categories.STRUCTURE * categories.INDIRECTFIRE, oArti.UnitId) then
                if oArti.GetWeapon and oArti:GetWeaponCount() > 0 then
                    --LOG('GetFacingAngle: oUnit='..oUnit.UnitId..GetUnitLifetimeCount(oUnit))
                    local oWeapon = oArti:GetWeapon(1)
                    if oWeapon and oWeapon.GetAimManipulator and oWeapon:GetAimManipulator().GetHeadingPitch then
                        LOG('oWeapon:GetAimManipulator():GetHeadingPitch()='..oWeapon:GetAimManipulator():GetHeadingPitch()..'; ConvertRadiansToAngle result='..AiBotUtilities.ConvertRadiansToAngle(oWeapon:GetAimManipulator():GetHeadingPitch())..'; new code increases this by 89')
                    else LOG('Returning 0')
                    end
                else LOG('Returning 0')
                end
                if oArti:IsValidBone('Turret') then
                    --0% = south, 25% = east, 50% = north; want to convert from % into angle where 0 is north
                    LOG('GetBoneDirection(Turret)='..oArti:GetBoneDirection('Turret')..'; ConvertCounterclockwisePercentageToAngle result='..oArti:GetBoneDirection('Turret'))
                else
                    LOG('No turret, arti heading='..oArti:GetHeading()..'; will return '..180 - oUnit:GetHeading() / math.pi * 180)
                end
            else
                --Other units (would expect to be mobile) - get the unit direction
                LOG('Not DF or IF structure, will return based on unit heading='..oArti:GetHeading()..', returning '..180 - oArti:GetHeading() / math.pi * 180)
            end
        end
        local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
        local oFirstUnitAvoidedDueToCaptureTarget, oCaptureTargetForFirstUnitAvoided
        local iShotCount = 1
        if oArti.UnitId == 'url0401' then iShotCount = 0.1 end

        local iAOE, iDamage, iMinRange, iMaxRange, iSalvoSize, iSalvoIndividualDelay = AiBotUnitInfo.GetLauncherAOEStrikeDamageMinAndMaxRange(oArti)
        --Wait if salvo size >1
        local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
        if iSalvoSize > 1 and not(bCalledFromSalvoSize) and oArti[AiBotUnitInfo.refiLastWeaponEvent] then
            --E.g. scathis - dont want to change targets after firing a single shot - we have fired the scathis before, and this has presumably been called from the onweaponevent trigger

            local iTimeToWait = 4
            if (iSalvoIndividualDelay or 0) > 0 then iTimeToWait = iSalvoSize * iSalvoIndividualDelay + 0.1 end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iTimeToWait)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if AiBotUnitInfo.IsUnitValid(oArti) then
                oArti[refbSalvoDelayActive] = true
                ForkThread(GetT3ArtiTarget, oArti, true)
            end
            --Scathis outside of FAF - it doesnt have a salvo, but does have wierd behaviour where changing targets causes it to move towards the target
        elseif not(AiBotUtilities.bFAFActive) and oArti.UnitId == 'url0401' and DontChangeCurrentScathisTarget(oArti) then
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to change t3 arti target yet as think we have a scathis') end
        else
            if (iMaxRange or 0) == 0 or (iAOE or 0) == 0 then AiBotUtilities.ErrorHandler('Arti '..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..' has no range or no aoe')
            end

            --First make sure pathing is setup
            if AiBotUtilities.IsTableEmpty(oArti[reftiPlateauAndZonesInRange]) then
                oArti[reftiPlateauAndZonesInRange] = {}
                AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
                    AiBotUtilities.ErrorHandler('No other zones located for oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti))
                else
                    local iPlateauOrZero
                    if bDebugMessages == true then LOG(sFunctionRef..': About to search through all zones for targets for oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..'; iMinRange='..(iMinRange or 'nil')..'; iMaxRange='..(iMaxRange or 'nil')) end
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                        --Stop searching once got past arti max range
                        if tSubtable[AiBotMap.subrefiDistance] > iMaxRange then
                            if bDebugMessages == true then LOG(sFunctionRef..': Are outside the max range so wil stop searching') end
                            break
                        end
                        --If outside min range then include
                        if tSubtable[AiBotMap.subrefiDistance] > iMinRange then
                            --Add to potential zone table
                            local tAltLZOrWZData
                            local tAltLZOrWZTeamData
                            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                iPlateauOrZero = 0

                                tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                            else
                                iPlateauOrZero = tSubtable[AiBotMap.subrefiPlateauOrPond]
                                tAltLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Recording plateau '..iPlateauOrZero..' zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..' as being within max range') end
                            table.insert(oArti[reftiPlateauAndZonesInRange], {iPlateauOrZero, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], AiBotUtilities.GetDistanceBetweenPositions(tAltLZOrWZData[AiBotMap.subrefMidpoint], tAltLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]), AiBotUtilities.GetAngleFromAToB(oArti:GetPosition(), tAltLZOrWZData[AiBotMap.subrefMidpoint])})
                        end
                    end
                end
            end

            --Cycle through each zone that may be in range and pick the best one
            local iCurValue
            local iBestValue = 0
            local iSecondBestValue = 0
            local iBestPlateauOrZero, iBestLZOrWZ, iSecondBestPlateauOrZero, iSecondBestLZOrWZ, iBestAngleFactor, iSecondBestAngleFactor
            local iCurMobileThreat
            local iCurAAThreat
            local iShotMissFactor
            local iArtiAngleFactor
            local tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings = {} --whenever a zone is ignored due to not having the highest value, or repalced as second most value, it is recorded here, so if we fail to find a target we can refer to these zones
            local tiLowerPriorityIndexAndStructureValue = {} --[x] is the index in tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings, returns the structure value in the zone

            local iFriendlyUnitReductionFactor = 2
            local iFriendlyUnitAOEFactor = 2
            local iSizeAdjust = 0.25
            local iMultipleShotMod = 1
            local iMobileValueFactorInner = 0.4
            local iShieldReductionFactor = 0.25 --i.e. amount by which value of target will be reduced if it is under shielding
            if iDamage >= 7500 and iAOE >= 6 then iShieldReductionFactor = math.min(math.max(iShieldReductionFactor, 0.7), iShieldReductionFactor * 1.5, 0.9) end
            if not(AiBotUtilities.bFAFActive) then iShieldReductionFactor = math.max(0.4, iShieldReductionFactor * 0.5) end

            --First consider other T3 arti on team, and if target is in our range, then prefer to target that as well as synchronised targeting likely to be best (but only if the target had a value of 20k+)
            local tBestArtiSynchronisedGroundTarget, oArtiSynchronisedTarget
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                local tBrainT3Arti = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, false, true)
                if AiBotUtilities.IsTableEmpty(tBrainT3Arti) == false then
                    local iOtherDistToUs
                    local tLocationsConsidered = {}
                    local bConsiderCurOrder
                    for iOtherArti, oOtherArti in tBrainT3Arti do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering oOtherArti='..oOtherArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOtherArti)..'; Last target value='..(oOtherArti[refiLastTargetValue] or 0)..'; iBestValue='..iBestValue..'; Other arti order count='..(oOtherArti[AiBotOrders.refiOrderCount] or 'nil')..'; reprs of oOtherArti[AiBotOrders.reftiLastOrders][oOtherArti[AiBotOrders.refiOrderCount]]='..reprs(oOtherArti[AiBotOrders.reftiLastOrders][oOtherArti[AiBotOrders.refiOrderCount]])) end
                        if not(oOtherArti == oArti) and AiBotUnitInfo.IsUnitValid(oOtherArti) and (oOtherArti[refiLastTargetValue] or 0) >= math.max(iBestValue * 0.75, 10000) then
                            local tLastArtiOrder = oOtherArti[AiBotOrders.reftiLastOrders][oOtherArti[AiBotOrders.refiOrderCount]]
                            local oLastArtiUnitTarget = tLastArtiOrder[AiBotOrders.subrefoOrderUnitTarget]
                            local tLastArtiTarget
                            if AiBotUtilities.IsTableEmpty(tLastArtiOrder[AiBotOrders.subreftOrderPosition]) == false then
                                tLastArtiTarget = {tLastArtiOrder[AiBotOrders.subreftOrderPosition][1], tLastArtiOrder[AiBotOrders.subreftOrderPosition][2], tLastArtiOrder[AiBotOrders.subreftOrderPosition][3]}
                            elseif oLastArtiUnitTarget then
                                tLastArtiTarget = oLastArtiUnitTarget:GetPosition()
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Last arti order position='..repru(tLastArtiOrder[AiBotOrders.subreftOrderPosition])..'; Last arti order target='..(tLastArtiOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastArtiOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')) end
                            if AiBotUtilities.IsTableEmpty(tLastArtiTarget) == false then
                                bConsiderCurOrder = true
                                if AiBotUtilities.IsTableEmpty(tLocationsConsidered) == false then
                                    for iLocation, tLocation in tLocationsConsidered do
                                        if AiBotUtilities.GetRoughDistanceBetweenPositions(tLocation, oArti:GetPosition()) <= 10 then
                                            bConsiderCurOrder = false
                                            break
                                        end
                                    end
                                end
                                if bConsiderCurOrder then
                                    table.insert(tLocationsConsidered, tLastArtiTarget)
                                    iOtherDistToUs = AiBotUtilities.GetDistanceBetweenPositions(tLastArtiTarget, oArti:GetPosition())
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering order of other target oOtherArti='..oOtherArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOtherArti)..' with iOtherDistToUs='..iOtherDistToUs..'; Other arti position='..repru(tLastArtiTarget)) end
                                    if iOtherDistToUs >= iMinRange and iOtherDistToUs <= iMaxRange then
                                        local iTargetPlateauOrZero, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLastArtiTarget)
                                        local bDontConsiderIfUnderwater = true
                                        if iTargetPlateauOrZero == 0 then bDontConsiderIfUnderwater = true end
                                        iCurValue = AiBotLogic.GetDamageFromBomb(aiBrain, tLastArtiTarget, iAOE, iDamage, iFriendlyUnitReductionFactor,       iFriendlyUnitAOEFactor,     false,                      iSizeAdjust,        iMultipleShotMod,                   iMobileValueFactorInner,                true,                   iShieldReductionFactor,         true,                           nil,                                    nil,                    nil,                    not(bDontConsiderIfUnderwater))
                                        --Adjust curvalue for shot count as well
                                        local tAltLZOrWZData, tAltLZOrWZTeamData
                                        if iTargetPlateauOrZero == 0 then
                                            tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTargetZone]][AiBotMap.subrefPondWaterZones][iTargetZone]
                                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        else
                                            tAltLZOrWZData = AiBotMap.tAllPlateaus[iTargetPlateauOrZero][AiBotMap.subrefPlateauLandZones][iTargetZone]
                                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                        end
                                        iShotMissFactor = GetArtiValueFactorForShotFailures((tAltLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 0))
                                        --Reduce shot miss factor as have multiple arti firing at it
                                        if iShotMissFactor < 1 then iShotMissFactor = 1 - (1 - iShotMissFactor) * 0.5 end
                                        --Increase value by 25% due to synchronisation benefit, and ignore angle factor
                                        iCurValue = iCurValue * iShotMissFactor * 1.25
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCurValue='..iCurValue..'; after applying iShotMissFactor='..iShotMissFactor..'; iBestValue so far='..iBestValue..'; subrefiIneffectiveArtiShotCount='..(tAltLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 'nil')) end
                                        if iCurValue > iBestValue then
                                            iBestValue = iCurValue
                                            tBestArtiSynchronisedGroundTarget = {tLastArtiTarget[1], tLastArtiTarget[2], tLastArtiTarget[3]}
                                            oArtiSynchronisedTarget = oLastArtiUnitTarget
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider this as our preferred synchronised shot target') end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will cycle through each plateau and zone in range now, is oArti[reftiPlateauAndZonesInRange] empty='..tostring(AiBotUtilities.IsTableEmpty(oArti[reftiPlateauAndZonesInRange]))) end

            local iShieldFactor --Impact on value from enemy shields
            local iMinShieldFactor = 0.2 --I.e. if 0.05 then wouldn't reduce value below 5% of what we would have calculated ignoring shield when determining best and second best zones
            if AiBotUtilities.bFAFActive then
                iShieldFactor = 2
            else
                iMinShieldFactor = 0.1
                if AiBotUtilities.bQuietModActive then
                    iShieldFactor = 5
                else
                    iShieldFactor = 8
                end
            end

            for iEntry, tPlateauZoneAndDist in oArti[reftiPlateauAndZonesInRange] do
                local tAltLZOrWZData
                local tAltLZOrWZTeamData
                if tPlateauZoneAndDist[1] == 0 then
                    tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tPlateauZoneAndDist[2]]][AiBotMap.subrefPondWaterZones][tPlateauZoneAndDist[2]]
                    tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                else
                    tAltLZOrWZData = AiBotMap.tAllPlateaus[tPlateauZoneAndDist[1]][AiBotMap.subrefPlateauLandZones][tPlateauZoneAndDist[2]]
                    tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                end
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAltLZOrWZData[AiBotMap.subrefMidpoint]) then
                    iCurMobileThreat = ((tAltLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tAltLZOrWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 0))
                    --Get more precise calculation - i.e. the threat calculation above reduces threat for health, meaning if we attack say a fatboy, its threat decreases as its shield decreases, making it likely we switch targets when its shield is about to be destroyed; however dont bother with low threat values
                    if iCurMobileThreat >= 1000 then
                        if tPlateauZoneAndDist[1] == 0 then
                            iCurMobileThreat = AiBotUnitInfo.GetMassCostOfUnits(EntityCategoryFilterDown(categories.MOBILE - AiBotUnitInfo.refCategoryAmphibious - categories.SUBMERSIBLE, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]), true)
                        else
                            iCurMobileThreat = AiBotUnitInfo.GetMassCostOfUnits(EntityCategoryFilterDown(categories.MOBILE, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]), true)
                        end
                    end
                    if tPlateauZoneAndDist[1] == 0 and tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 0 then
                        iCurValue = AiBotUnitInfo.GetMassCostOfUnits(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]), true) + iCurMobileThreat * 0.2
                    else
                        iCurValue = tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] + iCurMobileThreat * 0.2
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering plateau and zone '..tPlateauZoneAndDist[1]..'Z'..tPlateauZoneAndDist[2]..'; tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]='..(tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')..'; iCurMobileThreat='..iCurMobileThreat..'; subrefThreatEnemyShield='..(tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)) end
                    --Add extra mobile threat if enemy has long ranged units and is close to our nearest base
                    if iCurMobileThreat >= 4000 and tPlateauZoneAndDist[3] <= 300 and AiBotUtilities.IsTableEmpty(tAltLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
                        local iLongRangeThreat = 0
                        for iRange, iThreat in tAltLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                            if iRange >= 65 then --i.e. just above a megaliths range
                                iLongRangeThreat = iLongRangeThreat + iThreat
                            end
                        end
                        if iLongRangeThreat >= 1500 then
                            iCurValue = iCurValue + iCurMobileThreat * 0.8 --want based on mobile threat so less likely to run into issue for units like fatboy where threat decreases as shield decreases
                        end
                    end
                    --Add extra mobile threat if enemy has large mobile MAA
                    iCurAAThreat = (tAltLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tAltLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)
                    if iCurAAThreat >= 3000 then
                        local tEnemyMobileAA = EntityCategoryFilterDown(categories.MOBILE, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty( tEnemyMobileAA) == false then
                            iCurValue = iCurValue + iCurAAThreat * 0.2 + AiBotUnitInfo.GetMassCostOfUnits(tEnemyMobileAA, true) * 0.8
                        else
                            iCurValue = iCurValue + iCurAAThreat * 0.2
                        end
                    else
                        iCurValue = iCurValue + iCurAAThreat * 0.2
                    end

                    --Add extra threat if enemy has t2 arti near the nearest friendly base (relevant for team games, since 1v1 this hsould be inside the minimum rnage)
                    if tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] >= 4000 and tPlateauZoneAndDist[3] <= 200 and not(tPlateauZoneAndDist[1] == 0) then
                        local tEnemyT2ArtiAndMissileShips = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryTML + AiBotUnitInfo.refCategoryMissileShip, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty(tEnemyT2ArtiAndMissileShips) == false then
                            iCurValue = iCurValue + tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]
                        end
                    end

                    --Reduce value if shielded
                    if (tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Value before shield reduction factor='..iCurValue) end
                        if tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] <= iMinShieldFactor then
                            iCurValue = math.max(iCurValue * iMinShieldFactor, iCurValue - tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] * iShieldFactor)
                        else --Enemy likely has 2+ shields
                            iCurValue = math.max(iCurValue * iMinShieldFactor, iCurValue - tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] * iShieldFactor * 2)
                        end
                    end

                    --Campaign capture objectives - avoid capture targets unless they're far higher in value than other potential targets
                    if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tAltLZOrWZData[AiBotMap.subreftoUnitsToCapture]) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': Zone has capture targets so significantly reducing its value, iCurValue before reduction='..iCurValue) end
                        if iCurValue > iSecondBestValue and not(oCaptureTargetForFirstUnitAvoided) then oCaptureTargetForFirstUnitAvoided = tAltLZOrWZData[AiBotMap.subreftoUnitsToCapture][1] end
                        iCurValue = iCurValue / 20
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': Considering plateau '..tPlateauZoneAndDist[1]..' and zone '..tPlateauZoneAndDist[2]..'; Dist='..tPlateauZoneAndDist[3]..'; iCurValue before factoring in ineffective shot count='..iCurValue..'; tLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount]='..(tAltLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 'nil')..'; iCurAAThreat='..iCurAAThreat..'; iCurMobileThreat='..iCurMobileThreat..'; tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]='..tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]..'; iSecondBestValue='..iSecondBestValue) end

                    --Adjust value for number of times shots have hit
                    if iCurValue > iSecondBestValue then
                        --Adjust cur value for shot missed percentage
                        iShotMissFactor = GetArtiValueFactorForShotFailures((tAltLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 0))
                        --Adjust cur value for angle to target
                        iArtiAngleFactor = GetArtiValueFactorForFacingDifference(iArtiFacingAngle, tPlateauZoneAndDist[4])

                        iCurValue = iCurValue * iShotMissFactor * iArtiAngleFactor

                        --Record as best/second best
                        if iCurValue > iBestValue then
                            tBestArtiSynchronisedGroundTarget = nil
                            oArtiSynchronisedTarget = nil
                            iSecondBestValue = iBestValue
                            iSecondBestPlateauOrZero = iBestPlateauOrZero
                            iSecondBestLZOrWZ = iBestLZOrWZ
                            iSecondBestAngleFactor = iBestAngleFactor
                            iBestValue = iCurValue
                            iBestPlateauOrZero = tPlateauZoneAndDist[1]
                            iBestLZOrWZ = tPlateauZoneAndDist[2]
                            iBestAngleFactor = iArtiAngleFactor
                        elseif iCurValue > iSecondBestValue then
                            if iSecondBestPlateauOrZero then
                                local tSecondBestTeamData
                                if iSecondBestPlateauOrZero > 0 then
                                    tSecondBestTeamData = AiBotMap.tAllPlateaus[iSecondBestPlateauOrZero][AiBotMap.subrefPlateauLandZones][iSecondBestLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
                                else
                                    tSecondBestTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iSecondBestLZOrWZ]][AiBotMap.subrefPondWaterZones][iSecondBestLZOrWZ][AiBotMap.subrefWZTeamData][iTeam]
                                end
                                if (tSecondBestTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) > 500 then
                                    table.insert(tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings, {iSecondBestPlateauOrZero, iSecondBestLZOrWZ})
                                    table.insert(tiLowerPriorityIndexAndStructureValue, (tSecondBestTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0))
                                end
                            end
                            iSecondBestValue = iCurValue
                            iSecondBestPlateauOrZero = tPlateauZoneAndDist[1]
                            iSecondBestLZOrWZ = tPlateauZoneAndDist[2]
                            iSecondBestAngleFactor = iArtiAngleFactor
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurValue after adj='..iCurValue..'; iShotMissFactor='..iShotMissFactor..'; iArtiAngleFactor='..iArtiAngleFactor..'; iArtiFacingAngle='..iArtiFacingAngle..'; tPlateauZoneAndDist[4]='..(tPlateauZoneAndDist[4] or 'nil')) end
                    elseif (tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) > 500 then
                        table.insert(tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings, {tPlateauZoneAndDist[1], tPlateauZoneAndDist[2]})
                        table.insert(tiLowerPriorityIndexAndStructureValue, (tAltLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0))
                    end
                end
            end

            --Now have the best 2 zones on an aggregate basis, get the best location for the arti target within these zones
            --Reduce value of shields against high damage and aoe targets
            local iCaptureTargetDistanceThreshold = 34
            function GetBestUnitTargetAndValueInZone(iPlateauOrZero, iLZOrWZ, iAngleFactor)
                local tAltLZOrWZData
                local tAltLZOrWZTeamData
                local iCurValue
                local iBestCurValue = 0
                local oBestUnitTarget
                if iPlateauOrZero == 0 then
                    tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLZOrWZ]][AiBotMap.subrefPondWaterZones][iLZOrWZ]
                    tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                else
                    tAltLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLZOrWZ]
                    tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering best target in plateau '..iPlateauOrZero..'; Zone '..iLZOrWZ..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                if AiBotUtilities.IsTableEmpty(tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    local tPriorityUnits
                    local iMaxTargetsPerZone = 25
                    local bDontConsiderIfUnderwater = true
                    if iPlateauOrZero == 0 then bDontConsiderIfUnderwater = true end
                    if oArti[AiBotUnitInfo.refbEasyBrain] then
                        tPriorityUnits = EntityCategoryFilterDown(categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryStructure * categories.TECH3 + AiBotUnitInfo.refCategoryStructure * categories.TECH2, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                        iMaxTargetsPerZone = 10
                    else
                        tPriorityUnits = EntityCategoryFilterDown(categories.EXPERIMENTAL + categories.TECH3 + AiBotUnitInfo.refCategoryStructure * categories.TECH2 + AiBotUnitInfo.refCategoryCruiser * categories.TECH2, tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                    end

                    local iCurDist
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of priority units empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityUnits))) end
                    if AiBotUtilities.IsTableEmpty(tPriorityUnits) then tPriorityUnits = tAltLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] end
                    --Filter to the top 25 units in the zone by mass cost for performance reasons
                    local tiBaseValueOfPriorityUnits = {}
                    local iBaseValue
                    local toUnitsToAvoid
                    if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tAltLZOrWZData[AiBotMap.subreftoUnitsToCapture]) == false then toUnitsToAvoid = tAltLZOrWZData[AiBotMap.subreftoUnitsToCapture] end
                    function IsCloseToUnitToAvoid(oUnitToConsider)
                        if toUnitsToAvoid then
                            for iToAvoid, oToAvoid in toUnitsToAvoid do
                                if not(oToAvoid.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oToAvoid:GetPosition(), oUnitToConsider:GetPosition()) <= iCaptureTargetDistanceThreshold then
                                    if not(oFirstUnitAvoidedDueToCaptureTarget) then
                                        oFirstUnitAvoidedDueToCaptureTarget = oUnitToConsider
                                        oCaptureTargetForFirstUnitAvoided = oToAvoid
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iclosetounittoavoid: Unit '..oUnitToConsider.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToConsider)..' is too close to capture target '..oToAvoid.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oToAvoid)) end
                                    return true
                                else
                                end
                            end
                        end
                        return false
                    end

                    for iUnit, oUnit in tPriorityUnits do
                        --Double check are in range
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oArti:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering targeting oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; iMaxRange='..iMaxRange..'; iMinRange='..iMinRange..'; iAOE='..(iAOE or 'nil')..'; iDamage='..(iDamage or 'nil')..'; iFriendlyUnitReductionFactor='..(iFriendlyUnitReductionFactor or 'nil')..'; iFriendlyUnitAOEFactor='..(iFriendlyUnitAOEFactor or 'nil')..'; iSizeAdjust='..(iSizeAdjust or 'nil')..'; iMultipleShotMod='..(iMultipleShotMod or 'nil')..'; iMobileValueFactorInner='..(iMobileValueFactorInner or 'nil')..'; iShieldReductionFactor='..(iShieldReductionFactor or 'nil')) end
                            if iCurDist <= iMaxRange and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) and iCurDist >= iMinRange and (bDontConsiderIfUnderwater or not(AiBotUnitInfo.IsUnitUnderwater(oUnit))) then
                                if toUnitsToAvoid and IsCloseToUnitToAvoid(oUnit) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Ignoring unit as too close to a unit to avoid') end
                                else
                                    --Check if units to avoid
                                    iBaseValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                                    if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) and oUnit:GetFractionComplete() >= 0.98 then iBaseValue = iBaseValue * iMobileValueFactorInner end
                                    tiBaseValueOfPriorityUnits[iUnit] = iBaseValue
                                end
                            end
                        end
                    end
                    local iCurCount = 0
                    if AiBotUtilities.IsTableEmpty(tiBaseValueOfPriorityUnits) == false then
                        for iEntry, iValue in AiBotUtilities.SortTableByValue(tiBaseValueOfPriorityUnits, true) do
                            iCurCount = iCurCount + 1
                            if iCurCount > iMaxTargetsPerZone then break end
                            local oUnit = tPriorityUnits[iEntry]
                            --GetDamageFromBomb(aiBrain, tBaseLocation,     iAOE,   iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor, bCheckIfUnderwater)
                            iCurValue = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iDamage, iFriendlyUnitReductionFactor,       iFriendlyUnitAOEFactor,     false,                      iSizeAdjust,        iMultipleShotMod,                   iMobileValueFactorInner,                true,                   iShieldReductionFactor,         true,                           nil,                                    nil,                    nil,                    not(bDontConsiderIfUnderwater))
                            if bDebugMessages == true then LOG(sFunctionRef..': Damage from bomb if we target it at unit='..iCurValue..'; iBestCurValue='..(iBestCurValue or 'nil')) end
                            local iMinValue = 0
                            --Only set the min value if we dont have a negative value from the target (e.g. happens if targeting our own base or capture target)
                            if (iCurValue or 0) >= 0 and AiBotUnitInfo.IsUnitValid(oUnit) and oUnit.GetFractionComplete and (oUnit:GetFractionComplete() < 1 or EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId)) then
                                --redundancy for buildings and under construction units
                                iMinValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering increasing cur value to min basic value based on the unit target, iCurValue='..(iCurValue or 'nil')..'; iBestCurValue='..(iBestCurValue or 'nil')..'; iMinValue='..(iMinValue or 'nil')) end
                                iCurValue = math.max((iCurValue or 0), iMinValue)
                            end
                            if iCurValue > iBestCurValue then
                                tBestArtiSynchronisedGroundTarget = nil
                                oArtiSynchronisedTarget = nil
                                iBestCurValue = iCurValue
                                oBestUnitTarget = oUnit
                                if bDebugMessages == true then LOG(sFunctionRef..': Setting the best unit target to '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iBestCurValue='..iBestCurValue) end
                            end
                        end
                    end
                end
                return oBestUnitTarget, iBestCurValue
            end
            local oBestTarget
            if iBestLZOrWZ and iBestPlateauOrZero then
                oBestTarget, iBestValue = GetBestUnitTargetAndValueInZone(iBestPlateauOrZero, iBestLZOrWZ)
                if not(iBestAngleFactor) then iBestAngleFactor = GetArtiValueFactorForFacingDifference(0,180) end
                if not(iBestValue) then iBestValue = 0 end
                iBestValue = iBestAngleFactor * iBestValue
                if bDebugMessages == true then LOG(sFunctionRef..': iBestPlateauOrZero='..(iBestPlateauOrZero or 'nil')..'; iBestLZOrWZ='..(iBestLZOrWZ or 'nil')..'; iBestValue='..(iBestValue or 'nil')..'; oBestTarget='..(oBestTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget) or 'nil')..'; iBestAngleFactor='..(iBestAngleFactor or 'nil')) end
                if iSecondBestLZOrWZ then
                    local oAltTarget, iAltTargetValue = GetBestUnitTargetAndValueInZone(iSecondBestPlateauOrZero, iSecondBestLZOrWZ)
                    if bDebugMessages == true then LOG(sFunctionRef..': iSecondBestPlateauOrZero='..(iSecondBestPlateauOrZero or 'nil')..'; iSecondBestLZOrWZ='..(iSecondBestLZOrWZ or 'nil')..'; iAltTargetValue='..(iAltTargetValue or 'nil')..'; oAltTarget='..(oAltTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oAltTarget) or 'nil')..'; iBestValue before considering this='..(iBestValue or 'nil')..'; iSecondBestAngleFactor='..(iSecondBestAngleFactor or 'nil')) end
                    if not(iSecondBestAngleFactor) then iSecondBestAngleFactor = GetArtiValueFactorForFacingDifference(0,180) end
                    if not(iAltTargetValue) then iAltTargetValue = 0
                    elseif oAltTarget.GetPosition then
                        --Get value from targeting the best target in this alt zone
                        --GetDamageFromBomb(aiBrain, tBaseLocation,             iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, bCheckIfUnderwater)
                        iAltTargetValue  = AiBotLogic.GetDamageFromBomb(aiBrain, oAltTarget:GetPosition(), iAOE, iDamage, iFriendlyUnitReductionFactor,       iFriendlyUnitAOEFactor,     false,                      iSizeAdjust,        iMultipleShotMod,                   iMobileValueFactorInner,                true,                   iShieldReductionFactor,         true)
                    end
                    iAltTargetValue = iAltTargetValue * iSecondBestAngleFactor
                    if bDebugMessages == true then LOG(sFunctionRef..': iAltTargetValue='..iAltTargetValue..'; iBestValue before reflecting this='..iBestValue) end
                    if iAltTargetValue > iBestValue then
                        oBestTarget = oAltTarget
                        iBestValue = iAltTargetValue
                    end
                    if not(oBestTarget) and AiBotUtilities.IsTableEmpty(tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings) == false then
                        for iIndex, iBuildingValue in AiBotUtilities.SortTableByValue(tiLowerPriorityIndexAndStructureValue, true) do
                            GetBestUnitTargetAndValueInZone(tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings[iIndex][1], tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings[iIndex][2])
                            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering alternative for best unit target P'..tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings[iIndex][1]..'Z'..tiLowerPriorityPlateauAndLandZonesWithEnemyBuildings[iIndex][2]) end
                            if oBestTarget then break end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering first and second best zones, oBestTarget='..(oBestTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget) or 'nil')..'; tBestArtiSynchronisedGroundTarget='..repru(tBestArtiSynchronisedGroundTarget)..'; oArtiSynchronisedTarget='..(oArtiSynchronisedTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oArtiSynchronisedTarget) or 'nil')..'; oFirstUnitAvoidedDueToCaptureTarget='..(oFirstUnitAvoidedDueToCaptureTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnitAvoidedDueToCaptureTarget) or 'nil')..'; oCaptureTargetForFirstUnitAvoided='..(oCaptureTargetForFirstUnitAvoided.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oCaptureTargetForFirstUnitAvoided) or 'nil')) end
            if oArtiSynchronisedTarget and tBestArtiSynchronisedGroundTarget then oBestTarget = oArtiSynchronisedTarget end
            if not(oBestTarget) and not(tBestArtiSynchronisedGroundTarget) then
                local bGivenAltTarget = false
                if  oCaptureTargetForFirstUnitAvoided then
                    if not(oFirstUnitAvoidedDueToCaptureTarget) then
                        local tCaptureLZData, tCaptureLZTeamData = AiBotMap.GetLandOrWaterZoneData(oCaptureTargetForFirstUnitAvoided:GetPosition(), true, iTeam)
                        if (tCaptureLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) >= 200 and AiBotUtilities.IsTableEmpty(tCaptureLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            --Get the furthest building from capture target
                            local tEnemyBuildings = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tCaptureLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if AiBotUtilities.IsTableEmpty(tEnemyBuildings) == false then
                                local iFurthestDist = 10 --dont want units that are too close to capture target
                                local iCurDist
                                for iBuilding, oBuilding in tEnemyBuildings do
                                    if not(oBuilding.Dead) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBuilding:GetPosition(), oCaptureTargetForFirstUnitAvoided:GetPosition())
                                        if iCurDist > iFurthestDist then
                                            iFurthestDist = iCurDist
                                            oFirstUnitAvoidedDueToCaptureTarget = oBuilding
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': oFirstUnitAvoidedDueToCaptureTarget after checking furthest building='..(oFirstUnitAvoidedDueToCaptureTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnitAvoidedDueToCaptureTarget) or 'nil')..'; iFurthestDist='..iFurthestDist) end
                            end
                        end
                    end
                    if oFirstUnitAvoidedDueToCaptureTarget then
                        local iAngleToUnitFromCaptureTarget = AiBotUtilities.GetAngleFromAToB(oCaptureTargetForFirstUnitAvoided:GetPosition(), oFirstUnitAvoidedDueToCaptureTarget:GetPosition())
                        local iDistToMove = iCaptureTargetDistanceThreshold - AiBotUtilities.GetDistanceBetweenPositions(oFirstUnitAvoidedDueToCaptureTarget:GetPosition(), oCaptureTargetForFirstUnitAvoided:GetPosition())
                        local tAltTarget = AiBotUtilities.MoveInDirection(oFirstUnitAvoidedDueToCaptureTarget:GetPosition(), iAngleToUnitFromCaptureTarget, iDistToMove, true, false, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try targeting oFirstUnitAvoidedDueToCaptureTarget='..oFirstUnitAvoidedDueToCaptureTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnitAvoidedDueToCaptureTarget)..'; iDistToMove='..iDistToMove..'; Dist between the target and capture unit='..AiBotUtilities.GetDistanceBetweenPositions(oFirstUnitAvoidedDueToCaptureTarget:GetPosition(), oCaptureTargetForFirstUnitAvoided:GetPosition())) end
                        if AiBotUtilities.IsTableEmpty(tAltTarget) == false then
                            oArti[refiTimeLastGotBestArtiTarget] = GetGameTimeSeconds()
                            AiBotOrders.IssueTrackedGroundAttack(oArti, tAltTarget, 1, false, 'ArtiCaptU', false)
                            bGivenAltTarget = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try attacking unit near capture target') end
                        end
                    end
                end
                if not(bGivenAltTarget) then
                    AiBotUtilities.ErrorHandler('No target found for T3 arti, will fire at closest enemy base instead if we can hit it', true)
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    local toUnitsToAvoid
                    if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then toUnitsToAvoid = tLZData[AiBotMap.subreftoUnitsToCapture] end
                    function IsCloseToUnitToAvoid(oUnitToConsider)
                        if toUnitsToAvoid then
                            for iToAvoid, oToAvoid in toUnitsToAvoid do
                                if not(oToAvoid.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oToAvoid:GetPosition(), oUnitToConsider:GetPosition()) <= iCaptureTargetDistanceThreshold then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnitToConsider.UnitId..AiBotUnitInfo.GeetUnitLifetimeCount(oUnitToConsider)..' is too close to capture target '..oToAvoid.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oToAvoid)) end
                                    --Commented out below as no point recording for here as the logic using these is above/has already happened
                                    --[[if not(oFirstUnitAvoidedDueToCaptureTarget) then
                                        oFirstUnitAvoidedDueToCaptureTarget = oUnitToConsider
                                        oCaptureTargetForFirstUnitAvoided = oToAvoid
                                    end--]]
                                    return true
                                end
                            end
                        end
                        return false
                    end
                    local iDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], oArti:GetPosition())
                    if iDistToEnemyBase <= iMaxRange and iDistToEnemyBase >= iMinRange and ( bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZTeamData[AiBotMap.reftClosestEnemyBase])) then
                        --GetDamageFromBomb(aiBrain, tBaseLocation,                             iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory)
                        local iDamage = AiBotLogic.GetDamageFromBomb(aiBrain, tLZTeamData[AiBotMap.reftClosestEnemyBase], iAOE, iDamage, iFriendlyUnitReductionFactor, iFriendlyUnitAOEFactor,          false,                          iSizeAdjust,        iMultipleShotMod,               iMobileValueFactorInner,                    true,               iShieldReductionFactor,         true)
                        if iDamage >= 0 then --should mean dont have much in way of friendly forces there
                            --Check there are enemy units nearby
                            local bNearbyEnemyUnits = false
                            local tNearbyUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tLZTeamData[AiBotMap.reftClosestEnemyBase], iAOE * 1.3))
                            if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                                for iUnit, oUnit in tNearbyUnits do
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategoryStructure - categories.TECH1 * categories.MOBILE, oUnit.UnitId) then
                                        if IsEnemy(oUnit:GetAIBrain():GetArmyIndex(), aiBrain:GetArmyIndex()) then
                                            if toUnitsToAvoid and IsCloseToUnitToAvoid(oUnit) then
                                                --Ignore unit
                                            else
                                                bNearbyEnemyUnits = true
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                            if bNearbyEnemyUnits then
                                iBestValue = iDamage
                                --Is this the same as the last target?
                                oArti[refiLastTargetValue] = iBestValue
                                local tLastOrder = oArti[AiBotOrders.reftiLastOrders][oArti[AiBotOrders.refiOrderCount]]
                                if AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false and AiBotUtilities.GetRoughDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], tLZTeamData[AiBotMap.reftClosestEnemyBase]) > 1 then
                                    oArti[refiTimeLastGotBestArtiTarget] = GetGameTimeSeconds()
                                    AiBotOrders.IssueTrackedGroundAttack(oArti, tLZTeamData[AiBotMap.reftClosestEnemyBase], 1, false, 'ArtiEB'..'ALZ'..iLandZone, false)
                                    IncreaseArtiShotCount(tLZTeamData[AiBotMap.reftClosestEnemyBase], iTeam, iShotCount)
                                end
                                bGivenAltTarget = true
                            end
                        end
                    end
                    if oFirstUnitAvoidedDueToCaptureTarget and oCaptureTargetForFirstUnitAvoided then
                        local iAngleToUnitFromCaptureTarget = AiBotUtilities.GetAngleFromAToB(oCaptureTargetForFirstUnitAvoided:GetPosition(), oFirstUnitAvoidedDueToCaptureTarget:GetPosition())
                        local iDistToMove = iCaptureTargetDistanceThreshold - AiBotUtilities.GetDistanceBetweenPositions(oFirstUnitAvoidedDueToCaptureTarget:GetPosition(), oCaptureTargetForFirstUnitAvoided:GetPosition())
                        local tAltTarget = AiBotUtilities.MoveInDirection(oFirstUnitAvoidedDueToCaptureTarget:GetPosition(), iAngleToUnitFromCaptureTarget, iDistToMove, true, false, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try targeting oFirstUnitAvoidedDueToCaptureTarget='..oFirstUnitAvoidedDueToCaptureTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnitAvoidedDueToCaptureTarget)..'; iDistToMove='..iDistToMove..'; Dist between the target and capture unit='..AiBotUtilities.GetDistanceBetweenPositions(oFirstUnitAvoidedDueToCaptureTarget:GetPosition(), oCaptureTargetForFirstUnitAvoided:GetPosition())..'; tAltTarget='..repru(tAltTarget)) end
                        if AiBotUtilities.IsTableEmpty(tAltTarget) == false then
                            oArti[refiTimeLastGotBestArtiTarget] = GetGameTimeSeconds()
                            AiBotOrders.IssueTrackedGroundAttack(oArti, tAltTarget, 1, false, 'ArtiCaptU', false)
                            bGivenAltTarget = true
                        end
                    end
                    if not(bGivenAltTarget) then
                        AiBotOrders.IssueTrackedClearCommands(oArti)
                    end
                end
            else
                local tActualTarget
                local tLeadingTarget
                local bAttackUnitNotGround = false
                if bDebugMessages == true then LOG(sFunctionRef..': Considering oBestTarget='..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget)..'; Does this contain mobile='..tostring(EntityCategoryContains(categories.MOBILE, oBestTarget.UnitId))..'; Fraction complete='..oBestTarget:GetFractionComplete()..'; Is moving unit state='..tostring(oBestTarget:IsUnitState('Moving'))..'; Unit state='..AiBotUnitInfo.GetUnitState(oBestTarget)) end
                if not(tBestArtiSynchronisedGroundTarget) and EntityCategoryContains(categories.MOBILE, oBestTarget.UnitId) and oBestTarget:GetFractionComplete() == 1 and oBestTarget:IsUnitState('Moving') and not(oArti[AiBotUnitInfo.refbEasyBrain]) and (AiBotUtilities.bFAFActive or not(oArti.UnitId == 'url0401')) then
                    --If best target is mobile and moving, then consider a leading shot instead
                    local oBP = oArti:GetBlueprint()
                    local iWeaponVelocity
                    if oBP.Weapon and type(oBP.Weapon) == "table" then
                        for iCurWeapon, oCurWeapon in oBP.Weapon do
                            if (oCurWeapon.DamageRadius or 0) > 0 and (oCurWeapon.MaxRadius or 0) >= iMaxRange then
                                iWeaponVelocity = oCurWeapon.MuzzleVelocity
                                break
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iWeaponVelocity='..(iWeaponVelocity or 'nil')) end
                    if (iWeaponVelocity or 0) > 0 then
                        local iDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oBestTarget:GetPosition(), oArti:GetPosition())
                        local iTimeToImpact = 0.5 + iDistToEnemy * 1.75 / iWeaponVelocity
                        local iCurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oBestTarget)
                        local iDistToLead = iTimeToImpact * (oBestTarget:GetBlueprint().Physics.MaxSpeed or 0)
                        tLeadingTarget = AiBotUtilities.MoveInDirection(oBestTarget:GetPosition(), iCurFacingDirection, iDistToLead, true, false, AiBotMap.bIsCampaignMap)
                        if bDebugMessages == true then LOG(sFunctionRef..': tLeadingTarget='..repru(tLeadingTarget)..'; Dist to best arti='..AiBotUtilities.GetDistanceBetweenPositions(tLeadingTarget, oArti:GetPosition())..'; Min range='..iMinRange) end
                        if not(tLeadingTarget and AiBotUtilities.GetDistanceBetweenPositions(tLeadingTarget, oArti:GetPosition()) >= iMinRange) then
                            tLeadingTarget = nil
                        end
                    end
                end
                if tBestArtiSynchronisedGroundTarget then
                    tActualTarget = tBestArtiSynchronisedGroundTarget
                elseif tLeadingTarget then
                    if bDebugMessages == true then LOG(sFunctionRef..': Changing Arti target for oBestTarget='..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget)..' to try and lead target, oBestTarget position='..repru(oBestTarget:GetPosition())..'; tLeadingTarget='..repru(tLeadingTarget)..'; Time='..GetGameTimeSeconds()) end
                    tActualTarget = tLeadingTarget
                elseif AiBotUtilities.bFAFActive or not(oArti.UnitId == 'url0401') then
                    --GetBestAOETarget(aiBrain, tBaseLocation,            iAOE, iDamage, bOptionalCheckForSMD, tSMLLocationForSMDCheck, iOptionalTimeSMDNeedsToHaveBeenBuiltFor, iSMDRangeAdjust, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, iOptionalMaxDistanceCheckOptions, iMobileValueOverrideFactorWithin75Percent, iOptionalShieldReductionFactor, iOptionalReclaimFactor)
                    tActualTarget = AiBotLogic.GetBestAOETarget(aiBrain, oBestTarget:GetPosition(), iAOE, iDamage, false,                 nil,                    nil,                                    nil,            iFriendlyUnitReductionFactor,       iFriendlyUnitAOEFactor,     nil,                            iMobileValueFactorInner,                    iShieldReductionFactor,         nil)
                else
                    if AiBotUnitInfo.CanSeeUnit(aiBrain, oBestTarget, false) then
                        bAttackUnitNotGround = true
                    end
                    tActualTarget = oBestTarget:GetPosition()
                end



                --Double check are still in range
                local iTargetDist = AiBotUtilities.GetDistanceBetweenPositions(tActualTarget, oArti:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': tActualTarget='..repru(tActualTarget)..'; iTargetDist='..iTargetDist..'; iBestValue='..(iBestValue or 'nil')) end
                if iTargetDist > iMaxRange or iTargetDist < iMinRange then
                    if oBestTarget then
                        bAttackUnitNotGround = false --redundancy
                        tActualTarget = oBestTarget:GetPosition()
                    else
                        AiBotUtilities.ErrorHandler('Dont have oBestTarget, and our original target isnt in range, did we pick another t3 arti target that is out of range somehow?')
                    end
                end

                if AiBotMap.bIsCampaignMap and (iBestValue or 0) < 0 then
                    --Disable weapon
                    AiBotUnitInfo.DisableUnitWeapon(oArti)
                    if bDebugMessages == true then LOG(sFunctionRef..': Disabling Arti weapon, oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)) end
                    ForkThread(RecheckForArtiTargetSoon, oArti)
                else

                    --Issue attack order
                    oArti[refiLastTargetValue] = iBestValue
                    oArti[refiTimeLastGotBestArtiTarget] = GetGameTimeSeconds()
                    local tLastOrder = oArti[AiBotOrders.reftiLastOrders][oArti[AiBotOrders.refiOrderCount]]
                    if not(AiBotUtilities.bFAFActive) and oArti.UnitId == 'url0401' then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will do delayed order change for arti as it is scathis and not FAF') end
                        ForkThread(DelayedScathisOrderChange, bAttackUnitNotGround, oArti, oBestTarget, tActualTarget)
                    elseif bAttackUnitNotGround then
                        if bDebugMessages == true then LOG(sFunctionRef..': Issuing tracked attack for oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..' to attack oBestTarget='..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget)) end
                        AiBotOrders.IssueTrackedAttack(oArti, oBestTarget, false, 'ScaAtU', false)
                    else
                        if AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) or AiBotUtilities.GetRoughDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], tActualTarget) > 1 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Issuing tracked ground attack for oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..' to attack oBestTarget='..oBestTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestTarget)) end
                            AiBotOrders.IssueTrackedGroundAttack(oArti, tActualTarget, 1, false, 'ArtiGF'..'ALZ'..iLandZone, false, oBestTarget)
                        end
                    end
                    IncreaseArtiShotCount(tActualTarget, iTeam, iShotCount)
                    if bDebugMessages == true then LOG(sFunctionRef..': Sent order to attack to oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..', iBestValue='..iBestValue..'; tActualTarget='..repru(tActualTarget)..'; is tActualTarget in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tActualTarget))..'; rMapPlayableArea='..repru(AiBotMap.rMapPlayableArea)..'; Angle from arti to target='..AiBotUtilities.GetAngleFromAToB(oArti:GetPosition(), tActualTarget)) end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetArtiValueFactorForShotFailures(iShotFailedCount)
    --iShotFailedCount: Should be (tLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 0)
    local iFactor
    local iInterval = 13
    if iShotFailedCount >= iInterval then
        iFactor = math.max(0.03, 1 - math.floor(iShotFailedCount / iInterval) * iInterval * 0.03)
    else
        --Have failed fewer than 15 shots
        iFactor = 1
    end
    return iFactor
end
function GetArtiValueFactorForFacingDifference(iArtiFacingAngle, iAngleToTarget)
    local iAngleDif = AiBotUtilities.GetAngleDifference(iArtiFacingAngle, iAngleToTarget)
    if iAngleDif <= 10 then
        return 1
    else
        return 1 - 0.4 * iAngleDif / 180
    end
end

function JustFiredMissile(oLauncher)
    --Wait 1 tick then check if sitll have missile loaded and if so then consider firing another missile
    if EntityCategoryContains(AiBotUnitInfo.refCategoryTML + AiBotUnitInfo.refCategorySML, oLauncher.UnitId) then
        WaitTicks(1)
        if AiBotUnitInfo.IsUnitValid(oLauncher) then
            local iMissiles = 0 --For some reason the count is off by 1, presumably a slight delay between the event being called and the below ammo counts working
            if oLauncher.GetTacticalSiloAmmoCount then iMissiles = iMissiles + oLauncher:GetTacticalSiloAmmoCount() end
            if oLauncher.GetNukeSiloAmmoCount then iMissiles = iMissiles + oLauncher:GetNukeSiloAmmoCount() end
            if iMissiles > 0 then
                --LOG('consideration of launching missile 3')
                ConsiderLaunchingMissile(oLauncher)
            end
            --Track SML launchers who have recently fired
            if AiBotUnitInfo.IsUnitValid(oLauncher) and oLauncher:GetAIBrain().AiBotAI then
                if EntityCategoryContains(AiBotUnitInfo.refCategorySML, oLauncher.UnitId) then
                    local iTeam = oLauncher:GetAIBrain().AiBotTeam
                    local bAddToTable = true
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers] = {}
                    else
                        for iRecordedLauncher, oRecordedLauncher in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers] do
                            if oRecordedLauncher == oLauncher then
                                bAddToTable = false
                                break
                            end
                        end
                    end
                    if bAddToTable then
                        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoRecentlyFiredAlliedNukeLaunchers], oLauncher)
                    end
                end
            end

        end
    end
end

function ReserveLocationsForGameEnder(oUnit)
    --Reserve locations to provide shield coverage for oUnit
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ReserveLocationsForGameEnder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oUnit[reftArtiTemplateRefs]) then --redundancy as shouldve already checked before getting here

        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, gametimeseconds is '..GetGameTimeSeconds()..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; owned by '..oUnit:GetAIBrain().Nickname..' on team '..oUnit:GetAIBrain().AiBotTeam) end

        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
        if iLandZone > 0 then
            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
            local tiShieldBuildLocationOptions = {}
            local tiShieldLocationCountByOption = {}
            local sBlueprintToBuild = 'xsb4202'
            local iNewBuildingDiameter = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
            local iNewBuildingRadius = iNewBuildingDiameter * 0.5
            local iAdjacencyBuildingRadius = AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) * 0.5
            local tAdjacencyBuildingPosition = oUnit:GetPosition()

            local iCurZ, iCurX
            local iCornerAdjust = math.min(iNewBuildingDiameter, iAdjacencyBuildingRadius * 2)

            local iCurOptionCount = 0

            if bDebugMessages == true then LOG(sFunctionRef..': tAdjacencyBuildingPosition='..repru(tAdjacencyBuildingPosition)..'; iAdjacencyBuildingRadius='..iAdjacencyBuildingRadius..'; iNewBuildingRadius='..iNewBuildingRadius..'; iCornerAdjust='..iCornerAdjust) end
            local aiBrain = oUnit:GetAIBrain()

            --First go along top and bottom:
            local iCurMod = 0
            local iMostBuildLocations = 0
            local iBestOptionCountRef
            for iZFactor = -1, 1, 2 do
                iCurOptionCount = iCurOptionCount + 1
                tiShieldBuildLocationOptions[iCurOptionCount] = {}
                iCurZ = tAdjacencyBuildingPosition[3] + (iAdjacencyBuildingRadius + iNewBuildingRadius) * iZFactor
                --Include corner positions even though not adjacent
                for iCurX = tAdjacencyBuildingPosition[1] - iCornerAdjust, tAdjacencyBuildingPosition[1] + iCornerAdjust, 1 do
                    if iCurMod > 0 then
                        iCurMod = iCurMod - 1
                    elseif AiBotEngineer.CanBuildAtLocation(aiBrain, sBlueprintToBuild, { iCurX, 0, iCurZ}, iPlateau, iLandZone, nil, false, true, false, true, false) then
                        tiShieldLocationCountByOption[iCurOptionCount] = (tiShieldLocationCountByOption[iCurOptionCount] or 0) + 1
                        tiShieldBuildLocationOptions[iCurOptionCount][tiShieldLocationCountByOption[iCurOptionCount]] = {iCurX, GetSurfaceHeight(iCurX, iCurZ), iCurZ}
                        iCurMod = iCurMod + iNewBuildingDiameter - 1
                        if tiShieldLocationCountByOption[iCurOptionCount] > iMostBuildLocations then
                            iMostBuildLocations = tiShieldLocationCountByOption[iCurOptionCount]
                            iBestOptionCountRef = iCurOptionCount
                            if iMostBuildLocations >= 3 then break end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished considering top or bottom, iZFactor='..(iZFactor or 'nil')..'; iCurOptionCount='..(iCurOptionCount or 'nil')..'; tiShieldBuildLocationOptions[iCurOptionCount]='..repru(tiShieldBuildLocationOptions[iCurOptionCount])..'; tiShieldLocationCountByOption[iCurOptionCount]='..(tiShieldLocationCountByOption[iCurOptionCount] or 'nil')..'; iMostBuildLocations='..iMostBuildLocations) end
                if iMostBuildLocations >= 3 then break end
                iCurMod = 0
            end
            if iMostBuildLocations < 3 then
                --Next go along the sides:
                for iXFactor = -1, 1, 2 do
                    iCurMod = 0
                    iCurOptionCount = iCurOptionCount + 1
                    tiShieldBuildLocationOptions[iCurOptionCount] = {}

                    iCurX = tAdjacencyBuildingPosition[1] + (iAdjacencyBuildingRadius + iNewBuildingRadius) * iXFactor
                    for iCurZ = tAdjacencyBuildingPosition[3] - iCornerAdjust, tAdjacencyBuildingPosition[3] + iCornerAdjust, 1 do
                        if iCurMod > 0 then
                            iCurMod = iCurMod - 1
                        elseif AiBotEngineer.CanBuildAtLocation(aiBrain, sBlueprintToBuild, { iCurX, 0, iCurZ}, iPlateau, iLandZone, nil, false, true, false, true, false) then
                            tiShieldLocationCountByOption[iCurOptionCount] = (tiShieldLocationCountByOption[iCurOptionCount] or 0) + 1
                            tiShieldBuildLocationOptions[iCurOptionCount][tiShieldLocationCountByOption[iCurOptionCount]] = {iCurX, GetSurfaceHeight(iCurX, iCurZ), iCurZ}
                            iCurMod = iCurMod + iNewBuildingDiameter - 1
                            if tiShieldLocationCountByOption[iCurOptionCount] > iMostBuildLocations then
                                iMostBuildLocations = tiShieldLocationCountByOption[iCurOptionCount]
                                iBestOptionCountRef = iCurOptionCount
                                if iMostBuildLocations >= 3 then break end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering left or right side, iXFactor='..(iXFactor or 'nil')..'; iCurOptionCount='..(iCurOptionCount or 'nil')..'; tiShieldBuildLocationOptions[iCurOptionCount]='..repru(tiShieldBuildLocationOptions[iCurOptionCount])..'; tiShieldLocationCountByOption[iCurOptionCount]='..(tiShieldLocationCountByOption[iCurOptionCount] or 'nil')..'; iMostBuildLocations='..iMostBuildLocations) end
                    if iMostBuildLocations >= 3 then break end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iMostBuildLocations='..iMostBuildLocations) end

            if iMostBuildLocations >= 1 then
                --Figure out the best faction engineer that could realistically build the shield by locating the closest factory of each faction type
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                local iRecordedCount = 0
                if not(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) then tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] = {} end
                table.insert(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection], oUnit)
                RecordNearbyFactoryForShieldEngineers(oUnit)

                if bDebugMessages == true then LOG(sFunctionRef..': Can build at least 2 shields close to each other and the gameender, will now pick the best set of shield options, unit position='..repru(oUnit:GetPosition())..'; iBestOptionCountRef='..(iBestOptionCountRef or 'nil')..'; tiShieldBuildLocationOptions for this='..repru(tiShieldBuildLocationOptions[iBestOptionCountRef])) end
                if iBestOptionCountRef then
                    oUnit[reftLocationsForPriorityShield] = {}
                    if bDebugMessages == true then LOG(sFunctionRef..': Recording priority shield locations, tLocations='..repru(tiShieldBuildLocationOptions[iBestOptionCountRef])) end
                    for iLocation, tLocation in tiShieldBuildLocationOptions[iBestOptionCountRef] do
                        iRecordedCount = iRecordedCount + 1
                        table.insert(oUnit[reftLocationsForPriorityShield], {tLocation[1], tLocation[2], tLocation[3]})
                        --Blacklist the location
                        AiBotEngineer.RecordBlacklistLocation(tLocation, iNewBuildingRadius, 600, oUnit)
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Added shild build location '..repru(tLocation)..' against the game ender and will record blacklist, Will draw shield locations in black')
                            AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tLocation, iNewBuildingRadius), 3, 100)
                        end
                    end
                    --Add other shield locations if there are any and we want more to get to 3
                    if iRecordedCount < 3 then
                        for iShieldOption, tShieldLocations in tiShieldBuildLocationOptions do
                            if not(iShieldOption == iBestOptionCountRef) then
                                for iLocation, tLocation in tShieldLocations do
                                    if AiBotEngineer.CanBuildAtLocation(aiBrain, sBlueprintToBuild, tLocation, iPlateau, iLandZone, nil, false, true, true, true, false) then
                                        iRecordedCount = iRecordedCount + 1
                                        table.insert(oUnit[reftLocationsForPriorityShield], {tLocation[1], tLocation[2], tLocation[3]})
                                        --Blacklist the location
                                        AiBotEngineer.RecordBlacklistLocation(tLocation, iNewBuildingRadius, 600, oUnit)
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef..': Added further shild build location '..repru(tLocation)..' against the game ender and will record blacklist, Will draw shield location')
                                            AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tLocation, iNewBuildingRadius), 4, 100)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    --Update any buildable locaitons around here
                    if iRecordedCount > 0 then
                        for iLocation, tLocation in oUnit[reftLocationsForPriorityShield] do
                            AiBotEngineer.CheckIfBuildableLocationsNearPositionStillValid(aiBrain, tLocation, true, 5)
                        end
                    end


                    --CLear any engineers with queued orders that will conflict with a shield location
                    local tEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false then
                        local bClearEngineer
                        local tEngineersToClear = {}
                        for iEngineer, oEngineer in tEngineersInZone do
                            bClearEngineer = false
                            if AiBotUtilities.IsTableEmpty(oEngineer[AiBotEngineer.reftQueuedBuildings]) == false then
                                for iQueueRef, tQueueDetails in oEngineer[AiBotEngineer.reftQueuedBuildings] do
                                    if tQueueDetails[AiBotEngineer.subrefBuildingLocation] then
                                        for iReservedLocation, tReservedLocation in oUnit[reftLocationsForPriorityShield] do
                                            if AiBotUtilities.GetDistanceBetweenPositions(tReservedLocation, tQueueDetails[AiBotEngineer.subrefBuildingLocation]) - tQueueDetails[AiBotEngineer.subrefBuildingRadius] < 0 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have queued building '..tQueueDetails[AiBotEngineer.subrefBuildingID]..' at location that is within '..AiBotUtilities.GetDistanceBetweenPositions(tReservedLocation, tQueueDetails[AiBotEngineer.subrefBuildingLocation])..' of a shield reserved location, with building radius of '..tQueueDetails[AiBotEngineer.subrefBuildingRadius]..' so will clear the engineer') end
                                                bClearEngineer = true
                                                table.insert(tEngineersToClear, oEngineer)
                                                break
                                            end
                                        end
                                        if bClearEngineer then break end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of engineers to clear empty='..tostring(AiBotUtilities.IsTableEmpty(tEngineersToClear))) end
                        if AiBotUtilities.IsTableEmpty(tEngineersToClear) == false then
                            for iEngineer, oEngineer in tEngineersToClear do
                                AiBotOrders.IssueTrackedClearCommands(oEngineer)
                            end
                        end
                    end


                end
                --[[for iOption, tLocations in tiShieldBuildLocationOptions do
                    if (tiShieldBuildLocationOptions[iOption] or 0) >= iMostBuildLocations then
                        oUnit[reftLocationsForPriorityShield] = {}
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording priority shield locations, tLocations='..repru(tLocations)..'; tiShieldBuildLocationOptions[iOption]='..repru(tiShieldBuildLocationOptions[iOption])..'; iOption='..(iOption or 'nil')) end
                        for iLocation, tLocation in tLocations do
                            table.insert(oUnit[reftLocationsForPriorityShield], {tLocation[1], tLocation[2], tLocation[3]})
                            --Blacklist the location
                            AiBotEngineer.RecordBlacklistLocation(tLocation, iNewBuildingRadius, 600, oUnit)
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Will draw shield locations in black')
                                AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tLocation, iNewBuildingRadius), 3, 100)
                            end
                        end
                        break
                    end
                end--]]
                AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbStartedOnUnitWantingSpecialShielding] = true
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBestFactionFactoryOfCategory(oUnitToGetTo, iCategory, iDistanceCap, iLandSubteam, iUnitPlateau, tLZData)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBestFactionFactoryOfCategory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iClosestFactory = iDistanceCap
    local iCurDist, iCurPlateau, iCurLandZone, iCurZoneDist
    local iClosestZoneDist = iDistanceCap + 60
    local oBestFactory
    for iBrain, oBrain in AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        local tFactoriesOfCategory = oBrain:GetListOfUnits(iCategory, false, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of factories of catory empty for brain '..oBrain.Nickname..'='..tostring(AiBotUtilities.IsTableEmpty(tFactoriesOfCategory))) end
        if AiBotUtilities.IsTableEmpty(tFactoriesOfCategory) == false then
            for iFactory, oFactory in tFactoriesOfCategory do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering factory '..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; Fraction complete='..oFactory:GetFractionComplete()..'; Is factory valid='..tostring(AiBotUnitInfo.IsUnitValid(oFactory))) end
                if oFactory:GetFractionComplete() == 1 and AiBotUnitInfo.IsUnitValid(oFactory) then
                    --Is this in the same plateau?
                    iCurPlateau, iCurLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oFactory:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurPlateau='..(iCurPlateau or 'nil')..'; iUnitPlateau='..(iUnitPlateau or 'nil')) end
                    if iCurPlateau == iUnitPlateau then
                        --Get the travel distance
                        iCurZoneDist = tLZData[AiBotMap.subrefLZTravelDistToOtherLandZones][iCurPlateau][iCurLandZone]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering factory with iCurZoneDist='..(iCurZoneDist or 'nil')..'; iClosestZoneDist='..iClosestZoneDist..'; Dist between factory and unit to cover='..AiBotUtilities.GetDistanceBetweenPositions(oUnitToGetTo:GetPosition(), oFactory:GetPosition())) end
                        if iCurZoneDist then
                            if iCurZoneDist <= iClosestZoneDist then
                                if iCurZoneDist < iClosestZoneDist then
                                    iClosestZoneDist = iCurZoneDist
                                    iClosestFactory = iDistanceCap + 100 --reset the distance so any factory in a closer zone will be preferred, even if the factory itself might be further away
                                end
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnitToGetTo:GetPosition(), oFactory:GetPosition())
                                if iCurDist < iClosestFactory then
                                    iClosestFactory = iCurDist
                                    oBestFactory = oFactory
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oBestFactory
end

function UnitNoLongerRequiresFactoryFactionShieldEngineers(oUnit)
    local oFactory = oUnit[refoNearbyFactoryOfFaction]
    if AiBotUnitInfo.IsUnitValid(oFactory) and AiBotUtilities.IsTableEmpty(oFactory[reftoUnitsWantingFactoryEngineers]) == false then
        for iEntry, oEntry in oFactory[reftoUnitsWantingFactoryEngineers] do
            if oEntry == oUnit then
                table.remove(oFactory[reftoUnitsWantingFactoryEngineers], iEntry)
                break
            end
        end
        oUnit[refoNearbyFactoryOfFaction] = nil
    end
end

function RecordNearbyFactoryForShieldEngineers(oUnit, tbOptionalFactionsWanted)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordNearbyFactoryForShieldEngineers'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iDistanceCap = 350 --Wont try and get engineers from factories further away than this.
    local aiBrain = oUnit:GetAIBrain()
    local iLandSubteam = aiBrain.AiBotLandSubteam
    local oBestFactory

    local iUnitPlateau, iUnitLandZone
    if oUnit[reftArtiTemplateRefs] then iUnitPlateau = oUnit[reftArtiTemplateRefs][1] iUnitLandZone = oUnit[reftArtiTemplateRefs][2]
    else
        iUnitPlateau, iUnitLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want a special factory for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tbOptionalFactionsWanted='..repru(tbOptionalFactionsWanted)..'; iUnitPlateau='..(iUnitPlateau or 'nil')..'; iUnitLandZone='..(iUnitLandZone or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if (iUnitLandZone or 0) > 0 then
        local tLZData = AiBotMap.tAllPlateaus[iUnitPlateau][AiBotMap.subrefPlateauLandZones][iUnitLandZone]
        --Seraphim factories
        if not(tbOptionalFactionsWanted) or tbOptionalFactionsWanted[AiBotUnitInfo.refFactionSeraphim] then
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have Seraphim T3 land on our land subteam, iLandSubteam='..iLandSubteam..'; AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionSeraphim]='..repru(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionSeraphim])) end
            if (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionSeraphim][3] or 0) > 0 then
                oBestFactory = GetBestFactionFactoryOfCategory(oUnit, AiBotUnitInfo.refCategoryLandFactory * categories.TECH3 * categories.SERAPHIM, iDistanceCap, iLandSubteam, iUnitPlateau, tLZData)
                if bDebugMessages == true then LOG(sFunctionRef..': oBestFactory after checking for seraphim='..(oBestFactory.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestFactory) or 'nil')) end
            end
        end
        if not(oBestFactory) then
            --Aeon
            if not(tbOptionalFactionsWanted) or tbOptionalFactionsWanted[AiBotUnitInfo.refFactionAeon] then
                if (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionAeon][3] or 0) > 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': About to try and get the best factory at time '..GetGameTimeSeconds()..'; iDistanceCap='..(iDistanceCap or 'nil')..'; iLandSubteam='..(iLandSubteam or 'nil')..'; iUnitPlateau='..(iUnitPlateau or 'nil')..'; is tLZData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData))) end
                    oBestFactory = GetBestFactionFactoryOfCategory(oUnit, AiBotUnitInfo.refCategoryLandFactory * categories.TECH3 * categories.AEON, iDistanceCap, iLandSubteam, iUnitPlateau, tLZData)
                end
            end
            if not(oBestFactory) then
                --UEF
                if not(tbOptionalFactionsWanted) or tbOptionalFactionsWanted[AiBotUnitInfo.refFactionUEF] then
                    if (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionUEF][3] or 0) > 0 then
                        oBestFactory = GetBestFactionFactoryOfCategory(oUnit, AiBotUnitInfo.refCategoryLandFactory * categories.TECH3 * categories.UEF, iDistanceCap, iLandSubteam, iUnitPlateau, tLZData)
                    end
                end
                --If dont have any of these factions then dont worry about getting a faction specific shield
            end
        end
        --If have a best factory then record against the game ender
        oUnit[refoNearbyFactoryOfFaction] = oBestFactory
        if bDebugMessages == true then LOG(sFunctionRef..': Finished looking for nearby factories, oBestFactory='..(oBestFactory.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestFactory) or 'nil')) end
        if oBestFactory then
            if not(oBestFactory[reftoUnitsWantingFactoryEngineers]) then
                oBestFactory[reftoUnitsWantingFactoryEngineers] = {}
            end

            table.insert(oBestFactory[reftoUnitsWantingFactoryEngineers], oUnit)
            local iFactoryPlateau, iFactoryLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oBestFactory:GetPosition())
            local tFactoryLZTeamData = AiBotMap.tAllPlateaus[iFactoryPlateau][AiBotMap.subrefPlateauLandZones][iFactoryLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
            local bRecordedInZoneAlready = false
            if not(tFactoryLZTeamData[AiBotMap.reftFactoriesWantedForEngineers]) then tFactoryLZTeamData[AiBotMap.reftFactoriesWantedForEngineers] = {}
            else
                for iExistingFactory, oExistingFactory in tFactoryLZTeamData[AiBotMap.reftFactoriesWantedForEngineers] do
                    if oExistingFactory == oBestFactory then
                        bRecordedInZoneAlready = true
                    end
                end
            end
            if not(bRecordedInZoneAlready) then
                table.insert(tFactoryLZTeamData[AiBotMap.reftFactoriesWantedForEngineers], oBestFactory)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RemoveFactoryFromZoneList(oFactory)
    --If a factory was assigned as providing engineers to a unit such as a gameender for shielding, it'd be recorded in the zone it was in - this removes it (e.g. intended where the factory ahs no units to assist, or the factory is dead)
    local iFactoryPlateau, iFactoryLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oFactory:GetPosition())
    if iFactoryLandZone > 0 then
        local tLZTeamData = AiBotMap.tAllPlateaus[iFactoryPlateau][AiBotMap.subrefPlateauLandZones][iFactoryLandZone][AiBotMap.subrefLZTeamData][oFactory:GetAIBrain().AiBotTeam]
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers]) == false then
            local iExistingEntries = table.getn(tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers])
            for iCurEntry = iExistingEntries, 1, -1 do
                if tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers][iCurEntry] == oFactory or not(AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers][iCurEntry])) then
                    table.remove(tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers], iCurEntry)
                end
            end
        end
    end
end

function ClearTrackingOfDeadUnitWantingFactoryEngineers(oUnit)
    --If a gameender had a factory assigned as providing engineers e.g. for shielding, and the gameender is dead, then this clears related tracking
    if AiBotUtilities.IsTableEmpty(oUnit[refoNearbyFactoryOfFaction][reftoUnitsWantingFactoryEngineers]) == false then
        local oFactory = oUnit[refoNearbyFactoryOfFaction]
        local iExistingEntries = table.getn(oFactory[reftoUnitsWantingFactoryEngineers])
        for iCurEntry = iExistingEntries, 1, -1 do
            if oFactory[reftoUnitsWantingFactoryEngineers][iCurEntry] == oUnit or not(AiBotUnitInfo.IsUnitValid(oFactory[reftoUnitsWantingFactoryEngineers][iCurEntry])) then
                table.remove(oFactory[reftoUnitsWantingFactoryEngineers], iCurEntry)
            end
        end
        if AiBotUtilities.IsTableEmpty(  oFactory[reftoUnitsWantingFactoryEngineers]) then
            RemoveFactoryFromZoneList(oFactory)
        end
    end
    --Remove this unit from the zone
    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
    local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) == false then
        local iTotalEntries = table.getn(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection])
        for iCurEntry = iTotalEntries, 1, -1 do
            if tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection][iCurEntry] == oUnit or not(AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection][iCurEntry])) then
                table.remove(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection], iCurEntry)
            end
        end
    end
end

function UpdateTrackingOfDeadFactoryProvidingEngineers(oUnit)
    --If a factory that was providing engineers e.g. to a gameender for shielding dies, this updates the tracking variables and looks for a new factory to provide engineers
    local iExistingEntries = table.getn(oUnit[reftoUnitsWantingFactoryEngineers])
    for iCurEntry = iExistingEntries, 1, -1 do
        if oUnit[reftoUnitsWantingFactoryEngineers][iCurEntry][refoNearbyFactoryOfFaction] == oUnit then
            oUnit[reftoUnitsWantingFactoryEngineers][iCurEntry][refoNearbyFactoryOfFaction] = nil
            if AiBotUnitInfo.IsUnitValid(oUnit[reftoUnitsWantingFactoryEngineers][iCurEntry]) then
                --Get a new 'best factory to provide engineers' for the game ender
                RecordNearbyFactoryForShieldEngineers(oUnit[reftoUnitsWantingFactoryEngineers][iCurEntry])
            end
        end
    end
    --Remove this factory from the list of factories in the zone
    oUnit[reftoUnitsWantingFactoryEngineers] = nil
    RemoveFactoryFromZoneList(oUnit)
end

function AssignShieldToGameEnder(oConstruction, oEngineer, oOptionalBackupGameEnderToAssignTo)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignShieldToGameEnder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oConstruction:GetPosition())

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at game time '..GetGameTimeSeconds()..'; oConstruction='..(oConstruction.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oConstruction) or 'nil')..'; oEngineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..'; oConstruction iPlateau='..(iPlateau or 'nil')..'; Zone='..(iLandZone or 'nil')..'; oConstruction position='..repru(oConstruction:GetPosition())) end
    if (iLandZone or 0) > 0 then
        local oGameEnder
        local aiBrain = oEngineer:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
        if not(oEngineer[AiBotEngineer.refoUnitActivelyShielding]) then
            oGameEnder = oOptionalBackupGameEnderToAssignTo
            if not(oGameEnder) then
                AiBotUtilities.ErrorHandler('Dont have a unit recorded that the engineer is actively shielding, will just get the first gameender in the zone')
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) == false then
                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
                        oGameEnder = oUnit
                        break
                    end
                end
            end
        else
            oGameEnder = oEngineer[AiBotEngineer.refoUnitActivelyShielding]
            if bDebugMessages == true then LOG(sFunctionRef..': Engineer is actively shielding oGameEnder='..(oGameEnder.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oGameEnder) or 'nil')) end
        end
        if AiBotUnitInfo.IsUnitValid(oGameEnder) then
            if not(oGameEnder[reftoSpecialAssignedShields]) then
                oGameEnder[reftoSpecialAssignedShields] = {}
            end
            table.insert(oGameEnder[reftoSpecialAssignedShields], oConstruction)
            oConstruction[refoGameEnderBeingShielded] = oGameEnder
            if bDebugMessages == true then LOG(sFunctionRef..': Added oConstruction to the table of assigned shields for gameender') end
        else
            if oGameEnder then
                AiBotUtilities.ErrorHandler('Dont have a valid unit')
            end
        end
    else
        AiBotUtilities.ErrorHandler('Dont have valid land zone for construction')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

