function DetermineBuildingExpectedValues()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DetermineBuildingExpectedValues'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local tsT1EnergyStorageBlueprints = EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryEnergyStorage)
    local iLowestTechTier = 5
    local iHighestEnergyStored = 0
    local iCurTechLevel
    if AiBotUtilities.IsTableEmpty(tsT1EnergyStorageBlueprints) == false then
        for _, sBlueprint in tsT1EnergyStorageBlueprints do
            local oBP = __blueprints[sBlueprint]
            if (oBP.Economy.StorageEnergy or 0) > 0 then
                iCurTechLevel = AiBotUnitInfo.GetBlueprintTechLevel(sBlueprint)
                if iCurTechLevel < iLowestTechTier then
                    iLowestTechTier = iCurTechLevel
                    iHighestEnergyStored = oBP.Economy.StorageEnergy
                elseif iCurTechLevel == iLowestTechTier and iHighestEnergyStored < oBP.Economy.StorageEnergy then
                    iHighestEnergyStored = oBP.Economy.StorageEnergy
                end
            end
        end
    end
    iEnergyStorageExpectedCapacity = (iHighestEnergyStored or 5000)
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, iHighestEnergyStored='..iHighestEnergyStored..'; iLowestTechTier='..iLowestTechTier) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedConsiderLaunchingMissile(oLauncher, iSecondsToWait, bCheckIfStillLoaded, bOnlyConsiderIfNotFiredRecently)
    --Call via forkthread
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DelayedConsiderLaunchingMissile'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(iSecondsToWait)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oLauncher) then
        local bProceed = true
        if bCheckIfStillLoaded then
            bProceed = false
            local iMissiles = 0
            if oLauncher.GetTacticalSiloAmmoCount then iMissiles = iMissiles + oLauncher:GetTacticalSiloAmmoCount() end
            if oLauncher.GetNukeSiloAmmoCount then iMissiles = iMissiles + oLauncher:GetNukeSiloAmmoCount() end
            if iMissiles > 0 then bProceed = true end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Dealing with oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..'; bProceed='..tostring(bProceed)..'; Time='..GetGameTimeSeconds()) end
        if bProceed then
            if bDebugMessages == true then LOG(sFunctionRef..': Time since last weapon event='..(GetGameTimeSeconds() - oLauncher[AiBotUnitInfo.refiLastWeaponEvent] or -100)..'; iSecondsToWait='..iSecondsToWait..'; bOnlyConsiderIfNotFiredRecently='..tostring(bOnlyConsiderIfNotFiredRecently or false)) end
            if not(bOnlyConsiderIfNotFiredRecently) or GetGameTimeSeconds() - (oLauncher[AiBotUnitInfo.refiLastWeaponEvent] or -100) > iSecondsToWait then
                if bDebugMessages == true then LOG(sFunctionRef..': Will consider launching a missile') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                --LOG('consideration of launching missile 4')
                ConsiderLaunchingMissile(oLauncher)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AreUnitsAdjacent(oFirstUnit, oSecondUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AreUnitsAdjacent'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iFirstUnitSize = AiBotUnitInfo.GetBuildingSize(oFirstUnit.UnitId) * 0.5
    local iSecondUnitSize = AiBotUnitInfo.GetBuildingSize(oSecondUnit.UnitId) * 0.5
    local iMaxDif = iFirstUnitSize + iSecondUnitSize + 0.749 --assumed margin of error after where got to with mexes (where would go with 2.749 distance)
    local iMinDif = iFirstUnitSize + iSecondUnitSize - 0.749

    local iXDif = math.abs(oFirstUnit:GetPosition()[1] - oSecondUnit:GetPosition()[1])
    local iZDif = math.abs(oFirstUnit:GetPosition()[3] - oSecondUnit:GetPosition()[3])
    if bDebugMessages == true then LOG(sFunctionRef..': Considering oFirstUnit='..oFirstUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnit)..'; Position='..repru(oFirstUnit:GetPosition())..'; Size='..iFirstUnitSize..'; Second unit='..oSecondUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSecondUnit)..'; oSecondUnit position='..repru(oSecondUnit:GetPosition())..'; iSecondUnitSize='..iSecondUnitSize..'; iXDif='..iXDif..'; iZDif='..iZDif) end
    if (iXDif <= iMaxDif and iXDif >= iMinDif) or (iZDif <= iMaxDif and iZDif >= iMinDif) then
        --Are we in a corner position?
        --[[local iCornerDif = iFirstUnitSize + iSecondUnitSize - 0.1
        if bDebugMessages == true then LOG(sFunctionRef..': Units are close to each other, iXDif='..iXDif..'; iZDif='..iZDif..'; iCornerDif='..iCornerDif) end
        if iXDif < iCornerDif or iZDif < iCornerDif then--]]
        --Max smallest dif due to size dif
        local iMaxSmallestDif = math.abs(iFirstUnitSize - iSecondUnitSize) + 0.749
        if iXDif < iMaxSmallestDif or iZDif < iMaxSmallestDif then


            if bDebugMessages == true then LOG(sFunctionRef..': Units are adjacent') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
        --end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Units are adjacent') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ConsiderGiftingPowerToTeammateForAdjacency(oUnit)
    --Call when a t3 power has been constructed by an AiBot brain
    --WARNING: Not tested fully, so only gives a rough approximation.  do further testing if more accuracy needed

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderGiftingPowerToTeammateForAdjacency'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Wait 1s, and then check if unit is upgrading and is still valid, as otherwise can have issues
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(1)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            LOG(sFunctionRef..': Valid unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit))
        else LOG(sFunctionRef..': Unit is no longer valid, unit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil'))
        end
    end
    if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Upgrading')) and not(oUnit:IsUnitState('BeingUpgraded')) then
        local aiBrain = oUnit:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
            local iPotentialAdjacencyCategories = AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryAirFactory + AiBotUnitInfo.refCategoryStructure * categories.TECH3

            if EntityCategoryContains(AiBotUnitInfo.refCategoryT3Power, oUnit.UnitId) then
                --Are we adjacent to any air factories, omni, nuke launchers, t3 arti, owned by another teammate, and have no adjacency of such units on our own?

                if bDebugMessages == true then LOG(sFunctionRef..': is table of adjacent units empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit.AdjacentUnits))) end
                if AiBotUtilities.IsTableEmpty(oUnit.AdjacentUnits) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(iPotentialAdjacencyCategories, oUnit.AdjacentUnits)) then
                    --We have no existing adjacency
                    local tNearbyUnitsOfInterest = aiBrain:GetUnitsAroundPoint(iPotentialAdjacencyCategories, oUnit:GetPosition(), AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) + 1, 'Ally')
                    if AiBotUtilities.IsTableEmpty(tNearbyUnitsOfInterest) == false then
                        for iNearbyUnit, oNearbyUnit in tNearbyUnitsOfInterest do
                            if not(oNearbyUnit:GetAIBrain() == aiBrain) and oNearbyUnit:GetAIBrain().AiBotTeam == iTeam and (oNearbyUnit:GetAIBrain().AiBotAI or ScenarioInfo.Options.AiBotTeammate == 1) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oNearbyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearbyUnit)..'; Position='..repru(oNearbyUnit:GetPosition())..'; oUnit position='..repru(oUnit:GetPosition())) end
                                if AreUnitsAdjacent(oUnit, oNearbyUnit) then
                                    --Gift to other brain
                                    AiBotTeam.TransferUnitsToPlayer({oUnit}, oNearbyUnit:GetAIBrain():GetArmyIndex(), false)
                                    break
                                end
                            end
                        end
                    end
                end
            else
                local iSpecificAdjacencyCategories = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti - categories.MOBILE + AiBotUnitInfo.refCategorySML * categories.TECH3 + AiBotUnitInfo.refCategoryAirFactory * categories.TECH3 + AiBotUnitInfo.refCategoryMassFab * categories.TECH3 + AiBotUnitInfo.refCategoryT3Radar
                if EntityCategoryContains(iSpecificAdjacencyCategories, oUnit.UnitId) then
                    if bDebugMessages == true then LOG(sFunctionRef..': is table of adjacent units empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit.AdjacentUnits))) end
                    if AiBotUtilities.IsTableEmpty(oUnit.AdjacentUnits) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT3Power, oUnit.AdjacentUnits)) then
                        --We have no existing adjacency
                        local tNearbyUnitsOfInterest = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT3Power, oUnit:GetPosition(), AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) + 1, 'Ally')
                        if AiBotUtilities.IsTableEmpty(tNearbyUnitsOfInterest) == false then
                            for iNearbyUnit, oNearbyUnit in tNearbyUnitsOfInterest do
                                if not(oNearbyUnit:GetAIBrain() == aiBrain) and oNearbyUnit:GetAIBrain().AiBotTeam == iTeam and (oNearbyUnit:GetAIBrain().AiBotAI or ScenarioInfo.Options.AiBotTeammate == 1) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oNearbyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearbyUnit)..'; Position='..repru(oNearbyUnit:GetPosition())..'; oUnit position='..repru(oUnit:GetPosition())) end
                                    if AreUnitsAdjacent(oUnit, oNearbyUnit) then
                                        --Gift nearby t3 power to this unit's brain owner
                                        AiBotTeam.TransferUnitsToPlayer({oNearbyUnit}, oUnit:GetAIBrain():GetArmyIndex(), false)
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function JustBuiltParagon(oParagon)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'JustBuiltParagon'

    WaitTicks(1)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotUnitInfo.IsUnitValid(oParagon) then
        if bDebugMessages == true then LOG(sFunctionRef..': oParagon owner='..oParagon:GetAIBrain().Nickname..'; Unit='..oParagon.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oParagon)..'; GameTime='..GetGameTimeSeconds()..'; Fraction complete='..oParagon:GetFractionComplete()..'; oParagon(AiBotBuiltParagon)='..tostring(oParagon['AiBotBuiltParagon'] or false)) end
        if not(oParagon['AiBotBuiltParagon']) then
            oParagon['AiBotBuiltParagon'] = true
            local aiBrain = oParagon:GetAIBrain()
            local iTeam = aiBrain.AiBotTeam
            local oOtherBrain
            local bGiftedParagonToOtherBrain = false
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                --If we now own 2+ paragons, then gift this to a teammate
                if bDebugMessages == true then LOG(sFunctionRef..': Cur paragon units owned by brain='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryParagon)) end
                if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryParagon) >= 2 then
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        if not(oBrain == aiBrain) and not(oBrain.AiBotIsDefeated) and not(oBrain[AiBotEconomy.refbBuiltParagon]) then
                            if oBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 500 and oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer) >= 2 then
                                oOtherBrain = oBrain
                                break
                            end
                        end
                    end
                    if not(oOtherBrain) and ScenarioInfo.Options.AiBotTeammate == 1 then
                        for iBrain, oBrain in ArmyBrains do
                            if oBrain.AiBotTeam == iTeam and not(oBrain.AiBotAI) and not(oBrain[AiBotEconomy.refbBuiltParagon]) and not(oBrain.CampaignAI) and oBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 500 and not(oBrain.AiBotIsDefeated) and oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer) >= 3 and oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryParagon) == 0 then
                                oOtherBrain = oBrain
                                break
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is oOtherBrain nil='..tostring(oOtherBrain == nil)) end
                    if oOtherBrain then
                        bGiftedParagonToOtherBrain = true
                        if (AiBotOrders.bDontConsiderCombinedArmy or oParagon.AiBotActive) then
                            local tUnitsToGift = {oParagon}
                            AiBotTeam.TransferUnitsToPlayer(tUnitsToGift, oOtherBrain:GetArmyIndex(), false)
                            if not(oOtherBrain.AiBotAI) then
                                AiBotChat.SendMessage(aiBrain, 'ParagGift'..aiBrain:GetArmyIndex(), 'You look like you could use this resource generator more than me', 0, 300, true, true, nil, nil)
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Have gifted paragon to teammate') end
                        end
                    end
                end
                if not(bGiftedParagonToOtherBrain) then
                    --Gift mexes, mass storage, half of our pgens and (if are getting near unit cap) combat units to another teammate; meanwhile have teammates gift mass using units (factories engineers, SACUs) to us
                    --SACUs lose upgrades on transfer!
                    local AiBotACU = import('/lua/AiBot/AI/AiBotACU.lua')
                    local iMaxEngineersToGift = math.max(aiBrain[AiBotOverseer.refiExpectedRemainingCap] * 0.5, 30)
                    if iMaxEngineersToGift < 80 and GetArmyUnitCap(aiBrain:GetArmyIndex()) >= 700 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 1 then iMaxEngineersToGift = math.min(80, math.max(iMaxEngineersToGift, 30 + 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel])) end
                    local iEngineersGifted = 0
                    if bDebugMessages == true then LOG(sFunctionRef..': Getting details of engineers and factories and T1-T2 mexes to gift from paragon owner to teammates, iMaxEngineersToGift='..iMaxEngineersToGift) end
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; oBrain[AiBotEconomy.refiGrossMassBaseIncome]='..oBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                        if not(oBrain == aiBrain) and not(oBrain.AiBotIsDefeated) then
                            if oBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 500 then
                                oOtherBrain = oBrain
                                --Gift all non-land factories (retain land so we still build some units), fatboys, nukes, SMD, aircraft carriers
                                local tFactoriesToGift = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalFactory + AiBotUnitInfo.refCategoryAirFactory + AiBotUnitInfo.refCategoryQuantumGateway + AiBotUnitInfo.refCategorySML + AiBotUnitInfo.refCategorySMD + AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryCarrier + AiBotUnitInfo.refCategoryHive + AiBotUnitInfo.refCategoryRadar, false, true)
                                local tUnitsToGift = {}
                                if AiBotUtilities.IsTableEmpty(tFactoriesToGift) == false then
                                    for iUnit, oUnit in tFactoriesToGift do
                                        if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                                            table.insert(tUnitsToGift, oUnit)
                                        end
                                    end
                                end
                                if bDebugMessages == true then
                                    if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                                        LOG(sFunctionRef..': Finished considering factories, nukes, smd etc, size of tUnitsToGift='..table.getn(tUnitsToGift))
                                    else
                                        LOG(sFunctionRef..': Finished considering factories, none to gift')
                                    end
                                end
                                local tMexesToGift
                                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) > 0 then --Check we have a t3 mex (as proxy to make sure dont have unit restrictions)
                                    tMexesToGift = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryT1Mex + AiBotUnitInfo.refCategoryT2Mex, false, true)
                                end
                                if AiBotUtilities.IsTableEmpty(tMexesToGift) == false then
                                    for iMex, oMex in tMexesToGift do
                                        if not(oMex:IsUnitState('Upgrading')) or oMex:GetWorkProgress() <= 0.2 then
                                            table.insert(tUnitsToGift, oMex)
                                        end
                                    end
                                end
                                if bDebugMessages == true then
                                    if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                                        LOG(sFunctionRef..': Finished considering mexes, size of tUnitsToGift='..table.getn(tUnitsToGift))
                                    else
                                        LOG(sFunctionRef..': Finished considering mexes, none to gift')
                                    end
                                end
                                --FAF and staem - xfer SACUs that lack RAS upgrade and arent upgrading
                                if AiBotUtilities.bFAFActive or AiBotUtilities.bSteamActive then
                                    local tNonRASSACUs = oBrain:GetListOfUnits(categories.SUBCOMMANDER, false, true)
                                    if AiBotUtilities.IsTableEmpty(tNonRASSACUs) == false then
                                        for iSACU, oSACU in tNonRASSACUs do
                                            --Dont transfer shield SACUs being used for GE template, or RAS SACUs
                                            --Dont transfer if have any upgrades as theyre lost on transfer
                                            if not(oSACU:IsUnitState('Upgrading')) and oSACU[AiBotACU.refiUpgradeCount] == 0 then
                                                table.insert(tUnitsToGift, oSACU)
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then
                                    if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                                        LOG(sFunctionRef..': Finished considering SACUs, size of tUnitsToGift='..table.getn(tUnitsToGift))
                                    else
                                        LOG(sFunctionRef..': Finished considering SACUs, none to gift')
                                    end
                                end
                                --Fixed shields - xfer if not part of GE template
                                local tFixedShields = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFixedShield)
                                if AiBotUtilities.IsTableEmpty(tFixedShields) == false then
                                    for iShield, oShield in tFixedShields do
                                        if (not(oShield:IsUnitState('Upgrading')) or oShield:GetWorkProgress() <= 0.1) and not(oShield[reftArtiTemplateRefs]) then
                                            table.insert(tUnitsToGift, oShield)
                                        end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering shields, Size of tUnitsToGift to gift='..table.getn(tUnitsToGift)) end
                                    AiBotTeam.TransferUnitsToPlayer(tUnitsToGift, aiBrain:GetArmyIndex(), false)
                                end
                                if iEngineersGifted < iMaxEngineersToGift then
                                    local tEngineersAvailable = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer, false, true)
                                    if AiBotUtilities.IsTableEmpty(tEngineersAvailable) == false then
                                        local tEngineersToGift = {}
                                        local iCurCount = 0

                                        for iUnit, oUnit in tEngineersAvailable do
                                            if iCurCount > 0 then
                                                if not(oUnit:IsUnitState('Attached')) and not(oUnit[AiBotEngineer.refbPrimaryBuilder]) then
                                                    table.insert(tEngineersToGift, oUnit)
                                                    iEngineersGifted = iEngineersGifted + 1
                                                    if iEngineersGifted >= iMaxEngineersToGift then break end
                                                end
                                            end
                                            iCurCount = iCurCount + 1
                                            if iCurCount >= 3 then --i.e. transfer 75% of engineers
                                                iCurCount = 0
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering engineers, is tEngineersToGift empty='..tostring(AiBotUtilities.IsTableEmpty(tEngineersToGift))..'; iEngineersGifted='..iEngineersGifted) end
                                        if AiBotUtilities.IsTableEmpty(tEngineersToGift) == false then
                                            AiBotTeam.TransferUnitsToPlayer(tEngineersToGift, aiBrain:GetArmyIndex(), false)
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if not(oOtherBrain) and ScenarioInfo.Options.AiBotTeammate == 1 then
                --Do we have other (non-AiBot) teammates we can gift to, that aren't campaign AI?
                local oFirstTeammateBrain
                local oFirstHumanBrain
                for iBrain, oBrain in ArmyBrains do
                    if not(oBrain.AiBotIsDefeated) and not(oBrain:IsDefeated()) and oBrain.AiBotTeam == aiBrain.AiBotTeam and not(oBrain == aiBrain) and not(oBrain.CampaignAI) then
                        if not(oFirstTeammateBrain) then oFirstTeammateBrain = oBrain end
                        if not(oBrain.BrainType == 'AI') and not(oFirstHumanBrain) then
                            oFirstHumanBrain = oBrain
                            break
                        end
                    end
                end
                if oFirstHumanBrain then oOtherBrain = oFirstHumanBrain else oOtherBrain = oFirstTeammateBrain end
            end
            if oOtherBrain and not(bGiftedParagonToOtherBrain) then
                local tUnitsToGift = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryT3Mex + AiBotUnitInfo.refCategoryT1Power + AiBotUnitInfo.refCategoryT2Power + AiBotUnitInfo.refCategoryRASSACU + AiBotUnitInfo.refCategoryMassFab, false, true)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering gifting t3 mexes an any storage by such mexes to teammates') end
                if AiBotUtilities.IsTableEmpty(tUnitsToGift) then
                    tUnitsToGift = {}
                end

                local tMassStorage = aiBrain:GetListOfUnits( AiBotUnitInfo.refCategoryMassStorage, false, true)
                local tUnitsToPartiallyGift
                if AiBotUtilities.IsTableEmpty(tMassStorage) == false then
                    for iUnit, oUnit in tMassStorage do
                        --Is it near T3 mex?
                        local rSearchRectangle = AiBotUtilities.GetRectAroundLocation(oUnit:GetPosition(), 2.749)
                        local tNearbyUnits = GetUnitsInRect(rSearchRectangle) --at 1.5 end up with storage thats not adjacent being gifted in some cases but not in others; at 1 none of it gets gifted; the mass storage should be exactly 2 from the mex; however even at 2.1, 2.25 and 2.499 had cases where the mex wasnt identified so will try 2.75 since distances can vary/be snapped to the nearest 0.5 I think
                        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                            local tNearbyT3Mex = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT3Mex, tNearbyUnits)
                            if AiBotUtilities.IsTableEmpty(tNearbyT3Mex) == false then
                                table.insert(tUnitsToGift, oUnit)
                            end
                        end
                    end
                end

                if bDebugMessages == true then
                    if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                        LOG(sFunctionRef..': Finished checking for mass storage, tUnitsToGift size='..table.getn(tUnitsToGift))
                    else
                        LOG(sFunctionRef..': tUnitsToGift is empty after checking for mass storage')
                    end
                end
                local tT3Power = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryT3Power, false, true)
                if AiBotUtilities.IsTableEmpty(tT3Power) == false then
                    local iCurCount = -1
                    local iGiftThreshold = 1
                    for iUnit, oUnit in tT3Power do
                        iCurCount = iCurCount + 1
                        if iCurCount >= iGiftThreshold then
                            iCurCount = 0
                            table.insert(tUnitsToGift, oUnit)
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Size of tT3Power='..table.getn(tT3Power)) end
                end
                if bDebugMessages == true then
                    if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                        LOG(sFunctionRef..': Finished checking for power, tUnitsToGift size='..table.getn(tUnitsToGift))
                    else
                        LOG(sFunctionRef..': tUnitsToGift is empty after checking for power')
                    end
                end
                --If used up at laest half our unit cap then gift combta units to a teammate to free up some space
                if oOtherBrain.AiBotAI and oOtherBrain.BrainType == 'AI' and GetArmyUnitCostTotal(aiBrain:GetArmyIndex()) / GetArmyUnitCap(aiBrain:GetArmyIndex()) >= 0.5 then
                    tUnitsToPartiallyGift = aiBrain:GetListOfUnits(categories.MOBILE * categories.AIR + categories.LAND * categories.MOBILE + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryStructureAA - categories.COMMAND - categories.SUBCOMMANDER - categories.INSIGNIFICANTUNIT - categories.UNSELECTABLE - categories.EXPERIMENTAL - categories.ENGINEER - categories.FACTORY - categories.EXTERNALFACTORYUNIT, false, true)
                    if AiBotUtilities.IsTableEmpty(tUnitsToPartiallyGift) == false then
                        for iUnit, oUnit in tUnitsToPartiallyGift do
                            --Give away 40% of our army to free up unit cap
                            if math.random(1,5) <= 2  then
                                table.insert(tUnitsToGift, oUnit)
                            end
                        end
                    end
                end

                if AiBotUtilities.IsTableEmpty(tUnitsToGift) == false then
                    AiBotTeam.TransferUnitsToPlayer(tUnitsToGift, oOtherBrain:GetArmyIndex(), false)
                    if not(oOtherBrain.AiBotAI) then
                        AiBotChat.SendMessage(aiBrain, 'ParagGift'..aiBrain:GetArmyIndex(), 'You look like you could use these resource buildings more than me', 0, 300, true, true, nil, nil)
                    end
                end
            end
            --Unpause every unit (can repause in a moment)
            WaitTicks(1)
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority]) == false then
                for iPriority, tPausedUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                    for iUnit, oUnit in tPausedUnits do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false, iTeam)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderManualT2ArtiTarget(oArti, oOptionalWeapon, iOptionalDelaySecondsAndWeaponFireCheck)
    --Considers giving manual orders to the T2 arti, so e.g. can use aoe and shot firing randomness to damage enemy shields just outside of our range

    --oOptionalWeapon - if called from the weapon fire event then this means we can check our last target
    --iOptionalDelaySecondsAndWeaponFireCheck - if specified, then will wait this many seconds then check if we have fired since the code started, and if not then proceed (used so if we are targeting a mobile unit and it goes out of our range we arent stuck with an invalid fire order)
    local sFunctionRef = 'ConsiderManualT2ArtiTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oArti[AiBotUnitInfo.refbEasyBrain]) then
        local bProceedWithLogic = true
        if iOptionalDelaySecondsAndWeaponFireCheck then
            --e.g. we have targeted a mobile unit, so only check again if we have failed to fire recently
            bProceedWithLogic = false
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iOptionalDelaySecondsAndWeaponFireCheck)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if not(oArti[AiBotUnitInfo.refiLastWeaponEvent]) or GetGameTimeSeconds() - oArti[AiBotUnitInfo.refiLastWeaponEvent] >= iOptionalDelaySecondsAndWeaponFireCheck - 0.01 then
                bProceedWithLogic = true
            end
        elseif oArti[AiBotUnitInfo.refiTimeBetweenIFShots] and GetGameTimeSeconds() - (oArti[AiBotUnitInfo.refiLastWeaponEvent] or -100) < oArti[AiBotUnitInfo.refiTimeBetweenIFShots] - 2 then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to wait until Arti almost ready to fire before choosing the next target, oArti[AiBotUnitInfo.refiTimeBetweenIFShots]='..(oArti[AiBotUnitInfo.refiTimeBetweenIFShots] or 'nil')..'; Time since last weapn event='..(GetGameTimeSeconds() - (oArti[AiBotUnitInfo.refiLastWeaponEvent] or -100))) end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(math.min(oArti[AiBotUnitInfo.refiTimeBetweenIFShots] - 2, oArti[AiBotUnitInfo.refiTimeBetweenIFShots] -2 - (GetGameTimeSeconds() - (oArti[AiBotUnitInfo.refiLastWeaponEvent] or -100))))
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to proceed for oArti='..(oArti.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oArti) or 'nil')..'; Is oArti valid='..tostring(AiBotUnitInfo.IsUnitValid(oArti))..'; bProceedWithLogic='..tostring(bProceedWithLogic)..'; iOptionalDelaySecondsAndWeaponFireCheck='..(iOptionalDelaySecondsAndWeaponFireCheck or 'nil')..'; Is oOptionalWeapon nil='..tostring(oOptionalWeapon == nil)..'; Time='..GetGameTimeSeconds()) end
        if bProceedWithLogic and AiBotUnitInfo.IsUnitValid(oArti) then


            local bGivenOrder = false
            local tLastTarget
            if oOptionalWeapon.GetCurrentTarget then
                local vLastTarget = oOptionalWeapon:GetCurrentTarget()
                if vLastTarget.GetPosition then
                    tLastTarget = vLastTarget:GetPosition()
                elseif vLastTarget[1] and vLastTarget[3] and not(vLastTarget[4]) then
                    tLastTarget = {vLastTarget[1], vLastTarget[2], vLastTarget[3]}
                end
            end

            --Are there T2 arti nearby? if so then want to target the closest t2 arti or shield covering the t2 arti
            local aiBrain = oArti:GetAIBrain()
            local iTeam = aiBrain.AiBotTeam
            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oArti:GetPosition(), true, iTeam)
            local oClosestTargetOfInterest
            local iClosestTargetOfInterest
            local oClosestUnshieldedTargetOfInterest
            local iClosestUnshieldedTargetOfInterest
            if not(oArti[AiBotUnitInfo.refiIndirectRange]) then
                AiBotUtilities.ErrorHandler('Dont have indirect fire range for T2 Arti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti))
                iClosestTargetOfInterest = 115 + 30
                iClosestUnshieldedTargetOfInterest = iClosestTargetOfInterest
            else
                iClosestTargetOfInterest = oArti[AiBotUnitInfo.refiIndirectRange] + 30 --wont bother trying to fire at something further away than this (and in some cases will need to be closer - ie.. depends on shielding situation)
                iClosestUnshieldedTargetOfInterest = iClosestTargetOfInterest
            end
            local iCurDist
            local tArtiPosition = oArti:GetPosition()
            --Set the min range so we avoid targets inside this
            local iMinRange = oArti[AiBotUnitInfo.refiArtiMinRange]
            if not(iMinRange) then
                if oOptionalWeapon then
                    oArti[AiBotUnitInfo.refiArtiMinRange] = (oOptionalWeapon.MinRadius or 1)
                else
                    for iWeapon, tWeapon in oArti:GetBlueprint().Weapon do
                        if tWeapon.MinRadius then
                            oArti[AiBotUnitInfo.refiArtiMinRange] = tWeapon.MinRadius
                            break
                        end
                    end
                    iMinRange = oArti[AiBotUnitInfo.refiArtiMinRange]
                    if not(iMinRange) then
                        iMinRange = math.min(oArti[AiBotUnitInfo.refiIndirectRange] * 0.7, 50)
                    end
                end
            end
            local iCurTargetSegmentX, iCurTargetSegmentZ
            local bDontConsiderBlockedShots = AiBotUtilities.IsTableEmpty(oArti[reftbTerrainBlockedTargetsBySegment])
            local bAddIfUnshielded
            function UpdateClosestUnit(tUnits, bOnlyUpdateForClosestUnshieldedTarget)
                for iUnit, oUnit in tUnits do
                    if not(oUnit.Dead) then
                        --Check unit is on land and not attached
                        if not(oUnit:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tArtiPosition)
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..repru(iCurDist)..'; iClosestTargetOfInterest='..repru(iClosestTargetOfInterest)..'; iMinRange='..repru(iMinRange)) end
                            if iCurDist < iClosestTargetOfInterest and iCurDist >= iMinRange and not(bOnlyUpdateForClosestUnshieldedTarget) then
                                if bDontConsiderBlockedShots then
                                    iClosestTargetOfInterest = iCurDist
                                    oClosestTargetOfInterest = oUnit
                                else
                                    --Check are shot isnt likely to be blocked
                                    iCurTargetSegmentX, iCurTargetSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is Cur target expected to be blocked='..tostring(oArti[reftbTerrainBlockedTargetsBySegment][iCurTargetSegmentX][iCurTargetSegmentZ] or false)) end
                                    if not(oArti[reftbTerrainBlockedTargetsBySegment][iCurTargetSegmentX][iCurTargetSegmentZ]) then
                                        --This doesnt cover the scenario where taret is out of our range; however since we prioritise the closest unit, to stick with that target means we have no targets in our range, so am ok not covering that eventuality
                                        iClosestTargetOfInterest = iCurDist
                                        oClosestTargetOfInterest = oUnit
                                    end
                                end
                            end
                            if iCurDist < iClosestUnshieldedTargetOfInterest and iCurDist >= iMinRange then

                                if bDontConsiderBlockedShots then
                                    bAddIfUnshielded = true
                                else
                                    --Check are shot isnt likely to be blocked
                                    iCurTargetSegmentX, iCurTargetSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is Cur target expected to be blocked='..tostring(oArti[reftbTerrainBlockedTargetsBySegment][iCurTargetSegmentX][iCurTargetSegmentZ] or false)) end
                                    if not(oArti[reftbTerrainBlockedTargetsBySegment][iCurTargetSegmentX][iCurTargetSegmentZ]) then
                                        --This doesnt cover the scenario where taret is out of our range; however since we prioritise the closest unit, to stick with that target means we have no targets in our range, so am ok not covering that eventuality
                                        bAddIfUnshielded = true
                                    end
                                end
                                if bAddIfUnshielded then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if this unit is unshielded, in whicih case will update oClosestUnshieldedTargetOfInterest, IsTargetUnderShield='..tostring(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 4000, false, false, false, false, false))) end
                                    if not(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 4000, false, false, false, false, false)) then
                                        iClosestUnshieldedTargetOfInterest = iCurDist
                                        oClosestUnshieldedTargetOfInterest = oUnit
                                    end
                                end
                            end
                        end
                    end
                end
            end

            local iDistThresholdToConsiderOtherTargets = oArti[AiBotUnitInfo.refiIndirectRange] + 3 --i.e. if unit we want to target is out of this range we will look for targets less critical that are in our range

            --First consider enemy fatboys
            local bHaveEnemyFatboy = false
            if (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0 then
                UpdateClosestUnit(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats])
                if oClosestTargetOfInterest and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oClosestTargetOfInterest.UnitId) then bHaveEnemyFatboy = true end
            end

            if (not(oClosestTargetOfInterest) or iClosestTargetOfInterest > iDistThresholdToConsiderOtherTargets + 3) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                --Enemy has t2 arti nearby so consider groundfiring units unless they have a fatboy nearby
                UpdateClosestUnit(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits])
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oClosestTargetOfInterest after checking for nearby enemy LR threats and t2 arti='..(oClosestTargetOfInterest.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestTargetOfInterest) or 'nil')..'; Did we have a priority target before, tLastTarget='..repru(tLastTarget)) end
            local bOnlyLookForUnshieldedTargets = false
            if oClosestTargetOfInterest and iClosestTargetOfInterest < iDistThresholdToConsiderOtherTargets and iClosestUnshieldedTargetOfInterest > iDistThresholdToConsiderOtherTargets then
                bOnlyLookForUnshieldedTargets = true
            end
            if not(oClosestTargetOfInterest) or ((bOnlyLookForUnshieldedTargets or iClosestTargetOfInterest > iDistThresholdToConsiderOtherTargets) and not(bHaveEnemyFatboy)) then
                if not(tLastTarget) then iClosestTargetOfInterest = math.min(iClosestTargetOfInterest, oArti[AiBotUnitInfo.refiIndirectRange]) end
                --No T2 arti but we were firing at something before, so check if any enemy shields or T2 arti or ravagers around the arti and (if so) if we want to ground fire them
                local tNearbyUnitsOfPotentialInterest = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMissileShip + AiBotUnitInfo.refCategoryPD * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT2Plus + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryTML + AiBotUnitInfo.refCategoryCruiser + AiBotUnitInfo.refCategoryMobileLandShield + AiBotUnitInfo.refCategorySniperBot, tArtiPosition, iClosestTargetOfInterest - 1, 'Enemy')
                if bDebugMessages == true then LOG(sFunctionRef..': is tNearbyUnitsOfPotentialInterest empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnitsOfPotentialInterest))) end
                if AiBotUtilities.IsTableEmpty(tNearbyUnitsOfPotentialInterest) == false then
                    local tNearbyUnitsOfInterest = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMissileShip + AiBotUnitInfo.refCategoryPD * categories.TECH3, tNearbyUnitsOfPotentialInterest)
                    if AiBotUtilities.IsTableEmpty(tNearbyUnitsOfInterest) == false then
                        UpdateClosestUnit(tNearbyUnitsOfInterest, bOnlyLookForUnshieldedTargets)
                    end
                    if oClosestTargetOfInterest and not(bOnlyLookForUnshieldedTargets) and iClosestUnshieldedTargetOfInterest > iDistThresholdToConsiderOtherTargets then bOnlyLookForUnshieldedTargets = true
                    elseif bOnlyLookForUnshieldedTargets and iClosestUnshieldedTargetOfInterest < iDistThresholdToConsiderOtherTargets then
                        bOnlyLookForUnshieldedTargets = false
                    end
                    if not(oClosestTargetOfInterest) or bOnlyLookForUnshieldedTargets then
                        tNearbyUnitsOfInterest = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryIndirectT2Plus + AiBotUnitInfo.refCategoryT2PlusPD + AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryTML + AiBotUnitInfo.refCategoryCruiser, tNearbyUnitsOfPotentialInterest)
                        if AiBotUtilities.IsTableEmpty(tNearbyUnitsOfInterest) == false then
                            UpdateClosestUnit(tNearbyUnitsOfInterest, bOnlyLookForUnshieldedTargets)
                        end
                        if oClosestTargetOfInterest and not(bOnlyLookForUnshieldedTargets) and iClosestUnshieldedTargetOfInterest > iDistThresholdToConsiderOtherTargets then bOnlyLookForUnshieldedTargets = true
                        elseif bOnlyLookForUnshieldedTargets and iClosestUnshieldedTargetOfInterest < iDistThresholdToConsiderOtherTargets then
                            bOnlyLookForUnshieldedTargets = false
                        end
                        if not(oClosestTargetOfInterest) or bOnlyLookForUnshieldedTargets then
                            UpdateClosestUnit(tNearbyUnitsOfPotentialInterest, bOnlyLookForUnshieldedTargets)
                        end
                    end
                end
            end

            --If we have a unit consider attacking it, or groundfiring if it is out of our range
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for main target, oClosestTargetOfInterest='..(oClosestTargetOfInterest.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestTargetOfInterest) or 'nil')..'; iClosestTargetOfInterest='..iClosestTargetOfInterest) end
            if oClosestTargetOfInterest then
                --Is it covered by a fixed shield? if so then switch target to the closest shield that is covering it
                if AiBotUtilities.IsTableEmpty(oClosestTargetOfInterest[reftoShieldsProvidingCoverage]) == false then
                    local iOrigUnitDist = iClosestTargetOfInterest
                    local oOrigUnitTarget = oClosestTargetOfInterest
                    if oClosestUnshieldedTargetOfInterest and iClosestUnshieldedTargetOfInterest < iDistThresholdToConsiderOtherTargets then
                        if bDebugMessages == true then LOG(sFunctionRef..': Closest target is shielded, so will switch to the closest unshielded target, oClosestUnshieldedTargetOfInterest='..oClosestUnshieldedTargetOfInterest.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnshieldedTargetOfInterest)) end
                        iClosestTargetOfInterest = iClosestUnshieldedTargetOfInterest
                        oClosestTargetOfInterest = oClosestUnshieldedTargetOfInterest
                    else
                        iClosestTargetOfInterest = 100000
                        UpdateClosestUnit(oClosestTargetOfInterest[reftoShieldsProvidingCoverage])
                        if iClosestTargetOfInterest >= 100000 then --Redundancy (e.g. shot might be blocked on the shield but not the unit being shielded)
                            iClosestTargetOfInterest = iOrigUnitDist
                            oClosestTargetOfInterest = oOrigUnitTarget
                        elseif bDebugMessages == true then LOG(sFunctionRef..': Original target was covered by a fixed shield so will target the shield instead, revised target='..oOrigUnitTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrigUnitTarget)..'; iOrigUnitDist='..iOrigUnitDist)
                        end
                        if iClosestTargetOfInterest >= 100000 then --Redundancy (e.g. shot might be blocked on the shield but not the unit being shielded)
                            iClosestTargetOfInterest = iOrigUnitDist
                            oClosestTargetOfInterest = oOrigUnitTarget
                            if bDebugMessages == true then LOG(sFunctionRef..': Couldnt find valid target so reverting to previous shielded target') end
                        end
                    end
                end

                --If target is out of our range then check if the planned target is in range
                local tGroundFireTarget
                if iClosestTargetOfInterest > oArti[AiBotUnitInfo.refiIndirectRange] then
                    if oClosestTargetOfInterest.MyShield or iClosestTargetOfInterest <= oArti[AiBotUnitInfo.refiIndirectRange] + 20 then
                        local iDistShortfall = 1
                        local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
                        if GetGameTimeSeconds() - (oArti[AiBotEvents.refiLastWeaponEvent] or -100) >= 25 then iDistShortfall = 3 end --greater dist threshold in case are trying to fire at elevated position

                        tGroundFireTarget = AiBotUtilities.MoveInDirection(tArtiPosition, AiBotUtilities.GetAngleFromAToB(tArtiPosition, oClosestTargetOfInterest:GetPosition()), (oArti[AiBotUnitInfo.refiIndirectRange] or 115) - iDistShortfall, true, false, AiBotMap.bIsCampaignMap)
                        --Is shot blocked for this?
                        iCurTargetSegmentX, iCurTargetSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tGroundFireTarget)

                        if bDebugMessages == true then LOG(sFunctionRef..': Is ground fire expected target expected to be blocked='..tostring(oArti[reftbTerrainBlockedTargetsBySegment][iCurTargetSegmentX][iCurTargetSegmentZ] or false)) end
                        if oArti[reftbTerrainBlockedTargetsBySegment][iCurTargetSegmentX][iCurTargetSegmentZ] then
                            tGroundFireTarget = nil
                            --Try searching for any enemy non-mobile air target
                            local tAllInRangeEnemyUnits = aiBrain:GetUnitsAroundPoint(categories.ALLUNITS - categories.MOBILE * categories.AIR, oArti:GetPosition(), oArti[AiBotUnitInfo.refiIndirectRange], 'Enemy')
                            if AiBotUtilities.IsTableEmpty(tAllInRangeEnemyUnits) == false then
                                local oOldClosestUnit = oClosestTargetOfInterest
                                UpdateClosestUnit(tAllInRangeEnemyUnits)
                                if oClosestTargetOfInterest == oOldClosestUnit then
                                    if bDebugMessages == true then LOG(sFunctionRef..': No targets in range that dont ahve blocked shots') end
                                    oClosestTargetOfInterest = nil
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will switch to the target '..oClosestTargetOfInterest.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestTargetOfInterest)) end
                                end
                            end
                        end
                    end
                end
                if oClosestTargetOfInterest then

                    --Now have selcted the unit we want to target - if its in our range then issue an attack order, otherwise issue a ground fire order
                    local bTargetingMobileUnit = EntityCategoryContains(categories.MOBILE, oClosestTargetOfInterest.UnitId)
                    bGivenOrder = true
                    --Consider whether to ground fire
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to do ground fire attack; iClosestTargetOfInterest='..iClosestTargetOfInterest..'; oArti[AiBotUnitInfo.refiIndirectRange]='..(oArti[AiBotUnitInfo.refiIndirectRange] or 'nil')) end
                    if iClosestTargetOfInterest <= oArti[AiBotUnitInfo.refiIndirectRange] then
                        if bDebugMessages == true then LOG(sFunctionRef..': Can we see the oClosestTargetOfInterest='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oClosestTargetOfInterest, false))..'; oClosestTargetOfInterest='..(oClosestTargetOfInterest.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestTargetOfInterest) or 'nil')) end
                        if AiBotUnitInfo.CanSeeUnit(aiBrain, oClosestTargetOfInterest, false) then
                            AiBotOrders.IssueTrackedAttack(oArti, oClosestTargetOfInterest, false, 'ArtAt', false)
                        else
                            AiBotOrders.IssueTrackedGroundAttack(oArti, oClosestTargetOfInterest:GetPosition(), 0.1, false, 'ArtXG', false, oClosestTargetOfInterest)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will do ground attack as cant see the unit') end
                        end
                    else
                        --Ground fire as target is out of our range; dont even try ground firing if its not a shield and is well outside our range
                        if tGroundFireTarget then
                            AiBotOrders.IssueTrackedGroundAttack(oArti, tGroundFireTarget, 0.1, false, 'ArtGF', false, oClosestTargetOfInterest)
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Not targeting a shield and it is too far outside our range so will abort (or had error finding groundfiretarget)') end
                            bGivenOrder = false
                        end
                    end

                    --If we were targeting a mobile unit then reconsider targets 5s later if we have failed to fire a shot in the meantime
                    if bTargetingMobileUnit then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to start a forked thread to re-consider t2 arti target as we are targeting a mobile unit') end
                        ForkThread(ConsiderManualT2ArtiTarget, oArti, oOptionalWeapon, 5)
                    end
                end
            end

            --Clear orders if last order was attack ground and we havent given any new order (so will revert to default weapon targeting)
            if not(bGivenOrder) then
                AiBotOrders.UpdateRecordedOrders(oArti)
                local iLastOrderType = oArti[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType]
                if iLastOrderType == AiBotOrders.refiOrderIssueGroundAttack or iLastOrderType == AiBotOrders.refiOrderIssueAttack then
                    if bDebugMessages == true then LOG(sFunctionRef..': Couldnt find any targets and arti was given an attack or ground fire order so will clear the order') end
                    AiBotOrders.IssueTrackedClearCommands(oArti)
                else
                    --Give an attack ground order if we haven't fired a shot at all this game, so we are likely to be facing the right direction
                    local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
                    if bDebugMessages == true then LOG(sFunctionRef..': Last weapon event='..(oArti[AiBotEvents.refiLastWeaponEvent] or 'nil')) end
                    if not(oArti[AiBotEvents.refiLastWeaponEvent]) then
                        local tDirectionTowardsEnemy = AiBotUtilities.MoveInDirection(oArti:GetPosition(), AiBotUtilities.GetAngleFromAToB(oArti:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]), (oArti[AiBotUnitInfo.refiIndirectRange] or 110) - 5, true, false, AiBotMap.bIsCampaignMap)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and fire at tDirectionTowardsEnemy='..repru(tDirectionTowardsEnemy)..', Dist to arti='..AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), tDirectionTowardsEnemy)) end
                        AiBotOrders.IssueTrackedGroundAttack(oArti, tDirectionTowardsEnemy, 0.1, false, 'ArtGF', false, oClosestTargetOfInterest)
                        --Clear this order in 5s if still not got a target
                        ForkThread(ConsiderManualT2ArtiTarget, oArti, oOptionalWeapon, 5)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBestAOETargetForSpecifiedBuildings(aiBrain, iTeam, tLauncherPosition, tSMDBlockingTarget, iAOE, iDamage)
    --intended for yolona targeting blocking smds; start by getting the closest enemy SMD, returns revised target

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBestAOETargetForSpecifiedBuildings'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iClosestDist = 100000
    local oClosestSMD
    local iCurDist
    local tTarget
    local iClosestAltSMDToSMD = 100000
    local tNearbyAltSMD = {}

    if table.getn(tSMDBlockingTarget) == 1 then
        oClosestSMD = tSMDBlockingTarget[1]
    else
        for iSMD, oSMD in tSMDBlockingTarget do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLauncherPosition, oSMD:GetPosition())
            if iCurDist < iClosestDist then
                iClosestDist = iCurDist
                oClosestSMD = oSMD
            end
        end
    end

    --Competing concerns - if try to edge nuke SMD then might deal minimal damage to wider base once we break through; if instead target for max damage we might cause other SMD not previously in range to become in range
    --will therefore only consider best damage if there is only 1 SMD nearby

    local iNearbyThreshold = iAOE * 2
    local tiDistToClosestSMD = {}
    for iSMD, oSMD in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemySMD] do
        if not(oSMD == oClosestSMD) and AiBotUnitInfo.IsUnitValid(oSMD) then
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oClosestSMD:GetPosition(), oSMD:GetPosition())
            if iCurDist < iNearbyThreshold then
                table.insert(tNearbyAltSMD, oSMD)
                table.insert(tiDistToClosestSMD, iCurDist)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tNearbyAltSMD) == false then
        --work out the position that hits the max no. of units - approximate by taking the best midpoint between smd pairs that include the first
        local bCheckPlayableArea = AiBotMap.bIsCampaignMap
        local iBestSMDInRange = 0
        local tBestTarget
        for iSMD, oSMD in tNearbyAltSMD do
            local tCurMidpoint = AiBotUtilities.MoveInDirection(oClosestSMD:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestSMD:GetPosition(), oSMD:GetPosition()), tiDistToClosestSMD[iSMD] * 0.5, false, bCheckPlayableArea)
            local iSMDInRange = 2
            for iAltSMD, oAltSMD in tNearbyAltSMD do
                if not(oAltSMD == oSMD) then
                    if AiBotUtilities.GetDistanceBetweenPositions(tCurMidpoint, oAltSMD:GetPosition()) < iAOE then
                        if bDebugMessages == true then LOG(sFunctionRef..': IF target the midpoint between smd '..oSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSMD)..' and the closest SMD '..oClosestSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestSMD)..' then another SMD, oAltSMD='..oAltSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAltSMD)..' is also in range. is alt smd valid='..tostring(AiBotUnitInfo.IsUnitValid(oAltSMD))) end
                        iSMDInRange = iSMDInRange + 1
                    end
                end
            end
            if iSMDInRange > iBestSMDInRange then
                tBestTarget = {tCurMidpoint[1], tCurMidpoint[2], tCurMidpoint[3]}
                iBestSMDInRange = iSMDInRange
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iBestSMDInRange='..iBestSMDInRange..'; oClosestSMD='..oClosestSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestSMD)) end
        if iBestSMDInRange >= 2 then
            tTarget = tBestTarget
        else
            tTarget = AiBotLogic.GetBestAOETarget(aiBrain, oClosestSMD:GetPosition(), iAOE, iDamage, false)
        end

    else
        tTarget = AiBotLogic.GetBestAOETarget(aiBrain, oClosestSMD:GetPosition(), iAOE, iDamage, false)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tTarget='..repru(tTarget)..'; Time='..GetGameTimeSeconds()) end
    return tTarget
end

function MonitorShieldsForCycling(tTableRef, iTeam, iLandZone, iTemplateRef, tLZTeamData)
    --Called from the gameender template logic
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorShieldsForCycling'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(tTableRef[AiBotMap.subrefGEbActiveShieldMonitor]) and bShieldsCanDischarge then
        tTableRef[AiBotMap.subrefGEbActiveShieldMonitor] = true
        local oLowestHealthActiveShield, oHighestHealthActiveShield, iCompletedShieldCount, iCurHealth, iMaxHealth, iLowestHealth, iHighestHealth, iLongestRechargeTime
        local iSecondsBetweenShieldCycles = 1 --will change
        local AiBotConfig = import('/lua/AiBot/AiBotConfig.lua')
        local bUpdateName = AiBotConfig.AiBotShowUnitNames
        local iCurShieldRadius, iShieldWithHealth

        local tArtiMidpoint, iLowestHealthDistToArtiMidpoint, iCurDistToArtiMidpoint
        if table.getn(tTableRef[AiBotMap.subrefGEArtiLocations]) == 1 then
            tArtiMidpoint = tTableRef[AiBotMap.subrefGEArtiLocations][1]
        else
            tArtiMidpoint = {}
            for iArtiLocation, tArtiLocation in tTableRef[AiBotMap.subrefGEArtiLocations] do
                tArtiMidpoint[1] = (tArtiMidpoint[1] or 0) + tArtiLocation[1]
                tArtiMidpoint[3] = (tArtiMidpoint[3] or 0) + tArtiLocation[3]
            end
            tArtiMidpoint[1] = tArtiMidpoint[1] / table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
            tArtiMidpoint[3] = tArtiMidpoint[3] / table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
            tArtiMidpoint[2] = GetTerrainHeight(tArtiMidpoint[1], tArtiMidpoint[3])
        end
        local iTimeOfLastDischarge

        while AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subrefGEShieldUnits]) do
            --Get the highest and lowest health active shields
            iLowestHealth = 1000000
            iHighestHealth = 0
            oLowestHealthActiveShield = nil
            oHighestHealthActiveShield = nil
            iCompletedShieldCount = 0
            iLongestRechargeTime = 10
            iShieldWithHealth = 0
            for iShield, oShield in tTableRef[AiBotMap.subrefGEShieldUnits] do

                if oShield:GetFractionComplete() == 1 then
                    --Check we should include the shield (i.e. that it is covering the arti locations); assume UEF and seraphim T3+ are
                    if oShield[refbProtectingAllArtiAndShieldLocations] == nil or tTableRef[AiBotMap.subrefbHaveTooSmallShields] == nil then
                        oShield[refbProtectingAllArtiAndShieldLocations] = true --default
                        if not(EntityCategoryContains(categories.SERAPHIM + categories.UEF - categories.TECH2, oShield.UnitId)) and tTableRef[AiBotMap.subrefGESize] > 22 then
                            iCurShieldRadius = (oShield:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.5
                            if iCurShieldRadius < 10 then
                                oShield[refbProtectingAllArtiAndShieldLocations] = false
                            else
                                if AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subrefGEArtiUnits]) then
                                    for iArti, oArti in tTableRef[AiBotMap.subrefGEArtiUnits] do
                                        if AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), oShield:GetPosition()) > iCurShieldRadius then
                                            oShield[refbProtectingAllArtiAndShieldLocations] = false
                                            break
                                        end
                                    end
                                else
                                    --Use expected arti locations
                                    for iArti, tArti in tTableRef[AiBotMap.subrefGEArtiLocations] do
                                        if AiBotUtilities.GetDistanceBetweenPositions(tArti, oShield:GetPosition()) > iCurShieldRadius then
                                            oShield[refbProtectingAllArtiAndShieldLocations] = false
                                            break
                                        end
                                    end
                                end
                                if oShield[refbProtectingAllArtiAndShieldLocations] then
                                    --Cycle through shield locations
                                    for iShieldLocation, tShieldLocation in tTableRef[AiBotMap.subrefGEShieldLocations] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' is covering all arti and shield locations, dist to tShieldLocation='..AiBotUtilities.GetDistanceBetweenPositions(tShieldLocation, oShield:GetPosition())..'; iCurShieldRadius='..iCurShieldRadius) end
                                        if AiBotUtilities.GetDistanceBetweenPositions(tShieldLocation, oShield:GetPosition()) > iCurShieldRadius then
                                            if bDebugMessages == true then LOG(sFunctionRef..': We cant cover other shields from this location') end
                                            oShield[refbProtectingAllArtiAndShieldLocations] = false
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if not(oShield[refbProtectingAllArtiAndShieldLocations]) then tTableRef[AiBotMap.subrefbHaveTooSmallShields] = true end
                        if tTableRef[AiBotMap.subrefbHaveTooSmallShields] == nil then
                            --Check every shield to see if any have this flagged
                            for iRecordedShield, oRecordedShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                                if oRecordedShield[refbProtectingAllArtiAndShieldLocations] == false then
                                    tTableRef[AiBotMap.subrefbHaveTooSmallShields] = true
                                end
                            end
                            if not(tTableRef[AiBotMap.subrefbHaveTooSmallShields]) then
                                tTableRef[AiBotMap.subrefbHaveTooSmallShields] = false
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; oShield[refbProtectingAllArtiAndShieldLocations]='..tostring(oShield[refbProtectingAllArtiAndShieldLocations] or false)) end
                    if oShield[refbProtectingAllArtiAndShieldLocations] then
                        iCompletedShieldCount = iCompletedShieldCount + 1
                        iCurHealth, iMaxHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' at time='..GetGameTimeSeconds()..'; iCurHealth='..iCurHealth..'; iMaxHealth='..iMaxHealth..'; Is shield enabled='..tostring(AiBotUnitInfo.IsUnitShieldEnabled(oShield))..'; Time since last discharge='..GetGameTimeSeconds() - (oShield[refiTimeOfLastDischarge] or -100)..'; Is shield paused='..tostring(oShield[AiBotUnitInfo.refbPaused] or false)..'; Dist to arti midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tArtiMidpoint)) end
                        if iCurHealth > 0 then
                            iShieldWithHealth = iShieldWithHealth + 1
                            if iCurHealth < iLowestHealth then
                                iLowestHealth = iCurHealth
                                oLowestHealthActiveShield = oShield
                            elseif iCurHealth == iLowestHealth then
                                if not(oLowestHealthActiveShield) then
                                    iLowestHealth = iCurHealth
                                    oLowestHealthActiveShield = oShield
                                else
                                    --Want to discharge the shield furthest from the midpoint if they both have equal health
                                    iLowestHealthDistToArtiMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oHighestHealthActiveShield:GetPosition(), tArtiMidpoint)
                                    iCurDistToArtiMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tArtiMidpoint)
                                    if iCurDistToArtiMidpoint > iLowestHealthDistToArtiMidpoint then
                                        iLowestHealthDistToArtiMidpoint = iCurDistToArtiMidpoint
                                        oLowestHealthActiveShield = oShield
                                    end
                                end
                            end
                            if iCurHealth > iHighestHealth or (iCurHealth == iHighestHealth and (not(oHighestHealthActiveShield) or oLowestHealthActiveShield == oHighestHealthActiveShield)) then --want this to be >= and above to be < so that if we have 2 of the same shields at 100% health, we will have different shields recorded for lowest and highest health
                                iHighestHealth = iCurHealth
                                oHighestHealthActiveShield = oShield
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Time since last recharge='..GetGameTimeSeconds() - (oShield[refiTimeOfLastDischarge] or -100)..'; Is shield a transferred unit='..tostring(oShield[AiBotUnitInfo.refbTransferredUnit])..'; oUnit[refbShieldIsDisabled]='..repru(oShield[AiBotUnitInfo.refbShieldIsDisabled])) end
                            if not(oShield[refiManuallyEnabledTime]) or GetGameTimeSeconds() - oShield[refiManuallyEnabledTime] >= 30 then --as had a case where shields were stuck not recharging, so added in case due to running enableunitshield every tick
                                if (oShield[refiTimeOfLastDischarge] and GetGameTimeSeconds() - oShield[refiTimeOfLastDischarge] >= math.max(iLongestRechargeTime + 10, 40) and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeCreated] or 0) >= 5) then
                                    --Enable the shield incase it was somehow paused following the transfer, but only do this once every 10s
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enabling shield as it has been a long time since it was discharged, shield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Time='..GetGameTimeSeconds()) end
                                    AiBotUnitInfo.EnableUnitShield(oShield)
                                    oShield[refiManuallyEnabledTime] = GetGameTimeSeconds() --This is because also had a case where shield progress got stuck, which may have been due to this
                                elseif not(oShield[refiTimeOfLastDischarge]) and oShield[AiBotUnitInfo.refbTransferredUnit] and oShield[AiBotUnitInfo.refbShieldIsDisabled] == nil and iCurHealth == 0 and oShield:GetAIBrain():GetEconomyStoredRatio('ENERGY') >= 0.1 and not(oShield[AiBotUnitInfo.refbPaused]) and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeCreated] or 0) >= 5 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have 0 health shield that was transferred so will try enabling shield, shield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Time='..GetGameTimeSeconds()) end
                                    AiBotUnitInfo.EnableUnitShield(oShield)
                                    oShield[refiManuallyEnabledTime] = GetGameTimeSeconds()
                                end
                            end
                        end

                        iLongestRechargeTime = math.max(iLongestRechargeTime, (oShield:GetBlueprint().Defense.Shield.ShieldRechargeTime or 0))
                    end
                end
            end
            if iCompletedShieldCount == 0 then break end
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding how long to wait and whether to discharge a shield, iShieldWithHealth='..iShieldWithHealth..'; iCompletedShieldCount='..iCompletedShieldCount) end
            if not(oLowestHealthActiveShield) or oLowestHealthActiveShield == oHighestHealthActiveShield or iShieldWithHealth <= 1 then
                --We only have 1 shield active, so dont want to reset it
                iSecondsBetweenShieldCycles = 0.1 --review position next tick
                if bDebugMessages == true then LOG(sFunctionRef..': we either have no or 1 active shield so wont discharge but will check again in 1 tick') end
            else
                --If Aeon shell landed then the DOT effect could be beneath other shields; if we have 3+ shields active then seems unlikely, while if lowest health shield is <6k it wouldnt protect from the DOT effect either
                if oLowestHealthActiveShield[refiTimeOfLastAeonT3ArtiDamageToShield] and iCompletedShieldCount <= 2 and GetGameTimeSeconds() - oLowestHealthActiveShield[refiTimeOfLastAeonT3ArtiDamageToShield] <= 1 and iLowestHealth >= 6000 then
                    if bDebugMessages == true then LOG(sFunctionRef..': The lowest health shield took T3 arti fire from aeon recently, so a chance the shell DOT effect could destroy things if it occurred beneath the other shield currently active') end
                    iSecondsBetweenShieldCycles = 0.1 --review position next tick
                    --If enemy has lots of novaxes then consider keeping up at least 2 shields instead of 1
                elseif iCompletedShieldCount <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] <= 1 and tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 60 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont want to cycle 2 shields due to enemy having lots of novaxes at least one of which is nearby') end
                    iSecondsBetweenShieldCycles = 0.1
                else
                    --We will presumably have waited the appropriate time before getting here, so can disable the lowest health shield; work out how long we want to wait for the next shield
                    if iCompletedShieldCount > 1 then
                        iSecondsBetweenShieldCycles = iLongestRechargeTime / (iCompletedShieldCount - 1)
                    else
                        --Redundancy - should be impossible to get here
                        iSecondsBetweenShieldCycles = 10
                    end
                    if iShieldWithHealth <= 3 and iTimeOfLastDischarge and GetGameTimeSeconds() - iTimeOfLastDischarge + 0.5 < iSecondsBetweenShieldCycles then
                        if bDebugMessages == true then LOG(sFunctionRef..': It hasnt been long enoug hsince our last discharge so will wait before discharing even if we have multiple shields active') end
                        iSecondsBetweenShieldCycles = 0.5
                    else
                        AiBotUnitInfo.DischargeShield(oLowestHealthActiveShield)
                        iTimeOfLastDischarge = GetGameTimeSeconds()
                        if bDebugMessages == true then LOG(sFunctionRef..': have just discharged shield '..oLowestHealthActiveShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLowestHealthActiveShield)..' at time='..GetGameTimeSeconds()) end
                        oLowestHealthActiveShield[refiTimeOfLastDischarge] = GetGameTimeSeconds()
                        if bUpdateName then
                            AiBotOrders.UpdateUnitNameForOrder(oLowestHealthActiveShield, 'DischZ'..(oLowestHealthActiveShield[reftArtiTemplateRefs][2] or 'nil')..'T'..(oLowestHealthActiveShield[reftArtiTemplateRefs][3] or 'nil')..'; Tm='..math.floor(GetGameTimeSeconds()))
                        end
                    end
                end

            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iSecondsBetweenShieldCycles)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': No longer have valid shields, so will flag that we have no active shield monitor, time='..GetGameTimeSeconds()) end
        tTableRef[AiBotMap.subrefGEbActiveShieldMonitor] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorSACUShieldsForCycling(tTableRef, iTeam, iLandZone, iTemplateRef)
    --Called from the gameender template logic for adding an engineer that is a shieldSACU; will enable/disable shields instead of discharging
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorSACUShieldsForCycling'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(tTableRef[AiBotMap.subrefbActiveShieldSACUCycling]) and bShieldsCanDischarge then
        tTableRef[AiBotMap.subrefbActiveShieldSACUCycling] = true
        local oLowestHealthActiveShield, oHighestHealthActiveShield, iCompletedShieldCount, iCurHealth, iMaxHealth, iLowestHealth, iHighestHealth, iLongestRechargeTime
        local iSecondsBetweenShieldCycles = 1 --will change
        local iShieldWithHealth

        local tArtiMidpoint, iLowestHealthDistToArtiMidpoint, iCurDistToArtiMidpoint
        if table.getn(tTableRef[AiBotMap.subrefGEArtiLocations]) == 1 then
            tArtiMidpoint = tTableRef[AiBotMap.subrefGEArtiLocations][1]
        else
            tArtiMidpoint = {}
            for iArtiLocation, tArtiLocation in tTableRef[AiBotMap.subrefGEArtiLocations] do
                tArtiMidpoint[1] = (tArtiMidpoint[1] or 0) + tArtiLocation[1]
                tArtiMidpoint[3] = (tArtiMidpoint[3] or 0) + tArtiLocation[3]
            end
            tArtiMidpoint[1] = tArtiMidpoint[1] / table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
            tArtiMidpoint[3] = tArtiMidpoint[3] / table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
            tArtiMidpoint[2] = GetTerrainHeight(tArtiMidpoint[1], tArtiMidpoint[3])
        end
        local iTimeOfLastDischarge
        local bHaveRecentlyEnabledShield = false
        local iDisabledShieldCount, iEnabledShieldCount, iHighestEnabledShieldHealth

        while AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subreftoGEShieldSACUs]) do
            --Get the highest and lowest health active shields
            iLowestHealth = 1000000
            iHighestHealth = 0
            oLowestHealthActiveShield = nil
            oHighestHealthActiveShield = nil
            iCompletedShieldCount = 0
            iLongestRechargeTime = 10
            iShieldWithHealth = 0
            iDisabledShieldCount = 0
            iEnabledShieldCount = 0
            for iShield, oShield in tTableRef[AiBotMap.subreftoGEShieldSACUs] do
                --if bDebugMessages == true and oShield.MyShield.GetMaxHealth and oShield.MyShield:GetMaxHealth() >= 30000 then LOG(sFunctionRef..': reprs of myshield='..reprs(oShield.MyShield)..'; (oShield.MyShield.Size or 0)='..(oShield.MyShield.Size or 0)..'; Blueprint equiv='..(oShield:GetBlueprint().Defense.Shield.ShieldSize or 'nil')) end
                if oShield:GetFractionComplete() == 1 and (oShield.MyShield.Size or 0) >= 5 then --redundancy
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)) end
                    iCompletedShieldCount = iCompletedShieldCount + 1
                    iCurHealth, iMaxHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' at time='..GetGameTimeSeconds()..'; iCurHealth='..iCurHealth..'; iMaxHealth='..iMaxHealth..'; Is shield enabled='..tostring(AiBotUnitInfo.IsUnitShieldEnabled(oShield))..'; Time since last discharge='..GetGameTimeSeconds() - (oShield[refiTimeOfLastDischarge] or -100)..'; Is shield paused='..tostring(oShield[AiBotUnitInfo.refbPaused] or false)..'; Dist to arti midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tArtiMidpoint)) end
                    --First check we are close enough to the midpoint
                    iCurDistToArtiMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tArtiMidpoint)
                    if iCurDistToArtiMidpoint >= 6 and not(oShield:IsUnitState('Upgrading')) and iCurDistToArtiMidpoint >= (oShield.MyShield.Size or 20) * 0.4 - 1 and (iCurHealth > 0 or iCurDistToArtiMidpoint > (oShield.MyShield.Size or 20) * 0.5) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Moving oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' to arti midpoint, artimidpoint='..repru(tArtiMidpoint)..'; is oShield valid='..tostring(AiBotUnitInfo.IsUnitValid(oShield))) end
                        AiBotOrders.IssueTrackedMove(oShield, tArtiMidpoint, 2, false, 'ShSCUMvToMd', true)
                        AiBotMicro.TrackTemporaryUnitMicro(oShield, 5)
                    end

                    if iCurHealth > 0 then
                        iShieldWithHealth = iShieldWithHealth + 1
                        if iCurHealth < iLowestHealth then
                            iLowestHealth = iCurHealth
                            oLowestHealthActiveShield = oShield
                        elseif iCurHealth == iLowestHealth then
                            if not(oLowestHealthActiveShield) then
                                iLowestHealth = iCurHealth
                                oLowestHealthActiveShield = oShield
                            else
                                --Want to discharge the shield furthest from the midpoint if they both have equal health
                                if oHighestHealthActiveShield.GetPosition and tArtiMidpoint and not(oHighestHealthActiveShield.Dead) then
                                    iLowestHealthDistToArtiMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oHighestHealthActiveShield:GetPosition(), tArtiMidpoint)
                                    if iCurDistToArtiMidpoint > iLowestHealthDistToArtiMidpoint then
                                        iLowestHealthDistToArtiMidpoint = iCurDistToArtiMidpoint
                                        oLowestHealthActiveShield = oShield
                                    end
                                end
                            end
                        end
                        if not(oShield[AiBotUnitInfo.refbShieldIsDisabled]) and (iCurHealth > iHighestHealth or (iCurHealth == iHighestHealth and (not(oHighestHealthActiveShield) or oLowestHealthActiveShield == oHighestHealthActiveShield))) then --want this to be >= and above to be < so that if we have 2 of the same shields at 100% health, we will have different shields recorded for lowest and highest health
                            iHighestHealth = iCurHealth
                            oHighestHealthActiveShield = oShield
                        end
                    elseif iMaxHealth > 0 then --Might not have the shield upgrade yet
                        if bDebugMessages == true then LOG(sFunctionRef..': Time since last recharge='..GetGameTimeSeconds() - (oShield[refiTimeOfLastDischarge] or -100)..'; Is shield a transferred unit='..tostring(oShield[AiBotUnitInfo.refbTransferredUnit])..'; oUnit[refbShieldIsDisabled]='..repru(oShield[AiBotUnitInfo.refbShieldIsDisabled])) end
                        if not(oShield[AiBotUnitInfo.refbShieldIsDisabled]) and not(oShield[AiBotUnitInfo.refbShieldRecentlyEnabled]) and (not(oShield[refiManuallyEnabledTime]) or GetGameTimeSeconds() - oShield[refiManuallyEnabledTime] >= 30) then --as had a case where shields were stuck not recharging, so added in case due to running enableunitshield every tick
                            if (oShield[refiTimeOfLastDischarge] and GetGameTimeSeconds() - oShield[refiTimeOfLastDischarge] >= math.max(iLongestRechargeTime + 10, 40) and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeCreated] or 0) >= 5) then
                                --Enable the shield incase it was somehow paused following the transfer, but only do this once every 10s
                                if bDebugMessages == true then LOG(sFunctionRef..': Enabling shield as it has been a long time since it was discharged, shield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Time='..GetGameTimeSeconds()) end
                                AiBotUnitInfo.EnableUnitShield(oShield)
                                oShield[refiManuallyEnabledTime] = GetGameTimeSeconds() --This is because also had a case where shield progress got stuck, which may have been due to this
                            elseif not(oShield[refiTimeOfLastDischarge]) and oShield[AiBotUnitInfo.refbTransferredUnit] and oShield[AiBotUnitInfo.refbShieldIsDisabled] == nil and iCurHealth == 0 and oShield:GetAIBrain():GetEconomyStoredRatio('ENERGY') >= 0.1 and not(oShield[AiBotUnitInfo.refbPaused]) and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeCreated] or 0) >= 5 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have 0 health shield that was transferred so will try enabling shield, shield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Time='..GetGameTimeSeconds()) end
                                AiBotUnitInfo.EnableUnitShield(oShield)
                                oShield[refiManuallyEnabledTime] = GetGameTimeSeconds()
                            end
                        end
                    end
                    if oShield[AiBotUnitInfo.refbShieldIsDisabled] then iDisabledShieldCount = iDisabledShieldCount + 1
                    else
                        iEnabledShieldCount = iEnabledShieldCount + 1
                        if not(bHaveRecentlyEnabledShield) and oShield[AiBotUnitInfo.refbShieldRecentlyEnabled] then bHaveRecentlyEnabledShield = true end
                    end


                    iLongestRechargeTime = math.max(iLongestRechargeTime, (oShield.MyShield.ShieldRechargeTime or 215))
                elseif bDebugMessages == true then LOG(sFunctionRef..': Shield isnt complete or lacks a shield field, shield size='..(oShield.MyShield.Size or 0)..'; oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Upgrade count='..(oShield[import('/lua/AiBot/AI/AiBotACU.lua').refiUpgradeCount] or 'nil'))
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding how long to wait and whether to discharge a shield, iShieldWithHealth='..iShieldWithHealth..'; iCompletedShieldCount='..iCompletedShieldCount) end
            if iCompletedShieldCount == 0 or not(oHighestHealthActiveShield) or iHighestHealth == 0 then
                tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] = 0
            elseif oHighestHealthActiveShield.MyShield.GetMaxHealth then
                tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] = iHighestHealth / oHighestHealthActiveShield.MyShield:GetMaxHealth()
            else
                tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] = iHighestHealth / (oHighestHealthActiveShield.MyShield.ShieldMaxHealth or 52000)
            end

            --Enable/disable shields instead of discharging
            if bDebugMessages == true then LOG(sFunctionRef..': iLongestRechargeTime='..iLongestRechargeTime..'; tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent]='..tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent]..'; iShieldWithHealth='..iShieldWithHealth..'; iEnabledShieldCount='..iEnabledShieldCount..'; iDisabledShieldCount='..iDisabledShieldCount..'; bHaveRecentlyEnabledShield='..tostring(bHaveRecentlyEnabledShield)) end
            if iCompletedShieldCount == 0 then
                iSecondsBetweenShieldCycles = 10
            elseif iLongestRechargeTime >= 40 then
                iSecondsBetweenShieldCycles = 1
                --First consider if want to disable a shield
                if iShieldWithHealth > 1 and iEnabledShieldCount > 1 then
                    local oShieldToDisable
                    --Disable shield
                    if (not(oLowestHealthActiveShield.MyShield.GetHealth) or oLowestHealthActiveShield.MyShield:GetHealth() < iHighestHealth or (iLowestHealth == iHighestHealth and not(oLowestHealthActiveShield == oHighestHealthActiveShield))) then
                        --Disable lowest health shield
                        oShieldToDisable = oLowestHealthActiveShield
                    elseif iEnabledShieldCount >= 2 and iShieldWithHealth >= 2 and tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] >= 0.1 and (tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] >= 0.25 or iShieldWithHealth >= 3) then
                        for iShield, oShield in tTableRef[AiBotMap.subreftoGEShieldSACUs] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Looking for shield to disable, oShield health='..oLowestHealthActiveShield.MyShield:GetHealth()..'; iHighestHealth='..iHighestHealth) end
                            if not(oShield[AiBotUnitInfo.refbShieldIsDisabled]) and oShield:GetFractionComplete() == 1 and not(oShield == oHighestHealthActiveShield) and (not(oLowestHealthActiveShield.MyShield.GetHealth) or oLowestHealthActiveShield.MyShield:GetHealth() < iHighestHealth or oLowestHealthActiveShield.MyShield:GetHealth() == oLowestHealthActiveShield.MyShield:GetMaxHealth()) then
                                oShieldToDisable = oShield
                                break
                            end
                        end
                    else
                        --Only have 2 enabled shields, and our lowest health shield appears to have more health than our highest health, but might be temporarily down, so dont disable either
                        iSecondsBetweenShieldCycles = 0.5
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Will disable or discharge oShieldToDisable='..(oShieldToDisable.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShieldToDisable) or 'nil')..'; Time since last discharge='..GetGameTimeSeconds() - (iTimeOfLastDischarge or 0)) end
                    if oShieldToDisable then
                        local iShieldToDisableHealthPercent = oShieldToDisable.MyShield:GetHealth() / oShieldToDisable.MyShield:GetMaxHealth()
                        local iMinTimeBetweenDischargesWanted = iLongestRechargeTime / (iCompletedShieldCount - 1)
                        if oShieldToDisable.MyShield.GetHealth and iShieldToDisableHealthPercent < math.min(0.85, 0.65 + iCompletedShieldCount * 0.02) and (iShieldToDisableHealthPercent < 0.25 or not(iTimeOfLastDischarge) or GetGameTimeSeconds() - iTimeOfLastDischarge >= iMinTimeBetweenDischargesWanted or (iShieldToDisableHealthPercent < 0.5 and iCompletedShieldCount >= 0.4 and GetGameTimeSeconds() - iTimeOfLastDischarge >= iMinTimeBetweenDischargesWanted * 0.6)) then
                            --Discharge instead of disabling
                            AiBotUnitInfo.DischargeShield(oShieldToDisable)
                            iTimeOfLastDischarge = GetGameTimeSeconds()
                            if bDebugMessages == true then LOG(sFunctionRef..': Damaged shield so will discharge instead of disabling') end
                        else
                            --Disable instead of discharge
                            AiBotUnitInfo.DisableUnitShield(oShieldToDisable)
                            if bDebugMessages == true then LOG(sFunctionRef..': Shield has enough health that we will disable it and reuse in the future') end
                        end
                    end
                end
                --Then decide if want to enable a shield
                if not(bHaveRecentlyEnabledShield) and iDisabledShieldCount >= 1 and tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] <= 0.75 and tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] <= 0.1 + 0.2 * iDisabledShieldCount then
                    for iShield, oShield in tTableRef[AiBotMap.subreftoGEShieldSACUs] do
                        if oShield[AiBotUnitInfo.refbShieldIsDisabled] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will enable oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)) end
                            AiBotUnitInfo.EnableUnitShield(oShield)
                        end
                    end
                end
            else --Redundancy - although this works shield discharge isnt as good due to E upkeep

                if not(oLowestHealthActiveShield) or oLowestHealthActiveShield == oHighestHealthActiveShield or iShieldWithHealth <= 1 then
                    --We only have 1 shield active, so dont want to reset it
                    iSecondsBetweenShieldCycles = 0.1 --review position next tick
                    if bDebugMessages == true then LOG(sFunctionRef..': we either have no or 1 active shield so wont discharge but will check again in 1 tick') end
                else
                    --If Aeon shell landed then the DOT effect could be beneath other shields; if we have 3+ shields active then seems unlikely, while if lowest health shield is <6k it wouldnt protect from the DOT effect either
                    if oLowestHealthActiveShield[refiTimeOfLastAeonT3ArtiDamageToShield] and iCompletedShieldCount <= 2 and GetGameTimeSeconds() - oLowestHealthActiveShield[refiTimeOfLastAeonT3ArtiDamageToShield] <= 1 and iLowestHealth >= 6000 then
                        if bDebugMessages == true then LOG(sFunctionRef..': The lowest health shield took T3 arti fire from aeon recently, so a chance the shell DOT effect could destroy things if it occurred beneath the other shield currently active') end
                        iSecondsBetweenShieldCycles = 0.1 --review position next tick
                    else
                        --We will presumably have waited the appropriate time before getting here, so can disable the lowest health shield; work out how long we want to wait for the next shield
                        if iCompletedShieldCount > 1 then
                            iSecondsBetweenShieldCycles = iLongestRechargeTime / (iCompletedShieldCount - 1)
                        else
                            --Redundancy - should be impossible to get here
                            iSecondsBetweenShieldCycles = 10
                        end
                        if iShieldWithHealth <= 3 and iTimeOfLastDischarge and GetGameTimeSeconds() - iTimeOfLastDischarge + 0.5 < iSecondsBetweenShieldCycles then
                            if bDebugMessages == true then LOG(sFunctionRef..': It hasnt been long enoug hsince our last discharge so will wait before discharing even if we have multiple shields active') end
                            iSecondsBetweenShieldCycles = 0.5
                        else
                            AiBotUnitInfo.DischargeShield(oLowestHealthActiveShield)
                            iTimeOfLastDischarge = GetGameTimeSeconds()
                            if bDebugMessages == true then LOG(sFunctionRef..': have just discharged shield '..oLowestHealthActiveShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLowestHealthActiveShield)..' at time='..GetGameTimeSeconds()) end
                            oLowestHealthActiveShield[refiTimeOfLastDischarge] = GetGameTimeSeconds()
                            --Dont want ot update name as we want to have the name refer to engineer orders
                            --[[if bUpdateName then
                                AiBotOrders.UpdateUnitNameForOrder(oLowestHealthActiveShield, 'DischZ'..(oLowestHealthActiveShield[reftArtiTemplateRefs][2] or 'nil')..'T'..(oLowestHealthActiveShield[reftArtiTemplateRefs][3] or 'nil')..'; Tm='..math.floor(GetGameTimeSeconds()))
                            end--]]
                        end
                    end

                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iSecondsBetweenShieldCycles)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': No longer have valid shields, so will flag that we have no active shield monitor, time='..GetGameTimeSeconds()) end
        tTableRef[AiBotMap.subrefbActiveShieldSACUCycling] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderFiringFirstLoadedNukeOnTeam(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderFiringFirstLoadedNukeOnTeam'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Called when an SMD has just been killed; wait 2 ticks in case the SMD was just being transferred
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(2)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oSMLToConsiderFiring
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        if not(oBrain.AiBotEasy) then
            local tFriendlyNukes = oBrain:GetListOfUnits(AiBotUnitInfo.refCategorySML, true, false)
            if AiBotUtilities.IsTableEmpty(tFriendlyNukes) == false then
                for iNuke, oNuke in tFriendlyNukes do
                    if oNuke:GetFractionComplete() == 1 and oNuke.GetNukeSiloAmmoCount and oNuke:GetNukeSiloAmmoCount() >= 1 then
                        if not(oNuke[refiTimeLastFiredMissile]) or GetGameTimeSeconds() - oNuke[refiTimeLastFiredMissile] >= 10 then
                            oSMLToConsiderFiring = oNuke
                            break
                        end
                    end
                end
                if oSMLToConsiderFiring then break end
            end
        end
    end
    if oSMLToConsiderFiring then
        if bDebugMessages == true then LOG(sFunctionRef..': Will consider firing nuke launcher='..oSMLToConsiderFiring.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSMLToConsiderFiring)) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        --LOG('consideration of launching missile 5')
        ConsiderLaunchingMissile(oSMLToConsiderFiring)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordNukeTarget(iTeam, tLaunchLocation)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordNukeTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bCheckIfRecentlyRecorded = true
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) then
        if not(AiBotTeam.tTeamData[iTeam]) then AiBotTeam.tTeamData[iTeam] = {} end
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] = {}
        bCheckIfRecentlyRecorded = false
    end
    local iCurTime = math.floor(GetGameTimeSeconds())
    local bIgnoreAsRecentlyRecorded = false
    if bCheckIfRecentlyRecorded then
        for iTime, tRecordedLaunchLocation in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] do
            if bDebugMessages == true then LOG(sFunctionRef..': iCurTime-iTime='..(iCurTime - iTime)..'; Dist to tRecordedLaunchLocation='..AiBotUtilities.GetDistanceBetweenPositions(tLaunchLocation, tRecordedLaunchLocation)) end
            if iCurTime - iTime <= 2 and AiBotUtilities.GetDistanceBetweenPositions(tLaunchLocation, tRecordedLaunchLocation) <= 4 then
                bIgnoreAsRecentlyRecorded = true
                break
            end
        end
    end
    if not(bIgnoreAsRecentlyRecorded) then

        local iOrigCurTime = iCurTime
        local iCycleCount = 0
        if bDebugMessages == true then LOG(sFunctionRef..': Recording nuke target, iTeam='..iTeam..'; tLaunchLocation='..repru(tLaunchLocation)..'; Time='..GetGameTimeSeconds()..'; iCurTime='..iCurTime..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations])) end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][iCurTime] then iCurTime = GetGameTimeSeconds() end
        local bAbortRecording
        while AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][iCurTime] do
            iCurTime = iCurTime - 0.0001
            --Wierd issue where sometimes but not always iCurTime doesnt change (likely also rseolved by having iCurTime switch to gametimeseconds
            if iOrigCurTime == iCurTime then
                iCurTime = iCurTime - 0.1
            end
            iCycleCount = iCycleCount + 1
            if bDebugMessages == true then LOG(sFunctionRef..': iCycleCount='..iCycleCount..'; iCurTime='..iCurTime..'; is AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][iCurTime] nil='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][iCurTime] == nil)) end
            if iCycleCount >= 15 then
                bAbortRecording = true
                AiBotUtilities.ErrorHandler('Potential infinite loop or too many simultaneous missile launches, aborted recording nuke missile location')
                break
            end
        end
        if bAbortRecording then
            --Do nothing
        else
            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][iCurTime] = { tLaunchLocation[1],tLaunchLocation[2], tLaunchLocation[3] }
            ForkThread(RemoveOldNukeTarget, iTeam, iCurTime, math.max(180, 60*AiBotMap.iMapSize / 1024))
        end
        if bDebugMessages == true then LOG(sFunctionRef..': End of code, iTeam='..iTeam..'; tLaunchLocation='..repru(tLaunchLocation)..'; Time='..GetGameTimeSeconds()..'; iCurTime='..iCurTime..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations])) end
    elseif bDebugMessages == true then LOG(sFunctionRef..': End of code, not recording as have recenlty recorded this location or a very nearby one')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RemoveOldNukeTarget(iTeam, iRecordedTime, iDelayInSeconds)
    WaitSeconds(iDelayInSeconds)
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) == false then
        for iTime, tLocation in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] do
            if iRecordedTime == iTime then
                AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] = nil
                break
            end
        end
    end
end

function QuantumOpticsManager(aiBrain, oUnit)
    --Call via forkthread
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'QuantumOpticsManager'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) and not (oUnit[refbActiveOpticsManager]) then
        local iTeam = aiBrain.AiBotTeam
        oUnit[refbActiveOpticsManager] = true
        local oBP = oUnit:GetBlueprint()
        local iIntelRange = (oBP.Intel.RemoteViewingRadius or oBP.Intel.VisionRadius)
        local iThresholdForAdjacentScry = iIntelRange * 2 * 1.3 --i.e. if we wouldnt cover all of the zone even with a 30% increase in the scry size, then we will scry the 4 corners
        local iDelayInSeconds = math.max(1, (oBP.Intel.ReactivateTime or 1) * 0.1)
        local iScryRelocationSize = iIntelRange * 1.45

        local iEntryCount
        local iEntryToScout
        local iCurLZOrWZ, iCurPlateauOrZero, iCurZoneSizeX, iCurZoneSizeZ
        function ReadyToScry()
            if AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive and aiBrain:GetEconomyStoredRatio('ENERGY') >= 1 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 250 and aiBrain:GetEconomyStored('ENERGY') >= 14000 and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
                return true
            else
                return false
            end
        end
        local tAdjAreaToScout

        function ScryAdjacentAreaWhenReady(tBaseTarget, iXAdjust, iZAdjust)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iDelayInSeconds)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            while not(ReadyToScry) do
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(iDelayInSeconds)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            tAdjAreaToScout = {tBaseTarget[1] + (iXAdjust or 0), tBaseTarget[2], tBaseTarget[3] + (iZAdjust or 0)}
            tAdjAreaToScout[2] = GetSurfaceHeight(tBaseTarget[1], tBaseTarget[3])
            if bDebugMessages == true then
                LOG(sFunctionRef..': Scrying adjacent area, tBaseTarget='..repru(tBaseTarget)..'; iXAdjust='..(iXAdjust or 'nil')..'; iZAdjust='..(iZAdjust or 'nil')..'; tAdjAreaToScout='..repru(tAdjAreaToScout)..'; Time='..GetGameTimeSeconds())
                AiBotUtilities.DrawLocation(tAdjAreaToScout, nil, nil, iIntelRange)
            end
            oUnit:OnTargetLocation(tAdjAreaToScout)
        end

        while AiBotUnitInfo.IsUnitValid(oUnit) do
            if oUnit:GetFractionComplete() == 1 then
                if ReadyToScry() then
                    AiBotAir.UpdateScoutingShortlist(iTeam)
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]) == false then
                        --Pick a random location on the shortlist
                        iEntryCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist])
                        iEntryToScout = math.random(1, iEntryCount)
                        iCurPlateauOrZero = AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist][iEntryToScout][1]
                        iCurLZOrWZ = AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist][iEntryToScout][2]
                        local tLZOrWZData, tLZOrWZTeamData
                        if iCurPlateauOrZero == 0 then
                            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZ]][AiBotMap.subrefPondWaterZones][iCurLZOrWZ]
                            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                            iCurZoneSizeX = ((tLZOrWZData[AiBotMap.subrefWZMaxSegX] or 0) - (tLZOrWZData[AiBotMap.subrefWZMinSegX] or 0)) * AiBotMap.iLandZoneSegmentSize
                            iCurZoneSizeZ = ((tLZOrWZData[AiBotMap.subrefWZMaxSegZ] or 0) - (tLZOrWZData[AiBotMap.subrefWZMinSegZ] or 0)) * AiBotMap.iLandZoneSegmentSize
                        else
                            tLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ]
                            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                            iCurZoneSizeX = ((tLZOrWZData[AiBotMap.subrefLZMaxSegX] or 0) - (tLZOrWZData[AiBotMap.subrefLZMinSegX] or 0)) * AiBotMap.iLandZoneSegmentSize
                            iCurZoneSizeZ = ((tLZOrWZData[AiBotMap.subrefLZMaxSegZ] or 0) - (tLZOrWZData[AiBotMap.subrefLZMinSegZ] or 0)) * AiBotMap.iLandZoneSegmentSize
                        end

                        --Scout the midpoint
                        if bDebugMessages == true then LOG(sFunctionRef..': Scrying midpoint, tLZOrWZData[AiBotMap.subrefMidpoint]='..repru(tLZOrWZData[AiBotMap.subrefMidpoint])..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLZOrWZ='..(iCurLZOrWZ or 'nil'))
                            AiBotUtilities.DrawLocation(tLZOrWZData[AiBotMap.subrefMidpoint], nil, nil, iIntelRange)
                        end
                        oUnit:OnTargetLocation(tLZOrWZData[AiBotMap.subrefMidpoint]) --See M27 function ScryTarget for alternative ways of doing this that were attempted
                        --Update to reflect we have had visual of the target
                        tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] = GetGameTimeSeconds()
                        --Large zones - scry to either side once ready
                        if iCurZoneSizeX > iThresholdForAdjacentScry then
                            --Scry each adjacent threshold; based on visualisation (sketchup as cant be bothered with the maths), for a 100 radius circle will cover most (but not all) of the surrounding area if the next scry location is 145 in each direction (north, east, south, west)
                            ScryAdjacentAreaWhenReady(tLZOrWZData[AiBotMap.subrefMidpoint], -iScryRelocationSize, 0)
                            ScryAdjacentAreaWhenReady(tLZOrWZData[AiBotMap.subrefMidpoint], iScryRelocationSize, 0)
                        end
                        if iCurZoneSizeZ > iThresholdForAdjacentScry then
                            ScryAdjacentAreaWhenReady(tLZOrWZData[AiBotMap.subrefMidpoint], 0, -iScryRelocationSize)
                            ScryAdjacentAreaWhenReady(tLZOrWZData[AiBotMap.subrefMidpoint], 0, iScryRelocationSize)
                        end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': No locations on shortlist to scout')
                    end
                end
            end

            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iDelayInSeconds)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordExperimentalResourceGen(oUnit)
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        local iPlateau, iZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
        if iPlateau then
            local iTeam = oUnit:GetAIBrain().AiBotTeam
            local tStartLZOrWZData, tStartLZOrWZTeamData
            if iPlateau == 0 then
                tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iZone]][AiBotMap.subrefPondWaterZones][iZone]
                tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            else
                tStartLZOrWZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone]
                tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end
            AiBotAir.RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
            tStartLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen] = oUnit
            if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if tSubtable[AiBotMap.subrefiDistance] <= 400 then
                        local tOtherLZOrWZData, tOtherLZOrWZTeamData
                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                            tOtherLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                            tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        else
                            tOtherLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                            tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        end
                        if not(AiBotUnitInfo.IsUnitValid(tOtherLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) then
                            tOtherLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen] = oUnit
                        end
                    else
                        break
                    end
                end
            end
        end
    end
end

function MonitorUnitRecentPositions(oUnit, iOptionalDelayInSecondsOverride, iOptionalCycleLimit)
    --Used to track positions for TML targeting - abort this function if we are already tracking for one of the units
    if not(oUnit[AiBotUnitInfo.reftRecentUnitPositions]) and AiBotUnitInfo.IsUnitValid(oUnit) then
        local iDelay = (iOptionalDelayInSecondsOverride or 2)
        local iCycleCount = 0
        oUnit[AiBotUnitInfo.reftRecentUnitPositions] = {[1] = {0,0,0},[2]={0,0,0},[3]={0,0,0},[4]={0,0,0}}
        while AiBotUnitInfo.IsUnitValid(oUnit) do
            oUnit[AiBotUnitInfo.reftRecentUnitPositions][4] = {oUnit[AiBotUnitInfo.reftRecentUnitPositions][3][1], oUnit[AiBotUnitInfo.reftRecentUnitPositions][3][2], oUnit[AiBotUnitInfo.reftRecentUnitPositions][3][3]}
            oUnit[AiBotUnitInfo.reftRecentUnitPositions][3] = {oUnit[AiBotUnitInfo.reftRecentUnitPositions][2][1], oUnit[AiBotUnitInfo.reftRecentUnitPositions][2][2], oUnit[AiBotUnitInfo.reftRecentUnitPositions][2][3]}
            oUnit[AiBotUnitInfo.reftRecentUnitPositions][2] = {oUnit[AiBotUnitInfo.reftRecentUnitPositions][1][1], oUnit[AiBotUnitInfo.reftRecentUnitPositions][1][2], oUnit[AiBotUnitInfo.reftRecentUnitPositions][1][3]}
            oUnit[AiBotUnitInfo.reftRecentUnitPositions][1] = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
            WaitSeconds(iDelay)
            if iOptionalCycleLimit then
                iCycleCount = iCycleCount + 1
                if iCycleCount >= iOptionalCycleLimit then
                    oUnit[AiBotUnitInfo.reftRecentUnitPositions] = nil
                    break
                end
            end
        end
    end
end

function TMLBatteryMonitor(tLZTeamData, oLauncher)
    --Called the first time a TML is being assigned to the TML battery
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TMLBatteryMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAlreadyRecorded = false --redundancy
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) == false then
        for iUnit, oUnit in tLZTeamData[AiBotMap.reftoTMLBatteryUnits] do
            if oUnit == oLauncher then
                bAlreadyRecorded = true
                break
            end
        end
    else
        tLZTeamData[AiBotMap.reftoTMLBatteryUnits] = {}
    end
    if not(bAlreadyRecorded) then table.insert(tLZTeamData[AiBotMap.reftoTMLBatteryUnits], oLauncher) end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, bAlreadyRecorded='..tostring(bAlreadyRecorded)..'; oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..'; tLZTeamData[AiBotMap.refbActiveTMLMonitor]='..tostring(tLZTeamData[AiBotMap.refbActiveTMLMonitor] or false)..'; Time='..GetGameTimeSeconds()) end
    if not(tLZTeamData[AiBotMap.refbActiveTMLMonitor]) then
        local iTeam = oLauncher:GetAIBrain().AiBotTeam
        tLZTeamData[AiBotMap.refbActiveTMLMonitor] = true

        --Get the first TMl, and use this as the benchmark for deciding how close enemies are
        local tBasePosition = oLauncher:GetPosition()
        local iAOE, iStrikeDamage, iMinRange, iMaxRange, iSalvoSize, iSalvoIndividualDelay = AiBotUnitInfo.GetLauncherAOEStrikeDamageMinAndMaxRange(oLauncher)
        iMaxRange = (iMaxRange or iTMLMissileRange)
        local iMaxEffectiveRange = iMaxRange - 25 --want enemy to be a bit within our max range to consider, in case TML have been built further away, and to give somel eeway for tracking target
        local iClosestEnemy, iCurDist
        local iTimeToWaitBetweenLaunches = 6
        local iTimeToWaitInTicks


        function GetPredictedPositionForMobileTarget(oTML, oClosestEnemy, bAlwaysReturnTarget, iAngleDif, iAngleToTarget)
            local iHeightDifference = oTML:GetPosition()[2] + 40 - oClosestEnemy:GetPosition()[2]

            local iHeightAdjustedDistToEnemy = math.sqrt(iHeightDifference * iHeightDifference + iClosestEnemy * iClosestEnemy)
            local iEstTimeToTarget = 2.7 + iHeightAdjustedDistToEnemy / 12 --fa/projectiles/CIFMissileTactical03/CIFMissileTactical03_proj.bp has a max speed of 12; velocity is 10; so need to allow for the following: Time from giving the order to the missile releasing; slightly slower speed by traveling at 10 instead of 12; going vertical for a bit; will try and roughly approximate by saying itll take 5s; however after testing it looks like there is minimal/no launch time, and 3.2s is much closer to the point at which a full speed fatboy is hit roughly at hte middle; 3 seemed slightly better; now trying 2.7
            local iSpeed
            if iAngleDif < 90 then iSpeed = oClosestEnemy:GetBlueprint().Physics.MaxSpeed
            else iSpeed = (oClosestEnemy:GetBlueprint().Phsyics.MaxSpeedReverse or oClosestEnemy:GetBlueprint().Physics.MaxSpeed)
            end
            local iEstDistance = iEstTimeToTarget * iSpeed
            if bDebugMessages == true then LOG(sFunctionRef..': iEstDistance='..iEstDistance..'; iEstTimeToTarget='..iEstTimeToTarget..'; iHeightAdjustedDistToEnemy='..iHeightAdjustedDistToEnemy..'; iClosestEnemy='..iClosestEnemy..'; iHeightDifference='..iHeightDifference) end
            if not(bAlwaysReturnTarget) and iEstDistance > 30 and iClosestEnemy - 30 > oClosestEnemy[AiBotUnitInfo.refiDFRange] and (iClosestEnemy >= 170 or iAngleDif >= 5 or (iClosestEnemy >= 150 and iAngleDif >= 2)) then
                --Dont get target afterall as high risk enemy dodges
                return
            else
                return AiBotUtilities.MoveInDirection(oClosestEnemy:GetPosition(), iAngleToTarget, iEstDistance, true, false, not(AiBotMap.bIsCampaignMap))
            end
        end

        local oPrimaryTML
        local iMissileValueWanted = 300 --i.e. dont bother firing if we will do less mass damage than this*number of missiles we expect to fire; this means we should fire up to 3 tml missiles to killl a t2 mex

        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, is table of battery units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]))) end
        while AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) do
            --Does enemy have any targets for us to consider sniping?
            if bDebugMessages == true then LOG(sFunctionRef..': Start of TML loop, is table of long range enemy DF units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]))..'; Time='..GetGameTimeSeconds()) end
            iTimeToWaitInTicks = AiBotLand.iTicksPerLandCycle

            local oClosestEnemy
            iClosestEnemy = iMaxEffectiveRange
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]) then
                local iCurShieldHealth, iMaxShieldHealth
                local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                if aiBrain then
                    for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) then
                            --Check target not under lots of fixed shielding (ignore mobile shields though since we might be targeting fatboy
                            --IsTargetUnderShield(aiBrain, oTarget, iIgnoreShieldsWithLessThanThisCurHealth, bReturnShieldHealthInstead, bIgnoreMobileShields, bTreatPartCompleteAsComplete, bCumulativeShieldHealth, bReturnShieldsCovringTargetInstead)
                            iCurShieldHealth, iMaxShieldHealth = AiBotLogic.IsTargetUnderShield(aiBrain, oUnit,   0,                                          true,                       true,              true,                           true,                   false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy exp oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurShieldHealth (of fixed shields, cumulatively)='..iCurShieldHealth) end
                            if iCurShieldHealth <= 14000 then --seraphim t2 shield is 13k health
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tBasePosition, oUnit:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': Dist from oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to tBasePosition='..iCurDist..'; oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4]='..repru(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4])) end
                                if iCurDist < iClosestEnemy and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and not(oUnit:IsUnitState('Attached')) then
                                    --oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4]
                                    iClosestEnemy = iCurDist
                                    oClosestEnemy = oUnit
                                end
                            end
                        end
                    end
                else
                    AiBotUtilities.ErrorHandler('No longer hve a valid brain')
                end
            end
            local iAdditionalLoadedTMLNeeded = 0
            local bAttackingNormalTMLTarget = false
            if not(AiBotUnitInfo.IsUnitValid(oPrimaryTML)) then
                oClosestEnemy = nil
                oPrimaryTML = nil
                for iTML, oTML in tLZTeamData[AiBotMap.reftoTMLBatteryUnits] do
                    oPrimaryTML = oTML
                    break
                end
            end
            if not(oClosestEnemy) then --Check for normal TML targets
                if oPrimaryTML and AiBotConditions.IsTableOfUnitsStillValid(oPrimaryTML[reftUnitsInRangeOfThisTML]) then
                    local aiBrain = oPrimaryTML:GetAIBrain()
                    local iLeastTMDOrMissedShotsCoveringTarget = 3 --i.e. if a target has 4+ TMD covering it then we wont bother trying to target it
                    local iMissedShotsFactor = 4 --i.e. every 4 missiles fired at this target is treated as a 'missed shot' equivalent to 1 TMD in coverage mostly as a redundancy to stop constantly firing at the same target and failing
                    local iShieldFactor = 5500 --i.e. total shield health covering target divided by this is treated as an equivalent number of TMD
                    local iCurTMDOrMissedShotsCoveringTarget
                    local iBestValue = 0
                    local iCurValue, iCurShieldValue, iCurShieldHealth, iMaxShieldHealth
                    iClosestEnemy = iMaxEffectiveRange --redundancy
                    for iUnit, oUnit in oPrimaryTML[reftUnitsInRangeOfThisTML] do
                        iCurTMDOrMissedShotsCoveringTarget = 0
                        if AiBotConditions.IsTableOfUnitsStillValid(oUnit[reftTMDCoveringThisUnit]) then
                            --Do detailed check
                            if (oUnit[refiLastDetailedTMDProtectionCount] or 0) <= iLeastTMDOrMissedShotsCoveringTarget then
                                for iTMD, oTMD in oUnit[reftTMDCoveringThisUnit] do
                                    if IsTMDProtectingUnitFromTML(oTMD, oUnit, oPrimaryTML, AiBotUnitInfo.GetBuildingSize(oUnit.UnitId)) then
                                        if EntityCategoryContains(categories.AEON, oTMD.UnitId) then
                                            if AiBotUtilities.bFAFActive then
                                                iCurTMDOrMissedShotsCoveringTarget = iCurTMDOrMissedShotsCoveringTarget + 3
                                            else
                                                iCurTMDOrMissedShotsCoveringTarget = iCurTMDOrMissedShotsCoveringTarget + 10
                                            end
                                        else
                                            iCurTMDOrMissedShotsCoveringTarget = iCurTMDOrMissedShotsCoveringTarget + 1
                                        end
                                    end
                                end
                                oUnit[refiLastDetailedTMDProtectionCount] = iCurTMDOrMissedShotsCoveringTarget
                            else
                                iCurTMDOrMissedShotsCoveringTarget = table.getn(oUnit[reftTMDCoveringThisUnit])
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Number of TMD against unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has a table size='..table.getn(oUnit[reftTMDCoveringThisUnit])..'; oUnit[refiLastDetailedTMDProtectionCount]='..(oUnit[refiLastDetailedTMDProtectionCount] or 'nil')) end
                        end
                        if iCurTMDOrMissedShotsCoveringTarget <= iLeastTMDOrMissedShotsCoveringTarget then
                            --Adjust for missed shots
                            if (oUnit[refiTMLShotsFired] or 0) > (oUnit[refiTMLShotsHit] or 0) then iCurTMDOrMissedShotsCoveringTarget = iCurTMDOrMissedShotsCoveringTarget + (oUnit[refiTMLShotsFired] - (oUnit[refiTMLShotsHit] or 0)) / iMissedShotsFactor end
                            if iCurTMDOrMissedShotsCoveringTarget <= iLeastTMDOrMissedShotsCoveringTarget then
                                --Adjust for blocking terrain
                                if AiBotUtilities.IsTableEmpty(oPrimaryTML[reftTerrainBlockedTargets]) == false then
                                    for iBlockedTerrain, tBlockedTerrain in oPrimaryTML[reftTerrainBlockedTargets] do
                                        if AiBotUtilities.GetRoughDistanceBetweenPositions(tBlockedTerrain, oUnit:GetPosition()) <= 1 then
                                            iCurTMDOrMissedShotsCoveringTarget = iCurTMDOrMissedShotsCoveringTarget + 10
                                            ForkThread(RemoveUnitFromTMLTargetsInRange, oPrimaryTML, oUnit)
                                        end
                                    end
                                end
                                --Avoid targeting if it will cost so many missiles that the damage done isnt worth it
                                iCurValue = AiBotUnitInfo.GetUnitMassCost(oUnit) * oUnit:GetFractionComplete() - iMissileValueWanted * (iCurTMDOrMissedShotsCoveringTarget + 1)
                                if iCurValue <= 2000 and oUnit:GetFractionComplete() <= 0.8 then iCurValue = 0
                                elseif EntityCategoryContains(categories.VOLATILE, oUnit.UnitId) then
                                    if oUnit:GetFractionComplete() < 1 then iCurValue = iCurValue * 0.1
                                    else iCurValue = iCurValue * 1.5
                                    end
                                end
                                if iCurValue > 0 and iCurTMDOrMissedShotsCoveringTarget <= iLeastTMDOrMissedShotsCoveringTarget and (iCurTMDOrMissedShotsCoveringTarget < iLeastTMDOrMissedShotsCoveringTarget or iCurValue > iBestValue) then
                                    --Adjust for fixed shields
                                                                                --IsTargetUnderShield(aiBrain, oTarget, iIgnoreShieldsWithLessThanThisCurHealth, bReturnShieldHealthInstead, bIgnoreMobileShields, bTreatPartCompleteAsComplete, bCumulativeShieldHealth, bReturnShieldsCovringTargetInstead)
                                    iCurShieldHealth, iMaxShieldHealth = AiBotLogic.IsTargetUnderShield(aiBrain, oUnit,   0,                                          true,                       false,              true,                           true,                   false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurTMDOrMissedShotsCoveringTarget before shield adj='..iCurTMDOrMissedShotsCoveringTarget..'; iCurShieldHealth='..(iCurShieldHealth or 'nil')..'; iMaxShieldHealth='..(iMaxShieldHealth or 'nil')..'; iLeastTMDOrMissedShotsCoveringTarget='..iLeastTMDOrMissedShotsCoveringTarget) end
                                    if iMaxShieldHealth > 0 then
                                        iCurShieldValue = math.min(iMaxShieldHealth, math.max(iCurShieldHealth * 2, iCurShieldHealth + iStrikeDamage)) / iShieldFactor
                                        iCurTMDOrMissedShotsCoveringTarget = iCurTMDOrMissedShotsCoveringTarget + iCurShieldValue
                                        iCurValue = iCurValue - iMissileValueWanted * iCurShieldValue
                                    else
                                        iCurShieldValue = 0
                                    end
                                    if iCurTMDOrMissedShotsCoveringTarget <= iLeastTMDOrMissedShotsCoveringTarget and (iCurTMDOrMissedShotsCoveringTarget == 0 or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oPrimaryTML:GetPosition()) < iTMLMissileRange - 10) then
                                        if iCurTMDOrMissedShotsCoveringTarget < iLeastTMDOrMissedShotsCoveringTarget then iBestValue = 0 end
                                        if iCurValue > iBestValue then
                                            iBestValue = iCurValue
                                            oClosestEnemy = oUnit
                                            iAdditionalLoadedTMLNeeded = iCurTMDOrMissedShotsCoveringTarget * 2
                                            bAttackingNormalTMLTarget = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to try targeting enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurValue='..iCurValue..'; iAdditionalLoadedTMLNeeded='..iAdditionalLoadedTMLNeeded) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                if oClosestEnemy then bAttackingNormalTMLTarget = true end --redundancy
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nil')..'; iClosestEnemy='..iClosestEnemy..'; oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions]='..repru(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions])) end
            if oClosestEnemy then
                if not(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4]) then
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oClosestEnemy.UnitId) then
                        oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions] = {}
                        for iPosition = 1, 4 do
                            oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][iPosition] = {oClosestEnemy:GetPosition()[1], oClosestEnemy:GetPosition()[2], oClosestEnemy:GetPosition()[3]}
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Will call MonitorUnitRecentPositions for the unit') end
                        ForkThread(MonitorUnitRecentPositions, oClosestEnemy) --has a check to make sure not already running
                    end
                end
                if not(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4]) then
                else
                    --how many TML do we have with missiles?
                    local iLoadedTMLs = 0
                    local toLoadedTMLs = {}

                    for iTML, oTML in tLZTeamData[AiBotMap.reftoTMLBatteryUnits] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..'; Ammo count='..oTML:GetTacticalSiloAmmoCount()..'; Time since last fired='..GetGameTimeSeconds() - (oLauncher[refiTimeLastFiredMissile] or 0)) end
                        if AiBotUnitInfo.IsUnitValid(oTML) and oTML:GetTacticalSiloAmmoCount() > 0 then
                            if not(oLauncher[AiBotUnitInfo.refiLastWeaponEvent]) or GetGameTimeSeconds() - oLauncher[AiBotUnitInfo.refiLastWeaponEvent] > iTimeToWaitBetweenLaunches then
                                if not(oPrimaryTML) then
                                    oPrimaryTML = oTML
                                    tBasePosition = oTML:GetPosition()
                                end
                                table.insert(toLoadedTMLs, oTML)
                                iLoadedTMLs = iLoadedTMLs + 1
                            end
                        else
                            --Make sure autobuild is enabled
                            AiBotUnitInfo.SetUnitMissileAutoBuildStatus(oTML, true)
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iLoadedTMLs='..iLoadedTMLs) end
                    if iLoadedTMLs > 0 then
                        local iEnemyHealth = oClosestEnemy:GetHealth() + 10 --Add 5 as enemy hp regen might mean we think we will kill it but we wont
                        if oClosestEnemy.MyShield.GetHealth then
                            local iShield = oClosestEnemy.MyShield:GetHealth()
                            iEnemyHealth = iEnemyHealth + math.ceil(iShield / iStrikeDamage) * iStrikeDamage
                        end
                        --7 TMLs should be able to 1-shot a fatboy; for megalith will just have to do several salvos
                        if bDebugMessages == true then LOG(sFunctionRef..': iStrikeDamage * iLoadedTMLs='..iStrikeDamage * iLoadedTMLs..'; iEnemyHealth='..iEnemyHealth..'; iClosestEnemy='..iClosestEnemy..'; Enemy DF range='..(oClosestEnemy[AiBotUnitInfo.refiDFRange] or 0)) end
                        if iLoadedTMLs >= 8 or iStrikeDamage * (iLoadedTMLs - iAdditionalLoadedTMLNeeded) > iEnemyHealth or iClosestEnemy < (oClosestEnemy[AiBotUnitInfo.refiDFRange] or 0) + 6 or (iLoadedTMLs >= 7 and oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4] and AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4], oClosestEnemy:GetPosition()) <= 1 and AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][2], oClosestEnemy:GetPosition()) <= 1) then
                            --We should be able to 1-shot the enemy, so try and attack them if they are close enough to warrant firing
                            --How many shots have we already attempted at this unit? If a lot, then wait for it to get really close
                            local iMinDistWanted
                            if bAttackingNormalTMLTarget or (oClosestEnemy[refiTMLShotsFired] or 0) - (oClosestEnemy[refiTMLShotsHit] or 0) < iLoadedTMLs + (oClosestEnemy[refiTMLShotsHit] or 0) then
                                iMinDistWanted = iMaxEffectiveRange
                            else
                                --Reduce range by up to 60% if we are missing all our shots
                                local iFactorAffected = 0.6
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbTMLBatteryMissedLots]) and oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4] and AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4], oClosestEnemy:GetPosition()) <= 1 and not(oClosestEnemy:IsUnitState('Moving')) then
                                    iFactorAffected = 0.3
                                end
                                iMinDistWanted = math.max(iMaxEffectiveRange * ((1 - iFactorAffected) + iFactorAffected * math.max(iLoadedTMLs, (oClosestEnemy[refiTMLShotsHit] or iLoadedTMLs)) / oClosestEnemy[refiTMLShotsFired]), 60, math.min(iMaxEffectiveRange, (oClosestEnemy[AiBotUnitInfo.refiCombatRange] or 0) + 10))
                                if oClosestEnemy[refiTMLShotsFired] > 28 then --We have fired 28 TMLs at this enemy, so should switch to getting T2 arti
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refbTMLBatteryMissedLots] = true
                                end
                            end
                            if iClosestEnemy <= iMinDistWanted then
                                local iCurFacingAngle, iAngleToTarget, iAngleDif
                                --Is unit stationery? Or is it moving, at a decent speed, and is facing its current goal direction (or at an opposite to it, as it may be backing up)? If so then it is vulnerable to a missile attack
                                local tPredictedPosition
                                local iCurSpeed = AiBotUnitInfo.GetUnitSpeed(oClosestEnemy)
                                if bDebugMessages == true then LOG(sFunctionRef..': Closest enemy iCurSpeed='..iCurSpeed..'; Is moving='..tostring(oClosestEnemy:IsUnitState('Moving'))..'; Unit state='..AiBotUnitInfo.GetUnitState(oClosestEnemy)) end
                                local bMobileTarget = false
                                if bAttackingNormalTMLTarget and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oClosestEnemy.UnitId) then
                                    tPredictedPosition = oClosestEnemy:GetPosition()
                                elseif iCurSpeed <= 0.25 and not(oClosestEnemy:IsUnitState('Moving')) then
                                    --Have we not been moving for a while?
                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist to postiion from 2-4s ago='..AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy:GetPosition(), oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][2])) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy:GetPosition(), oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][2]) <= 1 then
                                        tPredictedPosition = oClosestEnemy:GetPosition()
                                    end
                                elseif iCurSpeed >= 1 and (oClosestEnemy:IsUnitState('Moving') or oClosestEnemy:IsUnitState('Attacking')) and oClosestEnemy.GetNavigator then
                                    bMobileTarget = true
                                    local oNavigator = oClosestEnemy:GetNavigator()
                                    if oNavigator then
                                        iCurFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oClosestEnemy)
                                        local tCurNavigatorTarget = oNavigator:GetCurrentTargetPos()
                                        iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oClosestEnemy:GetPosition(), tCurNavigatorTarget)
                                        iAngleDif = AiBotUtilities.GetAngleDifference(iCurFacingAngle, iAngleToTarget)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy iCurFacingAngle='..iCurFacingAngle..'; iAngleToTarget='..iAngleToTarget..'; iAngleDif='..iAngleDif) end
                                        if iAngleDif >= 174 or iAngleDif <= 8 then
                                            --Check we have moved in roughly this direction previously
                                            local iAngleToRecentPosition = AiBotUtilities.GetAngleFromAToB(oClosestEnemy:GetPosition(), oClosestEnemy[AiBotUnitInfo.reftRecentUnitPositions][4])
                                            if bDebugMessages == true then LOG(sFunctionRef..': iAngleToRecentPosition='..iAngleToRecentPosition..'; Angle dif to target='..AiBotUtilities.GetAngleDifference(iAngleToTarget, iAngleToRecentPosition)) end
                                            if AiBotUtilities.GetAngleDifference(iAngleToTarget, iAngleToRecentPosition) >= 170 then
                                                tPredictedPosition = GetPredictedPositionForMobileTarget(oPrimaryTML, oClosestEnemy, false, iAngleDif, iAngleToTarget)
                                            end
                                        end
                                    end
                                end
                                if tPredictedPosition then
                                    --Check our shot isn't blocked
                                    local tExpectedMissileVertical = AiBotUtilities.MoveInDirection(oPrimaryTML:GetPosition(), AiBotUtilities.GetAngleFromAToB(oPrimaryTML:GetPosition(), oClosestEnemy:GetPosition()), 31, true)
                                    tExpectedMissileVertical[2] = tExpectedMissileVertical[2] + 60 --Doing testing, it actually only goes up by 50, but I think it travels in an arc from here to the target, as in a test scenario doing at less than +60 meant it thought it would hit a cliff when it didnt
                                    -- {oLauncher:GetPosition()[1], oLauncher:GetPosition()[2] + 65, oLauncher:GetPosition()[3]}
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is line blocked='..tostring(AiBotLogic.IsLineBlocked(oPrimaryTML:GetAIBrain(), tExpectedMissileVertical, oClosestEnemy:GetPosition(), iAOE, false))) end
                                    if not(AiBotLogic.IsLineBlocked(oPrimaryTML:GetAIBrain(), tExpectedMissileVertical, oClosestEnemy:GetPosition(), iAOE, false)) then
                                        --Check there arent lots of TMD that could intercept the missile
                                        local tNearbyEnemyTMD
                                        local iBlockingTMD
                                        if bAttackingNormalTMLTarget then
                                            iBlockingTMD = iAdditionalLoadedTMLNeeded
                                        else
                                            tNearbyEnemyTMD = oClosestEnemy:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryTMD, oPrimaryTML:GetPosition(), iClosestEnemy + 15, 'Ally')
                                            iBlockingTMD = 0
                                            if AiBotUtilities.IsTableEmpty(tNearbyEnemyTMD) == false then
                                                RecordIfUnitIsProtectedFromTMLByTMD(oClosestEnemy, oPrimaryTML, tNearbyEnemyTMD)
                                                if AiBotUtilities.IsTableEmpty(oClosestEnemy[reftTMDCoveringThisUnit]) == false then
                                                    for iTMD, oTMD in oClosestEnemy[reftTMDCoveringThisUnit] do
                                                        --Distance check to act as basic protection from if for whatever reason the TMD aren't removed and the unit is moving around
                                                        if AiBotUnitInfo.IsUnitValid(oTMD) and AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oPrimaryTML:GetPosition()) < 20+iClosestEnemy then
                                                            --Also do a more detailed check of each TMD as they may not actually be blocking this TML
                                                            if IsTMDProtectingUnitFromTML(oTMD, oClosestEnemy, oPrimaryTML) then
                                                                iBlockingTMD = iBlockingTMD + 1
                                                                if EntityCategoryContains(categories.AEON, oTMD.UnitId) then
                                                                    if AiBotUtilities.bFAFActive then
                                                                        iBlockingTMD = iBlockingTMD + 2
                                                                    else
                                                                        iBlockingTMD = iBlockingTMD + 100
                                                                        break
                                                                    end
                                                                end
                                                            elseif bMobileTarget then
                                                                iBlockingTMD = iBlockingTMD + 0.35 --Still a risk the TMD could be blocking the units expected position
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iBlockingTMD='..iBlockingTMD) end
                                        if iBlockingTMD < math.min(iLoadedTMLs, 5) then
                                            local iTMLsToFire = iLoadedTMLs
                                            local iTMLsFired = 0
                                            local iTMLForAlternativeTarget = 0
                                            if bAttackingNormalTMLTarget then
                                                if iLoadedTMLs > math.floor(iEnemyHealth / iStrikeDamage) + 1 + iAdditionalLoadedTMLNeeded then
                                                    if iAdditionalLoadedTMLNeeded == 0 then
                                                        --Dont worry about multiple targets since no TMD/shields
                                                        if iEnemyHealth < iStrikeDamage then
                                                            --Just fire a single TML
                                                            iTMLsToFire = 1
                                                        else
                                                            --Fire 1 more missile than expect we need
                                                            iTMLsToFire = 2 + math.floor(iEnemyHealth / iStrikeDamage)
                                                        end
                                                    else
                                                        --Element of doubt whether we can kill in a single hit, fire 2 more missiles than we think we need
                                                        iTMLsToFire = iAdditionalLoadedTMLNeeded + 2 + math.floor(iEnemyHealth / iStrikeDamage)
                                                        if AiBotUnitInfo.GetUnitMassCost(oClosestEnemy) >= 2000 then iTMLsToFire = iTMLsToFire + 1 end
                                                        iTMLForAlternativeTarget = math.max(0, iLoadedTMLs - iTMLsToFire)
                                                    end
                                                end
                                            elseif iLoadedTMLs >= 3 and iBlockingTMD == 0 and iEnemyHealth < (iLoadedTMLs - 2) * iStrikeDamage then
                                                iTMLsToFire = math.floor(iEnemyHealth / iStrikeDamage) + 2
                                                if iTMLsToFire >= 5 then iTMLsToFire = iTMLsToFire + 1 end
                                            end
                                            --Megalith - adjust predicted position because if we hit at the midpoint of the megalith the shot does no damage, so we want to try and hit its back instead
                                            if oClosestEnemy.UnitId == 'xrl0403' then
                                                local iAngleToAdjust = AiBotUnitInfo.GetUnitFacingAngle(oClosestEnemy) - 180
                                                tPredictedPosition = AiBotUtilities.MoveInDirection(tPredictedPosition, iAngleToAdjust, 2, true, false, false)
                                                local iAngleFromTMLToPosition = AiBotUtilities.GetAngleFromAToB(oPrimaryTML:GetPosition(), tPredictedPosition)
                                                tPredictedPosition = AiBotUtilities.MoveInDirection(tPredictedPosition, iAngleFromTMLToPosition, 10, true, false, false) --Offset of 5 with no 'move back': 6/7 missiles hit. Offset of 10 with no 'move back': 7/7 hit but only just; offset of 10 with 2 move-back: 7/7 hit and looked a bit more central
                                            end
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef..': Will fire TMLs at tPredictedPosition='..repru(tPredictedPosition)..'; oClosestEnemy='..oClosestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy)..'; Dist to oClosestEnemy='..AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy:GetPosition(), tPredictedPosition)..'; Angle from enemy to predicted position='..AiBotUtilities.GetAngleFromAToB(oClosestEnemy:GetPosition(), tPredictedPosition)..'; iLoadedTMLs='..iLoadedTMLs..'; iTMLsToFire='..iTMLsToFire..'; iLoadedTMLs='..iLoadedTMLs..'; iTMLForAlternativeTarget='..iTMLForAlternativeTarget..'; bAttackingNormalTMLTarget='..tostring(bAttackingNormalTMLTarget or false))
                                                AiBotUtilities.DrawLocation(tPredictedPosition)
                                            end
                                            local iLongestDistToTarget = 0
                                            local iDistToTarget
                                            for iTMl, oTML in toLoadedTMLs do
                                                CheckIfWantToBuildAnotherMissile(oTML)
                                                --If predicted position is outside our range then just fire as cose to it as we can
                                                iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oTML:GetPosition(), tPredictedPosition)
                                                iLongestDistToTarget = math.max(iLongestDistToTarget, iDistToTarget)
                                                if iDistToTarget > iTMLMissileRange then
                                                    AiBotOrders.IssueTrackedTMLMissileLaunch(oTML, AiBotUtilities.MoveInDirection(oTML:GetPosition(), AiBotUtilities.GetAngleFromAToB(oTML:GetPosition(), tPredictedPosition), iTMLMissileRange, true, false, false), 1, false, 'TMLOutRSn')
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': oTML='..(oTML.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTML) or 'nil')..'; oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nil')..'; Is TML valid='..tostring(AiBotUnitInfo.IsUnitValid(oTML))..'; Is enemy valid='..tostring(AiBotUnitInfo.IsUnitValid(oClosestEnemy))..'; bMobileTarget='..tostring(bMobileTarget or false)) end
                                                    if bMobileTarget and iAngleToTarget and not(oTML == oPrimaryTML) and not(oClosestEnemy.UnitId == 'xrl0403') then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will get position specific to the TML, iAngleDif='..(iAngleDif or 'nil')..'; iAngleToTarget='..(iAngleToTarget or 'nil')..'; iAngleDif='..(iAngleDif or 'nil')) end
                                                        AiBotOrders.IssueTrackedTMLMissileLaunch(oTML, GetPredictedPositionForMobileTarget(oPrimaryTML, oClosestEnemy, true,  AiBotUtilities.GetAngleDifference((iCurFacingAngle or AiBotUnitInfo.GetUnitFacingAngle(oClosestEnemy)), iAngleToTarget), iAngleToTarget), 1, false, 'TMLSnipe')
                                                    else
                                                        AiBotOrders.IssueTrackedTMLMissileLaunch(oTML, tPredictedPosition, 1, false, 'TMLSnipe')
                                                    end
                                                    RecordTMLMissileTarget(oTML, oClosestEnemy)
                                                    iTMLsFired = iTMLsFired + 1
                                                end
                                                if iTMLsFired >= iTMLsToFire then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Have fired all the TMLs we want to at this target, iTMLForAlternativeTarget='..iTMLForAlternativeTarget) end
                                                    if iTMLForAlternativeTarget > 0 then
                                                        --Switch to an alternative target - if have TMD covering the unit then try and kill the closest TMD to us
                                                        local oNewEnemy
                                                        local iClosestTMDOrShield = iTMLMissileRange - 3
                                                        if AiBotUtilities.IsTableEmpty(oClosestEnemy[reftTMDCoveringThisUnit]) == false then
                                                            for iTMD, oTMD in oClosestEnemy[reftTMDCoveringThisUnit] do
                                                                if AiBotUnitInfo.IsUnitValid(oTMD) then
                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oTMD:GetPosition(), oTML:GetPosition())
                                                                    if iCurDist < iClosestTMDOrShield then
                                                                        oNewEnemy = oTMD
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        if AiBotUtilities.IsTableEmpty(oClosestEnemy[reftoShieldsProvidingCoverage]) == false then
                                                            for iShield, oShield in oClosestEnemy[reftoShieldsProvidingCoverage] do
                                                                if AiBotUnitInfo.IsUnitValid(oShield) then
                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oTML:GetPosition())
                                                                    if iCurDist < iClosestTMDOrShield then
                                                                        oNewEnemy = oShield
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        oClosestEnemy = oNewEnemy
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try firing at alternative target if have one, new oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nil')..'; iTMLsToFire for this='..iTMLsToFire..'; iTMLForAlternativeTarget='..iTMLForAlternativeTarget) end
                                                        if oClosestEnemy then
                                                            iTMLsToFire = math.max(math.min(iTMLForAlternativeTarget, 2), math.floor((AiBotUnitInfo.GetUnitCurHealthAndShield(oClosestEnemy) * 1.1 + 100) / iStrikeDamage) + 1)
                                                            iTMLForAlternativeTarget = math.max(0, iTMLForAlternativeTarget - iTMLsToFire)
                                                            bMobileTarget = false
                                                            tPredictedPosition = oClosestEnemy:GetPosition()
                                                            bAttackingNormalTMLTarget = true --redundancy
                                                            iTMLsFired = 0
                                                        else
                                                            break
                                                        end
                                                    else
                                                        break
                                                    end
                                                end
                                            end
                                            iTimeToWaitInTicks = iTimeToWaitBetweenLaunches * 10
                                            --If firing at normal target want to reduce overkilling
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to extent TML target, bAttackingNormalTMLTarget='..tostring(bAttackingNormalTMLTarget or false)..'; iLongestDistToTarget='..(iLongestDistToTarget or 'nil')..'; iTimeToWaitInTicks before potential extension='..iTimeToWaitInTicks..'; Cur time='..GetGameTimeSeconds()) end
                                            if bAttackingNormalTMLTarget and iLongestDistToTarget > 0 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will extend time to wait as firing at normal TML target, iLongestDistToTarget='..iLongestDistToTarget) end
                                                iTimeToWaitInTicks = math.max(100, iTimeToWaitInTicks, 35 + iLongestDistToTarget / 1.2) --at +30 we stil had missiles sometimes firing twice
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            else
                --No closest enemy, increase delay to once every 5s if shorter so we arent constnatly searching for nearby targets where we are doing more calculations
                iTimeToWaitInTicks = math.max(iTimeToWaitInTicks, 50)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will wait iTimeToWaitInTicks='..iTimeToWaitInTicks..' before next cycle') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(iTimeToWaitInTicks)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        tLZTeamData[AiBotMap.refbActiveTMLMonitor] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordTMLMissileTarget(oLauncher, oBestTarget)
    if not(oLauncher.Dead) and oLauncher:IsUnitState('Busy') and (GetGameTimeSeconds() - (oLauncher[refiTimeOfLastLaunch] or -100)) < 5 and AiBotUnitInfo.IsUnitValid(oLauncher[refoLastTMLTarget]) then
        oLauncher[refoLastTMLTarget][refiTMLShotsFired] = (oLauncher[refoLastTMLTarget][refiTMLShotsFired] or 0) - 1 --ignore thel ast target as looks like we never actually fired the missile
    end
    oBestTarget[refiTMLShotsFired] = (oBestTarget[refiTMLShotsFired] or 0) + 1
    oLauncher[refoLastTMLTarget] = oBestTarget
    oLauncher[refiLastTMLMassKills] = (oLauncher.VetExperience or oLauncher.Sync.totalMassKilled or 0)
    oBestTarget[refoLastTMLLauncher] = oLauncher
    oBestTarget[refiTimeOfLastLaunch] = GetGameTimeSeconds()
end

function RemoveUnitFromTMLTargetsInRange(oTML, oUnit)
    --Intended where terrain is blocking shots, so we dont continue to consider for TML battery due to the risk of greater cpu load
    if AiBotUtilities.IsTableEmpty(oTML[reftUnitsInRangeOfThisTML]) == false then
        for iTarget, oTarget in oTML[reftUnitsInRangeOfThisTML] do
            if oTarget == oUnit then
                table.remove(oTML[reftUnitsInRangeOfThisTML], iTarget)
                break
            end
        end
    end
end

function GetTargetsWithoutTMDCoverageBasedOnZoneMidpoint(tTMLLZTeamData, tTargetLZTeamData, iTargetPlateauOrZero, iTargetZone, tPlannedTMLLocation, iOptionalTMDRequiredToBlock)
    --Only refresh once every 60s for performance reasons (or 10s if we have targets, since those targets may well die and would expect we cancel TML builder logic if we have a TML already)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TMLBatteryMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bRefresh = false
    if not(tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone][iTargetPlateauOrZero][iTargetZone]) then
        bRefresh = true
        if not(tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone][iTargetPlateauOrZero]) then
            if not(tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone]) then
                tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone] = {}
                tTMLLZTeamData[AiBotMap.refiDetailedTMLTargetWithoutTMDCheckByPlateauAndZone] = {}
            end
            tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone][iTargetPlateauOrZero] = {}
            tTMLLZTeamData[AiBotMap.refiDetailedTMLTargetWithoutTMDCheckByPlateauAndZone][iTargetPlateauOrZero] = {}
        end
    else
        local iTimeSinceLastUpdate = GetGameTimeSeconds() - tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone][iTargetPlateauOrZero][iTargetZone]
        if iTimeSinceLastUpdate >= 60 or (iTimeSinceLastUpdate >= 10 and tTMLLZTeamData[AiBotMap.refiDetailedTMLTargetWithoutTMDCheckByPlateauAndZone][iTargetPlateauOrZero][iTargetZone] > 0) then
            bRefresh = true
        end
    end
    if bRefresh then
        local iTargetsWithoutTMD = 0
        local iTMDRequiredToBlock = iOptionalTMDRequiredToBlock or 1
        local iBlockingTMD
        if AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets]) == false then
            for iTarget, oTarget in tTargetLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets] do
                iBlockingTMD = 0
                if AiBotUnitInfo.IsUnitValid(oTarget) and AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), tPlannedTMLLocation) <= iTMLMissileRange then
                    if AiBotUtilities.IsTableEmpty(oTarget[reftTMDCoveringThisUnit]) == false then
                        for iTMD, oTMD in oTarget[reftTMDCoveringThisUnit] do
                            if AiBotUnitInfo.IsUnitValid(oTMD) then
                                if IsTMDProtectingUnitFromTML(oTMD, oTarget, nil, nil, tPlannedTMLLocation) then
                                    iBlockingTMD = iBlockingTMD + 1
                                    if iBlockingTMD >= iTMDRequiredToBlock then
                                        break
                                    else
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryAeon, oTMD.UnitId) then
                                            if AiBotUtilities.bFAFActive then
                                                iBlockingTMD = iBlockingTMD + 2
                                            else
                                                iBlockingTMD = iBlockingTMD + 100
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if iBlockingTMD < iTMDRequiredToBlock then
                        iTargetsWithoutTMD = iTargetsWithoutTMD + 1
                    end
                end
            end
        end
        tTMLLZTeamData[AiBotMap.refiTimeOfLastDetailedTMLTMDCheckByPlateauAndZone][iTargetPlateauOrZero][iTargetZone] = GetGameTimeSeconds()
        tTMLLZTeamData[AiBotMap.refiDetailedTMLTargetWithoutTMDCheckByPlateauAndZone][iTargetPlateauOrZero][iTargetZone] = iTargetsWithoutTMD
        if bDebugMessages == true then LOG(sFunctionRef..': Done detailed refresh for target P'..iTargetPlateauOrZero..'Z'..iTargetZone..'; iTargetsWithoutTMD='..iTargetsWithoutTMD) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return tTMLLZTeamData[AiBotMap.refiDetailedTMLTargetWithoutTMDCheckByPlateauAndZone][iTargetPlateauOrZero][iTargetZone]
end

function ConsiderGettingPreemptiveTMD(oPD)
    --Called where we finish construction of T2 PD - check how many T2 PD we have in the zone, and flag all T2 PD to have TMD preemptively
    if AiBotUnitInfo.IsUnitValid(oPD) then
        local iTeam = oPD:GetAIBrain().AiBotTeam
        --If enemy has T3 land then dont bother
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 then
            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oPD:GetPosition(), true, iTeam)
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local tFriendlyT2PD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tFriendlyT2PD) == false then
                    local iT2PDInZone = 1
                    for iUnit, oUnit in tFriendlyT2PD do
                        if not(oUnit.Dead) and not(oUnit == oPD) then
                            iT2PDInZone = iT2PDInZone + 1
                        end
                    end
                    if iT2PDInZone >= 3 and ((iT2PDInZone >= 6 and tLZTeamData[AiBotMap.refiRadarCoverage] < 160) or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileTML]) == false and (AiBotUnitInfo.IsUnitValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileTML][1]) or AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileTML]))) then
                        local iTMDWanted = math.min(3, iT2PDInZone - 2)
                        local toPDUpdated = {}
                        oPD[refiMinTMDWantedForUnit] = iTMDWanted --redundancy in case for some reason we havent yet recorded against the LZTeamData
                        table.insert(toPDUpdated, oPD)
                        for iUnit, oUnit in tFriendlyT2PD do
                            if not(oUnit.Dead) and not(oUnit == oPD) then
                                if (oUnit[refiMinTMDWantedForUnit] or 0) < iTMDWanted then
                                    oUnit[refiMinTMDWantedForUnit] = iTMDWanted
                                    table.insert(toPDUpdated, oUnit)
                                end
                            end
                        end
                        RecordIfUnitsWantTMDCoverageAgainstLandZone(iTeam, toPDUpdated, true)
                    end
                end
            end
        end
    end
end

function GetManualPDTarget(oUnit, oOptionalTargetToIgnore)    
    --Intended for use where PD shot is blocked
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetManualPDTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
        local aiBrain = oUnit:GetAIBrain()

        local tNearbyEnemies = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryNavalSurface, oUnit:GetPosition(), oUnit[AiBotUnitInfo.refiDFRange], 'Enemy')
        if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyEnemies empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemies))..'; PD oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; owned by '..aiBrain.Nickname..'; Time='..GetGameTimeSeconds()) end
        if AiBotUtilities.IsTableEmpty(tNearbyEnemies) == false then
            local toUnitByPriorityType = {}
            local iPriorityExperimental = 1
            local iPriorityIndirect = 2
            local iPriorityCombat = 3
            local iPriorityOther = 4
            local iUnitPriority
            local oExperimentalToTarget
            local oIndirectToTarget
            local oCombatToTarget
            local oOtherToTarget

            for iEnemy, oEnemy in tNearbyEnemies do
                if not(oOptionalTargetToIgnore) or not(oOptionalTargetToIgnore == oEnemy) then
                    iUnitPriority = nil
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oExperimentalToTarget.UnitId) then
                        iUnitPriority = 1
                    elseif not(oIndirectToTarget) then
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryIndirect, oEnemy.UnitId) then
                            iUnitPriority = 2
                        elseif not(oCombatToTarget) then
                            if (oEnemy[AiBotUnitInfo.refiCombatRange] or 0) > 0 then
                                iUnitPriority = 3
                            elseif not(oOtherToTarget) then
                                iUnitPriority = 4
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if shot blocked for oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; is shot blocked='..tostring(AiBotLogic.IsShotBlocked(oUnit, oEnemy))..'; iUnitPriority='..(iUnitPriority or 'nil')) end
                    if iUnitPriority and not(AiBotLogic.IsShotBlocked(oUnit, oEnemy)) then
                        toUnitByPriorityType[iUnitPriority] = oEnemy
                        if iUnitPriority == 1 then break end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(toUnitByPriorityType) == false then
                local iLowestPriority = 100
                local oEnemyToTarget
                for iPriority, oEnemy in toUnitByPriorityType do
                    if iPriority < iLowestPriority then
                        iLowestPriority = iPriority
                        oEnemyToTarget = oEnemy
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Will try manual attack of unit '..oEnemyToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget)) end
                AiBotOrders.IssueTrackedAttack(oUnit, oEnemyToTarget, false, 'PDManAtck', false)
            end
        end
    end
end

function AssessT3EngineerConstructionOptions(oUnit)
    --Called when a t3 engi is created - so can check for certain buildings (without worrying about them being present in the list of blueprints but not actually buildable to us in the game due say to unit restrictions or only being available for a particular faction)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssessT3EngineerConstructionOptions'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local aiBrain = oUnit:GetAIBrain()
    if aiBrain.AiBotAI then --redundancy
        --Can we build a super-powerful shield?
        local sMostExpensiveShield = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryFixedShield, oUnit, false, false, false, nil, false, nil, true)
        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; sMostExpensiveShield='..(sMostExpensiveShield or 'nil')) end
        if sMostExpensiveShield then
            local oBP = AiBotUnitInfo.GetBlueprintFromID(sMostExpensiveShield)
            if bDebugMessages == true then LOG(sFunctionRef..': oBP.Defense.Shield.ShieldMaxHealth='..(oBP.Defense.Shield.ShieldMaxHealth or 'nil')..'; iExperimentalShieldHealthValue='..iExperimentalShieldHealthValue) end
            local iMinShieldSize = 50 --sera t3 shield is 46, i.e. this means we have a very high health and large shield
            if oBP.Defense.Shield.ShieldMaxHealth >= iExperimentalShieldHealthValue and oBP.Defense.Shield.ShieldSize >= iMinShieldSize then
                --Get list of all shields we can build with this unit, and make sure the cheapest of them that satisfies the requirements is recorded
                local iMaxShieldCost = 20000 --If the shield costs more than 20k mass then there is no point building running our special logic as it'll lead to us just building loads of shields in our base while enemy overruns us with land units
                local iCheapestShield = iMaxShieldCost
                local tsShieldsOfInterest = {}
                local tAllShields = EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryFixedShield)
                local oCurBP
                for _, sShieldBlueprint in  tAllShields do
                    oCurBP = AiBotUnitInfo.GetBlueprintFromID(sShieldBlueprint)
                    if (oCurBP.Defense.Shield.ShieldMaxHealth or 0) >= iExperimentalShieldHealthValue and oCurBP.Economy.BuildCostMass <= iMaxShieldCost then
                        table.insert(tsShieldsOfInterest, sShieldBlueprint)
                        iCheapestShield = math.min(iCheapestShield, (oCurBP.Economy.BuildCostMass or 10000000))
                    end
                end
                if AiBotUtilities.IsTableEmpty(tsShieldsOfInterest) == false then
                    local iMassThreshold = iCheapestShield * 1.2
                    for _, sShieldBlueprint in tsShieldsOfInterest do
                        oCurBP = AiBotUnitInfo.GetBlueprintFromID(sShieldBlueprint)
                        if oCurBP.Economy.BuildCostMass <= iMassThreshold then
                            if not(aiBrain[AiBotOverseer.reftbExperimentalShieldsConsidered][sShieldBlueprint]) then
                                aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] = true
                                if not(aiBrain[AiBotOverseer.reftbExperimentalShieldsConsidered]) then aiBrain[AiBotOverseer.reftbExperimentalShieldsConsidered] = {} end
                                table.insert(aiBrain[AiBotOverseer.reftbExperimentalShieldsConsidered], sShieldBlueprint)
                                if not(aiBrain[AiBotOverseer.refiExperimentalShieldCategory]) then aiBrain[AiBotOverseer.refiExperimentalShieldCategory] = categories[sShieldBlueprint]
                                else aiBrain[AiBotOverseer.refiExperimentalShieldCategory] = aiBrain[AiBotOverseer.refiExperimentalShieldCategory] + categories[sShieldBlueprint]
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': recording that we can build experimental level shields for brain '..aiBrain.Nickname..'; recording sShieldBlueprint='..sShieldBlueprint..' with mass cost of '..oCurBP.Economy.BuildCostMass..' and a shield health of '..oCurBP.Defense.Shield.ShieldMaxHealth..' with a shield size of '..oCurBP.Defense.Shield.ShieldSize) end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderGiftingMassStorageToNearbyMexOwner(oJustBuilt)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderGiftingMassStorageToNearbyMexOwner'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --If just built a mass storage but we dont own the mex it is adjacent to, then gift the storage
    local rSearchRectangle = AiBotUtilities.GetRectAroundLocation(oJustBuilt:GetPosition(), 2.749)
    local tNearbyUnits = GetUnitsInRect(rSearchRectangle) --at 1.5 end up with storage thats not adjacent being gifted in some cases but not in others; at 1 none of it gets gifted; the mass storage should be exactly 2 from the mex; however even at 2.1, 2.25 and 2.499 had cases where the mex wasnt identified so will try 2.75 since distances can vary/be snapped to the nearest 0.5 I think
    local aiBrain = oJustBuilt:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam
    if bDebugMessages == true then
        LOG(sFunctionRef..': Storage gifting where built storage - oJustBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; owner='..aiBrain.Nickname..'; is tNearbyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnits)))
        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
            for iUnit, oUnit in tNearbyUnits do
                LOG(sFunctionRef..': iUnit '..iUnit..' in tNearbyUnits='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; owner='..oUnit:GetAIBrain().Nickname)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
        local tNearbyMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tNearbyUnits)
        if AiBotUtilities.IsTableEmpty(tNearbyMexes) == false then
            local bHaveMexWeOwnNearby = false
            local oBrainToTransferToIfWeOwnNoMexes
            for iUnit, oUnit in tNearbyMexes do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering nearby unit oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname) end
                if oUnit:GetAIBrain() == aiBrain then
                    bHaveMexWeOwnNearby = true
                elseif oUnit:GetAIBrain().AiBotTeam == iTeam and (oUnit:GetAIBrain().AiBotAI or ScenarioInfo.Options.AiBotTeammate == 1) then
                    oBrainToTransferToIfWeOwnNoMexes = oUnit:GetAIBrain()
                end
            end
            if not(bHaveMexWeOwnNearby) and oBrainToTransferToIfWeOwnNoMexes then
                if bDebugMessages == true then LOG(sFunctionRef..': Will try and gift the storage to the player who owns the mex already there') end
                AiBotTeam.TransferUnitsToPlayer({oJustBuilt}, oBrainToTransferToIfWeOwnNoMexes:GetArmyIndex(), false)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderUpgradingT2Radar(oRadar)
    --Consider getting omni in minor zones (as an upgrade of existing T2 radar), provided not close to the map edge, and still on our side of the map
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderUpgradingT2Radar'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start, is oRadar valid='..tostring(AiBotUnitInfo.IsUnitValid(oRadar))..'; Map size='..AiBotMap.iMapSize) end
    if AiBotUnitInfo.IsUnitValid(oRadar) and AiBotMap.iMapSize >= 800 then
        local aiBrain = oRadar:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oRadar:GetPosition(), true, iTeam)
        if bDebugMessages == true then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftClosestFriendlyBase]) == false then
                LOG(sFunctionRef..': Considering for oRadar='..oRadar.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRadar)..' owned by '..aiBrain.Nickname..' at time='..GetGameTimeSeconds()..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Dist to friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oRadar:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; LZMexCount='..(tLZData[AiBotMap.subrefLZOrWZMexCount] or 'nil'))
            else
                LOG(sFunctionRef..': Dont have a valid closest friendly base')
            end
        end
        if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.15 and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.45 and AiBotUtilities.GetDistanceBetweenPositions(oRadar:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 200 and (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0 then
            --Are we close to map edge?
            local iX = oRadar:GetPosition()[1]
            local iZ = oRadar:GetPosition()[3]
            local iMinDistFromMapEdge = 100
            if bDebugMessages == true then LOG(sFunctionRef..': iX='..iX..'; iZ='..iZ) end
            if iX >= iMinDistFromMapEdge and iZ >= iMinDistFromMapEdge and iX <= AiBotMap.iMapSize - iMinDistFromMapEdge and iZ <= AiBotMap.iMapSize - iMinDistFromMapEdge then
                local sUpgradeID = AiBotUnitInfo.GetUnitUpgradeBlueprint(oRadar, true)
                if bDebugMessages == true then
                    if sUpgradeID then LOG(sFunctionRef..': sUpgradeID='..(sUpgradeID or 'nil')..'; canbuild='..tostring(oRadar:CanBuild(sUpgradeID)))
                    else LOG(sFunctionRef..': No valid upgrade ID')
                    end
                end
                if sUpgradeID and oRadar:CanBuild(sUpgradeID) then
                    local iSecondsToWait = 30
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

                    WaitSeconds(iSecondsToWait * 2)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    while AiBotUnitInfo.IsUnitValid(oRadar) do
                        --Abort if we now have good radar coverage
                        if tLZTeamData[AiBotMap.refiRadarCoverage] > AiBotUnitInfo.iT2RadarSize + 80 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Radar coverage good enough that we dont need omni, tLZTeamData[AiBotMap.refiRadarCoverage]='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 'nil')) end
                            break
                        else
                            --Do we have the eco to support an omni outside of our core base?
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want to upgrade t2 radar '..oRadar.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRadar)..' owned by '..oRadar:GetAIBrain().Nickname..' to omni radar, T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Gross E='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Enemy combat in zone='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Enemy air to ground='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] or 'nil')..'; subrefiOurT1ToT3BomberThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]..'; our gunship threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; Time='..GetGameTimeSeconds()) end
                            if tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1500 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] == 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0) >= 25000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 35000) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))..'; Stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or false)) end
                                if not(AiBotConditions.HaveLowPower(iTeam)) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                                    --Upgrade unless already upgrading a t3 radar
                                    if bDebugMessages == true then
                                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingOther]) then LOG(sFunctionRef..': No other upgrades active on team')
                                        else
                                            LOG(sFunctionRef..': Is table of T2+ radar getting upgrade empty on team='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRadar - categories.TECH1, AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingOther]))))
                                        end

                                    end
                                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingOther]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRadar - categories.TECH1, AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingOther])) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try upgrading t2 radar to omni') end
                                        AiBotEconomy.UpgradeUnit(oRadar, true)
                                        break
                                    else
                                        iSecondsToWait = 5
                                    end
                                else
                                    iSecondsToWait = 30
                                end
                            else
                                iSecondsToWait = 30
                            end

                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitSeconds(iSecondsToWait)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GEMobileShieldTeleDefence(oTeleportingUnit, tTeleportDestination, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GEMobileShieldTeleDefence'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oTeleportingUnit) then
        --Get target zone and check for nearby shields that are part of a GE template

        local oFirstAiBotBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if oFirstAiBotBrain then
            local teleport = import('/lua/shared/teleport.lua')
            local energyCost, time, teleDelay
            if teleport and rawget(teleport, 'TeleportCostFunction') then
                if bDebugMessages == true then LOG(sFunctionRef..': calculating precise teleport time for FAF') end
                energyCost, time, teleDelay = import('/lua/shared/teleport.lua').TeleportCostFunction(oTeleportingUnit, tTeleportDestination)
            else
                if AiBotUtilities.bFAFActive then
                    AiBotUtilities.ErrorHandler('Failed to calculate teleport time in FAF, will use hardcoded value')
                    time = 15
                    teleDelay = 15
                elseif AiBotUtilities.bQuietModActive or AiBotUtilities.bLoudModActive then
                    time = 30 --https://github.com/Team-QUIET/QUIET/blob/547c370c538208501807bb64a15dc7e624c6f9a1/gamedata/lua/lua/sim/Unit.lua#L5391 - Az thought c.30s for 6-7km
                    teleDelay = 30
                else
                    time = 10
                    teleDelay = 10
                end
            end
            --For now am assuming time is the time until teleport compeltes in seconds, not 100% sure though
            local iTimeUntilTeleport = time
            local iTimeForShieldRecharge = 5
            if bDebugMessages == true then LOG(sFunctionRef..': oTeleportingUnit='..oTeleportingUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTeleportingUnit)..'; iTimeUntilTeleport='..iTimeUntilTeleport..'; time='..time..';teleDelay='..teleDelay..'; GameTime='..GetGameTimeSeconds()) end
            if iTimeUntilTeleport > (iTimeForShieldRecharge - 0.1) then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(iTimeUntilTeleport - iTimeForShieldRecharge + 1) --dont want shields to actually be enabled until after enemy has teleported, as highly unlikely we kill enemy in less than a second, and also unlikely enemy is quick enough to ctrlk in under a second
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if not(oFirstAiBotBrain.AiBotIsDefeated) then
                local tNearbyMobileShields = oFirstAiBotBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLandShield, tTeleportDestination, 60, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': is tNearbyMobileShields empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyMobileShields))) end
                if AiBotUtilities.IsTableEmpty(tNearbyMobileShields) == false then
                    local iMaxWaitTime = 60
                    for iShield, oShield in tNearbyMobileShields do
                        if bDebugMessages == true then LOG(sFunctionRef..': Will enable mobile shield if not already, oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; oShield[AiBotUnitInfo.refbShieldIsDisabled]='..tostring(oShield[AiBotUnitInfo.refbShieldIsDisabled] or false)) end
                        if oShield[AiBotUnitInfo.refbShieldIsDisabled] then
                            AiBotUnitInfo.EnableUnitShield(oShield)
                        end
                        AiBotMicro.EnableUnitMicroUntilManuallyTurnOff(oShield)
                    end
                    local iCurDistToTeleport, iMinDistWanted, iCurAngleToShieldTarget
                    local iTimeWaited = 0
                    local tTeleportOrUnitPosition, tCurShieldTarget, tTempMovePosition
                    while AiBotUnitInfo.IsUnitValid(oTeleportingUnit) and not(oFirstAiBotBrain.AiBotIsDefeated) do
                        --Enable all mobile shields around the target that are disabled, and if they are within 8 of their destination and also shield is overlapping the teleport destination have them move away
                        if AiBotConditions.IsTableOfUnitsStillValid(tNearbyMobileShields) then
                            if iTimeWaited > iTimeForShieldRecharge then
                                tTeleportOrUnitPosition = oTeleportingUnit:GetPosition()
                            else tTeleportOrUnitPosition = tTeleportDestination
                            end
                            local bCampaignMap = AiBotMap.bIsCampaignMap
                            if bDebugMessages == true then LOG(sFunctionRef..': Will loop through shields and keep them away from the teleport destination, time='..GetGameTimeSeconds()..'; iTimeWaited='..iTimeWaited..'; iMaxWaitTime') end
                            for iShield, oShield in tNearbyMobileShields do
                                if oShield:GetAIBrain().AiBotAI then
                                    iCurDistToTeleport = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tTeleportOrUnitPosition)
                                    iMinDistWanted = (oShield.MyShield.Size or oShield:GetBlueprint().Defense.Shield.ShieldSize or 17) * 0.5 + 3
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; CurShield health='..oShield.MyShield:GetHealth()..'; refbShieldIsDisabled='..tostring(oShield[AiBotUnitInfo.refbShieldIsDisabled] or false)..'; iCurDistToTeleport='..iCurDistToTeleport..'; iMinDistWanted='..iMinDistWanted..'; refbSpecialMicroActive='..tostring(oShield[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                                    if iCurDistToTeleport < iMinDistWanted then
                                        iCurAngleToShieldTarget = nil
                                        if AiBotUnitInfo.IsUnitValid(oShield[AiBotLand.refoMobileShieldTarget]) then
                                            tCurShieldTarget = oShield[AiBotLand.refoMobileShieldTarget]:GetPosition()
                                        elseif oShield[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition] then
                                            tCurShieldTarget = {oShield[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition][1], oShield[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition][2], oShield[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition][3]}
                                        else
                                            tCurShieldTarget = oShield:GetPosition()
                                            iCurAngleToShieldTarget = AiBotUtilities.GetAngleFromAToB(tTeleportOrUnitPosition, oShield:GetPosition())
                                        end
                                        if not(iCurAngleToShieldTarget) then iCurAngleToShieldTarget = AiBotUtilities.GetAngleFromAToB(oShield:GetPosition(), tCurShieldTarget)
                                            tTempMovePosition = AiBotUtilities.MoveInDirection(oShield:GetPosition(), iCurAngleToShieldTarget, math.max(4, iMinDistWanted - iCurDistToTeleport + 2), true, false, bCampaignMap)
                                            AiBotOrders.IssueTrackedMove(oShield, tTempMovePosition, 0.1, false, 'MobShTelMv', true)
                                        end
                                    end
                                end
                            end
                        end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitSeconds(1)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        iTimeWaited = iTimeWaited + 1
                        if iTimeWaited > iMaxWaitTime then break end
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(0.5) --just in case there's a delay on an explosion
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if AiBotConditions.IsTableOfUnitsStillValid(tNearbyMobileShields) then
                        for iShield, oShield in tNearbyMobileShields do
                            --Disable shields again if part of GE template
                            if oShield[reftArtiTemplateRefs] then
                                if bDebugMessages == true then LOG(sFunctionRef..': Disabling shield, oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)) end
                                AiBotUnitInfo.DisableUnitShield(oShield)
                            end
                            oShield[AiBotUnitInfo.refbSpecialMicroActive] = false
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpgradeShieldsCoveringSMD(iTeam)
    --Called via fork thread when enemy has t3 arti/novax and SML, so we make sure any t2 shields covering SMD are upgraded to t3 to make it slightly harder to break through
    while AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] do
        WaitSeconds(5)
    end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            local toSMD = oBrain:GetListOfUnits(AiBotUnitInfo.refCategorySMD, false, true)
            local toUpgradingShieldsByEntityId = {}

            if AiBotUtilities.IsTableEmpty(toSMD) == false then
                for iSMD, oSMD in toSMD do
                    if AiBotConditions.IsTableOfUnitsStillValid(oSMD[reftoShieldsProvidingCoverage]) then
                        for iShield, oShield in oSMD[reftoShieldsProvidingCoverage] do
                            if not(oShield.EntityId) or not(toUpgradingShieldsByEntityId[oShield.EntityId]) then
                                if EntityCategoryContains(categories.TECH2, oShield.UnitId) and oShield:GetBlueprint().General.UpgradesTo then
                                    if not(oShield:IsUnitState('Upgrading')) then --Will recheck this and similar in the logic to upgrade unit
                                        toUpgradingShieldsByEntityId[oShield.EntityId] = true
                                        AiBotEconomy.UpgradeUnit(oShield)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end